  str_item_intro_3420137 = "指定の★6光霊リストから、1名の光霊を選び、仲間にすることができます。以下の光霊が選択可能です：<color=#ffffff>ティアラ/シンゲイ/アルゴル/イスタバン・積痕/センキョク/レベッカ/タンドウ/ザーリャ/アントニー/ローレライ/セナ/ヨシュア/ソルラド・響鳴/インゲル/レオ/ハーティ/ティナ/ライン/イェリア/ユエ/シュウ/ヴィック/アクセリア/リリカ/ミノス/ポルクス/ジェノ/フィア/カレン・照魂/ニナ/バートン・鋭刃/ギルス/レノーア/アズール/ヨウ/アメモリ/リンネ/フロリナ/ルビー/シヴォーン/ノーヴィオ/ヘイディ/ベセル/ルーク/パロマ/グラム/レビィ/スモーキー/フェラール/ベリエ/ヒイロ/サメヤマ/イブ/ウリエル/カレン/キシローナ/シャリー/ラファエル/クラリン/カロン/エルシー/ビクトリア/ジョナ/ナシリス/ガブリエル/ミジャード/ミカエル/ガルー/イルンティ/ラス</color>\n注意：3周年記念特選召集ボックスには使用期限があります。期限を過ぎると自動的に3000光珀に変換され、ゲーム内メールにて送付されます。使用期限は2024年8月16日18:00です。期限までにご使用ください。",
