  str_item_6001520 = "リーダーの首飾り",
  str_item_6001521 = "戦友の胸章",
  str_item_6001524 = "携帯ゲーム機",
  str_item_6001525 = "ヒラメキの時",
  str_item_6001526 = "燃え絶ゆる日の章",
