  str_item_6001530 = "親友の証",
  str_item_6001531 = "愛の歌",
  str_item_6001532 = "これはあなたの星光",
  str_item_intro_6000001 = "記念メダル。長い月日を経て、驚くべき量のコインが貯まった。財布さえも、1棟の家屋ほど大きくなっている",
  str_item_intro_6000002 = "記念メダル。具体的な金額が分からないほどの財産。見ているだけで、めまいがする。そんな富はすべての人、特に影ノ街の商人のあこがれだ",
  str_item_intro_6000101 = "記念メダル。おめでとう！たった数回のチャレンジに過ぎないが、まだまだ道のりはながい",
  str_item_intro_6000102 = "記念メダル。自由自在に巨像を操縦できるようになった。蛍灯たちとも、ずっと仲良くなれた気がする",
  str_item_intro_6000103 = "記念メダル。目の前には雲、周りにも雲。白い雲から透けて見える大地と、雲の浮かぶ青空を眺める",
  str_item_intro_6000104 = "記念メダル。長い間「ソラヴァン」で旅をしていたら、空さえも自分の庭になったみたいだ。どこまでも飛んで行ける気がする",
  str_item_intro_6000201 = "記念メダル。目にした大陸の姿を心に刻み、その手を振れば、世界の姿が紙の上に現れる",
  str_item_intro_6000202 = "記念メダル。長い間旅を続けて、大陸の地形にも詳しくなった。山や川の姿がすぐに頭の中に浮かんでくるのでは？",
  str_item_intro_6000301 = "記念メダル。この先もまだまだ続く長い道のり。その隣にはきっと、個性豊かで信頼できる仲間たちがいてくれるはずだ",
  str_item_intro_6000302 = "記念メダル。多くの旅を通して、大勢の多彩な仲間たちと知り合うことができた",
  str_item_intro_6000303 = "記念メダル。どこへ行こうと、隣には仲間たちがいる。さまざまな挑戦に立ち向かい、喜びも苦痛も、物語も分かち合おう",
  str_item_intro_6000401 = "記念メダル。仲間が真の力に目覚めるたび、空に不思議な光が輝く。「光」の名を持つ力と空との不思議な繋がりなのかもしれない",
  str_item_intro_6000402 = "記念メダル。「光」の名を持つ力を掌握した時、空に輝く光がその両手の中に舞い降りる",
  str_item_intro_6000403 = "記念メダル。「光」の力を持つ仲間たちの力を集め、特別な人にゆだねれば、世界は明るく輝き、光を持たぬ者でも四方をあまねく照らせるだろう",
  str_item_intro_6000501 = "記念メダル。互いに輝く2つの星は信頼の証。2つの星のように、互いを光で照らし、片時も離れることはない",
  str_item_intro_6000502 = "記念メダル。星たちも互いに交わりながら移動する。心と思いが「信念」という道で交差し、通じ合い、共鳴し合うのと同じように",
  str_item_intro_6000503 = "記念メダル。仲間とは空一面の星のようなもの。その光は絶対的な信頼だけでなく、理念や意志の重なりを表している",
  str_item_intro_6000601 = "記念メダル。通じ合う者に初対面かどうかは関係ない。2人の両手はまるで1人の腕であるかのように息の合った動きを見せ、心は通じ合う",
  str_item_intro_6000602 = "記念メダル。長年地下に埋もれていたとしても、空を飛び回る感覚を忘れることはない。はじめの1回を覚えているから",
  str_item_intro_6000603 = "記念メダル。近づく足音は危険だけではない、崩壊の訪れを暗示する",
  str_item_intro_6000604 = "記念メダル。数えきれないほどの敵を前に、彼は轟音と共に敵を「道連れ」にすることを選んだ。決して無謀な犠牲ではない。機智に富んだ戦術なのだ",
  str_item_intro_6000605 = "記念メダル。同族からの知らせだ！そのか細い声は、一体何を訴え、どのような過去を背負っているのだろうか？",
  str_item_intro_6000606 = "記念メダル。それは青空に浮かぶもの。それは文明の中心。それは永遠不落。それは――光の象徴",
  str_item_intro_6000607 = "記念メダル。「未来に光はない、あるのは暗闇だけ――」その瞬間、彼女は恐ろしい笑みを浮かべた。同族を裏切り、別の道を歩み出したのだ",
  str_item_intro_6000608 = "記念メダル。すべてが策略通りに進み、敵は得意になっている。失望に沈む中、タンポポの種がふと目の前をよこぎる。未来は、どうなっていくのか？私たちに明日は来るのだろうか？",
  str_item_intro_6000609 = "記念メダル。「努力よりも選択が肝心」――アストラ大陸のことわざだ。多くの者が運命の分かれ道で迷うが、自らの心を信じ、直感を信じ、仲間を信じるしか道はない",
  str_item_intro_6000610 = "記念メダル。光を武器にできるのは、あの永遠不落の都だけだ。その代価は測り知れないが、敵を倒すためなら、すべて価値に価値がある",
  str_item_intro_6000611 = "記念メダル。黒い巨像は黒煙となって、かなたの谷へ落ちて行った。しかし、黒い巨像とその主は、まだ死んではいない…",
  str_item_intro_6000612 = "記念メダル。力を求める者は、その力によって身を亡ぼす。彼女が闇の道を選んだ時から、深淵の中で命を落とすことは決まっていたのだ…",
  str_item_intro_6000613 = "記念メダル。線は数学言語でいう「自然」、貝殻は価値を保存する容器。継続性は必ずしも必要ではないのだ",
  str_item_intro_6000614 = "記念メダル。過去に由来する理念。かつて戦いに明けくれた2人も、今は別々の道を歩んでいる",
  str_item_intro_6000615 = "記念メダル。「ハーモナイザー」によって、彼女は果てしなく深い眠りについた。眠りから目覚める時、彼女の奥深くに眠っていた強大な力が解き放たれる",
  str_item_intro_6000616 = "記念メダル。空の末裔はついに回帰の塔の下で自らのふるさとを手にした。しかし、ふるさとの出現は同時に彼の運命を変えようとしていた…",
  str_item_intro_6000617 = "記念メダル。極夜の地を前に白夜城の騎士と啓光連邦の軍人は手を結び、探索に向かう。彼らを待っているのは、ただの危険ではない",
  str_item_intro_6000618 = "記念メダル。多数の勢力が軍事演習に参加しようとしている。このメダルはこの上ない名誉を意味する",
  str_item_intro_6000619 = "記念メダル。シェルターの最下層では厚い扉が侵入者を阻み、重要な物がならず者の手に渡らないようにしている",
  str_item_intro_6000701 = "記念メダル。これはただの始まりではない。頭角を現すと同時に挑戦に立ち向かい、次々と先手を制する者だけが、頂点に上り詰める可能性を持っている",
  str_item_intro_6000702 = "記念メダル。常に飛躍し、常に向上し、険しい道のりであっても、進み続ける。これが力に目覚めるということか？",
  str_item_intro_6000703 = "記念メダル。高峰に到達した時、その者には多くの人々を見下ろすだけの力が備わっているはずだ。しかし、登り詰めた者は、それで満足しない。最終目的はまだ果たされていないのだから…",
  str_item_intro_6000704 = "記念メダル。頂上に至る時、そこに立つ者はすでに多くの挑戦者たちの上に立っている。しかし、征服の心が満たされることはなく、足取りが止まることもない",
  str_item_intro_6000705 = "記念メダル。\n山頂に立つ者は、数えきれぬ戦いを経た。\n山頂に立つ者の、苦しみを誰が知ろう。\n山頂に立つ者は、山を制して王を称え、\n山頂に立つ者は、頂を目指す者たちを俯瞰する。",
  str_item_intro_6000706 = "記念メダル。たとえ一度でもこの境地に到達できる者はまれだ。それだけでも常人とは一線を画している",
  str_item_intro_6000801 = "記念メダル。思いがけぬ拘束と思いがけぬ出会い。\n牢獄の高い壁にあらがう者が、その足かせと手かせを破る",
  str_item_intro_6000802 = "記念メダル。猫の望むものとはいったい何か？大好きな缶詰と、それから…",
  str_item_intro_6000803 = "記念メダル。「ホリデー」の家族は、彼女にこのカフェこそが自分の居場所、そして自分の家なのだと教えてくれた…",
  str_item_intro_6000804 = "記念メダル。雪と氷に覆われた宮殿は固く扉を閉ざしている。しかし、オーロラを見上げる小さな人影が訪れる時、その扉は大きく開かれる",
  str_item_intro_6000901 = "記念メダル。地面に蜂の巣のような、たくさんの細かい亀裂が走っている。互いに交わり、蜘蛛の巣のような網目をつくる亀裂から、不吉な空気が漂ってくる。どうやら、ただごとではないようだ…",
  str_item_intro_6000902 = "記念メダル。漆黒の闇につつまれる洞窟では、進入者自身の光の輝きだけが頼りだ。しかし、中は決して静かではない。多くの「住人」が訪れる者たちを出迎える。",
  str_item_intro_6000903 = "記念メダル。ここに本当に「果て」があるのだろうか？探索のたびにそんな考えが浮かび、頭から離れない。しかし、意志の固い探索者たちは、危険を顧みることもなく、変わらず足を踏み入れるのだろう",
  str_item_intro_6001001 = "記念メダル。映像は武器であり、虚構も鋭い刃物になりうる。「目」は時として、力強い腕よりも大きな威力を持つ。",
  str_item_intro_6001002 = "記念メダル。燃えあがれ！燃え盛る炎は、冒とくする敵をすべて滅ぼすことだろう",
  str_item_intro_6001003 = "記念メダル。高らかなおたけびが、敵の存在を示す。しかし、沈黙こそ彼らの終末であり、結末である。",
  str_item_intro_6001004 = "記念メダル。恐ろしいのは敵か、それとも無か？その存在を倒さなければ、永遠に封印し、閉じ込めることはできない。",
  str_item_intro_6001005 = "記念メダル。形をもたない身体には意識だけが漂う。しかし、光の波を前にしては、ただ消え去るしかない。",
  str_item_intro_6001006 = "記念メダル。運命は人を狂わせ、暗黒へと陥れる。その先に待っているのは、刃と刃の戦いだけだ",
  str_item_intro_6001007 = "記念メダル。尽きることのない痛みと終極の狂気に苦しみ続けてきた。すべてを終わらせよう！それこそが最高の贈り物だ",
  str_item_intro_6001008 = "記念メダル。夜明け前こそが最も深い闇につつまれる。しかし、その深い闇を過ぎれば、次に待っているのは大地に降りそそぐ朝日だ",
  str_item_intro_6001009 = "記念メダル。雑然と耳障りな音が入り混じるその声は、敵の苦しみと恨みそのものだ",
  str_item_intro_6001010 = "記念メダル。どこにも行き場のない者も追放されるのだろうか？もしかしたら、それも可能かもしれない。ただ、誰も気づかないだけのことだ",
  str_item_intro_6001011 = "記念メダル。血の色をした石は汚れから生まれ、幾重もの危険から脱した後、美しい宝石に生まれ変わる",
  str_item_intro_6001012 = "記念メダル。人には何の価値もない。魂こそが神々さえも血眼になる価値をもっている。抜け殻は履き古した靴のように捨てられるだけだ",
  str_item_intro_6001013 = "記念メダル。白夜城の騎士ではない、長年の敵手である。すでに打ち破られたふりをし、後は死闘を決するのみ。",
  str_item_intro_6001101 = "記念メダル。ページをめくるたびに心地よい声が頭の中に響く。文字でつづられた美しいものたちが、目の前に現れるかのようだ",
  str_item_intro_6001102 = "記念メダル。書物の上に座るのは、書物に対する不敬ではない。中に書かれていることはすべて知っているからだ",
  str_item_intro_6001103 = "記念メダル。書物をベッドや枕にすれば、夢の中でも書物の宝庫で時を過ごすことができる。広大な知識の中を行ったり来たりしながら、思う存分知識を楽しもう",
  str_item_intro_6001201 = "記念メダル。自らの手で育てた苗が不思議な植物に育った時、たとえ両手が泥だらけになっていたとしても、心は喜びに満ちている",
  str_item_intro_6001202 = "記念メダル。不思議な植物がたくさん育ち、一面に広がって新たな景観を造り上げた時、天空ノ庭の夕暮れは特別なものとなるだろう",
  str_item_intro_6001203 = "記念メダル。この手にある希少な魚こそが、釣り名人の証だ！",
  str_item_intro_6001204 = "記念メダル。今日は釣り好きのお祭りだ。祭りの季節がやって来たわけではない、あの釣りの名手がやってきたんだ！",
  str_item_intro_6001205 = "記念メダル。いつの間にか、こんなにも多くの建物が作れるようになった。あの谷間の空き地も、もう寂しくはないだろう",
  str_item_intro_6001206 = "記念メダル。これだけ多くの建築法を学んだのだ。その気になれば、天空ノ庭にぎやかな町に変えることもできる。天空ノ庭の主の力の見せ所だ",
  str_item_intro_6001301 = "記念メダル。静かなる地、いにしえの伝説。長い間深い眠りについていた英雄たちを呼び覚ます時、一体どのような絆が生まれるのだろうか？",
  str_item_intro_6001302 = "記念メダル。逆らえない、いにしえの契約。かつての敵は今なお強烈な迫力をもって立っている。たとえ口約束であろうと、彼らの意志を断ち、行動を止めることはできない",
  str_item_intro_6001400 = "記念メダル。ゲームもまた人生のようなもの。手のひらの上の冒険も同じように刺激的だ。過酷な条件でゲームをクリアできた人は、現実世界でも大きな収穫があるだろう",
  str_item_intro_6001401 = "記念メダル。忠実な記録は誰の肩も持たず、何一つ隠さない。同時に記録とは、記憶の保管者でもあり、昔日の記憶をいつでもあなたに示してくれる",
  str_item_intro_6001402 = "記念メダル。天空を漂うステージから、歌声が大陸の四方に響き渡る。夢と未来を届ける、愛と癒しの旋律",
  str_item_intro_6001403 = "記念メダル。果てしなく広がる海で、決して欠かすことのできないもの。船を正しい方向へと導いてくれるだけでなく、運命にかかった霧も晴らしてくれるという…",
  str_item_intro_6001404 = "記念メダル。贈り物でもあり、気持ちでもあり、また言葉でもある。口にせずとも、ただこれを相手に渡せば、それで十分伝わるものがあるはずだ",
  str_item_intro_6001405 = "記念メダル。特別な日の花が特別な時に咲き誇る。花の香りに酔いしれ、この素晴らしい瞬間を楽しもう。",
  str_item_intro_6001406 = "記念メダル。探偵から離れることはない。手を伸ばせば助けを得られる。これさえあれば、どれほど小さな手がかりも見逃さない。",
  str_item_intro_6001407 = "記念メダル。家族の一日の記憶は水晶の中の幻影だ。幻の世界、幻の人、幻の物、幻の出来事…すべて幻のはずなのに、自ら体験した真実のように思えてくる。",
  str_item_intro_6001408 = "虚妄の世界は真実に生きる人たちを閉じ込める。無理矢理壊そうとすると、かえってその中に束縛され、永遠に抜け出せなくなる…",
  str_item_intro_6001409 = "記念メダル。デヌオ渓谷に隠れて暮らす。ひらりと宙を舞い、鱗粉を撒けば、光の粒が一面に広がり、人々の心を奪う…",
  str_item_intro_6001410 = "記念メダル。勝利とは戦いでのみ得られるものではない。その多くは日頃の様々な生産活動や発展、繁栄によってもたらされるのだ。",
  str_item_intro_6002001 = "記念メダル。善良なる者の守護者、神々の使者は本当に存在するのだろうか？それとも、ただの幻想にすぎないのだろうか？",
  str_item_intro_6002002 = "記念メダル。光の環の下で武に備えよ。太陽が昇っても、暗黒の脅威を決して忘れてはならない。平和が訪れても、暗がりに潜む敵への警戒を永遠におこたってはならない",
  str_item_intro_6002003 = "記念メダル。北境の伝説に登場する、未知の古代生物。たった一息で炎をも凍らせ、町1つを氷で閉ざしてしまうという",
  str_item_intro_6002004 = "記念メダル。この世には、自分の姿のみを写す鏡があるらしい。だが、その姿には命があり、魂も宿っているという…",
  str_item_intro_6002005 = "記念メダル。ありきたりのただの物でも、知恵ある者が握れば、意識と魂を宿し、自らの使命を果たそうとする",
  str_item_intro_6002006 = "記念メダル。鋼は空気より何百倍も重いのに、なぜ空に浮かぶことができるのだろう？鉄は水より重いのに、どうして船になるのだろう？知識と理論は、時として常識を超えるのだ",
  str_item_intro_6002007 = "記念メダル。重い鋼を形なき音のごとく速く飛ばすなど、おそらく神にしかできない業だ",
  str_item_intro_6002008 = "記念メダル。果てしなく広がる砂と一面の乾いた大地。なぜこのようなところを歩くのか、誰にもわからない。もしかしたら、歩くことそのものに目的があるのかもしれない",
  str_item_intro_6002009 = "記念メダル。代価なしに何かを手に入れられる者などいない。今払わずに済んだとしても、いつか必ず払うことになる。しかも、同等以上の代価を――",
  str_item_intro_6002010 = "記念メダル。恐怖に満ちた叫び声と味方の歓呼が響く。戦いの力とは、征服や計略、もしくは勇気にあるのではない。「勝利」という名の祭壇の上に立つ、人々がいただかずにはいられない「王者」たちの手に握られているのだ",
  str_item_intro_6002011 = "記念メダル。人々を強大な戦士に変えるには、鋼を身に着けただけでは足りない。協調性や柔軟性、そして粘り強さが必要なのだ",
  str_item_intro_6002012 = "記念メダル。そんなビンが本当に存在しうるのだろうか？内と外の区別がなく、容積がないということは、裏返せば、無限の空間が広がっていると言えるのかもしれない。これはこの世のものではない。神だけが理解でき、創り出せるものだ",
  str_item_intro_6002013 = "記念メダル。1本の紙の帯にたった1つの面しかない？これがその疑問に「答え」てくれる。肝心なのは帯のつなぎ目。それが分かれば「世界のつなぎ目」の理も明らかになるだろう…",
  str_item_intro_6002014 = "記念メダル。どんなに小さな空間にも万物が存在する可能性がある。ビンの中の世界をのぞく時、誰かもまたこちらの世界をのぞいている――そう考えたことはないだろうか？",
  str_item_intro_6002015 = "記念メダル。万物は1本の木の上で生まれたという伝説がある。多くの人がその伝説を鼻であしらってきたが、ある生物の起源を研究したところ、それまでの自説を疑わざるを得なくなった…",
  str_item_intro_6002016 = "記念メダル。単列弦でも充分に美しい音色を出すハープが2列弦になったら、それは美しい音を奏でることだろう。しかし、演奏者にも高い技術と尋常ではない体力が必要だ",
  str_item_intro_6002017 = "記念メダル。輪っかの形をした体を活かし、「つぶす」ことを攻撃手段とする。回転しながら迫ってくる鋭い刃を一度目にしたら、戦場で再びまみえることがないようにと誰もが祈ることだろう",
  str_item_intro_6002018 = "記念メダル。要塞が伝説の巨像のように大陸の上を飛び回ることができたら、敵に出会うこともなくなるだろう",
  str_item_intro_6002019 = "記念メダル。人々が「虚無」について考える時、「虚無」はすでに実在のものとなっている。姿も形も持たないまま、こっそりと人々の目から頭へと入り込み、もう一つの虚無を形成するのだ",
  str_item_intro_6002020 = "記念メダル。疲れを知らず、愚痴もこぼさない。砂漠を生きる者にとって、まさに名馬そのものだ",
  str_item_intro_6002021 = "記念メダル。人々はチェスを好み、位の高い者はしばしばチェスを世界にたとえたがる。しかし現実の世界ではコマにもチェス盤にも自我があり、対局は崩れ、幾度も同じ争いが繰り返されるのだ",
  str_item_intro_6002022 = "記念メダル。「永遠の破滅に埋もれるがいい…目の前の世界を見るのだ、それが最後の記憶となる」暗黒から来た邪悪な者は、大陸の生きとし生ける者にそう告げる",
  str_item_intro_6002023 = "記念メダル。空に浮かぶ星の方位は人々の運命を示すといわれる。そこで人々は高い塔を造り、星の位置を観察し、未来を知ろうとした。ただ皮肉なことに、塔は自身の結末を予知することはできなかった",
  str_item_intro_6002024 = "記念メダル。たくましい体と素早く力強い動きが特徴のそれは、いかにも凶悪な見た目だが、本当に恐れるべきは、こうかつな頭脳と猛毒をもつ尾っぽの針だ",
  str_item_intro_6002025 = "記念メダル。地獄の死者のごとく、生者の怒りとともにこの世へやってきた。冥界は終着点ではない。死して再び生を得た輪廻こそがすべてである",
  str_item_intro_6001500 = "記念メダル。遠く響き渡る音、海棠は咲き誇る。その響きが聞こえる頃、東風遠きより至りて、今まさに花開かん。双閣港に弦生じ、灼華そこにあらん。",
  str_item_intro_6001507 = "記念メダル。\n北境の地は最近になって降った雪とはるか昔に降った雪で覆われている。手にとった雪はいつの時代のものだろう？",
  str_item_intro_6001508 = "記念メダル。\n共に経験した冒険は、すべて大切に保管されている",
  str_item_intro_6001510 = "毒に犯されていない花は純潔で美しい。\nまるで彼女のようだ。",
  str_item_intro_6001511 = "記念メダル。秀でた知恵は大陸間を結ぶ船舶を造ることもできるが、混乱を世にもたらす兵器を造ることもできる。いかなる選択を下すかもまた一つの知恵なのだ。",
  str_item_intro_6000620 = "記念メダル。\n啓光が造り出した巨大な戦闘アーマーで、強固な筐体と強大な火力を有する。この種の巨大な機械の弱点は往々にして外見からでは分からない…",
  str_item_intro_6000621 = "記念メダル。\n最後の防衛線を守る砲塔。襲来した敵をすべて消し去る。",
  str_item_intro_6001512 = "記念メダル。\n誰もが渇望してやまないものこそ、誰もが背負えるものではない。",
  str_item_intro_6001515 = "記念メダル。\n未知のリスクが残る機械は、運行時間を考証できず、いつも夜が更けて静まりかえった時にツーツーと気味の悪い音を立てている。",
  str_item_intro_6001516 = "記念メダル。\n光霊と祟霊はどこが違うのだろうか？どちらも春新節の花火の下で甘い飴細工を味わい、このめでたい祭りを共に祝う",
  str_item_intro_6001517 = "記念メダル。\nアルゴル自ら開発したハイテクリストバンド。心拍数、血圧、血中酸素飽和度などの健康データをリアルタイムでモニタリングし、着用者の運動データに基づいてフィットネス計画を立てられる。",
  str_item_intro_6001520 = "記念メダル。「守護」とは非常に重みのある言葉だ。だが彼らは自らを信じ、荒れ狂う雪の中に留まる。",
  str_item_intro_6001521 = "記念メダル。犠牲は決して栄誉のためなどではない。「あなたたちは英雄だ。でも決して、ただの英雄というだけではない」",
  str_item_intro_6001524 = "記念メダル\n「ホントに面白い！2周目行っくよ～！」",
  str_item_intro_6001525 = "記念メダル。\n頭の中でヒラメいた瞬間が、記録の中で記念すべき時となった。",
  str_item_intro_6001526 = "記念メダル\n「この力は、自分だけのものではない」",
  str_item_intro_6001529 = "記念メダル\n「久しぶりね、私の契約者。今回の旅は危険だけど、真理へと続いているわ」",
  str_item_intro_6001530 = "記念メダル。王子の冒険は、帰還かなうことなく終わりを迎えたが、民のために道を切り開いた。彼らの心はいつでも一つだ。子孫たちはいつの日かきっとこの大陸で再会するだろう。",
  str_item_intro_6001531 = "記念メダル。\n愛とはこの世の美しき夢である、彼女はそう聞いた。",
  str_item_intro_6001532 = "記念メダル。\n苦難に満ちた旅だったが、その結末はただ他人の再会の喜びを目の当たりにしただけだった。\nしかし、星を助けるために必死で努力したあなたに、深い感謝をおくらずにいられるわけがない。",
  str_item_6100001 = "記念パネル",
  str_item_6100002 = "戦いの記念パネル",
  str_item_6100003 = "岩の記念パネル",
  str_item_6100004 = "機械の記念パネル",
  str_item_intro_6100001 = "記念パネル。天空ノ庭に設置できる。記念メダルを飾っておこう",
  str_item_intro_6100002 = "記念パネル。このパネルに描かれているのは戦いをテーマにしたものだが、ほかのメダルを貼りつけてみてもなかなかいいだろう",
  str_item_intro_6100003 = "記念パネル。黒い岩石の山が荒野の息吹を感じさせるが、いったい誰が運んできたのだろう？それはともかく、このパネルの表面の細かい凹凸はメダルを貼り付けるのにちょうどよい",
  str_item_intro_6100004 = "記念パネル。描かれているのは…なにやら巨大な機械の中のようだ。工場の作業場のような背景に、思わずメダルをきれいに並べたくなってしまう。だが、自由に並べても構わない。入り乱れた感じもまた、いい味を出すかもしれない",
  str_item_6400001 = "称号・先手必勝",
