  str_item_9994015 = "体を縛する者",
  str_item_9994016 = "光輝ランス",
  str_item_9994017 = "光輝大剣",
  str_item_9994018 = "光輝の盾",
  str_item_9994019 = "銀月の長弓",
  str_item_9994020 = "銀月の猟刀",
  str_item_9994021 = "銀月の盾",
  str_item_9994022 = "ラッキーコイン",
  str_item_9994023 = "「烈陽」浮遊器",
  str_item_9994024 = "「氷原」浮遊器",
  str_item_9994025 = "「葉植」浮遊器",
  str_item_9994026 = "「雷霆」浮遊器",
  str_item_9995001 = "秘境の心",
  str_item_9995002 = "祝福のアーマー",
  str_item_9995003 = "光力の盾",
  str_item_9995004 = "裂解水晶",
  str_item_9995005 = "貫通の剣",
  str_item_9995006 = "万色の宝石",
  str_item_9995007 = "移動エネルギー器",
  str_item_9995008 = "雷撃者",
  str_item_9995009 = "爆裂ブーツ",
  str_item_9995010 = "散りゆく櫻",
  str_item_9995011 = "寂滅の女神像",
  str_item_9995012 = "ホログラムレンズ",
  str_item_9995013 = "運命のサイコロボックス",
  str_item_9995014 = "双生蘭",
  str_item_9995015 = "黎明の皿",
  str_item_9995016 = "呪いの手",
  str_item_9995017 = "死の手紙",
  str_item_9995018 = "輝光眼鏡",
  str_item_4090334 = "追憶の雪桜",
  str_item_intro_1400851 = "影ノ街に住む歴史の記録者。何事にも常に中立を保つ。肌身放さず持ち歩いているケースには大量の記録が保存されており、影ノ街の「情報屋」として名高い。",
  str_item_intro_3000220 = "行動ポイント：イベント内特定ステージに挑戦する際必要なポイント。時間とともに回復する",
  str_item_intro_3000221 = "ヤドリギの実は希少な木の実。北境の人々はこれを希望と豊饒の象徴と捉えている。スノーシダーの森の市場でプレゼントと交換できる",
  str_item_intro_3000001 = "特殊な技術で作られた光源の媒体。各種探索を行う際の必須物資である",
  str_item_intro_3000002 = "白夜城が発行しているコイン。純度が高く、種類も豊富で、大陸では最も広く認められている流通貨幣である",
  str_item_intro_3000003 = "クリスタルを磨き得られる宝石。\n光霊の召集、特別召集星標や召集星標の獲得、プリズムの購入に使える。",
  str_item_intro_3000004 = "各種対戦を指揮することで獲得できる経験値。レベルが高いほど巨像への感知が緊密になり、巨像に関する情報をさらに得ることができる",
  str_item_intro_3000005 = "蛍灯は自動修復機能を持っており、修復速度は光力貯蔵室の性能による。また溶錬室で巨像の基本材料を溶錬して増やすこともできる。蛍灯は巨像を操る者の命令で動作するマイクロ構造体であり、巨像の修理や日常的なメンテナンスなどの作業を担っている",
  str_item_intro_3000006 = "「光力測定器」に表示される数値。0になると極めて危険なため、ただちに離れる必要がある",
  str_item_intro_3000007 = "秘境で発見された古文書の欠片。その価値を認め、買い集めている機関があるという",
  str_item_intro_3000008 = "デイリー任務を完遂すると与えられる報酬ポイント。一定数値まで溜まると追加報酬が得られる",
  str_item_intro_3000009 = "功績の証",
  str_item_intro_3000010 = "光霊との関係がより親密になる",
  str_item_intro_3000011 = "聖物サイコロ",
  str_item_intro_3000012 = "資源携行室で発見した特殊な構造体。探索者のためにさまざまな物資を集めてくれる。\n【連続掃討時に使用すると、その回の挑戦クリアに必要なプリズムを消費することで、ただちに報酬を獲得できる】",
  str_item_intro_3000013 = "巨像の溶錬室で製造された特殊な生成物。大昔の科学技術を応用しているらしい。一部のアイテムの基本的性質を変え、新たなアイテムに生まれ変わらせることができる",
  str_item_intro_3000014 = "光力を含んだ天然の水晶。\nクリスタルを使うと、商店でギフトパックや光霊のコーデを購入できる。クリスタルを光珀に交換し、光霊の召集やプリズムの回復に使うこともできる。",
  str_item_intro_3000015 = "心珀と共に発見された透明な宝石。炎のような色がとても鮮やか。スターダイヤショップでレアアイテムと交換できる",
  str_item_intro_3000016 = "レアなダイヤ。非常に高価。スターダイヤの中でも特に貴重。シャインショップで一番人気",
  str_item_intro_3000017 = "巨像の活動に欠かせない物質。光力貯蔵室に蓄えられ、エネルギー源となる",
  str_item_intro_3000018 = "天空ノ庭の各地で発見される石片。遺物と思われるが、具体的な機能は不明。キューブたちの好物らしく、何かしらのアイテムと交換してくれる",
  str_item_intro_3000019 = "とてもレアなスターダイヤ。手を出せる人がほとんどいないほど高価で貴重。専門のミラクルショップでしか取引できない",
  str_item_intro_3000021 = "「ソラヴァン」のブリッジとシミュレーターが連携することで作成されるデータ保存チップ。ナビゲーターが自身の記憶をこの中に入力することで、巨像のクラウドストレージからホログラムを作成することができるようになる。",
  str_item_intro_3000022 = "貴重な木材。珍しい植物から生まれると言われており、現在では滅多にお目にかかれない。その希少性と自然な丸みから上流社会の人々に人気がある。影ノ街では専門の商会が買い取りを行っており、狭い範囲内で等価物として取引されている",
  str_item_intro_3000025 = "「末極の物」の言葉が書かれているという。現在解読する術はなく、よって書かれていることは推測にすぎない。だが、完全に近い形で残っているため、真相を追求しようとする組織にとっては価値があり、購入された。",
  str_item_intro_3000026 = "「末極の物」の言葉が書かれているという。現在解読する術はなく、よって書かれていることは推測にすぎない。非常に細かい断片になってしまっているため、一定数を集めない限り、購入者の興味は引けないだろう。",
  str_item_intro_3000029 = "特別事件簿をすべて閲覧したエリートが獲得できる金のしおり。\n【事件簿商店】でアイテム報酬と交換できる。",
  str_item_intro_3000030 = "特別事件簿をすべて閲覧した人が獲得できるしおり。\n【事件簿商店】でアイテム報酬と交換できる。",
  str_item_intro_3000031 = "特別事件簿をすべて閲覧した人が獲得できるアイテム。\n【事件簿商店】でノーマルコーデと交換できる。",
  str_item_intro_3000032 = "特別事件簿をすべて閲覧した人が獲得できるアイテム。\n【事件簿商店】で巨像の家具と交換できる。",
  str_item_intro_3501001 = "装備の精錬レベルが上がる。\nこの不思議な物質はモノとその所有者との間に強いつながりを発生させる。しかし、一瞬で消失してしまうため、特別な容器に入れ、保管する必要がある",
  str_item_intro_3000100 = "召集信号を発信する装置。\n通常ノーマル召集で光霊を獲得できる。",
  str_item_intro_3000101 = "特別召集信号を発信する装置。\n期間限定召集で光霊を獲得できる。",
  str_item_intro_3000110 = "ハロウィン特典召集専用アイテム。本特典召集で10回召集を行える。\n本アイテムは期間限定アイテムで、【ハロウィン特典召集】終了後3000光珀に変換される",
  str_item_intro_3000112 = "クリスマス特典召集専用アイテム。本特典召集で10回召集を行える。\n本アイテムは期間限定アイテムで、【クリスマス特典召集】終了後3000光珀に変換される",
  str_item_intro_3000113 = "コラボ限定召集専用のアイテムで、コラボ限定召集で10回の召集ができます。\n本アイテムは期間限定アイテムです。(UTC 9)2022年1月26日18:00までにお使いください。期限を過ぎるとアイテムは消失し、他のコンテンツに変換されることはありません。",
  str_item_intro_3000114 = "コラボ限定召集専用のアイテムで、コラボ限定召集で10回の召集ができます。\n本アイテムは期間限定アイテムです。(UTC 9)2022年2月12日18:00までにお使いください。期限を過ぎるとアイテムは消失し、他のコンテンツに変換されることはありません。",
  str_item_intro_3000343 = "コラボ限定召集専用のアイテム。コラボ限定召集で10回の召集ができる。\n※本アイテムは期間限定アイテムです。2023年11月7日18:00までにご利用ください。期限を過ぎるとアイテムは消失し、他のコンテンツに変換されることはありません。",
  str_item_intro_3000115 = "カーニバル特別召集専用アイテム。本特典召集で10回召集を行える。\n本アイテムは期間限定で有効。【カーニバル特別召集】期間終了後3000光珀に変換される",
  str_item_intro_3000116 = "【啓明の光】限定召集で1回召集できる\nこのアイテムは期間限定アイテムです。【啓明の光】限定召集が終了するまでにお使いください。期限を過ぎると、他のアイテムに変換されることなく消失します",
  str_item_intro_3000117 = "【啓明の光】限定召集で10回召集できる\nこのアイテムは期間限定アイテムです。【啓明の光】限定召集が終了するまでにお使いください。期限を過ぎると、他のアイテムに変換されることなく消失します",
  str_item_intro_3000141 = "【啓明の光】限定召集または【勇敢なる孤兵】オススメ召集で使用し、10回召集できる\nこのアイテムは期間限定アイテムです。【啓明の光】限定召集が終了するまでにお使いください。期限を過ぎると、他のアイテムに変換されることなく消失します",
  str_item_3000142 = "隙間特別召集星標",
  str_item_3000143 = "隙間10連召集霊",
  str_item_intro_3000142 = "【超常的出現】限定召集または【霧鎖の孤城】期間限定召集で使用し、1回召集できる\nこのアイテムは期間限定アイテムです。【超常的出現】限定召集が終了するまでにお使いください。期限を過ぎると、他のアイテムに変換されることなく消失します",
  str_item_intro_3000143 = "【超常的出現】限定召集または【霧鎖の孤城】期間限定召集で使用し、10回召集できる\nこのアイテムは期間限定アイテムです。【超常的出現】限定召集が終了するまでにお使いください。期限を過ぎると、他のアイテムに変換されることなく消失します",
  str_item_3000145 = "錬金術士10連召集霊",
  str_item_intro_3000145 = "コラボ限定召集【錬金術士】または【商才の旋律】で10回召集できる\nこのアイテムは期間限定アイテムです。上記の召集が終了するまでにお使いください。期限を過ぎると、他のアイテムに変換されることなく消失します",
  str_item_intro_3000118 = "コラボ限定召集専用のアイテム。コラボ限定召集で10回の召集ができる。\n※本アイテムは期間限定アイテムです。2022年8月3日18:00までにご利用ください。期限を過ぎるとアイテムは消失し、他のコンテンツに変換されることはありません。",
  str_item_intro_3000119 = "【北境の女王】限定召集で1回召集できる\nこのアイテムは期間限定アイテムです。【北境の女王】限定召集が終了するまでにお使いください。期限を過ぎると、他のアイテムに変換されることなく消失します",
  str_item_intro_3000120 = "【北境の女王】限定召集で10回召集できる\nこのアイテムは期間限定アイテムです。【北境の女王】限定召集が終了するまでにお使いください。期限を過ぎると、他のアイテムに変換されることなく消失します",
  str_item_intro_3000121 = "【夏風特別召集】で消費し、10回召集を行える。\n期間限定アイテム。【夏風特別召集】終了後は3000光珀に変換される",
  str_item_3000146 = "雪に立ち向かう鷹10連特別召集霊",
  str_item_intro_3000146 = "【雪に立ち向かう鷹特別召集】で消費し、10回召集を行える。\n期間限定アイテム。【雪に立ち向かう鷹特別召集】終了後は3000光珀に変換される",
  str_item_intro_3000122 = "【初冬特別召集】で消費し、10回召集を行える。\n期間限定アイテム。【初冬特別召集】終了後は3000光珀に変換される",
  str_item_intro_3000123 = "【北境の女王】限定召集で1回召集できる\nこのアイテムは期間限定アイテムです。【北境の女王】限定召集が終了するまでにお使いください。期限を過ぎると、他のアイテムに変換されることなく消失します",
  str_item_intro_3000124 = "これはただの記念アルバムではない、なんとゴルディのサイン付きだ！このアルバムを持っていれば、ゴルディとの間に不思議なつながりが生まれるだろう。\n【強運の天星】限定召集で1回召集できる\nこのアイテムは期間限定アイテムです。【強運の天星】限定召集が終了するまでにお使いください。期限を過ぎると、他のアイテムに変換されることなく消失します",
  str_item_intro_3000125 = "【春新節特別召集】で消費し、10回召集を行える。\n期間限定アイテム。【春新節特別召集】終了後は3000光珀に変換される",
  str_item_intro_3000126 = "【パトロール特典召集】で消費し、10回召集を行える。\n期間限定アイテム。【パトロール特典召集】終了後は3000光珀に変換される",
  str_item_intro_3000127 = "【昔日の残影】限定召集で1回召集できる\nこのアイテムは期間限定アイテムです。【昔日の残影】限定召集が終了するまでにお使いください。期限を過ぎると、他のアイテムに変換されることなく消失します",
  str_item_intro_3000128 = "【昔日の残影】限定召集で10回召集できる\nこのアイテムは期間限定アイテムです。【昔日の残影】限定召集が終了するまでにお使いください。期限を過ぎると、他のアイテムに変換されることなく消失します",
  str_item_intro_3000129 = "期間限定【遊園地特別召集】で消費し、10回召集を行える。\n期間限定アイテム。【遊園地特別召集】終了後は3000光珀に変換される",
  str_item_intro_3000133 = "期間限定【暖冬賛歌特別召集】で消費し、10回召集を行える。\n期間限定アイテム。【暖冬賛歌特別召集】終了後は3000光珀に変換される",
  str_item_intro_3000138 = "【カーニバル特別召集】で消費し、10回召集を行える。\n期間限定アイテム。【カーニバル特別召集】終了後は3000光珀に変換される",
  str_item_intro_3000201 = "R・Wのメンバーの何人かが作った小さなバッジ。ナットを改造したもので、彼らにとって「砂漠に認められし者」を意味する。そのため、このバッジはR・Wに認められた者にしか与えられない",
  str_item_intro_3000211 = "フルート・プラチナのフロントで特別ギフトと交換できる抽選券。押されているスタンプはホテル支配人の肖像らしい。",
  str_item_intro_3000212 = "特別事件簿の任務をクリアすると、影ノ街の貢献ポイントを一定数獲得し、対応する報酬を解放するのに使用できる。影ノ街は夢や望みを持つ冒険者を粗末に扱わない。",
  str_item_intro_3000213 = "行動ポイント：イベント内の特定ステージに挑戦するのに必要な行動ポイント。時間が経つと回復する。",
  str_item_intro_3000214 = "クーリエ隊専用の食べ物。仕事で消費した体力を補える。味は謎だが、いつか味見してもいいかもしれない",
  str_item_intro_3000215 = "再建進行度（詳細情報なし）",
  str_item_intro_3000217 = "軍功値：軍人の戦績を具体的に表すもの。啓光連邦に対する貢献の程度を示す",
  str_item_intro_3000219 = "汗にまみれ、痛みに耐え、己の拳で勝ち取った地下闘技場での名声。あなたの名が影ノ街にとどろく",
  str_item_intro_3000202 = "イベントアイテム。だるま割りの抽選に使用できる。一定数累積すると、ヒイロの専用ストーリーを解放できる。\n雲山の特産の一つ。雲桜の散った花びら。幸運をもたらすと雲山の住民に信じられている。",
  str_item_intro_3000224 = "イベント「白夜長明」のアイテム。累計で一定数量集めると雲上の声望より報酬を受け取り可能",
  str_item_intro_3000225 = "「メイドラゴンの休日」のイベントアイテム。【トールのキッチン】で抽選ができる。\nアツアツ料理、もうすぐ出来上がり！急いで食器を用意して、食事にしましょう！",
  str_item_intro_3000226 = "アストラ大陸では珍しい飲み物。飲むと頭がすっきりし、元気になれる。",
  str_item_intro_3000227 = "現代の貨幣とはかけ離れたもの。いかにも古めかしい。",
  str_item_intro_3000229 = "探検家、冒険家の栄誉の象徴。通常、卓越した努力の積み重ねや、危険極まりない難所を乗り越えてようやく獲得できる。",
  str_item_intro_3000236 = "挑戦をクリアすると獲得できるポイント。難易度の違いに応じて、獲得できるポイント数も変わってくる。",
  str_item_intro_3000238 = "祭りの季節になると、雲島の人々はこの紙に祈りの言葉を書き、1年の幸福を願うという。",
  str_item_intro_3000239 = "極東地域の人々が好む携帯食料。見た目が可愛らしく、持ち運びにも便利。中には具も入っている。",
  str_item_intro_3000240 = "「軽紗の夢境」願いの鏡専用アイテム。「軽紗の夢境」願いの鏡で願い事をすることができる\n（本アイテムは期間限定アイテムです。【「軽紗の夢境」願いの鏡】終了後、光珀×100に変換されます。）",
  str_item_intro_3000241 = "銀含有量の高い銀貨。雲島の主な流通貨幣。",
  str_item_intro_3000242 = "出場選手のタイムを記録したカード。レーサーが各チェックポイントで係員の署名を受ける",
  str_item_intro_3000244 = "奥底にいる者が自由に動けるようになり、束縛から抜け出すことも可能にするという不思議な力をもつ",
  str_item_intro_3000245 = "魂の欠片の異空間における「生成物」。一部の者にとっては、非常に興味をそそられるという",
  str_item_intro_3000246 = "収集したデータを量化および総合測定して得られる情報。これにもとづいて範囲を定め、探索活動を行える",
  str_item_intro_3000247 = "携帯探索機が検出した一般信号",
  str_item_intro_3000248 = "携帯探索機が検出した特殊信号",
  str_item_intro_3000253 = "強大な勢力を誇るアンデルセン商会が発行する手形。価値を認める人なら、何か別のものと交換できるかもしれない。",
  str_item_intro_3000256 = "盗賊団のアジト攻略のために必要なポイント。潜入中に遭遇した敵を倒し、先へ進もう。",
  str_item_intro_3000258 = "さまざまな情報や興味深い見聞、秘話を記したメモ。出来事の全貌を知りたければ、メモを手がかりに自ら調査に乗り出そう。",
  str_item_intro_3000259 = "祭りの開催時、ハーバーシティで市民に配布される特別なコイン。ストリートフェアで金券として使用できる",
  str_item_intro_3000266 = "水族館が新しくオープン！設備も飼育している水生生物もトップクラス。おまけに空いてる！今すぐ見に行こう。お見逃しなく！！\nアクアリウムツアー限定アイテム。アクアリウムツアーの祈りに使用できる。期間限定アイテム。アクアリウムツアーの期間終了後は光珀×100に変換される",
  str_item_intro_3000267 = "携帯探索機が検出した一般信号",
  str_item_intro_3000268 = "携帯探索機が検出した特殊信号",
  str_item_intro_3000270 = "あるマジシャンが言うには、これは一見ごく普通のカードだが、不思議な力が秘められており、さまざまなものに姿を変えられるという…\nイベント期間中、プリズムを消費してステージをクリアすると獲得できる。",
  str_item_intro_3000271 = "回収された空の薬莢（やっきょう）。物資集積所で物資交換に使える。\nイベント期間中、プリズムを消費してステージをクリアすると獲得できる。",
  str_item_intro_3000275 = "このチケットがあれば、「有名な俳優」の映画を鑑賞して、直接取材できるチャンスもあるらしい…。\n「スポットライトの下で」の抽選に使う専用アイテム。期間限定アイテムであり、「スポットライトの下で」終了後は光珀×100に変換される",
  str_item_intro_3000276 = "お化け屋敷の雰囲気を盛り上げるためにニナがデザインしたコイン。記念品と交換できる",
  str_item_intro_3000278 = "あちこちに散らばる部品。なにかの役に立つかもしれない！\nイベント期間中、プリズムを消費してステージをクリアすると獲得できる。",
  str_item_intro_3000280 = "復刻「軽紗の夢境」願いの鏡専用アイテム。復刻「軽紗の夢境」願いの鏡で願い事をすることができる\n（本アイテムは期間限定アイテムです。【復刻「軽紗の夢境」願いの鏡】終了後、光珀×100に変換されます）",
  str_item_intro_3000281 = "ある天才映画監督が撮ったといわれる作品。その監督は自分の撮ったホラー映画の試写中に笑い過ぎで亡くなったというウワサだ。",
  str_item_intro_3000282 = "ファンタジー系アドベンチャーの脚本。幻想的で想像力にあふれていると思いきや、よくある筋書きで味気ない感じもするストーリーである。",
  str_item_intro_3000283 = "実話に基づき書かれたという脚本。だが、主人公のモデルとなった人物が実際どのような最後を迎えたのかを知る者はなく、結末は芸術的な脚色を加え創作された。",
  str_item_intro_3000284 = "ジョムが無理やり渡してきた脚本。ジョムが言うには、事が成功した暁には、高額の報酬をくれるという。",
  str_item_intro_3000285 = "リリカから渡された脚本。リリカは自分には監督の才能があると思っているらしく、広告撮影の仕事をあなたに任せようとしている。",
  str_item_intro_3000286 = "ビビアンから渡された脚本。啓光で兵士を募集する際、新しい試みをしてみたいという。",
  str_item_intro_3000288 = "ベツレヘムがあなたと一緒に創作したときに記したメモ。二人の交錯する思いが秘められている。\n「メロディにつつまれて」専用アイテム。「メロディにつつまれて」で願い事をすることができる。期間限定アイテムであり、「メロディにつつまれて」終了後は光珀×100に変換される",
  str_item_intro_3000291 = "旅の途中で見つけた記録。これがあれば、帰ったあとも大切なことを思い出せるだろう。",
  str_item_intro_3000292 = "大陸一の人気を誇るアイドルのグッズ。これは見逃せない！熱烈なファンは間違いなく集めるだろうが、ひと儲けしようと買う者もいるだろう…",
  str_item_intro_3000293 = "北境では、冬の祝日の夜に靴下を枕元に掛ける風習がある。ほしいものを書いたメモを中に入れておくと、次の日、靴下の中にほしいものが入っているという。いったい誰が入れたのかは、秘密である",
  str_item_intro_3000294 = "このまっさらなカードには何やら「魔法の力」があるらしい。願い事を書いておくとかなうというのだが、もちろん確かな話でない。だが、こうした縁起のいいプレゼントは誰にでも喜ばれるだろう",
  str_item_intro_3000297 = "匿名の人物から得た脚本。一見、スリルとロマンあふれる物語のようだが、どこかで聞いたことのある話に思えてならない…",
  str_item_intro_3000298 = "ちまたに伝わる物語を脚本化したもの。あちこちに潜む危機、この世のありとあらゆる危険が迫る",
  str_item_intro_3000299 = "雲島で今、最も人気を集めている小説の一つ。謎の人物により海をはるばる越えてこの地にもたらされた。どうやら、刀剣の戦いと末世をテーマにした物語のようだ…",
  str_item_intro_3000300 = "リン家商会の手形。荷あげ場で額面相当のアイテムと交換できる",
  str_item_intro_3000307 = "石膏の奇妙な破片。像から落下したようだが、何らかの手がかりがあるかも…",
  str_item_intro_3000311 = "このグラスで誰かとお酒を飲むと、いつまでも酔わずにいられるという。\n「魅惑の夜」専用アイテム。「魅惑の夜」で願い事をすることができる。期間限定アイテムであり、「魅惑の夜」終了後は光珀×100に変換される",
  str_item_intro_3000313 = "啓光物資センターで流通している貨幣。物資の輸送や分配の際の唯一の証明として使う。",
  str_item_intro_3000321 = "不思議な水晶の破片。中にはさらに不思議な水滴が入っている…\n用途：【占いの間】で好きなアイテムを購入できる\n獲得方法：プリズムを消費するメインストーリーまたは資源ステージをクリア",
  str_item_intro_3000326 = "精巧な作りのコインだが、どこか危険な香りが漂う…だが、Ms.ロトがこのコインは物と交換できるというのだ。おそらく問題はないだろう…\n獲得方法：Ms.ロトの依頼任務をクリアする",
  str_item_intro_3000330 = "イバラの巻きついたつぼみが見事花を咲かせるかは、すべて自分次第、人々が思っているほど容易ではない。\nイベント「ファイアソーンの祈り」の専用アイテム、「ファイアソーンの祈り」で願い事をすることができる。本アイテムは期間限定アイテムです。「ファイアソーンの祈り」終了後、光珀×100に変換されます",
  str_item_intro_3000332 = "やるべきことが山積みだが、暗鬼の妨害も防ぎつつ、前方の動向も偵察しなければならない…そのため、ラス・傲骨は乏しい人的資源を合理的に管理、手配して、トワイライトシティの再建工事の一部を完了させなければならない。",
  str_item_intro_3000334 = "ラスの作戦に対するバートンの承認率",
  str_item_intro_3000335 = "ラスの作戦に対するヒイロの承認率",
  str_item_intro_3000336 = "ラスの作戦に対するビビアンの承認率",
  str_item_intro_3000337 = "ラスの作戦に対するキシローナの承認率",
  str_item_intro_3000353 = "心で思えば、願いは叶う",
  str_item_intro_3000354 = "願いのまゆを一定数ためると、交換センターでギフトと交換できます",
  str_item_intro_3000356 = "済の国の人々が好んで使う香。外観にも凝っており、上品な香りが特徴的。\n「火を焚き、白煙を捧げ、天地を祭る――かような文化があることはわらわも知っておるが、毎年必ず幾日か、目も開けられぬほど煙たい日があるのじゃ…」",
  str_item_intro_3000361 = "バグで乱れた映像データは、集めて整理するだけでもひと苦労。\n一定量消費すると、新しい映像を解放してステージを修復できる",
  str_item_intro_3000366 = "特定の光霊と契約を結ぶのに必須となるアイテム",
  str_item_intro_3000367 = "影ノ街製のロリポップ。ランダムで味が代わり、サプライズが楽しめる。物資の乏しい砂漠では通貨並みの価値がある。",
  str_item_intro_3000368 = "勤勉なナビゲーターのために用意された補給箱。\nすべての努力と成長が記録され、報酬という具体的な形となって返ってくる。",
  str_item_intro_3000374 = "レトロなデザインでゴツゴツしたゲームコイン。最強のプレイヤーは1コインで一晩中遊べるという。",
  str_item_intro_3000376 = "カナン城で日用品物資と交換できるチケット。啓光に特殊な貢献をした人は、チケットを使って申し込み、好みのアイテムをカスタマイズできる。",
  str_item_intro_3000377 = "聖者の血は無駄に流れることなく、琥珀のように永遠に存在するらしい。それを真理に捧げることは、主に敬虔さを捧げることと同じなのだ。",
  str_item_intro_3000381 = "夢から覚めたとき、まるで美しい夢は二度と見られないかのように、露は葉々の間で凝固し、瞬く間に消え去った。夢の中のミズチに捧げれば、何か見返りがあるかもしれない。",
  str_item_intro_3000383 = "天空ノ谷の色紙は、柔らかくて丈夫で、窓の周りの装飾にも、色とりどりの人形を作るのにも適している。ウィンデリオンの色紙は、過去への思いだけでなく、未来に進む自信も託している",
  str_item_intro_3100001 = "光霊のレベルを上げる。森属性光霊の効果+50%\n緑の蛍玉。これを使って瞑想することで、戦闘の記憶が一部戻り、経験値を少し獲得できる",
  str_item_intro_3100002 = "光霊のレベルを上げる。森属性光霊の効果+50%\n少し高価な緑の蛍玉。これを使うと戦闘の記憶がたくさん蘇り、多くの経験値を獲得できる",
  str_item_intro_3100003 = "光霊のレベルを上げる。森属性光霊の効果+50%\nとても高価な緑の蛍玉。過去の戦闘をリアルに追体験でき、大量の経験値を獲得できる",
  str_item_intro_3100004 = "光霊のレベルを上げる。水属性光霊の効果+50%\n青の蛍玉。これを使って瞑想することで、戦闘の記憶が一部戻り、経験値を少し獲得できる",
  str_item_intro_3100005 = "光霊のレベルを上げる。水属性光霊の効果+50%\n少し高価な青の蛍玉。これを使うと戦闘の記憶がたくさん蘇り、多くの経験値を獲得できる",
  str_item_intro_3100006 = "光霊のレベルを上げる。水属性光霊の効果+50%\nとても高価な青の蛍玉。過去の戦闘をリアルに追体験でき、大量の経験値を獲得できる",
  str_item_intro_3100007 = "光霊のレベルを上げる。雷属性光霊の効果+50%\n黄色い蛍玉。これを使って瞑想することで、戦闘の記憶が一部戻り、経験値を少し獲得できる",
  str_item_intro_3100008 = "光霊のレベルを上げる。雷属性光霊の効果+50%\n少し高価な黄色い蛍玉。これを使うと戦闘の記憶がたくさん蘇り、多くの経験値を獲得できる",
  str_item_intro_3100009 = "光霊のレベルを上げる。雷属性光霊の効果+50%\nとても高価な黄色い蛍玉。過去の戦闘をリアルに追体験でき、大量の経験値を獲得できる",
  str_item_intro_3100010 = "光霊のレベルを上げる。火属性光霊の効果+50%\n赤い蛍玉。これを使って瞑想することで、戦闘の記憶が一部戻り、経験値を少し獲得できる",
  str_item_intro_3100011 = "光霊のレベルを上げる。火属性光霊の効果+50%\n少し高価な赤い蛍玉。これを使うと戦闘の記憶がたくさん蘇り、多くの経験値を獲得できる",
  str_item_intro_3100012 = "光霊のレベルを上げる。火属性光霊の効果+50%\nとても高価な赤い蛍玉。過去の戦闘をリアルに追体験でき、大量の経験値を獲得できる",
  str_item_intro_3100013 = "光霊のレベルを上げることができる\n灰色の蛍玉。少し特別なエネルギーを秘めており、どんな光霊でも、これで経験値を少し獲得できる",
  str_item_intro_3100014 = "光霊のレベルを上げることができる\n少し高価な灰色の蛍玉。どんな光霊でも、これを使って戦闘時の感覚を思い返すことで、経験値をいくらか獲得できる",
  str_item_intro_3100015 = "光霊のレベルを上げることができる\nとても高価な灰色の蛍玉。どんな光霊でも、これで過去の戦闘を追体験し、多くの経験値を獲得できる",
  str_item_intro_3210101 = "初級覚醒材料。白夜城の光霊の覚醒に使う\n白夜城黎明学院で保管されているアイテム。独特な魔法構造でエネルギーが増幅されており、光霊の力を高めることができる",
  str_item_intro_3210201 = "初級覚醒材料。影ノ街の光霊の覚醒に使う\n影ノ街で流行っている強いお酒。口当たりが良く、飲んだ者の力を上昇させる",
  str_item_intro_3210301 = "初級覚醒材料。北境の光霊の覚醒に使う\n松の木の朝露、北境の特殊な環境の影響を受けているため、北境の者に強大な力をもたらすことができる",
  str_item_intro_3210401 = "初級覚醒材料。R・Wの光霊の覚醒に使う\n特別なレディーゼルオイル。強烈な刺激臭を放っており、これに手を出せるのは強靭なR・Wのメンバーぐらいだろう",
  str_item_intro_3210501 = "初級覚醒材料。啓光連邦の光霊の覚醒に使う\n啓光連邦の戦闘記録。読んだ者の戦闘能力を上昇させる",
  str_item_intro_3210601 = "初級覚醒材料。真理結社の光霊の覚醒に使う\n古の知識を記した断片。真理結社メンバーは、これを読むことで自身の能力を効果的に上げることができる",
  str_item_intro_3210701 = "初級覚醒材料。無勢力者の光霊の覚醒に使う\n様々な人種の見聞が乱雑に記されている。無勢力者が読むと様々なサバイバルスキルを獲得できる",
  str_item_intro_3210801 = "初級覚醒材料。龍州の光霊の覚醒に使う\n龍州の薬屋で作られた品質のよい丹薬で、体力増強のほか、骨や筋肉も丈夫にしてくれる。",
  str_item_intro_3210102 = "中級覚醒材料。白夜城の光霊の覚醒に使う\n白夜城黎明学院で保管されているアイテム。朝日のエネルギーを抽出して作られたらしい。光霊の力を高めることができる",
  str_item_intro_3210202 = "中級覚醒材料。影ノ街の光霊の覚醒に使う\n運命のシャンパンの一級品。口当たりが抜群に良くなり、飲んだ者の力を大幅に上げることができる",
  str_item_intro_3210302 = "中級覚醒材料。北境の光霊の覚醒に使う\n松の木についた朝露の霜。なかなかお目にかかれない。北境の人たちが体内に秘めた魔力の重要な源の一つだ",
  str_item_intro_3210402 = "中級覚醒材料。R・Wの光霊の覚醒に使う\nR・W砂漠の奥深くでしか見つからないレディーゼルオイルのエッセンス。R・Wメンバーの戦闘力を上昇させることができる",
  str_item_intro_3210502 = "中級覚醒材料。啓光連邦の光霊の覚醒に使う\n啓光連邦が大量のデータを集めて作った戦闘記録。読んだ者の戦闘能力を大幅に上げることができる",
  str_item_intro_3210602 = "中級覚醒材料。真理結社の光霊の覚醒に使う\n古の知識が大量に記録された巻物。これを解読することで真理結社メンバーの力を絶大に上げることができる",
  str_item_intro_3210702 = "中級覚醒材料。無勢力者の光霊の覚醒に使う\n様々な人種のサバイバル知識が記されている。これを読んだ無勢力者はきっと得る物がたくさんあるだろう",
  str_item_intro_3210802 = "中級覚醒材料。龍州の光霊の覚醒に使う\n龍州の修行者が作った丹薬。霊気を豊富に含む様々な材料を使っており、身体を健康にし、心を浄める効果があるという。",
  str_item_intro_3210103 = "上級覚醒材料。白夜城の光霊の覚醒に使う\n白夜城黎明学院で保管されているアイテム。独特な魔法でエネルギーが増幅されており、光霊の力をワンランク上げることができる",
  str_item_intro_3210203 = "上級覚醒材料。影ノ街の光霊の覚醒に使う\n運命のシャンパンのなかでも極めて珍しい一品。力を絶大に増幅することができる。口当たりも絶品",
  str_item_intro_3210303 = "上級覚醒材料。北境の光霊の覚醒に使う\n別名「北境の涙」と呼ばれ、完璧な朝露だと言われている。北境の人々に強力な魔力を提供できる",
  str_item_intro_3210403 = "上級覚醒材料。R・Wの光霊の覚醒に使う\n最もピュアなレディーゼルオイル。この半流動体のオイルを扱えるのは、R・Wでも最も強いメンバーぐらいだろう",
  str_item_intro_3210503 = "上級覚醒材料。啓光連邦の光霊の覚醒に使う\n啓光連邦が途方もない量のデータを集めて作った戦闘記録。読んだ者の戦闘能力をワンランク上げることができる",
  str_item_intro_3210603 = "上級覚醒材料。真理結社の光霊の覚醒に使う\n古の知識が記された書籍。これを解読することで真理結社メンバーの力をとてつもなく上げることができる",
  str_item_intro_3210703 = "上級覚醒材料。無勢力者の光霊の覚醒に使う\n様々な人種の見聞や心得が豊富に記されている。これを読めば有用なサバイバル能力を手に入れられるだろう",
  str_item_intro_3210803 = "上級覚醒材料。龍州の光霊の覚醒に使う\n龍州の隠者が作った丹薬で、天と地の粋を集めて作られている。再生の力があり、服用すれば、壁を乗り越え、修行が大きく進展するという。",
  str_item_intro_3201011 = "初級覚醒材料。水属性光霊が覚醒する時に必要なアイテム\n水辺の土の中に含まれるこのフレアパウダーは、工業加工などで幅広く使われている材料の一つである",
  str_item_intro_3201012 = "初級覚醒材料。水属性光霊が覚醒する時に必要なアイテム\n神秘的な青い光を放つ珍しい水晶粒子",
  str_item_intro_3201013 = "初級覚醒材料。水属性光霊が覚醒する時に必要なアイテム\n特殊な光力術で調合された純白のマジックパウダー",
  str_item_intro_3201014 = "初級覚醒材料。水属性光霊が覚醒する時に必要なアイテム\n神秘的な物質の一つ。海水が固まってできた石で、気孔がたくさんあるためとても脆い",
  str_item_intro_3201021 = "初級覚醒材料。火属性光霊が覚醒する時に必要なアイテム\n熱帯地域でよく発見されるこのフレアパウダーは、工業加工などで幅広く使われている材料の一つである",
  str_item_intro_3201022 = "初級覚醒材料。火属性光霊が覚醒する時に必要なアイテム\n強烈な赤い光りを放つ珍しい水晶粒子",
  str_item_intro_3201023 = "初級覚醒材料。火属性光霊が覚醒する時に必要なアイテム\n特殊な光力術で調合された赤いマジックパウダー",
  str_item_intro_3201024 = "初級覚醒材料。火属性光霊が覚醒する時に必要なアイテム\n神秘的な物質の一つ。高温で砕いた石を燃やして生成する",
  str_item_intro_3201031 = "初級覚醒材料。森属性光霊が覚醒する時に必要なアイテム\n岩層の中に含まれるこのフレアパウダーは、工業加工などで幅広く使われている材料の一つである",
  str_item_intro_3201032 = "初級覚醒材料。森属性光霊が覚醒する時に必要なアイテム\n青緑色の珍しい水晶粒子",
  str_item_intro_3201033 = "初級覚醒材料。森属性光霊が覚醒する時に必要なアイテム\n特殊な光力術で調合された青緑色のマジックパウダー",
  str_item_intro_3201034 = "初級覚醒材料。森属性光霊が覚醒する時に必要なアイテム\n神秘的な物質の一つ。古の植物が分解、転化してできた物だと言われている",
  str_item_intro_3201041 = "初級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム\n電気をとても通しやすいフレアパウダー。工業での使い道は多いが、加工しないと使えない",
  str_item_intro_3201042 = "初級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム\nたまに金色の電光が走る珍しい水晶粒子",
  str_item_intro_3201043 = "初級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム\n特殊な光力術で調合された金色のマジックパウダー",
  str_item_intro_3201044 = "初級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム\n神秘的な物質の一つ。雷が落ちた場所で発見されることが多い。雷の力を秘めていると言われている",
  str_item_intro_3202011 = "中級覚醒材料。水属性光霊が覚醒する時に必要なアイテム\n水のフレアパウダーを加工抽出して得られる砂。工業品を生成する時の初期の半製品",
  str_item_intro_3202012 = "中級覚醒材料。水属性光霊が覚醒する時に必要なアイテム\n神秘的な青い光を放つ珍しい水晶の欠片",
  str_item_intro_3202013 = "中級覚醒材料。水属性光霊が覚醒する時に必要なアイテム\n水絢爛素と特定の溶液を調合してできた産物",
  str_item_intro_3202014 = "中級覚醒材料。水属性光霊が覚醒する時に必要なアイテム\n海水で錫鉱石を蒸留してできる半流動体物質",
  str_item_intro_3202021 = "中級覚醒材料。火属性光霊が覚醒する時に必要なアイテム\n火のフレアパウダーを加工抽出して得られる砂。工業品を生成する時の初期の半製品",
  str_item_intro_3202022 = "中級覚醒材料。火属性光霊が覚醒する時に必要なアイテム\n強烈な赤い光を放つ珍しい水晶の欠片",
  str_item_intro_3202023 = "中級覚醒材料。火属性光霊が覚醒する時に必要なアイテム\n火絢爛素と特定の溶液を調合してできた産物",
  str_item_intro_3202024 = "中級覚醒材料。火属性光霊が覚醒する時に必要なアイテム\n激しく燃やす方法で得られる一種の特殊な物質",
  str_item_intro_3202031 = "中級覚醒材料。森属性光霊が覚醒する時に必要なアイテム\n森のフレアパウダーを加工抽出して得られる砂。工業品を生成する時の初期の半製品",
  str_item_intro_3202032 = "中級覚醒材料。森属性光霊が覚醒する時に必要なアイテム\n青緑色の珍しい水晶の欠片",
  str_item_intro_3202033 = "中級覚醒材料。森属性光霊が覚醒する時に必要なアイテム\n森絢爛素と特定の溶液を調合してできた産物",
  str_item_intro_3202034 = "中級覚醒材料。森属性光霊が覚醒する時に必要なアイテム\n様々な植物の抽出液と錫石を混ぜ合わせて転化させた特殊な物質",
  str_item_intro_3202041 = "中級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム\n加工された雷のフレアパウダーを更に加工抽出して得られる砂。工業品を生成する時の初期の半製品",
  str_item_intro_3202042 = "中級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム\nたまに紫色の電光が走る珍しい水晶粒子",
  str_item_intro_3202043 = "中級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム\n雷絢爛素と特定の溶液を調合してできた産物",
  str_item_intro_3202044 = "中級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム\n岩を雷の力で砕いて得られる特殊な物質",
  str_item_intro_3203011 = "上級覚醒材料。水属性光霊が覚醒する時に必要なアイテム\n水のフレアサンドを複雑な工程で加工して得られる片岩。標準的な工業半製品",
  str_item_intro_3203012 = "上級覚醒材料。水属性光霊が覚醒する時に必要なアイテム\n珍しい青色の水晶。硬く透き通った貴重な宝石",
  str_item_intro_3203013 = "上級覚醒材料。水属性光霊が覚醒する時に必要なアイテム\n水ポーションで合成された貴重な薬剤",
  str_item_intro_3203014 = "上級覚醒材料。水属性光霊が覚醒する時に必要なアイテム\n複雑な魔法行程を介して海水から精製された鉛パウダー",
  str_item_intro_3203021 = "上級覚醒材料。火属性光霊が覚醒する時に必要なアイテム\n火のフレアサンドを複雑な工程で加工して得られる片岩。標準的な工業半製品",
  str_item_intro_3203022 = "上級覚醒材料。火属性光霊が覚醒する時に必要なアイテム\n珍しい赤色の水晶。真っ赤に燃え上がる色をした貴重な宝石",
  str_item_intro_3203023 = "上級覚醒材料。火属性光霊が覚醒する時に必要なアイテム\n火ポーションから特殊な方法で合成した貴重な薬剤",
  str_item_intro_3203024 = "上級覚醒材料。火属性光霊が覚醒する時に必要なアイテム\n鉱石を高温で燃やして得られる、穴がたくさん開いた鉛の塊",
  str_item_intro_3203031 = "上級覚醒材料。森属性光霊が覚醒する時に必要なアイテム\n森のフレアサンドを複雑な工程で加工して得られる片岩。標準的な工業半製品",
  str_item_intro_3203032 = "上級覚醒材料。森属性光霊が覚醒する時に必要なアイテム\n珍しい緑色の水晶。柔らかな質感をした貴重な宝石",
  str_item_intro_3203033 = "上級覚醒材料。森属性光霊が覚醒する時に必要なアイテム\n森ポーションで合成された貴重な薬剤",
  str_item_intro_3203034 = "上級覚醒材料。森属性光霊が覚醒する時に必要なアイテム\n大量の植物から抽出された珍しい緑色の鉛パウダー",
  str_item_intro_3203041 = "上級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム\n雷のフレアサンドを複雑な工程で加工して得られる片岩。標準的な工業半製品",
  str_item_intro_3203042 = "上級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム\n珍しい金色の水晶。豪華な光を放つ貴重な宝石",
  str_item_intro_3203043 = "上級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム\n雷ポーションを蒸留、ろ過してできた貴重な薬剤",
  str_item_intro_3203044 = "上級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム\n岩を雷で粉砕して得られる鉛パウダー",
  str_item_intro_3204011 = "特級覚醒材料。水属性光霊が覚醒する時に必要なアイテム\n水のフレアロックを加工し、他の物質と混ぜ合わせてできた金属の塊。とても高価な工業製品",
  str_item_intro_3204012 = "特級覚醒材料。水属性光霊が覚醒する時に必要なアイテム\n珍しい青色水晶が集まって形成されたもの",
  str_item_intro_3204013 = "特級覚醒材料。水属性光霊が覚醒する時に必要なアイテム\n濃縮された水ポーションⅡ。光霊の力を大幅に上昇させることができる",
  str_item_intro_3204014 = "特級覚醒材料。水属性光霊が覚醒する時に必要なアイテム\n謎の魔法行程により深海の水と水銀を混ぜ合わせてできた強力な魔法材料",
  str_item_intro_3204021 = "特級覚醒材料。火属性光霊が覚醒する時に必要なアイテム\n火のフレアロックを加工し、他の物質と混ぜ合わせてできた金属の塊。とても高価な工業製品",
  str_item_intro_3204022 = "特級覚醒材料。火属性光霊が覚醒する時に必要なアイテム\n珍しい赤色水晶が集まって形成されたもの",
  str_item_intro_3204023 = "特級覚醒材料。火属性光霊が覚醒する時に必要なアイテム\n濃縮された火ポーションⅡ。光霊の力を大幅に上昇させることができる",
  str_item_intro_3204024 = "特級覚醒材料。火属性光霊が覚醒する時に必要なアイテム\n火山の噴火口で燃やした水銀の塊を更に溶錬して精製された物。強力なエネルギーを秘めている",
  str_item_intro_3204031 = "特級覚醒材料。森属性光霊が覚醒する時に必要なアイテム\n森のフレアロックを加工し、他の物質と混ぜ合わせてできた金属の塊。とても高価な工業製品",
  str_item_intro_3204032 = "特級覚醒材料。森属性光霊が覚醒する時に必要なアイテム\n珍しい緑色水晶が集まって形成されたもの",
  str_item_intro_3204033 = "特級覚醒材料。森属性光霊が覚醒する時に必要なアイテム\n濃縮された森ポーションⅡ。光霊の力を大幅に上昇させることができる",
  str_item_intro_3204034 = "特級覚醒材料。森属性光霊が覚醒する時に必要なアイテム\n珍しい植物をすりつぶし、特殊な緑水銀と混ぜて固めた物。強力なエネルギーを秘めている",
  str_item_intro_3204041 = "特級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム\n雷のフレアロックを加工し、他の物質と混ぜ合わせてできた金属の塊。とても高価な工業製品",
  str_item_intro_3204042 = "特級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム\n珍しい金色水晶が集まって形成されたもの",
  str_item_intro_3204043 = "特級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム\n濃縮された雷ポーションⅡ。光霊の力を大幅に上昇させることができる",
  str_item_intro_3204044 = "特級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム\n特殊な水銀に雷を流し込んで作られる魔法材料。強力なエネルギーを秘めている（不安定なので取り扱い注意）",
  str_item_intro_3205011 = "上級覚醒材料。水属性光霊が覚醒する時に必要なアイテム。\n水のフレアインゴットを特殊な技術で加工し、他の材料と混ぜ合わせた精製鋼。とても高価な工業製品",
  str_item_intro_3205012 = "上級覚醒材料。水属性光霊が覚醒する時に必要なアイテム。\n大量の青水晶に光力を込めて作られた珍しいダイヤ",
  str_item_intro_3205013 = "上級覚醒材料。水属性光霊が覚醒する時に必要なアイテム。\n水ポーションⅢを更に精製してできた物。光霊の力を大幅に上昇させることができる",
  str_item_intro_3205014 = "上級覚醒材料。水属性光霊が覚醒する時に必要なアイテム。\n深海の水を錬成してできた硬い物質。見た目も美しく、とても高価",
  str_item_intro_3205021 = "上級覚醒材料。火属性光霊が覚醒する時に必要なアイテム。\n火のフレアインゴットを特殊な技術で加工し、他の材料と混ぜ合わせた精製鋼。とても高価な工業製品",
  str_item_intro_3205022 = "上級覚醒材料。火属性光霊が覚醒する時に必要なアイテム。\n大量の赤水晶に光力を込めて作られた珍しいダイヤ",
  str_item_intro_3205023 = "上級覚醒材料。火属性光霊が覚醒する時に必要なアイテム。。\n火ポーションⅢを更に精製してできた物。光霊の力を大幅に上昇させることができる",
  str_item_intro_3205024 = "上級覚醒材料。火属性光霊が覚醒する時に必要なアイテム。\n火山岩を火に投入して溶錬した赤く硬い銀の塊。とても高価",
  str_item_intro_3205031 = "上級覚醒材料。森属性光霊が覚醒する時に必要なアイテム。\n森のフレアインゴットを特殊な技術で加工し、他の材料と混ぜ合わせた精製鋼。とても高価な工業製品",
  str_item_intro_3205032 = "上級覚醒材料。森属性光霊が覚醒する時に必要なアイテム。\n大量の緑水晶に光力を込めて作られた珍しいダイヤ。とてつもない光力を秘めている",
  str_item_intro_3205033 = "上級覚醒材料。森属性光霊が覚醒する時に必要なアイテム。\n森ポーションⅢを更に精製してできた物。光霊の力を大幅に上昇させることができる",
  str_item_intro_3205034 = "上級覚醒材料。森属性光霊が覚醒する時に必要なアイテム。\n珍しい植物の種を大量に集め、秘密の手法で分解・精製した銀の塊。とても高価",
  str_item_intro_3205041 = "上級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム。\n雷のフレアインゴットを特殊な技術で加工し、他の材料と混ぜ合わせた精製鋼。とても高価な工業製品",
  str_item_intro_3205042 = "上級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム。\n大量の黄水晶に光力を込めて作られた珍しいダイヤ。とてつもない光力を秘めている",
  str_item_intro_3205043 = "上級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム。\n雷ポーションⅢを更に精製してできた物。光霊の力を大幅に上昇させることができる",
  str_item_intro_3205044 = "上級覚醒材料。雷属性光霊が覚醒する時に必要なアイテム。\n銀の塊に雷を流し込んで作られた魔法材料。とても硬く、稲妻並みの力を秘めている",
  str_item_intro_3220000 = "光霊の突破に特別な作用を与える\n一部の光霊に対して特別な効果を発揮する珍しい宝石。内部の神秘的なエネルギーが光霊の潜在能力を呼び覚ます",
  str_item_intro_3220001 = "ナシリスの突破に必要なアイテム\n鏡のような一枚の宝石。よく見ると、優雅に舞う白服の少女の姿が浮かび上がる。",
  str_item_intro_3220002 = "ヒイロの突破に必要なアイテム\n時たま桜色の龍の姿が浮かび上がる宝石。とても高価",
  str_item_intro_3220004 = "クマ&ペギの突破に必要なアイテム\nクマとペギがこの宝石をつけると、宝石から冷気が放出される。二人のお気に入りアイテム",
  str_item_intro_3220005 = "ミヤの突破に必要なアイテム\nミヤのもう一つの姿が封印されているようだ……もしかしたらこれでミアの本心が分かるかもしれない",
  str_item_intro_3220006 = "カレンの突破に必要なアイテム\n時々、ランスのような形をした白い光を放つ宝石",
  str_item_intro_3220009 = "ファウストの突破に必要なアイテム\n時々怪しく歪んだ模様が浮かび上がる宝石。他者が身に着けるとなぜか不安が溢れてくるが、ファウストはそれを厭わず、逆に親しみを感じている",
  str_item_intro_3220010 = "ルイスの突破に必要なアイテム\n明るいオーラを持つ宝石。ルイス・カーライルに物語のインスピレーションを無数にもたらしているらしい",
  str_item_intro_3220011 = "キシローナの突破に必要なアイテム\nこのレアな宝石をよく見ると、眼前に巨龍の姿がぼんやりと浮かぶ",
  str_item_intro_3220012 = "ナミシスの突破に必要なアイテム\n非常に硬く、切断面が素晴らしく美しい宝石。所有者に驚異的な力をもたらす",
  str_item_intro_3220013 = "ノーアの突破に必要なアイテム\n撫でるとものすごい寒気を感じるが、凍傷にはならない不思議な宝石。ノーアのお気に入り",
  str_item_intro_3220014 = "ソルラドの突破に必要なアイテム\n強烈な光を放つ白い宝石。ソルラドはこれを自分だけでなく、白夜城をも代表している石だと思っている",
  str_item_intro_3220015 = "ハチ&ギンの突破に必要なアイテム\nこの宝石を通してハチとギンはたくさんの場景をのぞき見ることができ、並々ならぬ芸術的インスピレーションを得る",
  str_item_intro_3220016 = "カフカの突破に必要なアイテム\n極めて硬度が高い宝石。かつてある人物に向けられた致命的な攻撃を防いだことがあるらしい",
  str_item_intro_3220017 = "ラビの突破に必要なアイテム\nよく見ると中で炎が兎のように跳ね続けている宝石。ラビのラッキーシンボル",
  str_item_intro_3220018 = "レジーナの突破に必要なアイテム\n太陽のような光を放つ宝石。真っ暗闇でも光をもたらし、レジーナの音楽をさらなる高みへ導く",
  str_item_intro_3220019 = "ビクトリアの突破に必要なアイテム\n中に涙のしずく状の微細な粒がびっしり詰まっている宝石。ビクトリア自身の血液だとか…",
  str_item_intro_3220021 = "ジョラの突破に必要なアイテム\nジョラが触れると、宝石の周囲に蝶番の形状をした緑色の波紋が現れる",
  str_item_intro_3220023 = "クラリンの突破に必要なアイテム\n黒い水滴が凝集した宝石。クラリンが持つと非常に硬くなる",
  str_item_intro_3220024 = "ベニ&クロの突破に必要なアイテム\n赤と黒の光が明滅している水晶。近づくと刀剣が切り結ぶ音や、銃弾の発射音が聞こえる",
  str_item_intro_3220025 = "カロンの突破に必要なアイテム\n赤と黒の光がストライプ状に並んで明滅している、カロンの大好きな宝石",
  str_item_intro_3220026 = "ウリエルの突破に必要なアイテム\n時に灰色や黒い炎がパッとちらつくダイヤ。とても美しいが、虚無感をもたらす…",
  str_item_intro_3220027 = "ミカエルの突破に必要なアイテム\n轟雷の中で発見されたという宝石。真なる主人に強大な力をもたらす",
  str_item_intro_3220028 = "ラファエルの突破に必要なアイテム\n不思議な力を持つ透明な宝石。ラファエルが使うと治癒力が増強される",
  str_item_intro_3220029 = "ガブリエルの突破に必要なアイテム\nガブリエルが使うと、極めて美しい緑色の光を放つ宝石",
  str_item_intro_3220030 = "サメヤマの突破に必要なアイテム\n常に焼けつくような熱を放っている宝石。サメヤマしか装着できない",
  str_item_intro_3220033 = "バイスの突破に必要なアイテム\n見るたびに色が変わる不思議な輝きを持つ宝石。何やら過去の伝説を秘めているようだ…",
  str_item_intro_3220036 = "ヒドライの突破に必要なアイテム\n得体の知れないオーラを放つ宝石。ヒドライは恐れるどころか、いつも「あれは…俺と同じだ」と言っている",
  str_item_intro_3220038 = "ガルーの突破に必要なアイテム\n人工的に作られた要素を多く含んでいる宝石。自然に形成されたものではない、古代文明の遺留品",
  str_item_intro_3220040 = "ボンバーの突破に必要なアイテム\nこの宝石に触れると火花が散る。みだりに手に取ったりしないほうがいい",
  str_item_intro_3220041 = "Ms.ブランの突破に必要なアイテム\n優雅な光をまとっている宝石。近づくと静寂を感じさせる。端正で威厳ある女性にピッタリ",
  str_item_intro_3220042 = "バートンの突破に必要なアイテム\nバートンにしか見えない、戦火のような赤い斑点を持つ宝石。彼の願望をリアルに体現しているのかもしれない",
  str_item_intro_3220044 = "ビビアンの突破に必要なアイテム\n強烈な光を放っている宝石。装飾として剣の柄にはめ込むのに最適",
  str_item_intro_3220045 = "ネイルスの突破に必要なアイテム\n縁が非常に鋭利な宝石。ある人によれば、これは「懲罰」を表しているのだとか…",
  str_item_intro_3220046 = "キーティンの突破に必要なアイテム\nキーティンのメンバー達がこの宝石を身に着けると、いつも脳裏にたくさんの「詩句」が浮かぶ",
  str_item_intro_3220048 = "ダイナの突破に必要なアイテム\nダイナはこの宝石を装着すると、より多くの格闘技術をマスターできるという",
  str_item_intro_3220054 = "ナディーンの突破に必要なアイテム\nいつでも温かく、穏やかな光を放っている白い宝石",
  str_item_intro_3220055 = "ピアタマンの突破に必要なアイテム\nかつてピアタマンも迷ったことがある。しかしこの水晶が彼に揺るぎない力をあたえた",
  str_item_intro_3220056 = "コンスタンの突破に必要なアイテム\nコンスタンが暗鬼を殺した詳細を自動的に記録する水晶。彼の暗黙のパートナー",
  str_item_intro_3220057 = "フィリスの突破に必要なアイテム\n時々黒いオーラを放つ水晶。近づくと、フィリスの心の内が見える",
  str_item_intro_3220060 = "ジョナの突破に必要なアイテム\n溶けた真鍮のような台座を持つ水晶。ジョナの拳銃の銃弾から鋳造されており、彼女の過去の戦果を物語っている",
  str_item_intro_3220061 = "チャンドラの突破に必要なアイテム\n透明な宝石。よく見ると中には常に脈動している息の塊がある。まるで様々な感情を集めているかのように。",
  str_item_intro_3220062 = "シルヴァの突破に必要なアイテム\n風脈の森の奥で発見されたと伝わる宝石で、触れるとひんやりする。守人シルヴァのシンボル",
  str_item_intro_3220064 = "ラスの突破に必要なアイテム\nとても重いが、ラスの手の中では空中に浮くほどに軽くなる宝石",
  str_item_intro_3220065 = "タタの突破に必要なアイテム\nタタがこの水晶を見つめると、彼女の故郷、雲山の姿がぼんやりと浮かんでくる…",
  str_item_intro_3220067 = "アリスの突破に必要なアイテム\nアリスの手の中ではハート形になり、特別な活力を生み出す宝石",
  str_item_intro_3220068 = "ウェンディの突破に必要なアイテム\nとても軽いのに硬い宝石。ウェンディの性格とそっくり",
  str_item_intro_3220070 = "リオナの突破に必要なアイテム\nこの水晶を凝視すれば、耳元で邪龍の咆哮が聞こえてくる",
  str_item_intro_3220071 = "タキの突破に必要なアイテム\n時に巨龍が火を吐いている光景を映し出す水晶。それはまさにタキを体現しており、だからこそ間違いなく彼の物だといえる",
  str_item_intro_3220073 = "パテ＆パシの突破に必要なアイテム\n赤い光と黒いオーラを代わる代わる放っている宝石",
  str_item_intro_3220075 = "オティの突破に必要なアイテム\nこの宝石を耳に当てると、電流の流れる音が微かに聞こえる。通信に使えるかもしれない",
  str_item_intro_3220076 = "クレーケンの突破に必要なアイテム\nこの奇妙な宝石は見る角度によって色が異なり、とりわけクレーケンの手の中ではころころと色が変わる",
  str_item_intro_3220077 = "ベツレヘムの突破に必要なアイテム\nキラキラ輝く非常に冷たい宝石。氷で作られた世界初の宝石といわれ、北境の女王のみ装着できる",
  str_item_intro_3220078 = "ロビンの突破に必要なアイテム\nエメラルドグリーンの宝石。これを装着すると、あらゆる毒への耐性ができるという。ロビンのお守り",
  str_item_intro_3220079 = "ミジェンニの突破に必要なアイテム\n真四角で、完璧な重心を持つ宝石。天秤のバランスを保つのに使えるらしい",
  str_item_intro_3220081 = "ヘールの突破に必要なアイテム\n触れるととても熱い宝石。誰かさんの衰えることを知らぬ活力のようだ",
  str_item_intro_3220083 = "リリムの突破に必要なアイテム\nこの宝石は真の主人に近づくと、電気回路のような奇妙な柄が浮かび上がる",
  str_item_intro_3220084 = "イスタバンの突破に必要なアイテム\n周囲に小さな青い炎が揺れている宝石。近づくと「シャドウマスター」と呼ぶ声が微かに聞こえる",
  str_item_intro_3220085 = "ジェーンの突破に必要なアイテム\nこの黒い宝石を見つめると、記録された言葉がたくさん見えてくるようだ…",
  str_item_intro_3220086 = "ユーライアの突破に必要なアイテム\n花の図柄が刻まれている白い玉石。優美で洗練されている",
  str_item_intro_3220087 = "バーバリーの突破に必要なアイテム\n時に槍状のスパークを放つ宝石。その形状はバーバリーの雷槍そっくり",
  str_item_intro_3220088 = "マギーの突破に必要なアイテム\n時々奇妙な黄色い光を放つ水晶。近づくと中に少女の姿が見える",
  str_item_intro_3220089 = "イルンティの突破に必要なアイテム\n時々青い稲光を放つ宝石。強い力を秘めている",
  str_item_intro_3220090 = "バーバラの突破に必要なアイテム\n真紅の台座を持つ宝石。近づくと騒々しい曲が微かに聞こえる",
  str_item_intro_3220091 = "クロエの突破に必要なアイテム\nこの白い水晶は、まるで泣いているかのようにいつも水滴を滴らせており、近づくと微かに琴の音が聞こえる",
  str_item_intro_3220092 = "セファーの突破に必要なアイテム\nとても硬く、どうやっても傷がつかないという宝石",
  str_item_intro_3220093 = "ミジャードの突破に必要なアイテム\nある人工生命体の背骨から抽出されたらしい宝石。謎のエネルギーを保有している…",
  str_item_intro_3220095 = "レスターの突破に必要なアイテム\n嗅ぐと荒野の中にいるように感じられる宝石。レスターはこれを使ってお気に入りの匂いを見つけている",
  str_item_intro_3220096 = "シャリーの突破に必要なアイテム\nシャリーの手の中では元の形状を保てず、水滴のようになる宝石。彼女に強力な力をもたらしてもいる",
  str_item_intro_3220097 = "ワタリの突破に必要なアイテム\n触れると非常に冷たい宝石。ある種の刃物の代わりに使えるほど縁が鋭利",
  str_item_intro_3220098 = "クスッタの突破に必要なアイテム\nよく見ると中にしおれた黒い花が見える水晶",
  str_item_intro_3220099 = "アイリーナの突破に必要なアイテム\nアイリーナがこの水晶を見ると、呪いの力がだいぶ弱まるらしい",
  str_item_intro_3220100 = "スカーレイの突破に必要なアイテム\n中に「星空」が広がっている宝石。スカーレイの力の真なる源らしい",
  str_item_intro_3220101 = "アンシアの突破に必要なアイテム\n真鍮色の光沢があり、微かに振動している。この振動はある帯域の音の周波数に近い",
  str_item_intro_3220102 = "テッサの突破に必要なアイテム\n常に不規則にスパークを放っている宝石。うっかり近づくと突然スパークを放つ。そのタイミングをしっかり把握できるのはテッサだけ",
  str_item_intro_3220103 = "エルシーの突破に必要なアイテム\nこの水晶をじっと眺めていると、中からある種の「放射線」が放出されているのが分かる。なんて恐ろしい…",
  str_item_intro_3220104 = "ドーンの突破に必要なアイテム\nドーン専用の宝石で、彼女が握ると表面に白い花の影が浮かび上がる。その影は彼女の心の支えである。",
  str_item_intro_3220105 = "イブの突破に必要なアイテム\nイブが触れると周囲に小さなアークが出現する水晶。これこそが彼女の持つ特別な力だ",
  str_item_intro_3220107 = "禁衛座の心珀",
  str_item_intro_3220108 = "焚霜座の心珀",
  str_item_intro_3220109 = "童謡座の心珀",
  str_item_intro_3220110 = "鎮魂座の心珀",
  str_item_intro_3220111 = "ベリエの突破に必要なアイテム\nベリエが手に握ると、血の赤に染まる水晶。ベリエの体の結晶と連動するかのように変化する…",
  str_item_intro_3220112 = "スモーキーの突破に必要なアイテム\n近くにある可燃物が理由なく燃えてしまう宝石。スモーキーが手にしている時は、この不思議な力が収まる",
  str_item_intro_3220113 = "ボナーズの突破に必要なアイテム\nボナーズが触れるとインスピレーションが無数に浮かび、新しい楽章の創作ができる宝石",
  str_item_intro_3220114 = "ジュヌヴィエーヴの突破に必要なアイテム\n常に赤い光を放って輝き、燃え盛る炎のよう。時に激しい馬の鳴き声を発する",
  str_item_intro_3220115 = "ナルセールの突破に必要なアイテム\nナルセールがこの水晶を身に付けると、まるで大自然の声が聞こえるかのごとく、動植物との意思疎通がよりスムーズになる",
  str_item_intro_3220116 = "フェラールの突破に必要なアイテム\nフェラールにたくさんの設計インスピレーションを与えてくれる宝石。「オリジナルメカ製造計画」を一歩先に進めることができる",
  str_item_intro_3220117 = "グラムの突破に必要なアイテム\nこれを手に握ると、グラムはまるで「勇士別働隊」にいた頃に戻ったかのように感慨にふける",
  str_item_intro_3220119 = "レビィの突破に必要なアイテム\nレビィがこの宝石に触れると、巨剣と鎖が摩擦し合う音が聞こえ、電気の流れを感じることができる",
  str_item_intro_3220120 = "ヘイディの突破に必要なアイテム\nこの宝石を日の光にかざすと、白い鎧と同じような光沢を放つ",
  str_item_intro_3220121 = "パロマの突破に必要なアイテム\nこの宝石には時おりショートカットの女の子の姿が浮かぶ。それはパロマが誰よりもよく知る人物だ…",
  str_item_intro_3220122 = "アルーラの突破に必要なアイテム\nアルーラがこの宝石を耳元にもっていくと、「カチカチ」と時計が動く音が聞こえ、より精確に時間を知ることができる",
  str_item_intro_3220123 = "カーティの突破に必要なアイテム\nこの宝石があれば、カーティは突発的状況にも素早く対応できるようになる",
  str_item_intro_3220126 = "ベセルの突破に必要なアイテム\nこの水晶はべセルの胸元の宝石に溶け込むと、さらに美しい光を放つ",
  str_item_intro_3220127 = "パソロの突破に必要なアイテム\nパソロが手にすると極薄になる水晶で、とても軽く、舞い散るように空中に浮かべられる",
  str_item_intro_3220129 = "ルークの突破に必要なアイテム\nこの水晶は非常に軽く、ルークはこれを宙に浮かばせ、蝶のように軽やかにダンスさせることができる",
  str_item_intro_3220131 = "ノーヴィオの突破に必要なアイテム\nこの宝石の表面には難解な文字が刻まれており、解読できるのはノーヴィオだけのようだ",
  str_item_intro_3220132 = "ローラの突破に必要なアイテム\nハチミツの中に漬けられた宝石。透き通った美しい光沢とともに甘い香りを漂わせている",
  str_item_intro_3220133 = "トールの突破に必要なアイテム。近づくと焼けつく炎のような光を放つが、小林さんの側では優しいピンク色に変わる。",
  str_item_intro_3220134 = "カンナの突破に必要なアイテム。電光がキラキラと光る宝石。しかし、手に握ると不思議と柔らかい。",
  str_item_intro_3220135 = "エルマの突破に必要なアイテム。この宝石には暖流が規則正しく流れていて、心を鎮めて耳を傾けると清らかな水の音が聞こえる",
  str_item_intro_3220136 = "ルコアの突破に必要なアイテム。この宝石を見つめていると、空や海、山、川、都市などの景色が次々と浮かび、最後には底の見えない眼差しのオッドアイが見える。",
  str_item_intro_3220137 = "ファフニールの突破に必要なアイテム。この宝石に近づくと不吉な叫び声が聞こえ、そこにはファフニールが何かを唱える低い声が混じっている。",
  str_item_intro_3220138 = "シヴォーンの突破に必要なアイテム。\nシヴォーンがこれを手に持つと、緑色の糸のようなものが見える…",
  str_item_intro_3220139 = "エリカの突破に必要なアイテム。\nこの宝石を耳元に当て、耳を澄ませば、未知なる存在の呼び声が聞こえるかもしれない",
  str_item_intro_3220140 = "フロリナの突破に必要なアイテム\nとてもきれいに磨かれていて、一点の曇りもない宝石。羊皮紙とインクの匂いが漂い、本を読み、祈りを捧げる声が中からかすかに反響してくる",
  str_item_intro_3220141 = "ルビーの突破に必要なアイテム\n強度が高く、バットで打つと高く清々しい音を発する。ルビーのバッティング練習にもってこいだ",
  str_item_intro_3220142 = "ルージュの突破に必要なアイテム\n一見ごく普通の宝石だが、ルージュが触れると燃え盛る炎の幻影が浮かび上がる",
  str_item_intro_3220143 = "リンネの突破に必要なアイテム\n時どき淡いピンク色の光を放っており、そうっと振ると涼やかで楽しげな鈴の音が聞こえてくる",
  str_item_intro_3220144 = "カヤノの突破に必要なアイテム\n平たくどこにでもありそうな宝石だが、かすかに冷たく、静かな夜にはかすかな光を放つ",
  str_item_intro_3220145 = "アメモリの突破に必要なアイテム\nアメモリが持つととても軽くなり、時おり「忍」の文字が光って浮かび上がる",
  str_item_intro_3220146 = "ヨウの突破に必要なアイテム\nかすかに食べ物の香りを放っている。近くで観察すると、中で何か奇妙な赤い光がきらめいているように見える",
  str_item_intro_3220147 = "モモ＆アンズの突破に必要なアイテム\n色とりどりの宝石。なぜか美味しそうに見えてくる。よく観察すると、宝石の中に2つの同じような輝きがあることに気付くだろう",
  str_item_intro_3220148 = "アズールの突破に必要なアイテム\nひんやりとした手触りの宝石。太陽の光で照らすとダークブルーの光を放つ",
  str_item_intro_3220149 = "ロイの突破に必要なアイテム\n温もりのある質感。目立たない宝石。表面に銀髪の人影が浮かび上がることがあり、よく見ようとすると、いつもロイに取り上げられてしまう。ロイは背が高く取り返すことはできない",
  str_item_intro_3220150 = "レノーアの突破に必要なアイテム\nこの宝石からは、なぜか「カチカチ」と音が聞こえてくる。人形のゼンマイを巻く音のようだ",
  str_item_intro_3220151 = "ギルスの突破に必要なアイテム\n非常に硬く、高温な宝石。ギルスが触れると、驚くことに羊の角の形に変わる",
  str_item_intro_3220152 = "メイの突破に必要なアイテム\nメイが握ると、宝石に1匹の猫の姿が浮かんでくる。時おり光霊の影がよぎることもあるが、はっきりと誰であるかは分からない",
  str_item_intro_3220153 = "レインハトの突破に必要なアイテム\n啓光で最も尊敬を集める宝石職人の手によって磨かれた宝石。啓光連邦の頂点に立つ者のみが手にすることが出来る",
  str_item_intro_3220154 = "バイス・空の瞳の突破に必要なアイテム\nバイスが近づくたびにかすかに振動し、赤と緑の光を交互に放つ",
  str_item_intro_3220187 = "テンカンの突破に必要なアイテム\n手に張り付く感覚のある宝石で、近づくと甘い香りがする。これを使うといつも、テンカンは何かおいしい物を食べているような笑顔を浮かべる。まさかアメ玉なのだろうか？",
  str_item_intro_3220188 = "タンドウの突破に必要なアイテム\n滑らかな質感の宝石。近づくとかすかに花の香が漂い、よく見ると細かい海棠の華の紋様が施されている。",
  str_item_intro_3221000 = "限定光霊の心珀と交換できる",
  str_item_intro_3221001 = "★5森属性光霊（限定光霊を除く）の心珀と交換できる",
  str_item_intro_3221002 = "★5雷属性光霊（限定光霊を除く）の心珀と交換できる",
  str_item_intro_3221003 = "★5火属性光霊（限定光霊を除く）の心珀と交換できる",
  str_item_intro_3221004 = "★5水属性光霊（限定光霊を除く）の心珀と交換できる",
  str_item_intro_3221005 = "★6森属性光霊（限定光霊を除く）の心珀と交換できる",
  str_item_intro_3221006 = "★6雷属性光霊（限定光霊を除く）の心珀と交換できる",
  str_item_intro_3221007 = "★6火属性光霊（限定光霊を除く）の心珀と交換できる",
  str_item_intro_3221008 = "★6水属性光霊（限定光霊を除く）の心珀と交換できる",
  str_item_intro_5840001 = "最も基本的な不思議なツリーの種子パック。一般的な不思議なツリーを栽培できる",
  str_item_intro_5840002 = "アンコモン不思議なツリーの種子パック。小さな突然変異によって生まれたアンコモン不思議なツリーを栽培できる",
  str_item_intro_5840003 = "レア不思議なツリーの種子パック。小さな突然変異によって生まれたレア不思議なツリーを栽培できる",
  str_item_intro_5840004 = "エクセレント不思議なツリーの種子パック。複雑な突然変異によって生まれたエクセレント不思議なツリーを栽培できる",
  str_item_intro_3220155 = "バートン・鋭刃の突破に必要なアイテム\n硬くて重い宝石。時折、中に大きな黒い影が映る。猛獣の低い咆哮が聞こえてくるかのようだ",
  str_item_intro_3220156 = "ニナの突破に必要なアイテム\n見るからに珍しそうな宝石。目を凝らして見てみると、宝石の放つ光が変化し続けていることに気がつくだろう。それはまるで不屈の意志の表れのようだ",
  str_item_intro_3220157 = "サナエの突破に必要なアイテム\nどんなに落としても割れないほど丈夫。どうしてそのことが分かったかについては、サナエしか知らない",
  str_item_intro_3220158 = "ジョーカーの突破に必要なアイテム\n強烈な輝きを放つ宝石。\n反逆の意志が沸々と伝わってくる。",
  str_item_intro_3220159 = "クイーンの突破に必要なアイテム\n透き通った輝く宝石。\n反逆の意志が沸々と伝わってくる。",
  str_item_intro_3220160 = "フォックスの突破に必要なアイテム\n温かく、なめらかな手触りの宝石。\n反逆の意志が沸々と伝わってくる。",
  str_item_intro_3220161 = "ヴァイオレットの突破に必要なアイテム\n小さな花をかたどった宝石。\n反逆の意志が沸々と伝わってくる。",
  str_item_intro_3220162 = "モナの突破に必要なアイテム\n表面に爪痕のようなものがある宝石。\n反逆の意志が沸々と伝わってくる。",
  str_item_intro_3220164 = "カレン・照魂の突破に必要なアイテム\n一瞬、中に水蒸気が満ちているように見えるが、たちまち激しい炎に変わる。しかし、どのように変化しようと、この宝石の毅然とした本質が変わることはない",
  str_item_intro_3220165 = "シエルの突破に必要なアイテム\nシエルがこの結晶を見つめると、中に不思議な公式が浮かび、尽きることのないインスピレーションを与えてくれる",
  str_item_intro_3220166 = "フィアの突破に必要なアイテム\n近くに珍獣がいる時、この宝石は激しく震動する",
  str_item_intro_3220167 = "ジェノの突破に必要なアイテム\n不思議な宝石。近くに宝石自身の幻影を作り出せる…幻影に騙されないように注意が必要",
  str_item_intro_3220168 = "レインボーの突破に必要なアイテム\n冷たい感触の宝石。時折、中から波の音が聞こえる",
  str_item_intro_3220169 = "この宝石を握りしめると、サディはあふれる勇気が手のひらから全身に流れ込み、心臓の鼓動まで変わるのを感じる\nサディが突破するための必須アイテム",
  str_item_intro_3220170 = "ポルクスの突破に必要なアイテム\n硝煙の香り漂う宝石。不思議なことに、この宝石の表面には1振りの刀の影がちらちらと浮かぶ",
  str_item_intro_3220171 = "キャスタの突破に必要なアイテム\n不思議な宝石。よく耳を傾けると、中からカラスの鳴き声のような音が聞こえてくる",
  str_item_intro_3220172 = "よく見ると、この宝石は時おり美しい映画のワンシーンを映し出す。これがあればリリカの演技もワンランクアップ！\nリリカが突破するための必須アイテム",
  str_item_intro_3220173 = "ミノスの銃口から炎がほとばしる時、この宝石にミノタウロスのような悪魔の影が映し出される\nミノスが突破するための必須アイテム",
  str_item_intro_3220175 = "アクセリアの突破に必要なアイテム\n傷だらけの宝石。握りしめた時にとがった角が手に当たるが、そのまま握りしめていると、不思議な温もりを感じられる",
  str_item_intro_3220176 = "ベルタの突破に必要なアイテム\n美しい色の宝石。磨かれてはいないが、まばゆい輝きを放っている。ときどき、宝石の中を飛ぶ鳥の影が見える",
  str_item_intro_3220177 = "ゴルディの突破に必要なアイテム\nこのカラフルな宝石は触れるととても滑らかで美しく、長い間持ち歩いているとゴルディの幸運にあやかれるらしい",
  str_item_intro_3220178 = "ヴィックの突破に必要なアイテム\n硬い宝石で、ハンマーで力いっぱい叩いてもキズ一つつかない",
  str_item_intro_3220180 = "ブランディの突破に必要なアイテム\n少し硬いが弾力があり、指で押すとすぐに押し返される。ブランディがシャッターを素早く切る練習をするのに使っているという",
  str_item_intro_3220181 = "シュウの突破に必要なアイテム\nこの宝石に触れると、手に暖かさが伝わってくる。まさにシュウの熱く燃える心の証である",
  str_item_intro_3220182 = "ユエの突破に必要なアイテム\n薄く硬い宝石。まるで魚のうろこのように、光の角度によって色が変化する",
  str_item_intro_3220183 = "リンセイの突破に必要なアイテム\n青草の香りが漂う。わずかに苦みを帯びた香りは、薬屋を思わせる",
  str_item_intro_3220184 = "イェリアの突破に必要なアイテム\n触ってみると、無数の風雨で摩耗したように感じるが、澄んだ美しさも感じられる",
  str_item_intro_3220185 = "キアの突破に必要なアイテム\nいつもキアになでられているのか、手触りは非常にスベスベしている。目を凝らすと、動いている時計の文字盤が透けて見える。これは時計だったのだろうか？",
  str_item_intro_3220186 = "ティナの突破に必要なアイテム\n白い聖なる光に包まれた宝石。むやみに触れるとその輝きを汚してしまうかも…",
  str_item_intro_3220189 = "ラインの突破に必要なアイテム\n手触りは硬く、陽光の下でまばゆく輝いている。ほのかに花の香りがする。",
  str_item_intro_3220190 = "マシューの突破に必要なアイテム\n使われた技術は不明だが、とても美しくカッティングされた宝石。恐らく高価なので早く元の場所に戻しましょう",
  str_item_intro_3220191 = "ハーティの突破に必要なアイテム\n一見硬そうだが、触ると意外にも柔らかく弾力がある。子犬の手のようで、思わずずっと触っていたくなる",
  str_item_intro_3220192 = "レオの突破に必要なアイテム\n光沢のない、手触りもザラザラとした宝石。レオが言うには、辺境の風砂に吹かれたからだという。",
  str_item_intro_3220193 = "クリステンの突破に必要なアイテム\n近づくと水の流れる音が聞こえてくるようだ。クリステンの心の中には、まさに伏流のようにあふれるものがあるのかもしれない",
  str_item_intro_3220199 = "インゲルの突破に必要なアイテム\n澄んだ輝きを放つ透明の宝石。その光沢の奥から、鳥のさえずりのような美しい音が響いてくる。",
  str_item_intro_3220200 = "アナトリアの突破に必要なアイテム\nアナトリアが集めた宝石。極夜の地にある鉱脈で採れるもので、はるばる啓光まで持ち帰ってきた。きめ細かく光沢のある手触りで、その表面は人の姿も映し出せるようだ。",
  str_item_intro_3220201 = "ミヤ・浄魂の突破に必要なアイテム\n目立たない石だが、耳を傾けると、2つの音が互いに絡み合って共鳴を生んでおり、石がますます輝いて見える。",
  str_item_intro_3220202 = "ソルラド・響鳴の突破に必要なアイテム\nこの宝石をのぞくと、雷雨の過ぎ去った後の晴れ渡った空が見える。それは彼の統治下にある白夜城の未来そのものだ。",
  str_item_intro_3220203 = "ジャキーニの突破に必要なアイテム\n美しい宝石。太陽の光を浴びると、色とりどりの光を放ち、1冊の占いの本の姿が浮かび上がる。",
  str_item_intro_3220204 = "ヨシュアの突破に必要なアイテム\n宝石は暖かい光に包まれ、まるで冬の寒い夜の火や闇夜の迷い人を導く街灯のようだ",
  str_item_intro_3220205 = "ブラン・洗心の突破に必要なアイテム\nMs.ブランは常にこの美しい宝石を手にとり遊んでいる。この宝石の奥に赤いぼんやりとした光が浮かんでいると彼女は言うが、他の者には見えない",
  str_item_intro_3220206 = "ローレライの突破に必要なアイテム\nローレライはよくこの宝石からはお金の匂いがすると冗談を言っているが、実はその匂いが好きである",
  str_item_intro_3220207 = "セナの突破に必要なアイテム\n丸みがあるように見えるが、触ると鋭い感覚のする水晶。輝かしい外見とは違い、過去に負った傷を隠しているかのようだ。",
  str_item_intro_3220208 = "バップの突破に必要なアイテム\n燃え盛るように熱く、輝く水晶。ゆっくりと回転し続けている…",
  str_item_intro_3220209 = "ラス・傲骨の突破に必要なアイテム\n触れると微かに刺すような痛みがある。その痛みは結晶の中を巡っている赤い雷光の疼きであり、彼女が戦場へと向かう時を今か今かと待ち望んでいる",
  str_item_intro_3220210 = "ジョセリンの突破に必要なアイテム\nよく見ると、穏やかな光が宝石の中心で律動している。それはまるで信者の祈りのようでもあり、夜の帳を破る聖なる光のようでもある",
  str_item_intro_3220211 = "アントニーの突破に必要なアイテム\nこの宝石は長い間地下に埋まっていたもので、アントニーが掘り起こし、付着していた土を払ったことで、その秘密の輝きを取り戻した。",
  str_item_intro_3220212 = "ザーリャの突破に必要なアイテム\n宝石というよりは天然の氷の結晶である。ザーリャ自身が作りだしたものの可能性もある。",
  str_item_intro_3220213 = "33号の突破に必要なアイテム\n33号が遺跡の近くで見つけた宝石。耐えがたいほどの孤独に襲われると、33号はこれを「仲間」だと思い、話しかけていた。",
  str_item_intro_3220214 = "レベッカの突破に必要なアイテム\nレベッカの父母が彼女に贈った宝石。これを握り締めるたびに、彼女は永遠に消えることのない家族のぬくもりを感じることができる",
  str_item_intro_3220215 = "イーサの突破に必要なアイテム\nレベッカの毒液が凝結してできた宝石。これを身に着けているだけで、イーサの体は力で満たされる",
  str_item_intro_3220216 = "センキョクの突破に必要なアイテム\n一見ごく普通の石だが、中には未知の力が秘められている。センキョクはいったいどのようなカラクリに組み込むつもりなのだろう。",
  str_item_intro_3220218 = "シェオルの突破に必要なアイテム\n不思議な宝石である。ちょうど白夜コイン1枚分の重さがあり、耳を傾けると、まるで宝石の中から、ジャラジャラと白夜コインが立てる音が響いてくるようだ",
  str_item_intro_3220219 = "イスタバン・積痕の突破に必要なアイテム\nどっしりと重みのある光輝く宝石。手に取ると、はるか昔の感情の動きが微かに伝わってくる。奥深くに眠っていた昔日の出来事が今にも噴き出してきそうだ",
  str_item_intro_3220220 = "バージルの突破に必要なアイテム\nバージル自身が鑑定した宝石で、芸術的価値が非常に高い。まるでお守りかのように、肌身離さず持ち歩いているという",
  str_item_intro_3220221 = "アルゴルの突破に必要なアイテム\n来歴不明の宝石だが、見る者の心を強く揺り動かす。まるで光霊の予測不能の未来を告げているかのよう…",
  str_item_intro_3220223 = "シンゲイの突破に必要なアイテム\n遠い昔の鱗が変化してできた石。シンゲイの一族がはるかなる思いを託しているのかもしれない",
  str_item_intro_3220224 = "ラショウの突破に必要なアイテム\n神秘的な力を秘めている可能性がある石。ラショウは悪さをする祟霊の頭をたたくために使っているかもしれない",
  str_item_intro_3220225 = "ティアラの突破に必要なアイテム\n保護色をした宝石で、雪の中に落ちると、雪の色に溶け込んでしまい、見つけるのが難しい。落とさないようにしっかりと持っていよう。",
  str_item_intro_3220227 = "レイチェルの突破に必要なアイテム\n角が異常に鋭い光珀で、うっかり手に取るとけがをしてしまう。だが、そうっと触れれば、微かな温度が伝わってくる",
  str_item_intro_3220228 = "ゼタの突破に必要なアイテム\n華やかな美しい宝石で、きらきらと彩豊かな光を放ち、近づくと微かに甘いキャンディーの香りがする",
  str_item_intro_3220229 = "バティアの突破に必要なアイテム\n普通の石。バティアはつるはしと溶鉱炉を通じて獲得できると言っているが、別の方法でもいい。",
  str_item_intro_3220230 = "「ビクトリア・墓歌」の突破に必要なアイテム\nこの宝石に触れた瞬間、遠くでも耳元でもなく、脳の奥深くで脈打つ、はるか昔のつぶやきを聞くことができる。それはまるで、長い間存在していた生物が外に出ようともがいているかのようだ。",
  str_item_intro_3220231 = "「ヴィルヘルム」の突破に必要なアイテム\n怪しげで美しい色の宝石。手を触れた瞬間、部屋の壁から血がゆっくりと流れ落ちる。驚いて手を引っ込めると、すべてが幻覚だったことに気づく。",
  str_item_intro_3220232 = "「ネイルス・祭礼」の突破に必要なアイテム\nこの宝石を握りしめると、天からまるで無数の鋭い刃が降り注ぎ、肉体を切り裂かれるような感覚が走る。激痛の中で悲鳴をあげ、目を凝らして自分の体を見ると、まったく傷ついていないことに気付く。",
  str_item_intro_3220233 = "ライザの突破に必要なアイテム\n遺跡から発掘された宝石、冒険の情熱を伝えているかのようだ",
  str_item_intro_3220234 = "クラウディアの突破に必要なアイテム\n遺跡から発掘された宝石、音楽のすばらしさを伝えているかのようだ",
  str_item_intro_3220235 = "パトリツィアの突破に必要なアイテム\n遺跡から発掘された宝石、高貴な気品を伝えているかのようだ",
  str_item_intro_3220237 = "マヤの突破に必要なアイテム\nキラキラと光る宝石、その手触りは雲間を流れる涼風のようであり、深海の優しさのようでもある。\n手に握っていると、かすかな囁きが聞こえてくる――「怖がる必要はない。世界は夢の中で深い眠りについている」",
  str_item_intro_3220238 = "「ミトラ」の突破に必要なアイテム\n素朴な見た目に似合わずエッジは非常に鋭い。まるで静かな憤怒のような、心を奮い立たせるパワーを秘めている。",
  str_item_intro_3231101 = "普通のギフト。白夜城勢力の光霊に贈るとより効果的\n羽毛のように軽くて薄い銀箔。とても手が込んでおり、白夜城の人々に好まれる",
  str_item_intro_3232101 = "高級なギフト。白夜城勢力の光霊に贈るとより効果的\n光珀を金箔で包んだ美しい装飾品。白夜城の上流社会で流行っている宝石",
  str_item_intro_3233101 = "白夜城勢力の光霊に贈るとより効果的\nとても貴重な工芸品。光力を持つ宝石を貴重な白水晶に象嵌して作られている",
  str_item_intro_3231102 = "普通のギフト。影ノ街勢力の光霊に贈るとより効果的\n有名な油絵の模写版。影ノ街で大人気",
  str_item_intro_3232102 = "高級なギフト。影ノ街勢力の光霊に贈るとより効果的\n影ノ街の成金だけがたまにありつける貴重な秘蔵の酒",
  str_item_intro_3233102 = "影ノ街勢力の光霊に贈るとより効果的\n独特な緑色の蛍光を放つ、魅力たっぷりの宝石。影ノ街の人々はこれに目がない",
  str_item_intro_3231103 = "普通のギフト。R・W勢力の光霊に贈るとより効果的\n旧時代から残っている油脂。R・Wのメンバーはみなこれでオシャレしたり、巨像のご機嫌を取ったりしている",
  str_item_intro_3232103 = "高級なギフト。R・W勢力の光霊に贈るとより効果的\n火薬に点火するための重要な物質で、銃弾にも爆薬にも使える。R・W内部の安定した通貨",
  str_item_intro_3233103 = "R・W勢力の光霊に贈るとより効果的\n1杯で気持ちよくなれる珍しい蒸留酒。R・Wの人々はみなこれが好き",
  str_item_intro_3231104 = "普通のギフト。啓光連邦勢力の光霊に贈るとより効果的\n啓光連邦の基礎知識に関する書籍。ほとんどが自然関連の知識を記載した図鑑で、挿し絵が美しく、読みやすい",
  str_item_intro_3232104 = "高級なギフト。啓光連邦勢力の光霊に贈るとより効果的\n啓光連邦のガイドブック。各種科学知識の運用や、様々な問題の処理法を、読者に微に入り細に入り教えている。",
  str_item_intro_3233104 = "啓光勢力の光霊に贈るとより効果的\n啓光連邦の内部書籍。これまでに連邦で発見された各種知識が記載された役立つ本",
  str_item_intro_3231105 = "普通のギフト。北境の光霊に贈るとより効果的\n水が雪の結晶になったばかりの時の姿。北境人は、強力な魔法を秘めていると信じており、みなこれを収集するのが好き",
  str_item_intro_3232105 = "高級なギフト。北境勢力の光霊に贈るとより効果的。\n虹の下で発見された宝石。北境人はこれが幸運の証で、とても貴重な品だと信じている",
  str_item_intro_3233105 = "北境勢力の光霊に贈るとより効果的\n北境の凍らない鏡湖から採取した水を凍らせたもの。煌びやかで、北境人最愛の品",
  str_item_intro_3231106 = "普通のギフト。真理結社勢力の光霊に贈るとより効果的\n古代から残された琥珀化したカブトムシ。真理結社の人々は、これには神秘的な魔力が秘められていると信じている",
  str_item_intro_3232106 = "高級なギフト。真理結社勢力の光霊に贈るとより効果的\n神秘の「天啓知識」が記されている巻物。真理結社の人々が解読に成功すれば、多くの知られざる知識が掘り起こされるだろう",
  str_item_intro_3233106 = "真理結社勢力の光霊に贈るとより効果的\n真理結社の人々は、今の文明世界の認識を覆すほどの究極の秘密がこれに隠されていると信じている",
  str_item_intro_3231107 = "普通のギフト。無勢力者の光霊に贈るとより効果的\n脱水技術を用いて作られた圧縮食糧。軽くて携帯に便利なため、小さな集落の多くで人気",
  str_item_intro_3232107 = "高級なギフト。無勢力者の光霊に贈るとより効果的\n神秘の魔法治療薬。所持者が居住地で医師になれる",
  str_item_intro_3233107 = "無勢力者の光霊に贈るとより効果的\n多くの人が珍重しているお宝の地図の欠片。大量の宝があるのなら、一か八かの賭けに出る値打ちもあるというもの",
  str_item_intro_3232108 = "普通のギフト。龍州勢力の光霊に贈るとより効果的\n折りたためる扇。竹の骨に紙を貼って作られている。美しい自然の景観が描かれており、龍州の上流社会で重宝されている。",
  str_item_intro_3233108 = "高級なギフト。龍州勢力の光霊に贈るとより効果的\n赤い紐で編んだ装飾品。通じ合う心と固く結ばれた情を表す。龍州の人にとって最も大切な意味のある贈り物の一つだ。",
  str_item_intro_3231201 = "普通のギフト。童心を持った光霊に贈るとより効果的\n童心を持った人が好きなキャンディ。5つの味があり、吹くと音がするところが最大の売り",
  str_item_intro_3232201 = "高級なギフト。童心を持った光霊に贈るとより効果的\n童心を持った人が好きなゲームブック。使用者は特別なアドベンチャーゲームを、読みながら体験できる",
  str_item_intro_3233201 = "童心を持った光霊に贈るとより効果的\n童心を持った人が好きな模型。内部のディテールまでほぼ完璧で、現在は絶版となっている",
  str_item_intro_3231202 = "普通のギフト。ロマンチストな光霊に贈るとより効果的\nロマンチストが好きな手作りの人形。兎にもクマにも見えて、作者は不明",
  str_item_intro_3232202 = "高級なギフト。ロマンチストな光霊に贈るとより効果的\n雲間から差す美しい光を閉じ込めたボトル。薄暗い中でも鑑賞でき、とてもロマンチック",
  str_item_intro_3233202 = "ロマンチストな光霊に贈るとより効果的\n「純花」という珍しい植物を使って作られている美しい栞。模様と色が様々に変化する",
  str_item_intro_3231203 = "普通のギフト。変わった趣味を持っている光霊に贈るとより効果的\n奇妙な外見で有名な昆虫で、変わった趣味の持ち主はこの標本をコレクションしている",
  str_item_intro_3232203 = "高級なギフト。変わった趣味を持っている光霊に贈るとより効果的\n結晶化してトゲだらけになった謎の生物の骨。変わった趣味の持ち主がコレクションしている",
  str_item_intro_3233203 = "変わった趣味を持っている光霊に贈るとより効果的\n変わった趣味の持ち主がこの腐った木片を収集しているのは、その断面から時折、不思議な囁き声が聞こえるからである",
  str_item_intro_3231204 = "普通のギフト。高貴な光霊に贈るとより効果的\n小さくて軽く、美しい彫刻が施された銀の鈴。高貴な人々はこれが幸運をもたらすと信じている",
  str_item_intro_3232204 = "高級なギフト。高貴な光霊に贈るとより効果的\n照度によって色が変わる珍しい鉱物。貴族たちはよくこれを贈り物にしている",
  str_item_intro_3233204 = "高貴な光霊に贈るとより効果的\n貴族が愛してやまない希少な特殊素材。多くは寒冷地で産出する。柔らかいうえに軽くて薄く、かつ摩耗しにくい",
  str_item_intro_3231205 = "普通のギフト。さっぱりした性格の光霊に贈るとより効果的\n砂漠地帯で有名な特色ある食品。さっぱりした性格の人々はこの独特な味を好む",
  str_item_intro_3232205 = "高級なギフト。さっぱりした性格の光霊に贈るとより効果的\nほとんどの製作・修理ニーズに応えるツールボックス。特にさっぱりした性格の人々に喜ばれる",
  str_item_intro_3233205 = "さっぱりした性格の光霊に贈るとより効果的\n生物と機械の機能数値を検出できる。直感的な人に最適な品",
  str_item_intro_3239997 = "いろいろな味のアメ。光霊にプレゼントすると、光の絆を大幅に上げられる",
  str_item_intro_3239998 = "光霊にプレゼントすると、光の絆を大幅に上げられる",
  str_item_intro_3239999 = "美味しいチョコレート。光霊にプレゼントすると、光の絆を大幅に上げられる",
  str_item_intro_3300001 = "とても堅硬な物質。金属ではなく、古き時代が遺したバイオ複合材料らしい。巨像の損傷修復やエネルギー通路の接続に使える",
  str_item_intro_3300002 = "巨像の基本材料に強化加工を施したもの。巨像内のルームをさらに頑丈にできる",
  str_item_intro_3300003 = "この類の材料は固いだけでなく弾力もある。微かに浮かび上がっている解読不可能な文字は、巨像の一部中枢施設を修復する際の必須材料",
  str_item_intro_3300004 = "「ブリッジ」と呼ばれている巨像のコアをレベルアップする際に必要なプラグイン。とても希少なため、慎重に使うこと",
  str_item_intro_3300005 = "キューブ状の奇怪な構造をした遺物。勇敢な探検家が残したものと思われる。これに刻まれた情報を巨像のデータベースに登録すれば、新しい部屋を解放できるかもしれない",
  str_item_intro_3300006 = "地下に長く埋もれていたプラグイン。17年前ソラヴァンが失くしたあのプラグインのようだ！これを使えば巨像の中の部屋を解放できる",
  str_item_intro_3400001 = "青色の初級強化箱。水属性の初級覚醒材料をそれぞれ1個獲得できる",
  str_item_intro_3400002 = "赤色の初級強化箱。火属性の初級覚醒材料をそれぞれ1個獲得できる",
  str_item_intro_3400003 = "緑色の初級強化箱。森属性の初級覚醒材料をそれぞれ1個獲得できる",
  str_item_intro_3400004 = "黄の初級強化箱。雷属性の初級覚醒材料をそれぞれ1個獲得できる",
  str_item_intro_3400005 = "青色の中級強化箱。水属性の中級覚醒材料をそれぞれ1個獲得できる",
  str_item_intro_3400006 = "赤色の中級強化箱。火属性の中級覚醒材料をそれぞれ1個獲得できる",
  str_item_intro_3400007 = "緑色の中級強化箱。森属性の中級覚醒材料をそれぞれ1個獲得できる",
  str_item_intro_3400008 = "黄の中級強化箱。雷属性の中級覚醒材料をそれぞれ1個獲得できる",
  str_item_intro_3400009 = "青色の上級強化箱。水属性の上級覚醒材料をそれぞれ1個獲得できる",
  str_item_intro_3400010 = "赤色の上級強化箱。火属性の上級覚醒材料をそれぞれ1個獲得できる",
  str_item_intro_3400011 = "緑色の上級強化箱。森属性の上級覚醒材料をそれぞれ1個獲得できる",
  str_item_intro_3400012 = "黄の上級強化箱。雷属性の上級覚醒材料をそれぞれ1個獲得できる",
  str_item_intro_3400013 = "青色の初級補給箱。水属性の初級覚醒材料をランダムで1個獲得できる",
  str_item_intro_3400014 = "赤色の初級補給箱。火属性の初級覚醒材料をランダムで1個獲得できる",
  str_item_intro_3400015 = "緑色の初級補給箱。森属性の初級覚醒材料をランダムで1個獲得できる",
  str_item_intro_3400016 = "黄の初級補給箱。雷属性の初級覚醒材料をランダムで1個獲得できる",
  str_item_intro_3400017 = "青色の中級補給箱。水属性の中級覚醒材料をランダムで1個獲得できる",
  str_item_intro_3400018 = "赤色の中級補給箱。火属性の中級覚醒材料をランダムで1個獲得できる",
  str_item_intro_3400019 = "緑色の中級補給箱。森属性の中級覚醒材料をランダムで1個獲得できる",
  str_item_intro_3400020 = "黄の中級補給箱。雷属性の中級覚醒材料をランダムで1個獲得できる",
  str_item_intro_3400021 = "青色の上級補給箱。水属性の上級覚醒材料をランダムで1個獲得できる",
  str_item_intro_3400022 = "赤色の上級補給箱。火属性の上級覚醒材料をランダムで1個獲得できる",
  str_item_intro_3400023 = "緑色の上級補給箱。森属性の上級覚醒材料をランダムで1個獲得できる",
  str_item_intro_3400024 = "黄の上級補給箱。雷属性の上級覚醒材料をランダムで1個獲得できる",
  str_item_intro_3400025 = "総合的な初級強化箱。全ての初級覚醒材料をそれぞれ1個獲得できる",
  str_item_intro_3400026 = "総合的な中級強化箱。全ての中級覚醒材料をそれぞれ1個獲得できる",
  str_item_intro_3400027 = "総合的な上級強化箱。全ての上級覚醒材料をそれぞれ1個獲得できる",
  str_item_intro_3400028 = "緊急用の初級補給箱。初級覚醒材料をランダムで1個獲得できる",
  str_item_intro_3400029 = "緊急用の中級補給箱。中級覚醒材料をランダムで1個獲得できる",
  str_item_intro_3400030 = "緊急用の上級補給箱。上級覚醒材料をランダムで1個獲得できる",
  str_item_intro_3400031 = "よく見かける蛍玉の原石。使用するとR1蛍玉をランダムで1個（水、火、雷、森の中から1種類）獲得できる",
  str_item_intro_3400032 = "様々な種類の蛍玉と多様な色彩を持つ共生石。使用するとR1蛍玉（水、火、雷、森）をそれぞれ1個獲得できる",
  str_item_intro_3400033 = "ありふれた蛍玉の原石。使用すると、R2蛍玉をランダムで1つ（水、火、雷、森の中から1種）獲得できる",
  str_item_intro_3400034 = "様々な種類の蛍玉と豊かな色彩を持つ共生石。使用するとR2蛍玉（水、火、雷、森）をそれぞれ1個獲得できる",
  str_item_intro_3400035 = "華やかな色彩を持つ蛍玉の原石。使用するとR3蛍玉をランダムで1個（水、火、雷、森の中から1種類）獲得できる",
  str_item_intro_3400036 = "様々な種類の蛍玉と華やかな色彩を持つ共生石。使用するとR3蛍玉（水、火、雷、森）をそれぞれ1個獲得できる",
  str_item_intro_3400037 = "誰から贈られてきたかわからないギフト袋。中にはなにかしらのプレゼントが入っているらしい。とりあえず開けてみよう\n通常ギフトをランダムで1個獲得できる",
  str_item_intro_3400038 = "突然現れたきれいなギフトパック。いいプレゼントが入っている…はず\n上級ギフトをランダムで1個獲得できる",
  str_item_intro_3400039 = "きれいに包装されたギフトボックス。きっと豪華なプレゼントが入っているに違いない。早く開けてみよう\n使用するとかなり高価な光霊ギフトをランダムで1つ獲得できる",
  str_item_intro_3400040 = "水晶を原材料とし、光力術で補強した透明なボックス。軽くて丈夫。中には貴重な光珀が入っている\n使用すると50光珀を獲得できる",
  str_item_intro_3400041 = "白夜城が発行したコインを保管するための箱。白夜コインが流通するようになってから、この箱もよく見られるようになった\n中には白夜コインが100000枚入っている",
  str_item_intro_3400042 = "微かに光っている透明な水晶箱。中に保存されている光力は、プリズムを満タンまでチャージできる\n使用すると10プリズムを獲得できる",
  str_item_intro_3400043 = "見た目は正方形の水晶の箱。中心が光を放っており、プリズムに比較的多くのエネルギーを供給できる\n使用すると60プリズム獲得できる",
  str_item_intro_3400044 = "大きな水晶から研ぎ出した、華麗な装飾の小箱。プリズムにより多くのエネルギーを回復させる大量の光力を内部に埋蔵している\n使用すると50プリズムを獲得できる",
  str_item_intro_3400045 = "微かに光っている大型の水晶箱。中に保存されている光力は数枚のプリズムをチャージできる\n使用すると60プリズムを獲得できる",
  str_item_intro_3400046 = "かつて光霊連合軍が開発した補給箱。以下の材料からランダムで1つ獲得できる：白夜石、運命のシャンパンⅠ、朝松の露、レディーゼルオイルⅠ、戦闘記録Ⅰ、在りし日の断片、大陸生存術Ⅰ、壮骨散丹。",
  str_item_intro_3400047 = "かつて光霊連合軍が開発した補給箱。以下の材料からランダムで1つ獲得できる：朝光石、運命のシャンパンⅡ、朝松の霜、レディーゼルオイルⅡ、戦闘記録Ⅱ、在りし日の古書、大陸生存術Ⅱ、洗髄霊丹。",
  str_item_intro_3400048 = "かつて光霊連合軍が開発した補給箱。以下の材料からランダムで1つ獲得できる：黎明石、運命のシャンパンⅢ、朝松の泪、レディーゼルオイルⅢ、戦闘記録Ⅲ、在りし日の典籍、大陸生存術Ⅲ、再造金丹。",
  str_item_intro_3400049 = "北境には灯台がそびえ立っている。その灯台が光を放っている限り、暗鬼が極北の地を脅かすことはない。",
  str_item_intro_3400050 = "獲得すると助手-「バイス-通常」が使用可能になる\nバイスの普段着",
  str_item_intro_3400052 = "獲得すると背景-雪の森が使用可能になる\n北境の端に生い茂る、冬は厚い雪に覆われる森。美しい景色だが、しばしば森に迷い込んだ人から方向感覚を奪う",
  str_item_intro_3400053 = "獲得すると背景-極東の道場が使用可能になる\n極東地域では、武術の鍛錬に励む場であると同時に、修身を積み、精神を養う場でもある",
  str_item_intro_3400054 = "獲得すると背景-心に描く空が使用可能になる\n忘れ去られた太古の都市では、この空が人々にとって最大の慰めであった",
  str_item_intro_3400055 = "獲得すると背景-少女たちのステージが使用可能になる\n夏の日、少女たちが共に踊った場所。月日が経っても、あの日と同じ熱い空気が残っている。",
  str_item_intro_3400056 = "獲得すると背景-桜の回廊が使用可能になる\n極東の特徴を存分に捉えた回廊と庭園。桜の季節には趣深い風景を楽しめる",
  str_item_intro_3400057 = "獲得すると背景-軍団長専用列車が使用可能になる\n啓光連邦の軍団長4名が1つの列車に同乗している。恐らく何か重要なことがあったのだろう…",
  str_item_intro_3400058 = "獲得すると背景-オアシスが使用可能になる\nR・Wの主要拠点の1つ。複雑な周囲の地形に守られている",
  str_item_intro_3400059 = "獲得すると背景-四大天使が使用可能になる\n4人の騎士団長は白夜城貴族の強大な力の象徴である",
  str_item_intro_3400060 = "獲得すると背景-夏夜のライブ会場が使用可能になる\n真夏の夜、少女たちが歌い踊った舞台。今でも楽しげな歓声と歌声が響くかのようだ",
  str_item_intro_3400061 = "獲得すると背景-灼熱の牙が使用可能になる\n犬の牙が嚙み合わさるような地形から名付けられた峡谷。非常に険しく、通るのが難しい",
  str_item_intro_3400062 = "獲得すると背景-謎の邸宅が使用可能になる\n由来も所有者も謎に包まれた邸宅。のんびりとした時間を過ごせるようだが…",
  str_item_intro_3400063 = "獲得すると背景-リングシステムが使用可能になる\n古代に由来するエリア。そこには一体どんな秘密があるのだろうか？",
  str_item_intro_3400064 = "獲得すると背景-ハーモナイザーが使用可能になる\n謎の空間、そして謎の力…",
  str_item_intro_3400065 = "獲得すると背景-デュエットが使用可能になる\n覚えている？バイスと一緒にこれを起動させた時のことを…",
  str_item_intro_3400066 = "獲得すると背景-天空ノ谷の巨像が使用可能になる\n巨像が再び天空ノ谷に現れる時、それは何かの予兆なのだろうか？",
  str_item_intro_3400067 = "獲得すると背景-便りを風に乗せてが使用可能になる\n風が届けてくれる便りは、あの空の末裔に「家に帰ろう」と伝えるそうだ",
  str_item_intro_3400068 = "獲得すると背景-静寂の墓地が使用可能になる\n天空ノ谷にあるひっそりとした場所。ここでは時の流れも止まっているかのようだ",
  str_item_intro_3400069 = "獲得すると背景-華やかな『止まり木』が使用可能になる\n天空ノ谷の『止まり木』の装飾が一新された。これから始まる祭りの夜に期待しよう",
  str_item_intro_3400070 = "獲得すると背景-祭りの記憶が使用可能になる\nあれは天空ノ谷で過ごした最初の祭りの夜だった…",
  str_item_intro_3400071 = "獲得すると背景-影ノ街の夜道が使用可能になる\n夜の影ノ街。道は静まり返り、危険な気配が漂い始める。",
  str_item_intro_3400072 = "獲得すると背景-夜霧に躍る影が使用可能になる\n闇と霧に覆われる影ノ街で、人々は一筋の光を取り戻せるだろうか？",
  str_item_intro_3400073 = "獲得すると背景-夜霧に躍る影が使用可能になる\n堂々とした風格の邸宅は、この屋敷の主たる者の富と風雅を存分に体現している",
  str_item_intro_3400074 = "獲得すると背景-雲桜旅館が使用可能になる\n食事と部屋は素晴らしく、温泉も最高です。浴衣の貸し出しもありますよ。",
  str_item_intro_3400075 = "獲得すると背景-ハーバーサイドが使用可能になる\n青空の下でそよ風を楽しむなら、ハーバーシティの港が一番！",
  str_item_intro_3400076 = "獲得すると背景-オーシャンナイトが使用可能になる\nこのような時間が永遠に続くなら、それ以上の人生はないだろう",
  str_item_intro_3400077 = "獲得すると背景-ビーチの危険な遊びが使用可能になる\n降り下ろしたら、ゲームどころじゃなくなっちゃう！",
  str_item_intro_3400078 = "獲得すると背景-教会跡地が使用可能になる\nユーフォリアにある荒れ果てた建物。他と同じで、雨風をしのげるだけの場所である",
  str_item_intro_3400079 = "獲得すると背景-神秘の地が使用可能になる\n名もなき秘密の地に埋もれた、多くの過去と秘密。再び白日の下に晒される日は来るのだろうか？",
  str_item_intro_3400080 = "獲得すると背景-犠牲？が使用可能になる\n押し寄せる暗鬼を前に、選んだのは「犠牲」。だが、それも彼の計画のうちだった…",
  str_item_intro_3400082 = "獲得すると背景-真理の追求が使用可能になる\n大陸の誰もが知る知識を偽りだと考える人々。本当の真理ははるか遠くにあり、彼らがたどり着くのを待っていると言う。",
  str_item_intro_3400083 = "獲得すると背景-巨像のステージが使用可能になる\n「ソラヴァン」の酒場内にあるステージ。設備もそろっており、仲間たちが才能を発揮するのに十分な場を提供している",
  str_item_intro_3400084 = "獲得すると背景-太古の廃都市が使用可能になる\n崩れた巨大建築を眺めているだけで、太古の戦争の壮絶さを感じられる",
  str_item_intro_3400085 = "獲得すると背景-冬空の下でが使用可能になる\nあの光り輝く長剣と風に舞う金色の髪を見かけたら、それはきっと巡行中の北境の女王だ。冬空の下、女王はつぶさに北境の地を見て回っている",
  str_item_intro_3400086 = "獲得すると背景-オーロラの天幕が使用可能になる\n北境でも空いっぱいに広がるオーロラはめったに見られない。そのようなオーロラが現れる時は、不思議なことが起こると言われている…",
  str_item_intro_3400087 = "獲得すると背景-歌声の道が使用可能になる\n巨像内のいたるところが、その少女の姿でいっぱい。希望に満ちた歌声も、大陸全土に降り注ぐだろう",
  str_item_intro_3400088 = "獲得すると背景-蜃風号の甲板が使用可能になる\n高くそびえる船楼を支えられるのは、この巨大で丈夫な甲板だけだ",
  str_item_intro_3400089 = "獲得すると背景-東方の波止場が使用可能になる\nもう1つの大陸に位置する波止場。家屋も船もアストラ大陸とは大きく異なるが、騒がしく、慌ただしい光景は同じだ",
  str_item_intro_3400090 = "獲得すると背景-戦友の反目が使用可能になる\n大元帥とともに戦い、無数の敵を倒してきた戦友が今、彼女に牙を向けている。運命とは、かくも人をもてあそぶものなのだ！",
  str_item_intro_3400091 = "獲得すると背景-R・Wのクーリエが使用可能になる\nR・W砂漠にあるクーリエ隊支部。現地の暮らしにすっかり適応しているようだ",
  str_item_intro_3400092 = "獲得すると背景-イェリアのオフィスが使用可能になる\n日々の業務に取り組む時も、イェリアは自身の個性を存分に表現することを忘れない",
  str_item_intro_3400093 = "獲得すると背景-やすらぎの場所が使用可能になる\nこうした雰囲気の漂う空間は、そこがカフェであろうと、レストランやバーであろうと、誰でも同じように心身ともにやすらぎ、ゆったりとした時間を楽しめる",
  str_item_intro_3400094 = "獲得すると背景-氷雪のウェディングが使用可能になる\n透き通った光り輝く装飾に新郎新婦の姿が映し出される。一切のくもりのない、透き通った空間は2人の純潔な心の表れだ。氷雪に覆われた地の寒さも、2つの熱い心が寄り添うのを妨げることはできない",
  str_item_intro_3400099 = "獲得すると背景-烈火に浮かぶ影が使用可能になる\n真っ赤な悪魔が四方から襲いかかってくる。そこに手を差し伸べる影が…",
  str_item_intro_3400100 = "獲得すると背景-倉庫の奥が使用可能になる\nどこにでもあるような物置にも、知られざる過去が隠されているのかもしれない。",
  str_item_intro_3400101 = "獲得すると背景-アップタウンの景色が使用可能になる\n整然と優雅な「永劫不落」の街は白夜城の中心であると同時に、この大陸の中心とも言える…",
  str_item_intro_3400102 = "獲得すると背景-二人のひと時が使用可能になる\n姉妹がふざけあうひと時の思い出は数千もの昼夜を越えて、今も鮮やかに映る",
  str_item_intro_3400103 = "獲得すると背景-夜に浮かぶ広場が使用可能になる\n白夜城の中央広場は夜になろうと、その輝きを失うことなく、昼のごとく輝き続ける",
  str_item_intro_3400109 = "獲得すると背景-黎明学院が使用可能になる\n白夜城内には光の神の敬虔な信徒を育成する所があり、敬慕の心をもった人々が集まっている。",
  str_item_intro_3400110 = "獲得すると背景-謎の遺跡が使用可能になる\nここは北境の地下にある未知の空間。何やら人工物の装置が今も動いているらしい。",
  str_item_intro_3400111 = "獲得すると背景-静謐な星空が使用可能になる\n星空の下のブリッジで、ひとり眠れぬ夜を過ごす。制御装置の鍵盤には触れず、宇宙から聞こえてくる音楽に耳を澄ます。",
  str_item_intro_3400112 = "獲得すると背景-穏やかな午後が使用可能になる\n白夜城には美しく、あたたかな雰囲気の庭園が多く存在し、貴族らはそこでアフターヌーンティーを楽しんでいる。世界の終わりなど彼らとはまったく関わりないかのようだ。",
  str_item_intro_3400113 = "獲得後、背景-ヤミ診療所が使用可能になる\n簡素な診療所。しかし、この場所には大切な思い出がある",
  str_item_intro_3400114 = "獲得後、背景-薄暗い隅が使用可能になる\n暗闇の中にいても、彼女は再び光を抱きしめたいと願っている",
  str_item_intro_3400115 = "獲得後、背景-おもてなしが使用可能になる\nシェオルに認められた者だけが、この豪華で快適な部屋に泊まれる",
  str_item_intro_3400116 = "獲得すると背景-新大陸が使用可能になる\n蜃風号は見事新大陸に到着した。しかし、それは冒険の終わりを告げるものではない。さらに多くの未知なるものが彼らを待ち受けている。",
  str_item_intro_3400117 = "獲得すると背景-影は、いつもそこにいるが使用可能になる\n邸宅の中でも、シャドウマスターは常に影ノ街を見ている。影は、いつも見つめている。",
  str_item_intro_3400118 = "獲得すると背景-歴史の影が使用可能になる\n封印された過去も、いつかは解かれる日がやってくる。彼は影ノ街を支配する独裁者なのだろうか？それとも影ノ街を救う英雄なのだろうか？",
  str_item_intro_3400119 = "獲得すると背景-応接室が使用可能になる\n適度な明るさの部屋の中には、あらゆる物品と装飾品が整然と並べられている。仕事や接客に使われる部屋である。",
  str_item_intro_3400120 = "獲得すると背景-龍州の要素が使用可能になる\n双閣港の西側は影ノ街が管理しているが、人々の風習などの面では、龍州ならではの魅力を垣間見ることができる。街角や小路に掛けられた提灯から、龍州のおいしい軽食まで、どれも龍州の特徴をはっきりと示している。ここに来る人々は、龍州の文化や習慣を存分に楽しめるだろう",
  str_item_intro_3400121 = "獲得すると背景-双閣港のふ頭が使用可能になる\n龍州大陸から出航する貨物船は、最終的に双閣港のふ頭に停泊する。彼らはそこで品物の売買や交換を行い、再び龍州大陸へ戻る。こうした港は龍州大陸とアストラ大陸を結ぶ航海にとって、重要な役割を果たしていると言えるだろう",
  str_item_intro_3400122 = "獲得すると背景-済の国の春新節が使用可能になる\n春新節は龍州の最も重要な祝日だ。春新節の期間中、王室は宴を開いて貴賓をもてなし、庶民は家族で集まり、ゆっくりと過ごす。そのほか、済の国では縁日も催され、人々は龍女廟に参拝し、年獣を祓って、来る年の安寧と幸運を祈る。一部の商家は祟霊を雇って年獣を祓う儀式を行い、新年の祝い事に花を添える",
  str_item_intro_3400126 = "獲得すると背景-春新節のごちそうが使用可能になる\n龍州では、春新節の夜は団らんの時間だ。龍州の仲間たちは空の末裔の周りに集まり、おいしくて縁起のいい祭りのごちそうを一緒に食べ、彼がすばらしい1年を迎えられることを願っている",
  str_item_intro_3400123 = "獲得すると背景-田園風景が使用可能になる\n浮空島にある荘園は美しい風景に恵まれている。その独特の地理と深い文化的環境は白夜城貴族からひとしお好まれている。貴族らはよくここで散歩し、ゆったりとした時間を過ごす。",
  str_item_intro_3400129 = "獲得すると背景-辺境の洞窟が使用可能になる\n氷と雪に覆われた洞窟の奥は、つららが天井から地面までつながっており、まるで神の彫刻のよう。極光が降り注ぐと、まっすぐにそびえるつららや洞窟の壁の氷紋が不思議な形に固まって、荘厳で凛とした雰囲気を迎える。",
  str_item_intro_3400130 = "獲得すると背景-雪原の片隅が使用可能になる\nどんよりした雪の日、どこまでも続く荒涼たる雪原にも果てがある。高い山の峰が城壁のように遠くにそびえ立ち、世界を隔てている。山麓には雪と氷に覆われた数軒の小さな家が見え隠れしている。ここでの暮らしは、寂しさに満ちているのではなかろうか？",
  str_item_intro_3400133 = "獲得すると背景-地下火山コアが使用可能になる\nこれまで、砂漠を駆け巡るR・Wのメンバーたちもこの地下火山が今も活発に活動しているとは知らなかった",
  str_item_intro_3400134 = "獲得すると背景-デザートナイトが使用可能になる\n永遠に交わることはないだろうと思われていた者たちが今、砂漠の星空の下、膝を突き合わせ座っている。その瞳には、互いの記憶が絡み合いながら、輝いている",
  str_item_intro_3400135 = "獲得すると背景-突撃者号が使用可能になる\nソラヴァンに比べて、その内部構造はよりシンプルでなめらかだ。各制御装置からは危険な雰囲気が漂う。",
  str_item_intro_3400136 = "獲得すると背景-豪快に燃やせが使用可能になる\n反逆と服従、どちらも形の異なる薪にすぎず、十分な温度で火をつければ同じように激しく燃える。",
  str_item_intro_3400138 = "獲得すると背景-聖鳴祭の巡行が使用可能になる\nあなたは真理結社の集合知を体現している。あらゆる経験が、真理結社を未来の道へと導くだろう",
  str_item_intro_3400139 = "獲得すると背景-遺跡の孤島の砂浜が使用可能になる。\nはるか遠い海に、世間から忘れ去られた孤島があった。どこまでも続く紺碧に囲まれた島は、青々とした密林に覆われていた。古い遺跡はこの手つかずの自然の中で、長い年月眠っている。",
  str_item_intro_3400140 = "獲得すると背景-水遊びのひと時が使用可能になる。\n過去を埋蔵したまま沈黙する島、そして新たな夏の冒険が始まる。\nともに行動し、助け合う仲間は、一番の宝物。\n限られた時間の中で、仲間たちと、この果てしない冒険を楽しもう！",
  str_item_intro_3400141 = "獲得すると背景-千年を超える思いが使用可能になる",
  str_item_intro_3400142 = "獲得すると背景-やっとの再会が使用可能になる\n星が帰るべき場所にたどり着いたとき\n彼は歩き出し、太陽の下にいる仲間たちのもとへ向かう",
  str_item_intro_3410101 = "青色の初級注文箱。水属性の初級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410102 = "青色の中級注文箱。水属性の中級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410103 = "青色の上級注文箱。水属性の上級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410104 = "青色の特級注文箱。水属性の特級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410201 = "赤色の初級注文箱。火属性の初級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410202 = "赤色の中級注文箱。火属性の中級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410203 = "赤色の上級注文箱。火属性の上級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410204 = "赤色の特級注文箱。火属性の特級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410301 = "緑色の初級注文箱。森属性の初級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410302 = "緑色の中級注文箱。森属性の中級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410303 = "緑色の上級注文箱。森属性の上級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410304 = "緑色の特級注文箱。森属性の特級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410401 = "黄の初級注文箱。雷属性の初級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410402 = "黄の中級注文箱。雷属性の中級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410403 = "黄の上級注文箱。雷属性の上級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410404 = "黄の特級注文箱。雷属性の特級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410501 = "光霊連合軍製の注文箱。初級勢力覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410502 = "光霊連合軍製の注文箱。中級勢力覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410503 = "光霊連合軍製の注文箱。上級勢力覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410504 = "光霊連合軍製の注文箱。特級勢力覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410601 = "影ノ街商会製の蛍玉注文箱。R1蛍玉を1つ選んで獲得できる",
  str_item_intro_3410602 = "影ノ街商会製の蛍玉注文箱。R2蛍玉を1つ選んで獲得できる",
  str_item_intro_3410603 = "影ノ街商会製の蛍玉注文箱。R3蛍玉を1つ選んで獲得できる",
  str_item_intro_3410604 = "かつて光霊連合軍が使用していたギフトパック。高級な勢力ギフトを1つ選んで獲得できる",
  str_item_intro_3410605 = "終典で功績を残すと獲得できる自分だけの報酬パック。\n各種育成材料をランダムで手に入るほか、低確率で召集星標が入っている",
  str_item_intro_3410606 = "この宝箱は「静かなる猟兵」のメンバーと深い絆を結んだことの証である。開けると中には豪華な報酬が入っている",
  str_item_intro_3410607 = "特殊な構造体の入った宝箱。開くとトモモ1体を獲得できる。",
  str_item_intro_3410608 = "混沌としたカーニバルイベントで獲得できるボックス。中に何が入っているのか分からないが、そこが一番面白い。",
  str_item_intro_3410609 = "特別注文のギフトパック。任意の高級ギフトを1つ選べる",
  str_item_intro_3410610 = "上級注文箱セット。上級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410611 = "特級注文箱セット。特級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410612 = "心珀クラスター・雷、心珀クラスター・水、心珀クラスター・森、心珀クラスター・火から1つを選択できる",
  str_item_intro_3410613 = "初級注文箱セット。初級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410614 = "中級注文箱セット。中級覚醒材料を1つ選んで獲得できる",
  str_item_intro_3410615 = "光霊覚醒3の強化に利用する材料を獲得できる。内容：R2蛍玉・共通×300、白夜コイン×750000、連合軍の初級注文箱×10、連合軍の中級注文箱×10、連合軍の上級注文箱×10、初級注文箱セット×30、中級注文箱セット×50、上級注文箱セット×50、特級注文箱セット×20",
  str_item_intro_3410616 = "苦難だらけのパトロール、危険な追放。これらの行動に報いがないわけではない。今すぐ中にどのような戦利品が入っているか見てみよう！",
  str_item_intro_3420101 = "ワタリが支援し、冒険に加わってくれる。\n「ワタリ」およびワタリを覚醒1Lv10まで強化する全育成材料を獲得できる",
