  str_item_intro_3420135 = "指定の★5光霊リストから1名の光霊を選び、仲間にすることができます。以下の光霊が選択可能です：<color=#ffffff>ベルタ/キャスタ/シエル/サナエ/ロイ/カヤノ/エリカ/ダイナ/ビビアン/ミヤ/ナミシス/レジーナ/ロビン/ファウスト/クレーケン/バートン/キーティン/ルイス/ノーア/ヒドライ/ソルラド/マギー/イスタバン/バーバラ/リオナ/セファー/オティ/フィリス/ワタリ/ベニ&クロ/クスッタ/アイリーナ/スカーレイ/バーバリー/タキ/ジュヌヴィエーヴ/ナルセール/カーティ/キア/クリステン/ブラン・洗心/ジョセリン/イーサ/テンカン</color>。",
  str_item_intro_3420130 = "指定の★6光霊リストから、1名の光霊を選び、仲間にすることができます。以下の光霊が選択可能です：<color=#ffffff>ビクトリア/ラファエル/クラリン/ウリエル/ガルー/カロン/カレン/サメヤマ/キシローナ/ガブリエル/ナシリス/イブ/ジョナ/ミカエル/ラス/イルンティ/シャリー/エルシー/ミジャード/ヒイロ/ベリエ/フェラール/スモーキー/レビィ/グラム/パロマ/ベセル/ルーク/ヘイディ/ノーヴィオ/シヴォーン/フロリナ/ルビー/リンネ/アメモリ/ヨウ/アズール/レノーア/ギルス/バートン・鋭刃/ニナ/カレン・照魂/フィア/ジェノ/ポルクス/リリカ/ミノス/アクセリア/ヴィック</color>\n注意：2周年記念特選召集ボックスは使用期限を過ぎると3000光珀に変換され、ゲーム内メールにて送付されます。使用期限は2023年8月31日18:00です。期限までにご使用ください。",
