  str_item_intro_3430103 = "「ヒドライ」、「イスタバン」、「ビビアン」、「ルイス」から1人を選んで獲得できる。さらにその光霊を覚醒1Lv10まで強化する全育成材料も獲得できる",
  str_item_intro_3440001 = "激ウマビターチョコ、光珀、光霊のランダム育成材料を獲得できる",
  str_item_intro_3440002 = "ハッピーキャンディー、光珀、光霊のランダム育成材料を獲得できる",
  str_item_intro_3440003 = "「蜃風号」で一緒に「春新節」を過ごした際に、船長のユエが皆に配ったお年玉。中には、いったいどんなサプライズが入っているのだろう？",
  str_item_intro_3440005 = "光珀、光霊のランダム育成材料を獲得できる",
  str_item_intro_3500001 = "古代遺跡で見つかった神秘的な物質。不思議な力を宿している。装備改造の必須材料",
  str_item_intro_3500003 = "光霊を覚醒2Lv1にできる。\n不思議な古代の遺物。太陽のような眩しさを放つ謎の物質が入っており、光霊の能力を最大限に高められる",
  str_item_intro_3511001 = "水属性の啓発レベルを上げるのに使用する\n啓発者が提供する謎の立方体。石版に跡を残すことなく埋め込み、起動させることができ、啓発訓練中の瞬間的な場面を具現化できる",
