  str_item_intro_3513001 = "森属性の啓発レベルを上げるのに使用する\n啓発者が提供する謎の立方体。石版に跡を残すことなく埋め込み、起動させることができ、啓発訓練中の瞬間的な場面を具現化できる",
  str_item_intro_3513002 = "森属性の啓発レベルを上げるのに使用する\n啓発者が提供する謎の立方体。石版に跡を残すことなく埋め込み、起動させることができ、啓発訓練中の断片的な場面を具現化できる",
  str_item_intro_3513003 = "森属性の啓発レベルを上げるのに使用する\n啓発者が提供する謎の立方体。石版に跡を残すことなく埋め込み、起動させることができ、啓発訓練中の特定の場面を具現化できる",
  str_item_intro_3513004 = "森属性の啓発レベルを上げるのに使用する\n啓発者が提供する謎の立方体。石版に跡を残すことなく埋め込み、起動させることができ、啓発訓練中の重要な場面を具現化できる",
  str_item_intro_3513005 = "森属性の啓発レベルを上げるのに使用する\n啓発者が提供する謎の立方体。石版に跡を残すことなく埋め込み、起動させることができ、啓発訓練中の肝心な場面を具現化できる",
  str_item_intro_3514001 = "雷属性の啓発レベルを上げるのに使用する\n啓発者が提供する謎の立方体。石版に跡を残すことなく埋め込み、起動させることができ、啓発訓練中の瞬間的な場面を具現化できる",
  str_item_intro_3514002 = "雷属性の啓発レベルを上げるのに使用する\n啓発者が提供する謎の立方体。石版に跡を残すことなく埋め込み、起動させることができ、啓発訓練中の断片的な場面を具現化できる",
  str_item_intro_3514003 = "雷属性の啓発レベルを上げるのに使用する\n啓発者が提供する謎の立方体。石版に跡を残すことなく埋め込み、起動させることができ、啓発訓練中の特定の場面を具現化できる",
  str_item_intro_3514004 = "雷属性の啓発レベルを上げるのに使用する\n啓発者が提供する謎の立方体。石版に跡を残すことなく埋め込み、起動させることができ、啓発訓練中の重要な場面を具現化できる",
  str_item_intro_3514005 = "雷属性の啓発レベルを上げるのに使用する\n啓発者が提供する謎の立方体。石版に跡を残すことなく埋め込み、起動させることができ、啓発訓練中の肝心な場面を具現化できる",
  str_item_intro_3621001 = "クッションのついたハイバックチェア。背中全体でもたれかかるだけでなく、頭を背もたれに乗せて居眠りすることもできそうだ",
  str_item_intro_3621002 = "1人で腰かけるのに適したソファー。背もたれがないため、もたれかかることはできない。ローテーブルを一緒に置いた方がよさそうだ…",
  str_item_intro_3621003 = "2人同時に座れる大きめのソファー。もちろん1人で寝転がっても問題ない…",
  str_item_intro_3621004 = "珍しいロングソファー。4人一緒に座れる。パーティーでの使用に最適",
  str_item_intro_3621005 = "六角形のローテーブル。飲み物、ティーポット、コップ、お菓子の皿などを置くのに使う。小規模なパーティーを開く部屋に置くとよい",
  str_item_intro_3621006 = "長方形のローテーブル。2人用のソファー、4人用のソファーと組み合わせるのに適している。大規模なパーティーを開く部屋に置くとよい",
  str_item_intro_3621007 = "自動で飲み物を作ってくれる機械。当然だが、どの飲み物を作るかは中に入れた原料次第。例えば、インスタントコーヒーを入れればブラックコーヒー、角砂糖を入れれば普通の砂糖水が出てくる…",
  str_item_intro_3621008 = "ある集落で使われていた太鼓のような楽器から進化したもの。影ノ街から流行が発祥した。通常は1つの大太鼓、複数の中太鼓、シンバルで構成されている。演奏内容により、他の打楽器を加えることもあるが、どれほど多くの楽器を組み合わせても1人で演奏する",
  str_item_intro_3621009 = "小さな植木鉢に植えられた背の低い植物。部屋に緑を加え、空気を浄化してくれる",
  str_item_intro_3621010 = "人の背丈ほどある大きな鉢植え。空気を浄化できるだけでなく、部屋のインテリアとして自然の色彩を加えてくれる。いざという時には身を隠すのにも役立つかも…",
  str_item_intro_3622001 = "細かく丁寧に描かれた風景画。壁にかけると、室内に居ながらにして各地の美しい景色を楽しめる",
  str_item_intro_3623001 = "裏側を天井にぺったりと貼りつけられる照明。太陽のような形をしており、照明範囲が広く、ほとんど死角がない。そのため、「太陽灯」と呼ばれている",
  str_item_intro_3623002 = "鉄の棒で吊るし、天井に取り付ける照明。軽くて取り付けが簡単。さらに様々な飾り付けができるので、幅広い用途で使える",
  str_item_intro_3623003 = "部屋に冷たい風を吹かせる装置。啓光連邦でシェルターの風通しを良くするために使われていた機械が始まりらしい。その後、人々はこの機械の別の機能――部屋を涼しく快適にできることに気付いた",
  str_item_intro_3623004 = "天井に取り付ける照明。省エネ、省スペースで広範囲を照らせるため、多くの都市で使用されている",
  str_item_intro_3623005 = "天井からつるされた照明器具。錠締め構造のため調整が簡単だが、地震や突風が起こるとグラグラと揺れ、大変危険だ。このため船舶での使用は禁止されている",
  str_item_intro_3631001 = "外国の品。大海原を征服した船団が極東から持ち帰った豪華な調度品。きめ細かい手触りの質感とエレガントな配色が特徴。ただし、壊れやすいので設置する時は要注意",
  str_item_intro_3631002 = "太陽の形をした聖像。荘厳で迫力がある。部屋の隅に静かに立たせておくだけでも、思わず拝みたくなるだろう",
  str_item_intro_3631003 = "有名な職人が作った大樽。華やかな見た目をしている。豪華な装飾に釣り合うのは年代物の高い酒だけだろう",
  str_item_intro_3631004 = "このタイプの家具は極東が起源と言われている。風よけ、仕切り、目隠しの機能があり、部屋の飾り付けや美化にも使える。さらに部屋の主のミステリアスな雰囲気も演出可能だ。そのため、アストラ大陸の各都市であっという間に流行り出した",
  str_item_intro_3631005 = "金色の巨大なアストロラーベ。様々な宝石がはめ込まれ、星の位置を表している。占星術に熟達した学者が素早く星占いを行うのに使う。ただし、精度は…",
  str_item_intro_3632001 = "啓光の製品。以前はシェルター間の通信に使われていた。交流が活発になるにつれ、他の都市でも徐々にこのような最先端のコミュニケーションデバイスを使うようになった。",
  str_item_intro_3632002 = "普段は白夜城で式典を開催する時に置かれる。華やかな装飾が施された金杯。ある特殊な光力術が付与されており、翼のような動く幻影を生み出せる",
  str_item_intro_3632003 = "このレリーフは白夜城に伝わる古い文明を象徴しており、どの模様にもたくさんの物語が詰まっている。それらを見るたびに、悠久の歴史へと思いを馳せることができる…",
  str_item_intro_3632004 = "この燭台は特殊な光力術によって強化されており、どれだけ時が経とうと煙や煤で黒くなることはない。しかも、ロウソクは独りでに点灯、消灯できる",
  str_item_intro_3632005 = "啓光の機械技術と白夜城の職人のハイレベルな構想によって作られた豪華な掛け時計。この掛け時計にとって、時間を知らせることは副次的な役割でしかない。主な用途はインテリアなのだ",
  str_item_intro_3641101 = "白夜城の貴族たちの伝統的な調度品。特に武を貴ぶ家では必ずと言っていいほど甲冑を飾っている。それは単なる調度品ではなく、ある種のシンボルにもなっているのだ。さらに一族の子孫に対し、武を貴ぶ気構えを忘れて堕落してはならないと戒める役割を担っている",
  str_item_intro_3641201 = "影ノ街の風雅な人物が愛する調度品。高価な木材で作られ、著名な書物や名器などが置かれている。だが、これらの骨董品が本物かどうかは謎だ…",
  str_item_intro_3641301 = "啓光の製品。ライフルを置くスタンド。部屋の中に置くと、戦場にいるような気がする。暗鬼に立ち向かう主要勢力だけあって、家具も軍事的色彩が濃い。従来の2タイプのデザインに比べ、重心のバランスが取れているだけでなく、全体の重量が大幅に減った",
  str_item_intro_3641501 = "ミニチュアサイズにした自動車の模型。たくさんのパイプ、リベット、溶接された金属板の他に、木材まで取り付けられており、寄せ集め感が半端ではない。見るからにR・Wのオープンカー「フォース」がモデル",
  str_item_intro_3641102 = "豪奢な布地に繊細な織物技術、これこそ白夜城の職人の手によるじゅうたん。とても一般人の手に届くものではない。金銭的な価値だけでなく、高貴な身分の象徴でもある",
  str_item_intro_3641202 = "影ノ街で作られる大きな黒い絨毯。縫い目が細かく、柔らかくて厚みがある。足で踏んでもほとんど音がしない",
  str_item_intro_3641302 = "真四角のじゅうたん。きっちりと組まれた縦糸と横糸は、啓光連邦の強い製造力の証だ。一目見てカナン城の工場の製品であることが分かる。耐久性に優れている",
  str_item_intro_3641402 = "とても厚い絨毯。北境で生産される綿と、動物の毛を大量に使って作られている。どんなに寒い環境でも、床から伝わる冷気を遮断してくれる",
  str_item_intro_3641502 = "R・Wの荒くれ者どもが古びた服を適当に縫い合わせて作ったものだろう…かすかにレディーゼルオイルのにおいがするのは、それで染色したからに違いない。大枚をはたいてこれをわざわざ家に置く人なんているのだろうか？",
  str_item_intro_3641602 = "とても人目を惹く赤い絨毯。その模様は見落とされがちだが、注意して見てみると、絨毯の縫い目がかすかに動いているようだ。見ているうちに不思議と胸騒ぎがしてくる。本当にこのような絨毯を気に入る人がいるのだろうか…",
  str_item_intro_3642102 = "家具。巨像のルーム内に設置できる。\n白夜城の名も知れない画家の傑作。本物はある大貴族が所有しており、これは複製品。見る者の心になぜか安らぎを与える卓越した絵画の技術が注目され、しぜん多くの摸写作品も出回った。これもそのうちの一つである。高価ながら購入希望者が絶えない。",
  str_item_intro_3642201 = "様々な地下勢力がしのぎを削る影ノ街。仲裁ができない場合はこの二振りのレイピアの出番となる。当事者双方がそれぞれ1名剣客を派遣し、決闘で最後の裁きを下すのだ",
  str_item_intro_3642301 = "啓光のインテリアは軍事的色彩が濃い――壁に何かを飾ろうとした時、彼らが最初に思いつくのはこのライフルだ。啓光の人間は本当にいかなる時も戦いの準備を忘れないようだ",
  str_item_intro_3642401 = "家具。巨像のルーム内に設置できる。\n氷と雪に覆われた北境にあっても、この植物は四季を通じて青々とした葉を茂らせている。そのため、北境の人々はこれを希望と豊饒の象徴と捉え、「ヤドリギのない所に幸福は訪れない」と讃える。また、北境の人々はよくヤドリギを採集してリースに編み、幸運をもたらすものとして家の中に飾っている",
  str_item_intro_3641103 = "家具。巨像のルーム内に設置できる。\n白夜城の王侯貴族の権力を象徴するもの。全体が貴金属で作られ、華やかな装飾が施されている。権力の魅力だけでなく、その重みも象徴している。",
  str_item_intro_3641503 = "鋼材やトタン、釘などさまざまな廃材をつなぎ合わせて出来ている。どこから持ってきたのか、マットも敷かれていて、ボロボロではあるが、座ればそこそこ柔らかく、意外に丈夫である",
  str_item_intro_3651001 = "尖塔のミニチュアモデル。強い質感があり、デザインも細部まで再現されている。尖塔の中に封印されている力を与えてくれるかのようだ",
  str_item_intro_3651002 = "尖塔をそのまま小さくしたかのような、本物そっくりの置き物。近づくと尖塔の中にある古き神秘の力を感じることができる",
  str_item_intro_3651003 = "尖塔の上層階を探索した者のみが手に入れられる装飾品。見た目がそっくりなだけでなく、尖塔の力の一部も封印されている。これを見た者は、まるで本物の尖塔の前に立っているような感覚を覚える",
  str_item_intro_3651004 = "尖塔を探索した者だけが手にすることのできる極めて珍しい記念品。模型だが、その形状は尖塔と瓜二つで、よく見ると尖塔の構造の細部までもがきちんと再現されているのが分かる。これがあれば本物の尖塔にも影響を与えることができるという噂だ…",
  str_item_intro_3651005 = "尖塔から「贈られた」記念品らしい。尖塔を隅々まで探索しないと獲得できない。尖塔の意志と探索者に対する賞賛を表しているのだろう",
  str_item_intro_3651101 = "秘境の中で見つかった暗鬼のミニチュアモデル。他の探索者が残した記念品だろう。動かないし、暗鬼の恐ろしいオーラもないので、恐怖を感じることはない。慣れてしまえばかわいく思えるかも…",
  str_item_intro_3651102 = "秘境の奥地で発見された模型。とある上級暗鬼の彫像のようだ。その怖ろしい顔つきは例え動かなくても恐怖を与えるのに十分。慣れてしまったのなら、家のどこかに置いてコソ泥を脅かすのに使ってみるのも悪くないかもしれない…",
  str_item_intro_3651201 = "極めてレアなミニチュアモデル。見た目は「ソラヴァン」そっくり。ナビゲーターの仲間が自分たちの光力術を集め、「ソラヴァン」の秘密技術によって作られたもの。彼らとナビゲーター、そして「ソラヴァン」の固い絆を表している",
  str_item_intro_3662001 = "暗鬼の追撃から逃れた後、皆との初めての出会いを記録するため、ソラヴァンは録画をもとにして蛍灯にこの絵を描かせた。当時の光景を忠実に再現しているため、見る人はみんな写真だと思っている",
  str_item_intro_3661101 = "赤眼谷で見つかった岩石。火山の力を宿しており、触るととても熱い。たまに小さな「爆発音」を発したり「小噴火」を起こしたりするが、全体的に見れば無害なものだ。度胸のある人はこれで米を炊いたり、肉を焼いたりするかもしれない",
  str_item_intro_3661102 = "ドーンが赤眼谷で栽培している白い花。数年に一度だけ花を咲かせ、花びらがとても美しい。花言葉は「夜明けの希望」",
  str_item_intro_3662101 = "病気のため、イブは一度に15℃程度の水か45℃程度のお湯しか飲めない。水が不足するR・W砂漠では、サメヤマは妹がいつでも水が飲めるよう、常にこの2つの魔法瓶を持ち歩いている。表面には笑顔が描かれ、妹の心を慰めている",
  str_item_intro_3661103 = "道館はもうなくなってしまったが、刀架の状態は良好だ。埃を払って刀を載せれば、栄角道館の往年の輝きの一部を目にすることができる",
  str_item_intro_3661104 = "雲山一帯でのみ見られる希少な桜の木で、とても鮮やかな色をしている。人々はおみくじをこの木に結び、願い事が叶うよう祈る",
  str_item_intro_3662102 = "異国情緒溢れる絵画。爪と牙をむき出しにした大きな龍が描かれているが、見る者に威圧感は与えず、むしろ何とも言えない安心感すらある。もしかしたら極東独自の文化と関係があるのかもしれない",
  str_item_intro_3661105 = "雲山地区で人気のおもちゃ。家に置くと幸運がもたらされるという。もしかしたら持ち主の願い事を叶えてくれるかも",
  str_item_intro_3661106 = "怖ろしい見た目のだるま。家に置くと凶運を退け、悪人がやってくるのを防いでくれるという",
  str_item_intro_3661107 = "時々金色に光るだるま。このだるまを見ていると、すぐにお金持ちになれそうな気になる。なれるといいな",
  str_item_intro_3661108 = "学識を司るというだるま。合格祈願にと大勢の受験生がこれを求める。カナン城に持って行ったら、きっと高く売れるだろう",
  str_item_intro_3661109 = "伝説によれば、人はそれぞれに一番相応しいだるまに必ず出会えるという。そのだるまは願い事を叶え、あなたを一生守ってくれるとか",
  str_item_intro_3661110 = "家具。巨像のルーム内に設置できる。\n誇張されたデザインをした海辺の城の模型。神秘的で怪しげな雰囲気を保っている。時折、かすかな悲鳴のような音が聞こえ、古くからそこに伝わる伝説を思わず連想させる",
  str_item_intro_3661111 = "家具。巨像のルーム内に設置できる。\nフェラールはソラヴァンの技術を参考にして大型ロボット「レディーゼルエンジン・メカレンチVゼロ号機」を作った。これはその模型。本物に比べて性能は大幅に向上しており、パーフェクトと言えるだろう。とても小さいことを除いては。",
  str_item_intro_3661112 = "家具。巨像のルーム内に設置できる。\n臨時収入を稼ぐために作ったワゴン。特別な機械で氷を作り、かき氷にして販売する。猛暑の夏に涼しさを与えてくれる。営業は終了したが、ワゴンの機材はまだ使える。時折、「まだまだ現役」だと言わんばかりに、勝手に動き出す。",
  str_item_intro_3661113 = "家具。巨像のルーム内に設置できる。\n「ホテル・フルートプラチナ」のエアソファー。背面にウォーターガンが備えられており、定期的に水を噴射して暑い夏に涼しさを与えてくれる。",
  str_item_intro_3661114 = "家具。巨像のルーム内に設置できる。\n「ホテル・フルートプラチナ」のエアソファー。クッションの後ろに噴射装置があり、定期的に噴水のように水を噴射する。とても涼しいが、噴射の勢いが強すぎるため、座っている人を驚かすこともしばしば。",
  str_item_intro_3661115 = "家具。巨像のルーム内に設置できる。\n「ホテル・フルートプラチナ」のエアソファー。背面に自動花火打ち上げ装置がついているため、持ち運びには要注意。装置が起動すると、カラフルな花火が打ち上げられ、ちょっとした花火ショーを楽しめる。座っている人が花火で怪我をすることはないが、打ち上げ角度の関係で、びっくりさせてしまうかもしれない。",
  str_item_intro_3661116 = "家具。巨像のルーム内に設置できる。\n「ホテル・フルートプラチナ」のエアソファー。両側の肘掛がバブルマシンになっている。起動させると、周囲にカラフルなシャボン玉が舞い始める。子供たちには大好評。",
  str_item_intro_3661117 = "家具。巨像のルーム内に設置できる。\n「ホテル・フルートプラチナ」のウォーターソファー。持ち運びに便利。広げると付属品のヤシの木を飾れる。中に水を入れて座ると、ビーチに来たような気分を味わえる。",
  str_item_intro_3661118 = "家具。巨像のルーム内に設置できる。\n「ホテル・フルートプラチナ」のサーフボード。特殊な材質で作られ、軽量さ、耐久性、強度に優れている。流線形に富んだデザインをしており、サーファーにはうってつけ。",
  str_item_intro_3662103 = "家具。巨像のルーム内に設置できる。\n「潮汐祭」の記念の品。描かれている青い海と青い空、砂浜と緑の木々を見ると、再びビーチに戻ったかのような気分になり、楽しかった日々を再体験できる。",
  str_item_intro_3661119 = "家具。巨像のルーム内に設置できる。\nシェルター24号は熱砂防衛線の重要拠点の一つ。熱砂防衛線全体の後方支援、新兵訓練、医療などの役割をほぼ網羅している。このミニチュア模型は、それらの機能を完璧に再現している。",
  str_item_intro_3661120 = "家具。巨像のルーム内に設置できる。\n啓光連邦士官学校で使われる演習用ジオラマ。測量の専門家が実地で測量と製図を行い、等倍に縮小して粘土、砂、木材、小型模型で作った地図。戦場の環境を再現し、士官候補生たちが戦いの指揮をとるための演習を行える。",
  str_item_intro_3661121 = "家具。巨像のルーム内に設置できる。\nたくさんの穴が開いた鉄の板でできている。かつて「勇士別働隊」が暗鬼と戦った際に残した証しであり、彼らの誇りでもあるようだ。勲章が掛けられており、「勇士別働隊」は遠く離れることなく、熱砂防衛線で他の戦士たちとともに暗鬼と戦っているという想いが込められている。",
  str_item_intro_3662104 = "家具。巨像のルーム内に設置できる。\n熱砂防衛線の守備軍が暗鬼の大規模侵攻を防いだことを称え、啓光連邦から特別に授与された軍旗。防衛線の守備兵はこれを目にするたびに名誉を感じ、「自分のいる場所こそが防衛線」という信条を思い起こす。",
  str_item_intro_3661122 = "ここに死者は埋葬されておらず、「墓標」とは呼べないのでご安心を。えっ？あの手は何かって？大丈夫大丈夫、ただの演出だ",
  str_item_intro_3661123 = "白夜コインをあげないと現れるよ！わかったよ。こいつは喋らないし、本物の幽霊ではないんだ。実はシーツを被ったニワトリなんだ～",
  str_item_intro_3662105 = "木材をつなぎ合わせてカボチャの形にしたランプ。顔の部分の「目」、「鼻」、「口」から光が出て照らしてくれる。とても不気味な感じがする",
  str_item_intro_3661124 = "高くそびえる白い塔は天空ノ谷の象徴。頂上は真っ直ぐで、すべて白色。白い塔の姿を完璧に再現しており、真に迫った精巧な模型",
  str_item_intro_3661125 = "空の末裔の少年のフィギュア。床に置くと可愛らしく見える。しかも蛍灯たちの人気者のようだ",
  str_item_intro_3661126 = "タンポポを植えた鉢植え。花はとても繊細に見えるが、水と土さえあれば生きていけるタフな植物",
  str_item_intro_3661127 = "家具。巨像のルーム内に設置できる。\nこれは本当に模型だろうか？世界をそのまま小さくしたようだ！実際に動く列車だけでなく、山や川、植物など自然景観もそっくりそのまま。模型の列車が山をぐるぐる走る様子を見ているだけで、自分も実際に列車に乗って、絶景を眺めている気分になれる。",
  str_item_intro_3661128 = "家具。巨像のルーム内に設置できる。\nまさか秋の樹木まで巨像に持ち込むとは…どういう原理なのかは知らないが、この鉢植えは今だ秋の色を保っている。時おり黄色くなった葉っぱがひらりと落ち、いつでもどこでも秋のどこか物悲しい気分を味わえる。清掃係泣かせなのが、玉に瑕だが。",
  str_item_intro_3661129 = "家具。巨像のルーム内に設置できる。\n永遠に太陽に向かい続ける花！見ているだけで向上心が湧いてくる。これを置いておけば、部屋中暖かい空気に包まれる。",
  str_item_intro_3661130 = "家具。巨像のルーム内に設置できる。\n栄誉を表すチャンピオンベルト。影ノ街の「地下闘技場」で汗にまみれ、痛みをこらえて戦った証だ。軽々しく触ってはならない。遠くから見るだけにしよう。",
  str_item_intro_3661131 = "家具。巨像のルーム内に設置できる。\n合理的な取り引きは、当事者双方にとって公平だ。物を量る道具である、この金の天秤は取り引き双方が認める公正さの象徴だ。そのため、影ノ街の商会では、よくホールに飾られ、その商会の取り引きが公正であり、不正のないことを訪れる者に告げている。",
  str_item_intro_3662106 = "家具。巨像のルーム内に設置できる。\n舶来品。扇面は軽くて柔らかいにもかかわらず、丈夫な紙で出来ており、そこに描かれた趣ある絵は異国情緒に満ちている。",
  str_item_intro_3662107 = "家具。巨像のルーム内に設置できる。\n白夜城の職人がその卓越した技術で色とりどりのガラスをつなぎ合わせ、完成させた絵。光が差し込むと、きらびやかで美しい色彩に目を奪われる。",
  str_item_intro_3661132 = "家具。巨像のルーム内に設置できる。\nかつては氷の龍が北境上空を見張っていたといわれる。しかし、この「龍」にそのような脅威ではなく、彫像として室内に飾ることができる。しかも部屋の空気がひんやりするので、なかなかの優れものだ",
  str_item_intro_3661133 = "家具。巨像のルーム内に設置できる。\nとてもシンプルな作りのハンガーとマントだが、北境の老人たちによると、その裏には、ある不思議な物語があるという",
  str_item_intro_3661134 = "家具。巨像のルーム内に設置できる。\n北境の民の言い伝えでは、これを履くと男女を問わず真実の愛を見つけられるという",
  str_item_intro_3661135 = "家具。巨像のルーム内に設置できる。\n北境で最もよく見られる家屋の模型。屋根には真っ白な雪が積もっている。煙突から時おり立ち上る白い煙と窓に映る揺れ動く灯は、まるで小人が本当に中で暮らしているかのようだ",
  str_item_intro_3662109 = "家具。巨像のルーム内に設置できる。\n一見シカの頭のようだが、剥製ではないので部屋に置いても怖くはない。北境の民が毛皮と木材で作った装飾品で、中には特別な仕掛けが施されており、時おり目が動く",
  str_item_intro_3661136 = "家具。巨像のルーム内に設置できる。\n料理で愛情を伝えるなら、自身の一部を調理するのが一番！？トールは自分の尻尾の味にとても自信があり、サシの入り方と味わいは、通常の食材をはるかに上回っているという。火加減の上手いトールの作る尻尾焼きは絶品ではあるが、毒があるので注意。",
  str_item_intro_3661137 = "家具。巨像のルーム内に設置できる。\nトールが気まぐれで造ってみた木彫りの置物。ドラゴンからすると、人の造る「芸術」はモチーフも創作方法もあまりに簡単すぎて理解しがたい。この置物も他人の作品をまねて造っただけで、意味はよく分かっていない。しかし、誰かに気に入ってもらえるのなら、それで十分だ。",
  str_item_intro_3662110 = "家具。巨像のルーム内に設置できる。\nせっかく遊びに来たんだから、写真を撮ろう！ほら、皆もっと近づいて！1枚にドラゴン5匹はなかなか窮屈だけど…じゃあ、撮るよ、ハイッ、チーズ！",
  str_item_intro_3661138 = "家具。巨像のルーム内に設置できる。\n忘れ去られた都市で発見されたピアノ。アストラ大陸のものと似た様式だが、不思議な材質で造られており、長い歳月が経ってなお、美しい音色を響かせる。衝撃で一部の音がずれても、独自の内部構造により調律が可能。音楽家にとっては、非常に貴重な宝である。",
  str_item_intro_3661139 = "家具。巨像のルーム内に設置できる。\n非常にシンプルなデザインながら、啓光のこだわる「素朴」さとは異なったスタイル。光沢ある特別な材質と美しい外観は、白夜城の好みにも合いそうだ。",
  str_item_intro_3661140 = "家具。巨像のルーム内に設置できる。\n忘れ去られた都市で発見された絨毯（じゅうたん）。きわめて特殊な材質で出来ており、交差する糸が織りなす菱形模様は人々の目を引き付ける。忘れ去られた都市のかつての住民たちの美的感覚は、他とは少し異なっていたようだ。",
  str_item_intro_3661141 = "家具。巨像のルーム内に設置できる。\n街灯よりも多いのではと思えるほど、忘れ去られた都市の至る所に設置されている。道路標識として使えるのではないかとさえ思えてしまう…パネルにはさまざまな模様が描かれ、絶えず点滅しており、一体何のためのものなのかは不明。中を開いて見ないと分かりそうもない。",
  str_item_intro_3661142 = "家具。巨像のルーム内に設置できる。\n忘れ去られた都市にあった郵便ポスト。表面に書かれた文字はすでに読めなくなっている。当初、緊急用の食糧を蓄えておく小型貯蔵庫の類かと思われたが、中に手紙が入っていたことから、郵便ポストだと判明した。しかし、今はもう投函する者もいないだろう。",
  str_item_intro_3661143 = "家具。巨像のルーム内に設置できる。\n忘れ去られた都市でよく見かけるベンチ。多くは道端に設置されており、道行く人が足を休めるためのものだろう。持ち帰れば、座るだけでなく、寝ころんで居眠りもできそうだ。",
  str_item_intro_3661144 = "家具。巨像のルーム内に設置できる。\n長い年月が経っているというのに、まだ壊れていないとは！忘れ去られた都市の技術は、やはり不思議だ。紙を入れると、何本もの細かいテープ状にカットされ、書かれていた文字が読めなくなってしまう。秘密保持の意識が高い人たちだったようだ。",
  str_item_intro_3661145 = "家具。巨像のルーム内に設置できる。\nこんなにも長い年月が経っているというのに、完全な姿を留めている…ただ、使っていた人はもはやいないだろう。掃除をすると、きれいな上面と、そこに並べられたさまざまなオフィス用品が姿を現した。ここに座っていた人のやる気が見えるようだ。",
  str_item_intro_3661146 = "家具。巨像のルーム内に設置できる。\nこの不思議なイスはどの方向にも動けるだけでなく、高さを調整することができ、背もたれを倒して、一休みすることもできる。色調はデスクと調和しており、一緒に並べれば時間を忘れて仕事に打ち込めそうだ。",
  str_item_intro_3661147 = "家具。巨像のルーム内に設置できる。\n極東地域で見られる庭飾りで、竹で作られている。水の力で動き、一定の間隔で「カコーン」と切れの良く清々しい音を立てる仕掛け。時計代わりにもなるかも？",
  str_item_intro_3661148 = "家具。巨像のルーム内に設置できる。\n大きな竹の盆栽。成長が速いため、頻繁に剪定を行う必要がある。手はかかるが竹材を大量に手に入れることができ、竹の葉が風に吹かれた時に出す「サラサラ」という音には、なんとも言えない趣がある。",
  str_item_intro_3663001 = "家具。巨像のルーム内に設置できる。\nドアや窓の外に吊るす人形。簡単に作れるが、とても可愛らしい。風に揺られ、宙に踊る様子は、本当に晴天を祈っているかのようだ。もし空が晴れたなら、それはきっと、空が人形たちのダンスを見てくれたのだろう。",
  str_item_intro_3661149 = "家具。巨像のルーム内に設置できる。\n極東の武士たちが被る兜。目を見張る飾りものが多い。その武士の属する勢力や家を表すだけでなく、栄誉の象徴でもあるらしい。",
  str_item_intro_3661150 = "家具。巨像のルーム内に設置できる。\n元は兵士や武士たちが戦闘の時、背中に挿していた旗。後に続く軍を導く役割も果たしていた。室内にこれを飾れば、気分が引き締まる。",
  str_item_intro_3662111 = "家具。巨像のルーム内に設置できる。\n極東の人々に好まれている書道の手本集。通常、書道の大家が筆を執るが、当然ほとんどは臨模作品、すなわち書き写し。手本集に載っている文字は極東で特別な美を持つものとして愛でられているが、それ以外の地域の人々にとっては、その美的感覚はなかなか理解しがたい。",
  str_item_intro_3661151 = "家具。巨像のルーム内に設置できる。\n「山水」とは言うものの、「枯」の字が表すように、水はなく、代わりに細かい砂が水、石が山を表している。極東では、このような静止した変わることのない景観は心を静める効果があり、瞑想に良いとされる。",
  str_item_intro_3661152 = "家具。巨像のルーム内に設置できる。\n雲島の至る所で見られる街灯。極東風の装飾が施されている。この地の人々にとっては単なる照明ではなく、標識としての意味合いもある。",
  str_item_intro_3663002 = "家具。巨像のルーム内に設置できる。\n江富城の人々が好んで使う提灯。普段は出入り口に吊るして照明として使い、立ち並ぶ家々に吊るされた提灯が道を昼間のように明るく照らす。外して竹竿に掛け、夜道を歩く際の照明具として使うこともできる。",
  str_item_intro_3661159 = "家具。巨像のルーム内に設置できる。\nカレンが騎士の称号を授けられた時に贈られたランス。カレンと生死を共にし、彼女になくてはならない武器となっている。これは本物ではないが、室内に飾っておけば、「月繭」の威光を感じることができる…",
  str_item_intro_3662116 = "家具。巨像のルーム内に設置できる。\n自称「有名」プロデューサーであるツアードッグのお気に入り。家の中に吊るせば、拍子木のぶつかり合う乾いた音をいつでも聞ける。仕事の開始を示すその音は、彼のやる気を無限に引き出す…らしい。彼が懸命に働く姿を見れば、周りの人も思わず影響され、一緒に頑張ろうと思う…はずだ。",
  str_item_intro_3661153 = "家具。巨像のルーム内に設置できる。\nスポーツなどの応援でよく見られるポンポン。さまざまなダンスのお供として出場者を激励する。しかし、誰かが改造し不思議な装置を加えたため、自動で応援するようになった。奇妙に感じるかもしれないが、慣れてくれば面白いと思えるだろう",
  str_item_intro_3661154 = "家具。巨像のルーム内に設置できる。\n元々はレースで使われていたタイヤ。長期間の使用で破れた後、廃棄物として再利用され、積み重ねられて椅子に改造された。無骨な見た目だが、座ってみると結構柔らかい",
  str_item_intro_3662112 = "家具。巨像のルーム内に設置できる。\n「灼熱ラリー」のゴールに置かれる旗らしい。多くのレース出場者が持ち帰って家や車に飾って記念にしたりしている",
  str_item_intro_3661155 = "家具。巨像のルーム内に設置できる。\nR・Wが開催するラリーは、すべてのメンバーが出場できるだけでなく、さまざまな勢力からの観戦客が訪れており、中には自分の腕前を披露しようとする者までいる。このトロフィーはラリーで優秀な成績を収めた者の証しとなっている",
  str_item_intro_3661156 = "家具。巨像のルーム内に設置できる。\n砂漠にしか生えない植物。寒さにとても強く、水がなくても生きられるため、とても育てやすい鉢植えらしい。ただしトゲには要注意。それから水をあげすぎないこと",
  str_item_intro_3662113 = "家具。巨像のルーム内に設置できる。\n「パワータイヤ」と呼ばれているが、実際は普通のレーシングタイヤ。壁に掛けると、ラリー会場にいるような気分にしてくれる",
  str_item_intro_3661157 = "家具。巨像のルーム内に設置できる。\n真理結社のメンバーたちによると、この巻物はある古代遺跡で見つかったらしい。文字は書かれていないが、多くの真理結社のメンバーがその中に特別な「啓示」を見たそうだ…",
  str_item_intro_3642602 = "家具。巨像のルーム内に設置できる。\n真理結社の無名メンバーによって描かれた絵。「世界の真実」を見た後に描いたと話し、その後すぐに謎の失踪を遂げたが、誰もその話を本当だと思っていない。とても怪しげな絵だが、人を惹きつける不思議な力を持っている…",
  str_item_intro_3661158 = "家具。巨像のルーム内に設置できる。\n「不可分」、「完璧」、「循環」、「真実」、「唯一」、大勢の真理結社メンバーがこの模様に対して異なる解釈を持っているが、その誰もが七芒星の絨毯を足下にしくことで、「究極の真理」を垣間見ることができると考えている",
  str_item_intro_3662115 = "家具。巨像のルーム内に設置できる。\n砂漠だ！レースだ！灼熱ラリーは勇敢で機敏、そしてタフなレーサーがスピードで勝負するレース！世界の果てまで走り切ろう！",
  str_item_intro_3661169 = "家具。巨像のルーム内に設置できる。\n不思議な力で動く小型機械。少し押すだけで回転を続ける。意図的に停止させないと世界が終わるまで回り続けるらしい",
  str_item_intro_3661170 = "家具。巨像のルーム内に設置できる。\n天空ノ庭に置かれていた扉。上品なデザインで、他の場所に飾るのにも適している",
  str_item_intro_3661162 = "家具。巨像のルーム内に設置できる。\n魚の骨を見事に取り出し、これほど綺麗に並べられる人は、魚に対する深い知見があるに違いない。この置物は装飾品であるばかりか、技術の結晶でもある",
  str_item_intro_3662117 = "家具。巨像のルーム内に設置できる。\n魚拓からも釣り人の腕前をうかがい知れる。釣り人は激しく波を立てる巨大魚との闘いの末、ようやく釣り上げたに違いない。その記念として残しているのだろう",
  str_item_intro_3661163 = "家具。巨像のルーム内に設置できる。\n丸い切り株をそのまま使用して作った椅子。表面はでこぼこしており、木の年輪がうかがえる。しかし、それが部屋に独特の原野の雰囲気を添えている",
  str_item_intro_3661164 = "家具。巨像のルーム内に設置できる。\n空の末裔が使っていたじゅうたんと言われている。表面にはさまざまな線や図形が組み合わされた模様が描かれている。その模様を見ていると、塔の一部のようだと言う人もいれば、大空を連想する人もいるという…",
  str_item_intro_3661165 = "家具。巨像のルーム内に設置できる。\n異世界では「車」と呼ばれる移動手段の模型。\n心の怪盗団には馴染みのあるデザインのようだ。\n模型を眺めるモナが得意げに見えるのは気のせいか？",
  str_item_intro_3661166 = "家具。巨像のルーム内に設置できる。\n異世界の、とある地域に伝わる妖精がモデルのぬいぐるみ。\n雪だるまを思わせるフォルムが魅力的。\nときおり「ヒーホー」と聞こえるのは気のせいか？",
  str_item_intro_3661167 = "家具。巨像のルーム内に設置できる。\n古代遺跡で発見された不思議な鍋。自動で食材に火を通し、さらには味付けもできるという。あまりにも珍しいものであるため、この鍋を手に入れようと多くの人が集まり、料理バトルが行われたとか…",
  str_item_intro_3661168 = "家具。巨像のルーム内に設置できる。\n油、穀物、お好みで砂糖などの調味料を投入してスイッチを入れると、穀物が膨らみ、不思議なお菓子ができあがる。残念ながらこれはレプリカなので、実際には作れない…",
  str_item_intro_3661160 = "家具。巨像のルーム内に設置できる\n遊園地にほぼ欠かせないアトラクションの1つ。子どもたちに乗馬の楽しさを教えてくれる。もっとも、このメリーゴーランドはやや小さく、観賞用としてしか使えないだろう",
  str_item_intro_3661161 = "家具。巨像のルーム内に設置できる\nぎったんばっこん！見るからに小動物しか遊べないサイズだが、巨像では蛍灯たちに大人気。シーソーで動きの連携を鍛えられると考えているのか、よくシーソーで遊んでいるところを見かける",
  str_item_intro_3661001 = "家具。巨像のルーム内に設置できる。\nこの浮き輪、空気を入れるとまるで…手強い暗鬼みたい？うーん…ただの浮き輪だし、ピンク色をしているので狂暴そうには見えない。それどころか可愛らしくすら思える",
  str_item_intro_3661002 = "家具。巨像のルーム内に設置できる。\n元々は啓光連邦で製造され、外部に販売されていた自動扇風機。ある村の人たちが塗装し直し、夏らしさを感じさせてくれるようになった。新しい塗装にしてからは、吹き出す風がとてもひんやりしているらしい。真偽のほどは不明だが",
  str_item_intro_3661003 = "家具。巨像のルーム内に設置できる。\n白夜城のフィーダーポートに設置された標識。とても丈夫で耐久性に優れた素材が使われ、長年太陽や風雨にさらされても錆び一つない。シンプルな配色で大きめのデザインをしており、記念品として持ち帰ってコレクションするのに最適。",
  str_item_intro_3661004 = "家具。巨像のルーム内に設置できる。\nこの王冠はあの王冠とは違う。真の権力の象徴ではなく、真の魅力の象徴なのだ。かつて影ノ街で開催された美人コンテストで、優勝者にこの王冠が贈られた。華やかな宝石と魅惑的な美しさが相まって、影ノ街の人々に深い印象を残した。",
  str_item_intro_3661005 = "家具。巨像のルーム内に設置できる。\n砂漠から伝わった帽子の一種。つばの部分がとても広いのは、風や砂を防ぐためだと言われている。砂漠地帯の住民たちは祭りになると、仮面やこのようなフード付きマントを身につけて踊りや歌を披露し、外から来た人に特別な体験をさせてくれる。",
  str_item_intro_3661006 = "家具。巨像のルーム内に設置できる。\n砂漠地帯の一部住民はジャガイモで作る「ポテバッグ」と呼ばれる食べ物を好んでいた。「ポテバッグ」を愛するあまり、彼らは「ポテバッグ」の形をしたソファーまで作ってしまった。ソファーには可愛い顔のワッペンが貼られており、頭を埋めたくなる。",
  str_item_intro_3661007 = "家具。巨像のルーム内に設置できる。\n巨像の中でも格闘技の試合が見られる置物。選手たちを投影して「格闘」させることができ、試合を再現できる。",
  str_item_intro_3661008 = "家具。巨像のルーム内に設置できる。\n大き目のモミジの鉢植え。この鉢植え1つで十分部屋の飾り付けになる。もちろん、他のものと組み合わせて飾ることができれば、なおいい。",
  str_item_intro_3661009 = "家具。巨像のルーム内に設置できる。\n小型のモミジを植えた盆栽。いくつもの盆栽と組み合わせて飾るとより美しい。",
  str_item_intro_3661010 = "家具。巨像のルーム内に設置できる。\nある村の住民たちはこの鬼の面で敵をおどかし、追い払ったことから、幸運をもたらすものとして、大切にされるようになった。家の目立つ所に置き、家族全員に幸福が訪れるよう願いを込める。",
  str_item_intro_3661011 = "家具。巨像のルーム内に設置できる。\n極東地域で流行している家具。近年大陸でも流行り出した。冬の寒い日に暖かさと安らぎを与えてくれる。一度入ると1日中出られなくなる、「こたつの呪い」があるとも言われている。",
  str_item_intro_3661012 = "家具。巨像のルーム内に設置できる。\nハリモミは北境で最もよく見られる木で、家屋や家具の原材料としても使われるため、北境では「家」の象徴となっている。新年の頃になると、北境の人々はいろいろな飾りをこの木に掛け、プレゼントをその下に置き、祝日を迎えると同時にプレゼントを開いてお祝いをする。",
  str_item_intro_3661013 = "家具。巨像のルーム内に設置できる。\n極東の人々が新年を祝うために飾る装飾品。その起源は食べ物だと言われており、縁起物として扱われるようになってから、粘土や布で作られるようになった。どこかタタに似ている",
  str_item_intro_3661014 = "家具。巨像のルーム内に設置できる。\n「特別な日には、愛する人にハート形のケーキを」いつの頃からかそのような風潮が起こり、ことに若い女性たちの間で一世を風靡した。ハート形のケーキは見た目がいいだけでなく大変おいしいが、何より大切なのは、その甘さである。",
  str_item_intro_3661015 = "家具。巨像のルーム内に設置できる。\n極東から伝わった飾り。軽くて、かさばらず、軒や窓に掛けておける。風が吹くと、「チリンチリン」と透き通った音を奏で、なんとも心地よい。",
  str_item_intro_3661016 = "家具。巨像のルーム内に設置できる。\n可愛らしいクマの形をしている。思いを寄せる人へのプレゼントにピッタリ。見た目だけでなく、意外にも美味。ただ、食べてしまうのは、少々心苦しい。",
  str_item_intro_3661017 = "家具。巨像のルーム内に設置できる。\n古代の国王の側に使えたと言われる「ピエロ」をモデルにしたオモチャ。滑稽でありながら、可愛らしさもあり、特別な日に友人に贈れば、いつもとは違った趣向を添えられるかもしれない。",
  str_item_intro_3661018 = "家具。巨像のルーム内に設置できる。\nR・Wメンバーが愛用しているヘルメット。事故から守ってくれるだけでなく、運転中に顔に襲いかかる風や砂を防ぐこともできる。鮮やかな色彩のため、目立ちやすく注目を集められる",
  str_item_intro_3661019 = "家具。巨像のルーム内に設置できる。\n特殊な薄片を組み合わせて作られたソラヴァンの立体模型。子どもの作品のように見える。可能な限りソラヴァンを再現しているが、ところどころ子どもっぽさが残っているようだ",
  str_item_intro_3661020 = "家具。巨像のルーム内に設置できる。\n共に過ごした1年間を祝うため、特注した巨大ケーキタワー。目の前に置かれると実に壮観だ。なぜなら本当に…背が高いからだ。それだけでなく、ケーキの各段がゆっくりと回転し、数々の飾りがカラフルに演出しているのだ",
  str_item_intro_3661021 = "家具。巨像のルーム内に設置できる。\nあぁ…もう1年経ったのか。過去の思い出はすべてここに…",
  str_item_intro_3662118 = "家具。巨像のルーム内に設置できる。\n異世界で心の怪盗団が標的に送り付ける「予告状」を\nあしらったポスター。独創的なデザインに芸術性を感じる。\nポスターを眺めるフォックスが得意げに見えるのは\n気のせいか？",
  str_item_intro_3661022 = "家具。巨像のルーム内に設置できる。\nこの色使い、見覚えがある？その通り、ヘールがモデルのサーフボードだ。ヘール本人と同様、丈夫で耐用性にすぐれ、性能もよく、おまけに操作が簡単である",
  str_item_intro_3661176 = "家具。巨像のルーム内に設置できる。\n鑑賞するためにわざわざ…木をまるごと鉢植えに移し替えてしまった！そんなことをやろうと思った人は、きっとヤシの木が大好きなのだろう。",
  str_item_intro_3661171 = "家具。巨像のルーム内に設置できる。\n生き生きとしたヒトデの像。陸に上がってきたようにしか見えない。砂で作られているがなぜか粘着性があり、柔らかい砂がびっしりとくっついている。意外なほど丈夫。",
  str_item_intro_3661172 = "家具。巨像のルーム内に設置できる。\n丈夫に作られてはいるがしょせんは砂の城、文字通りに受け取ってはいけない。この名前には少しでも長く形を残しておきたいという想いが込められている。城の外見を見る限り、とてもよくできている。",
  str_item_intro_3661173 = "家具。巨像のルーム内に設置できる。\nさあさあ、急いで見に行こう！不思議なパフォーマンスが目白押し！「まさかこんなものが見られるなんて」と驚くこと間違いなし。一度見たら、きっと忘れられない。そんなショーのポスターは当然、たった1枚の絵でも、魅力たっぷりだ。",
  str_item_intro_3661174 = "家具。巨像のルーム内に設置できる。\n色とりどりのボール。さまざまなジャグリング技はもちろん、使っているだけでステージ上で観客の目をくぎ付けにできる。素晴らしいショーには欠かせない小道具の1つ。",
  str_item_intro_3661175 = "家具。巨像のルーム内に設置できる。\n風船がこんなにたくさん！カラフルで、手に持つと浮力さえ感じる。小さな子どもが手を離さないように気を付けて。本当に空まで飛んで行ってしまうから…",
  str_item_intro_3661177 = "家具。巨像内のルームに配置できる\nこの木はどのように成長するのだろう？こんなにゆがんだ枝でも生きられるなんて…。ホラーの雰囲気を盛り上げるのにぴったり。ランプをかけるとたいていの人は不気味に思うはず",
  str_item_intro_3661178 = "家具。巨像内のルームに配置できる\n彼女はなぜ笑っているのか？それは作り手のみぞ知る。じっと見つめていると笑顔が奇妙に思えてくる。いや、本当に笑顔なのだろうか…？",
  str_item_intro_3661179 = "家具。巨像内のルームに配置できる\nグツグツ…グツグツ…奇妙な大釜で煮え立っているのは何？おとぎ話の魔法の薬？それとも…暗黒料理？",
  str_item_intro_3661180 = "家具。巨像内のルームに配置できる\n影ノ街の怪しい商人が作った人形。単なる巨像の模型に見えるが、中は空洞で軽く押すと奇怪な鳴き声を出す。何かのパロディだろうか…",
  str_item_intro_3661023 = "家具。巨像のルーム内に設置できる。\n入れておいた水を噴射できる装置。涼しくなるので夏にうってつけ。ただし、遊んだ後は床を拭くのを忘れずに。",
  str_item_intro_3661024 = "家具。巨像のルーム内に設置できる。\n車輪1つで倒れないなんて！スピードは出ないようだけど…曲芸クラスの技に思わずビックリ。しかし、やはりハラハラしてしまう…",
  str_item_intro_3661025 = "家具。巨像内のルームに配置できる\n謎の遺跡から発見された機械。やや古いが動作に問題はなく、忠実に映像を記録できる",
  str_item_intro_3701001 = "散逸した書籍。今は、カフェの書棚に置かれている。興味があれば見に行ってみよう",
  str_item_intro_3701002 = "散逸した書籍。今は、カフェの書棚に置かれている。興味があれば見に行ってみよう",
  str_item_intro_3701003 = "散逸した書籍。今は、カフェの書棚に置かれている。興味があれば見に行ってみよう",
