  str_item_intro_3710002 = "散逸した書籍。今は、カフェの書棚に置かれている。興味があれば見に行ってみよう",
  str_item_intro_3710003 = "散逸した書籍。今は、カフェの書棚に置かれている。興味があれば見に行ってみよう",
  str_item_intro_3710004 = "散逸した書籍。今は、カフェの書棚に置かれている。興味があれば見に行ってみよう",
  str_item_intro_3710005 = "散逸した書籍。今は、カフェの書棚に置かれている。興味があれば見に行ってみよう",
  str_item_intro_3711001 = "散逸した書籍。今は、カフェの書棚に置かれている。興味があれば見に行ってみよう",
  str_item_intro_3711002 = "散逸した書籍。今は、カフェの書棚に置かれている。興味があれば見に行ってみよう",
  str_item_intro_3711003 = "散逸した書籍。今は、カフェの書棚に置かれている。興味があれば見に行ってみよう",
  str_item_intro_3711004 = "散逸した書籍。今は、カフェの書棚に置かれている。興味があれば見に行ってみよう",
  str_item_intro_3711005 = "散逸した書籍。今は、カフェの書棚に置かれている。興味があれば見に行ってみよう",
  str_item_intro_3751002 = "獲得すると対応するアイコンが使用可能になる\n「良いこと思いついた！え、あなたも？まって、お互い秘密にしておきましょ！そっちの方が、秘密を共有してるみたいで楽しいもの！」",
  str_item_intro_3751003 = "獲得すると対応するアイコンが使用可能になる\n「見て見てあの人！面白いね！ええ！そうなの！？ほんとに～？」",
  str_item_intro_3751004 = "獲得すると対応するアイコンが使用可能になる\n「なんだかうまくいかないね。どうしよっか…。ネガティブなことは言いたくないけど、でも――！」",
  str_item_intro_3751005 = "獲得すると対応するアイコンが使用可能になる\n「はあ、面倒ね。どうしてこんなことに…。きっとまだまだ努力が足りないのね、一緒に頑張ろう！」",
  str_item_intro_3751006 = "獲得すると対応するアイコンが使用可能になる\n「失敗しちゃった…長官から叱られるかも…だめだめ、悪い方に考えるのはやめよう…はあ…」",
  str_item_intro_3751009 = "獲得すると対応するアイコンが使用可能になる\n「自分を疑わないで。あなたにはあなたの使命があるわ、きっと！」",
  str_item_intro_3751011 = "獲得すると対応するアイコンが使用可能になる\n「お任せした任務、全部完了したんですか？じゃあこのお花をあげましょう！」",
  str_item_intro_3751015 = "獲得すると対応するアイコンが使用可能になる\n「この声、安心するし聞き心地がいいです。一緒に聞きますか？」",
  str_item_intro_3751017 = "獲得すると対応するアイコンが使用可能になる\n「皆の足を引っ張らないようにしなくっちゃ。新しいものを発明しよっか？例えばね～！」",
  str_item_intro_3751019 = "獲得すると対応するアイコンが使用可能になる\n「どれほどの知識と見聞をもってしても眼下のこれを言い表すことはできぬ。目を見張るほどだ」",
  str_item_intro_3751023 = "獲得すると対応するアイコンが使用可能になる\n「なんでそんなに急いでいるの？ただご飯を食べるため？早く行かないと冷めちゃうよ。」",
  str_item_intro_3751025 = "獲得すると対応するアイコンが使用可能になる\n「つまらない人～。なんで暇つぶししようと頑張るの？他にやることがないの？」",
  str_item_intro_3751030 = "獲得すると対応するアイコンが使用可能になる\n「親愛なる巨像さん、なぜ強がって、空飛ぶの？」",
  str_item_intro_3751032 = "獲得すると対応するアイコンが使用可能になる\n「なぜ自分がわからないの？なぜ鏡を見ないの？全くなってない人たち、本当に己を知らないな。」",
  str_item_intro_3751033 = "獲得すると対応するアイコンが使用可能になる\n「共に杯を挙げよう、だが余の手には刃も握られている」",
  str_item_intro_3751034 = "獲得すると対応するアイコンが使用可能になる\n「お前が影を見つめる時、影もお前を見つめている」",
  str_item_intro_3751035 = "獲得すると対応するアイコンが使用可能になる\n「真理は雲の中にまぎれて、いつでも見え隠れしているものよ。だから、見極める目が必要なの」",
  str_item_intro_3751036 = "獲得すると対応するアイコンが使用可能になる\n「秩序？ルール？ハハハ、なんだそりゃ？」",
  str_item_intro_3751037 = "獲得すると対応するアイコンが使用可能になる\n「未来はいまだ闇に包まれている。しかし、私には一筋の夜明けの光が見える」",
  str_item_intro_3751038 = "獲得すると対応するアイコンが使用可能になる\n「すばらしい！私と共に暗鬼と戦おう！啓明の光のために！」",
  str_item_intro_3751301 = "獲得すると対応するアイコンが使用可能になる。\n「よくやった！R・Wに入らないか？」",
  str_item_intro_3751302 = "獲得すると対応するアイコンが使用可能になる。\n「みんなありがとう。もうすっかり元気だよ。暗鬼を倒すの手伝おうか？」",
  str_item_intro_3751303 = "獲得すると対応するアイコンが使用可能になる\n「私と一緒に雲山へお花見に行きましょう」",
  str_item_intro_3751304 = "獲得すると対応するアイコンが使用可能になる\n「『かき氷魂』を持った店主が心を込めて作ったかき氷。夏の日に至極の冷たさを与えてくれる。」",
  str_item_intro_3751305 = "獲得すると対応するアイコンが使用可能になる\n「これをつけるんだ！今日からキミが『レディーゼルエンジン・メカレンチVゼロ号機』だ！」",
  str_item_intro_3751306 = "獲得すると対応するアイコンが使用可能になる\n「あぁ…みんな遊びに行ったみたい。私も…」",
  str_item_intro_3751307 = "獲得すると対応するアイコンが使用可能になる\n「涼みたいの？いいわ。氷花～」",
  str_item_intro_3751308 = "獲得すると対応するアイコンが使用可能になる\n「もう100日なの？ケーキでお祝いしなくちゃ～」",
  str_item_intro_3751309 = "獲得すると対応するアイコンが使用可能になる\n「あっ…おいら、砂漠の人みたい。」",
  str_item_intro_3751310 = "獲得すると対応するアイコンが使用可能になる\n「何だか頭が重いな。こいつらのせいか…だったらこのままにしておこう。」",
  str_item_intro_3751311 = "獲得すると対応するアイコンが使用可能になる\n「勝利したの？祝砲でお祝いしましょう！」",
  str_item_intro_3751312 = "獲得すると対応するアイコンが使用可能になる\n「この件について、あなたと合意できればいいのですが」",
  str_item_intro_3751313 = "獲得すると対応するアイコンが使用可能になる\n「仮面の下の顔が見たい？いいよ、それならまず傭兵団に入ってもらおうか」",
  str_item_intro_3751314 = "獲得すると対応するアイコンが使用可能になる\n「白夜に捧ぐ。この世の不公平は私が粛清します」",
  str_item_intro_3751315 = "獲得すると対応するアイコンが使用可能になる\n「影ノ街地下闘技場の最高栄誉、トップ選手の証だ！」",
  str_item_intro_3751316 = "獲得すると対応するアイコンが使用可能になる\n「お兄さん、うち、魔法が使えるようになりましたえ！」",
  str_item_intro_3751317 = "獲得すると対応するアイコンが使用可能になる\n「ほら、お面だよ！一緒に思いっきり楽しもう！」",
  str_item_intro_3751318 = "獲得すると対応するアイコンが使用可能になる\n「パトロール中に可愛い猫ちゃんに会えるなんて、今日はとってもいい気分！！」",
  str_item_intro_3751319 = "獲得すると対応するアイコンが使用可能になる\n「白夜城において、それはまさに権力の象徴だ。通常、貴族しか所有は許されない」",
  str_item_intro_3751320 = "獲得すると対応するアイコンが使用可能になる\n「北境では新年に、皆このような恰好をするのだ。私も例外ではない」",
  str_item_intro_3751321 = "獲得すると対応するアイコンが使用可能になる\n「新しい年におかれましても、あなたが幸せに暮らせますように」",
  str_item_intro_3751322 = "獲得すると対応するアイコンが使用可能になる\n「これで私が世界一のメイドだと分かったことでしょう！」",
  str_item_intro_3751323 = "獲得すると対応するアイコンが使用可能になる\n「いい子は寝ている時もいい子。頭にミカンを置かれても動かないから大丈夫」",
  str_item_intro_3751324 = "獲得すると対応するアイコンが使用可能になる\n「全てを…絵に残しておこう。」",
  str_item_intro_3751325 = "獲得すると対応するアイコンが使用可能になる\n「ほら、これを…恐らく1000年はくだらない年代物ですよ！」",
  str_item_intro_3751326 = "獲得すると対応するアイコンが使用可能になる\n「お祝いですか？祝日も、いろいろやることがあるんですねー」",
  str_item_intro_3751327 = "獲得すると対応するアイコンが使用可能になる\n「ハ～イ！一緒に外をぶらぶらしましょ！」",
  str_item_intro_3751328 = "獲得すると対応するアイコンが使用可能になる\n「どんなに記憶力が良くても、ノートに勝るものはないわ」",
  str_item_intro_3751329 = "獲得すると対応するアイコンが使用可能になる\n「ガォオオ～、驚いた～？」",
  str_item_intro_3751330 = "獲得すると対応するアイコンが\n使用可能になる\n「人の愛は貴く\n自由の価値は計り難し\nされど誓いのためならば\n両者いずれも捨て置かん」",
  str_item_intro_3751331 = "獲得すると対応するアイコンが使用可能になる\n「チリンチリ～ン、鈴はいかがですかニャ？」",
  str_item_intro_3751332 = "獲得すると対応するアイコンが使用可能になる\n「神楽鈴の音色に耳を澄ませてくださいませ」",
  str_item_intro_3751333 = "獲得すると対応するアイコンが使用可能になる\n「肉まんは、誰にも分けてあげないから！」",
  str_item_intro_3751334 = "獲得すると対応するアイコンが使用可能になる\n「目が覚めた？だったら、早く仕事しなよ。」",
  str_item_intro_3751335 = "獲得すると対応するアイコンが使用可能になる\n「勝ったわ！ねえ、面白いことでもしに行かない？」",
  str_item_intro_3751336 = "獲得すると対応するアイコンが使用可能になる\n「俺に似てねェか？」",
  str_item_intro_3751338 = "獲得すると対応するアイコンが使用可能になる\n「アハハ、ニャンコも見てるよ」",
  str_item_intro_3751339 = "獲得すると対応するアイコンが使用可能になる\n「これ…何が違うのかしら？」",
  str_item_intro_3751340 = "獲得すると対応するアイコンが使用可能になる\n「ずっと助けられてばかりだから、これ、受け取って」",
  str_item_intro_3751341 = "獲得すると対応するアイコンが使用可能になる\n「今日は気持ちを伝える日だって聞いたけど…こういうことか？」",
  str_item_intro_3751342 = "獲得すると対応するアイコンが使用可能になる\n「この着ぐるみ…大人気なんだってな？かなり並んでやっと買えたんだぞ！」",
  str_item_intro_3751343 = "獲得すると対応するアイコンが使用可能になる\n「目の色が…変わった。」",
  str_item_intro_3751344 = "獲得すると対応するアイコンが使用可能になる\n「ううん…何かやり忘れた仕事があるような…」",
  str_item_intro_3751345 = "獲得すると対応するアイコンが使用可能になる\n「重要事項をすぐに書き留めるのは参謀長として大切な習慣です」",
  str_item_intro_3751346 = "獲得すると対応するアイコンが使用可能になる\n「この服？影ノ街をブラブラしていて見つけたの。変わったスタイルでしょ？」",
  str_item_intro_3751347 = "獲得すると対応するアイコンが使用可能になる\n「キューブの商人が何かいいものを買い取ったらしく、嬉しそうに歌っていた。」",
  str_item_intro_3751348 = "獲得すると対応するアイコンが使用可能になる\n「啓光はお前の力を必要としている。加入を待っているぞ！」",
  str_item_intro_3751349 = "獲得すると対応するアイコンが使用可能になる\n「えっ？あたしの歌を聞きたい？いいよ。その代わり、ゲームに付き合ってよね！」",
  str_item_intro_3751350 = "獲得すると対応するアイコンが使用可能になる\n「どうしてユミのコスプレかって？かわいいからだよ。」",
  str_item_intro_3751351 = "獲得すると対応するアイコンが使用可能になる\n「このネコ耳？フィリスがどうしてもつけろって言うんだ。つけないと僕がうっかり尻尾を踏んだこと、キシローナさんに言いつけるって脅すから…」",
  str_item_intro_3751352 = "獲得すると対応するアイコンが使用可能になる\n「俺様とチームを組め！そうすればどんな試合にも負けねぇぞ！」",
  str_item_intro_3751353 = "獲得すると対応するアイコンが使用可能になる\n「え？何か難しいことあんの？」",
  str_item_intro_3751354 = "獲得すると対応するアイコンが使用可能になる\n「時にはリラックスすることも大切だ」",
  str_item_intro_3751355 = "獲得すると対応するアイコンが使用可能になる\n「どこまで掘ったんだろ？」",
  str_item_intro_3751356 = "獲得すると対応するアイコンが使用可能になる\n「ああ、すごく暑いね」",
  str_item_intro_3751357 = "獲得すると対応するアイコンが使用可能になる\n「今年の夏は暑い。帽子は日焼け予防になる。ナビゲーター、そなたも熱中症には気を付けるんだな」",
  str_item_intro_3751358 = "獲得すると対応するアイコンが使用可能になる\n「この暑い夏に、冷たくて美味しいかき氷を食べたくない人なんているんでしょうか？」",
  str_item_intro_3751359 = "獲得すると対応するアイコンが使用可能になる\n「暑い夏、カレンの側にいれば、一時の涼しさを感じられる」",
  str_item_intro_3751360 = "獲得すると対応するアイコンが使用可能になる\n「本当に気持ちいい風ね。騒ぎの中の静けさを一緒に楽しみましょ」",
  str_item_intro_3751361 = "獲得すると対応するアイコンが使用可能になる\n「闇夜は我が仲間、コウモリが臣下。さあ、私が誰か分かるかな？」",
  str_item_intro_3763022 = "獲得すると対応するアイコンが使用可能になる\n「怖がることはございません。催しを盛り上げるためのランタンです。なかなかでしょう？」",
  str_item_intro_3751362 = "獲得すると対応するアイコンが使用可能になる\n「あら、何かあったのかしら？」",
  str_item_intro_3751363 = "獲得すると対応するアイコンが使用可能になる\n「真剣な時だって、蛇は頭に乗っていていいのよ」",
  str_item_intro_3751365 = "獲得すると対応するアイコンが使用可能になる\n「お菓子が欲しいの？だったら、物語と交換よ」",
  str_item_intro_3751366 = "獲得すると対応するアイコンが使用可能になる\n「オオカミの仮装よ、イヤとは言わないわよね？」",
  str_item_intro_3751367 = "獲得すると対応するアイコンが使用可能になる\n「カロンは喜び勇んで牙をつけ、マントをはおった。さあ、舞台の始まりだ！」",
  str_item_intro_3751368 = "獲得すると対応するアイコンが使用可能になる\n「魔術師になることも、ヒイロにとっては修行の一環だ」",
  str_item_intro_3751369 = "獲得すると対応するアイコンが使用可能になる\n「パロマは包帯を巻きつけ、お菓子をもらいにくる子どもを驚かせようと待ちかまえている」",
  str_item_intro_3751370 = "獲得すると対応するアイコンが使用可能になる\n「このコインは…あたしの過去そのもの」",
  str_item_intro_3751371 = "獲得すると対応するアイコンが使用可能になる\n「色とりどりのネオンがきれいですね」",
  str_item_intro_3751372 = "獲得すると対応するアイコンが使用可能になる\n「私と一緒に、アイドルになりましょ！」",
  str_item_intro_3751373 = "獲得すると対応するアイコンが使用可能になる\n「レディー…アクション！」",
  str_item_intro_3751374 = "獲得すると対応するアイコンが使用可能になる\n「フィリスがニボシと交換して手に入れた新年の人気のパジャマだと言っていたが…確かに着心地はいい。ただ、なぜ耳が付いている？」",
  str_item_intro_3751375 = "獲得すると対応するアイコンが使用可能になる\n「変わった香りのするタニシ麺。ユエの大好物である。」",
  str_item_intro_3751376 = "獲得すると対応するアイコンが使用可能になる\n「なんだか具合が悪そうだね、診てあげようか？」",
  str_item_intro_3751377 = "獲得すると対応するアイコンが使用可能になる\n「じっと周囲の人や物事を観察するのが、イェリアのクセである」",
  str_item_intro_3751378 = "獲得すると対応するアイコンが使用可能になる\n「公正無私のミカエルは、目にしたバラをすべて没収する」",
  str_item_intro_3751379 = "獲得すると対応するアイコンが使用可能になる\n「時には変装して外を歩いてみるのもいいものだな」",
  str_item_intro_3751380 = "獲得すると対応するアイコンが使用可能になる\n「危険なのでまねしないでください」",
  str_item_intro_3751381 = "獲得すると対応するアイコンが使用可能になる\n「ジェノが一緒にブラックコーヒーを飲もうと誘っている。彼の誘いを受ける？」",
  str_item_intro_3751382 = "獲得すると対応するアイコンが使用可能になる\n「白夜城の裁判官たる者、ためらわず裁きを下す胆力が必要です」",
  str_item_intro_3751383 = "獲得すると対応するアイコンが使用可能になる\n「このぬいぐるみ、ボクとそっくりだ。抱えてると安心するな」",
  str_item_intro_3751384 = "獲得すると対応するアイコンが使用可能になる\n「これ、私の好きな音楽です。心が静まります」",
  str_item_intro_3751385 = "獲得すると対応するアイコンが使用可能になる\n「ヒタキと仲良しのインゲルは、きっと心が優しいにちがいない」",
  str_item_intro_3751386 = "獲得すると対応するアイコンが使用可能になる\n「外なる敵には剣を向け、内なる民の手を握る。レオの守り続ける信条だ」",
  str_item_intro_3751387 = "獲得すると対応するアイコンが使用可能になる\n「紅茶の香りはミヤの心を静め、癒してくれる」",
  str_item_intro_3751388 = "獲得すると対応するアイコンが使用可能になる\n「彼が手にしているアラセイトウは誰の好きな花だろう？」",
  str_item_intro_3751389 = "獲得すると対応するアイコンが使用可能になる\n「水晶玉に映るのは過去か、それとも未来か？」",
  str_item_intro_3751390 = "獲得すると対応するアイコンが使用可能になる\n「つらい時に優しい抱擁があれば、きっと楽になるでしょう？」",
  str_item_intro_3751391 = "獲得すると対応するアイコンが使用可能になる\n「わたくしの観客になるか、わたくしと一緒に踊るか？どちらがいいかしら？」",
  str_item_intro_3751392 = "獲得すると対応するアイコンが使用可能になる\n「炎天下に冷たいかき氷を食べて暑さを打ち消しましょう！」",
  str_item_intro_3751393 = "獲得すると対応するアイコンが使用可能になる\n「いいビジネスのアイデアがあるんだけど、一緒にやってみない？」",
  str_item_intro_3751394 = "獲得すると対応するアイコンが使用可能になる\n「なんで笑ってるかって？それは…当ててみな」",
  str_item_intro_3751395 = "獲得すると対応するアイコンが使用可能になる\n「夏のスイーツで好きな物？そうだな、トカゲの干物アイスかな」",
  str_item_intro_3751501 = "獲得すると対応するアイコンが使用可能になる\n「このヨアケバナは希望の象徴。これを身に着けて、重苦しい過去から解き放たれよう！」",
  str_item_intro_3751502 = "獲得すると対応するアイコンが使用可能になる\n「櫻花一族の紋章。ヒイロが君を認めた証だ。」",
  str_item_intro_3751503 = "獲得すると対応するアイコンが使用可能になる\n「謎の戦士の助けが必要な時は、何でも屋のタキに連絡してみよう。」",
  str_item_intro_3751504 = "獲得すると対応するアイコンが使用可能になる\n「うふふ、一緒にアフタヌーンティーはいかが？\nまだ紅茶7樽しか飲んでないのに、もうダメなの？」",
  str_item_intro_3751505 = "獲得すると対応するアイコンが使用可能になる\n「余と共に永遠の暗闇へと戻るのだ」",
  str_item_intro_3751506 = "獲得すると対応するアイコンが使用可能になる\n「暗鬼を倒せないだぁ？心配するな。俺に任せろ！」",
  str_item_intro_3751507 = "獲得すると対応するアイコンが使用可能になる\n「ウィンデリオンのサプライズだよ！中身はどんなプレゼントだろう？」",
  str_item_intro_3751508 = "獲得すると対応するアイコンが使用可能になる\n「杯を交わし、この美しい夜を楽しもうじゃないか」",
  str_item_intro_3751509 = "獲得すると対応するアイコンが使用可能になる\n「わたくしの助けが必要なようですね。」",
  str_item_intro_3751510 = "獲得すると対応するアイコンが使用可能になる\n「言っておきますが、これは小林さんのために用意したんです。食べてはいけません！」",
  str_item_intro_3751511 = "獲得すると対応するアイコンが使用可能になる\n「私ですか？徹夜などしていませんよ…」",
  str_item_intro_3751512 = "獲得すると対応するアイコンが使用可能になる\n「ああ…寝起きはとってもノドが乾きますね。水分をしっかりとらなくては」",
  str_item_intro_3751513 = "獲得すると対応するアイコンが使用可能になる\n「あら、ナビゲーター様をどう思っているか、でございますか…」",
  str_item_intro_3751514 = "獲得すると対応するアイコンが使用可能になる\n「食べ物はどこ？」",
  str_item_intro_3751515 = "獲得すると対応するアイコンが使用可能になる\n「ハ～イ！私とドライブにでも行かない？」",
  str_item_intro_3751516 = "獲得すると対応するアイコンが使用可能になる\n「レノーアの気持ちを感じますか？」",
  str_item_intro_3751517 = "獲得すると対応するアイコンが使用可能になる\n「将来の戦略…」",
  str_item_intro_3751518 = "獲得すると対応するアイコンが使用可能になる\n「アフターヌーンティーこそ、\n最も素晴らしい時間の楽しみ方ですのよ」",
  str_item_intro_3751519 = "獲得すると対応するアイコンが使用可能になる\n「頂戴する」",
  str_item_intro_3751520 = "獲得すると対応するアイコンが使用可能になる\n「ワガハイの出番か？」",
  str_item_intro_3751521 = "獲得すると対応するアイコンが使用可能になる\n「白夜城、大陸…こうはならない、させはしない」",
  str_item_intro_3751522 = "獲得すると対応するアイコンが使用可能になる\n「悩みごと？じゃあ、一緒に涼しくなっちゃお～」",
  str_item_intro_3751523 = "獲得すると対応するアイコンが使用可能になる\n「さあ、勝負よ！」",
  str_item_intro_3751524 = "獲得すると対応するアイコンが使用可能になる\n「ふぅ…片付いたわね」",
  str_item_intro_3751525 = "獲得すると対応するアイコンが使用可能になる\n「生きるべきか死ぬべきか？\nそれは永遠の問題だ」",
  str_item_intro_3751526 = "獲得すると対応するアイコンが使用可能になる\n「インスピレーションが湧いてきた！よし、撮れたわ！今度こそきっと大人気よ！」",
  str_item_intro_3751527 = "獲得すると対応するアイコンが使用可能になる\n「帽子にオバケを乗っけて、義賊はワルモノぶっ飛ばす。クールスターをもったサディは、ラップしながら追っかける」",
  str_item_intro_3751530 = "獲得すると対応するアイコンが使用可能になる\n「お花を育てていると、心が磨かれるわ！」",
  str_item_intro_3751531 = "獲得すると対応するアイコンが使用可能になる\n「彼女は美しい。そして…危険だ。」",
  str_item_intro_3751532 = "獲得すると対応するアイコンが使用可能になる\n「はぁ…ふわふわであったかいな…」",
  str_item_intro_3751533 = "獲得すると対応するアイコンが使用可能になる\n「彼女は『あの人』の物語に浸っているようだ。邪魔しないでおこう」",
  str_item_intro_3751534 = "獲得すると対応するアイコンが使用可能になる\n「新年おめでとう！一緒に花火でもどうかしら？」",
  str_item_intro_3751535 = "獲得すると対応するアイコンが使用可能になる\n「船って…本当に魅力的ね。」",
  str_item_intro_3751536 = "獲得すると対応するアイコンが使用可能になる\n「おいしい！まだある？」",
  str_item_intro_3751537 = "獲得すると対応するアイコンが使用可能になる\n「間に合いません！食べながら向かいましょう！」",
  str_item_intro_3751538 = "獲得すると対応するアイコンが使用可能になる\n「私、寝ていませんわよ…zzz…」",
  str_item_intro_3751539 = "獲得すると対応するアイコンが使用可能になる\n「1回でクリアできる？」",
  str_item_intro_3751540 = "獲得すると対応するアイコンが使用可能になる\n「父さん、母さん…」",
  str_item_intro_3751541 = "獲得すると対応するアイコンが使用可能になる\n「犯人どもめ…私が必ず捕まえてやる！」",
  str_item_intro_3751542 = "獲得すると対応するアイコンが使用可能になる\n「獲物？獲物なら目の前にいるじゃない」",
  str_item_intro_3751543 = "獲得すると対応するアイコンが使用可能になる\n「ノートに勝る記憶力はない…」",
  str_item_intro_3751544 = "獲得すると対応するアイコンが使用可能になる\n「合同演習、始まります！」",
  str_item_intro_3751545 = "獲得すると対応するアイコンが使用可能になる\n「何事もおろそかにしてはならぬ。細かな所こそ重要なのだ」",
  str_item_intro_3751547 = "獲得すると対応するアイコンが使用可能になる\n「こうして静かに彼女たちを見ているだけでも、幸せな気分になれるわ。」",
  str_item_intro_3751548 = "獲得すると対応するアイコンが使用可能になる\n「あら、見たいの？だったら堂々と見なさい」",
  str_item_intro_3751549 = "獲得すると対応するアイコンが使用可能になる\n「美しいものほど危険な香りがする。そうでしょう？」",
  str_item_intro_3751550 = "獲得すると対応するアイコンが使用可能になる\n「発想力と行動力。それが成功の基本よ！」",
  str_item_intro_3751601 = "獲得すると対応するアイコンが使用可能になる\n「ヒビの入ったスクトゥム。白夜城騎士団の専用装備であり、下から上へ広がる直線的なシルエットが、凧のようにも見える。表には教会の紋章が刻まれている」",
  str_item_intro_3751602 = "獲得すると対応するアイコンが使用可能になる\n「1本の枯れ木に3つのカラフルなボールが吊るされている。マーサにしてみれば、過去は枯れたも同然。灯に照らされた雪国で新しい人生を迎えるのだ」",
  str_item_intro_3751603 = "獲得すると対応するアイコンが使用可能になる\n「タイヤの中央には歯車がはめられている。ローザの車はすでに砂漠の奥深くまで進んでいた。後を追って来た者には、彼女の後姿は見えず、残っているのはタイヤの跡だけだった。」",
  str_item_intro_3751604 = "獲得すると対応するアイコンが使用可能になる\n「怒りに花開いたユリにかくれ、鋭い刃が命令の時を待っている。イヴォンは筆を走らせ、紅水銀の夫人の運命は濃霧に紛れる。果たして彼女は、手にした剣を繰り出すのか、それとも襟元のユリを贈るのか、その結末が測り知られることはない。」",
  str_item_intro_3751901 = "獲得すると対応するアイコンが使用可能になる\nソラヴァンはただの巨像じゃない。君と17年も付き添った友達だ",
  str_item_intro_3751902 = "獲得すると対応するアイコンが使用可能になる\nこのヘルメットを被っていると、白夜の守護者になったような気分になる。「白夜」が何かについては、深く考えない方がいい",
  str_item_intro_3755004 = "獲得すると対応するアイコンが使用可能になる\n「珠重々に綴りし清暁の窓掛、花の蕾は旧に依る。世人知るや否や」",
  str_item_intro_3762001 = "獲得すると対応するフレームが使用可能になる\n古の紋様は「静かなる猟兵」が君を認めたことを表している。過去からの無上の栄誉に浴しよう",
  str_item_intro_3762002 = "獲得すると対応するアイコンが使用可能になる\n暖かみのある、手の込んだ飾りで、アイコンに花を添えよう！",
  str_item_intro_3763001 = "獲得すると対応するフレームが使用可能になる\n強い日差しと青い波、そして忘れられない思い出が熱気に満ちたビーチに残されている",
  str_item_intro_3763002 = "獲得すると対応するアイコンが使用可能になる\n啓光連邦の軍帽を被ると、彼らの一員になったかのようだ。",
  str_item_intro_3763003 = "獲得すると対応するフレームが使用可能になる\nこれがあれば、いつでも正確な判断ができる。便利なお助けグッズである。",
  str_item_intro_3763004 = "獲得すると対応するフレームが使用可能になる\nこれを身につければ、パーティーで一番注目を浴びること間違いなし！",
  str_item_intro_3763005 = "獲得すると対応するアイコンが使用可能になる\n優秀な生徒だけに送られる表彰旗だよー！頑張ろうねー！",
  str_item_intro_3763006 = "獲得すると対応するアイコンが使用可能になる\n可愛いかな？",
  str_item_intro_3763007 = "獲得すると対応するアイコンが使用可能になる\nずっとお側にいますよ…",
  str_item_intro_3763008 = "獲得すると対応するフレームが使用可能になる\n金魚すくいの戦利品！",
  str_item_intro_3763010 = "獲得すると対応するフレームが使用可能になる\n春の香りね！",
  str_item_intro_3763011 = "獲得すると対応するフレームが使用可能になる\nこれを身につければ、すごいレーサーになれる気がする！",
  str_item_intro_3763012 = "獲得すると対応するフレームが使用可能になる\n真紅の幕の下にあるのは、黒い童謡だった…",
  str_item_intro_3763013 = "獲得すると対応するフレームが使用可能になる\n高貴なる冠。人々の目を引き付ける",
  str_item_intro_3763014 = "獲得すると対応するフレームが使用可能になる\n「大元帥だけが着られるのだ！」",
  str_item_intro_3763015 = "獲得すると対応するアイコンが使用可能になる\nこれを身に付ければ、サービス精神が向上する…？",
  str_item_intro_3763016 = "獲得すると対応するフレームが使用可能になる\nさあ、かぶるがいい、偉大なマジシャンよ！",
  str_item_intro_3763017 = "獲得すると対応するフレームが使用可能になる\n日差しが強いから、日焼けしないように気を付けて～",
  str_item_intro_3763018 = "獲得すると対応するフレームが使用可能になる\n「1周年だよ！これを身に着けてお祝いしよう！」",
  str_item_intro_3763019 = "獲得すると対応するフレームが使用可能になる\nこれをつければビッカーのようにモフモフになれる！",
  str_item_intro_3763020 = "獲得すると対応するフレームが使用可能になる\n安心してください、熱くないですよ！",
  str_item_intro_3763021 = "獲得すると対応するフレームが使用可能になる\nコウモリが頭にしがみついているみたい？実はただカチューシャがきついだけである。",
  str_item_intro_3763023 = "獲得すると対応するフレームが使用可能になる\nこのキャップをかぶるとラップがうまくなって、野球の腕もあがる…？",
  str_item_intro_3763024 = "獲得すると対応するフレームが使用可能になる\n歌手の必需品！さあ、音楽の世界に浸ろう",
  str_item_intro_3763025 = "獲得すると対応するフレームが使用可能になる\n食べ物ではなく、かぶり物です！",
  str_item_intro_3763026 = "獲得すると対応するフレームが使用可能になる\nこれをかぶれば、イェリアと同じくらいの力を持てるだろうか？少なくとも風よけにはなりそうだ",
  str_item_intro_3763027 = "獲得すると対応するフレームが使用可能になる\n実はこれ、度なし眼鏡である",
  str_item_intro_3763028 = "獲得すると対応するフレームが使用可能になる\n分かった！犯人はあいつだ！",
  str_item_intro_3763029 = "獲得すると対応するフレームが使用可能になる\n2周年記念？早速使おう！1周年記念版を外すのも忘れずに。",
  str_item_intro_3763031 = "獲得すると対応するフレームが使用可能になる\nあの世界は本当に存在するのだろうか？もし存在しないなら、なぜ中に入れるのだろう？",
  str_item_intro_3763032 = "獲得すると対応するフレームが使用可能になる\nトゲだらけだが…付ける人はいるのだろうか…",
  str_item_intro_3763033 = "獲得すると対応するフレームが使用可能になる\nこうすれば紳士になれる？",
  str_item_intro_3800001 = "中には50光珀が入っている",
  str_item_intro_3800002 = "中には50光珀が入っている",
  str_item_intro_3800003 = "中には50光珀が入っている",
  str_item_intro_3800004 = "中には50光珀が入っている",
  str_item_intro_3800005 = "中には50光珀が入っている",
  str_item_intro_3801001 = "エピック光霊の突破に必要なアイテム。\n「静かなる猟兵」メンバーが所持している紋章。数千年の時を経てもなお強力な力を維持しており、同メンバーの潜在力を引き出すことができる",
  str_item_intro_3900101 = "指揮密録では1回のシミュレーションごとに、成果に応じたポイントが付与される。指揮ポイントが一定量に達すると、戦闘指揮の習熟度を示す指揮レベルが上がる",
  str_item_intro_3900201 = "シミュレーション室で指揮戦闘の練習を行うと、「データディスク」に保存された大量のデータの中から貴重なデータの欠片を獲得できる。一定量貯まると断片化されていたデータがつながり、完全な情報を得ることができる。",
  str_item_intro_3910100 = "長年積み重ねた訓練こそが勝利をみちびく。\nこのデータディスクに入っている挑戦は、すべての敵を倒さないとクリアできない。",
  str_item_intro_3910200 = "多くの場合、戦いの目的は敵を撃破することではなく、資源を得ることにある。\nこのデータディスクに入っている挑戦では、X個の特定アイテムを獲得しないとクリアできない。",
  str_item_intro_3910300 = "この命に代えてでも、仲間を守れ。\nこのデータディスクに入っている挑戦では、XターンNPCを守り切るとクリアできる。",
  str_item_intro_3910400 = "どのような敵に遭遇するだろうか？例外なく強大な敵が現れる。注意が必要だ。\nこのデータディスクに入っている挑戦では、精鋭エントリーを持つ敵を倒さなければクリアできない。",
  str_item_intro_3910500 = "頭脳は刃にも勝る。知能で勝利を勝ち取ろう。\nこのデータディスクに入っている挑戦では、パズルを解かないとクリアできない。",
  str_item_intro_3910600 = "戦闘とは駆け引きである。それはまるでチェスのようだ。\nこのデータディスクに入っている挑戦では、敵を全て倒さないとクリアできない。",
  str_item_intro_3910700 = "戦いとは残酷である。唯一勝利を手にする者は最後まで生き残ったものである。\nこのデータディスクに入っている挑戦では、Xターン撃破されずに生存するとクリアできる。",
  str_item_intro_3910800 = "敵は波の如く訪れ、守りを固めた砂浜に容赦なく打ち付ける。何とか持ちこたえねばならない。\nこのデータディスクに入っている挑戦では、敵を全て倒さないとクリアできない。",
  str_item_intro_3910900 = "敵がこちらと似た戦術をとっている。いや…敵はあなた自身とその仲間ともいえる。\nこのデータディスクに入っている挑戦では、敵を全て倒さないとクリアできない。",
  str_item_intro_3911000 = "賊を撃つなら、その王を撃ち取れ。敵の首領を倒さなければ、この戦いも、この戦争も終わらない。\nこのデータディスクに入っている挑戦では、敵のリーダーを倒さなければクリアできない。",
  str_item_intro_4090014 = "双子の絆は深く絡み合い、砕け散った記憶がゆっくりと組み合わさっていく。その雪のように白い双生の水仙は、鏡湖のほとりで墨色の雪に包まれながら静かに咲き、鏡の中の人との再会を待ち望んでいる。",
  str_item_intro_4090334 = "雲桜旅館の、バイスの身体の特徴に合わせて改良した女性用の浴衣。雲山を彷彿とさせるような、シンプルな色使いに、特色あふれる帯と帯飾り、可愛らしい鈴…いつもとは少し違うしとやかさを、何気なく添えてくれる。この浴衣を着る度、バイスはいつも、忘れられない大切な時間を思い返すのだ。",
  str_item_intro_4090923 = "「…ジロジロ見ないでよ…！」\nこれほどの窮地が他にあるだろうか？絡みついたイバラがセファーの両足を吊るし上げ、薄いストッキングや黒い生地がボロボロになっている。混乱の中でも、彼女は手に持ったワイングラスのバランスを何とか保っていた。上品で華やかなドレスだが、見た目ほど着やすいわけではなさそうだ。",
  str_item_intro_4090383 = "大ピンチ！ガルーがオモチャ箱から飛び出した！新年を祝うため、ガルーが用意したサプライズ。オモチャの中に埋もれる彼女がとても可愛らしい。祝日の雰囲気が出る赤と白の服に、ロボットアームにまで蝶々結びのリボン。だが、手にある爆弾は、いくらなんでもやりすぎでは…",
  str_item_intro_4090333 = "潮汐祭に参加するバイスが自分のために選んだ、シンプル・スポーティな水着。バイスが着やすいよう尻尾を自由に振れる特殊な構造デザインが用いられている。よく観察してみると、特殊な構造のほかにも黒と金の配色の日焼け防止ジャケットが付いており、元気よく動き回る彼女にはぴったりのデザインとなっている。ガチャガチャと音を立てる製氷機の隣で、満面の笑みを浮かべたショートヘアの少女が水遊びに誘う。ビーチバレー、冷たいドリンク、かき氷のワゴン…この夏、あなたとバイスが過ごした2人だけの思い出がたっぷりと詰め込まれている。",
  str_item_intro_4090853 = "クールなトップスとエレガントなスカートを組み合わせた、メランコリックでピュア、ちょっと不気味で美しいコーデ。 精巧に編み上げられた袖、荘厳な儀式を彷彿させるようなベールに、クールなブーツ……ジェーンのコーデは、驚きを与えてくれるだけではない。どうやら、スカートの裾に咲く花には、特別な意味が込められているようだ。ただ不思議なのは――常に傍観者であろうとする彼女が、このコーデを選んだ理由である。",
  str_item_intro_4090863 = "潮汐祭をテーマにデザインされた、白い乙女シリーズのコーデ。ユーライアの立場を考慮し、無垢な純白を用いて純真さと敬虔さを表現している。彼女の周りには花のつるが軽やかに浮かんでおり、いつでも彼女の呼びかけに応えてくれる。一見普段と変わらないように見える彼女だが、静かに佇む花たちだけが、彼女が着なれない水着に恥じらっていることを知っている。晴れ渡った空、潮の香りを含んだ風、ひんやりと冷たい海水…そして彼女が手に持つ儀式用の剣をひとたび振りかざせば、美しい音楽が奏でられるのだ。",
  str_item_intro_4090573 = "昼下がりに見た素敵な夢。フィリスはモコモコのパジャマを着てベッドで丸くなり、熟睡していた。夢の中ではユミが自分を抱きしめて、髪を撫でている。彼女が心と体に感じる温かみは、暖炉にも似ていた。まるで、何もかもが昔のままであるかのように…",
  str_item_intro_4091023 = "「燃える心」を体現したシンプルなこの服が、暗くて狭い地下闘技場で唯一明るい光を放つものだ。ファイターたちはリングに上がり、肉体をぶつけ、精神力の戦いを繰り広げ、血を炎のように燃え上がらせる。来るときは猛火のごとく、去るときは燃え殻のように。彼女は指を鳴らしながら、目の前のすべてを打ち倒そうとしていた。",
  str_item_intro_4090453 = "大雪とともに、厳しい冬がやって来た。道には行き交う人もおらず、暖かい灯の光だけが瞬いている。もしあなたが独りこの地を訪れた旅人であったとしても、道に迷う心配はない。この道の角には――白い燕尾服に黒いブーツを履き、しっかりと撫でつけられた髪の、優雅な立ち居振る舞いと控えめな物腰の紳士が、馬車の傍らであなたを待ち続けている。",
  str_item_intro_4090993 = "アイリーナは恥じらいながらソファーの上で縮こまり、両の素足を晒している。無造作に置かれた靴と身に付けたドレスが、先程までの舞踏会の賑わいを物語る。「シンデレラ」の童話のように、美しい魔法のドレスは時間と共に失われていく。しかし、思い出は――今夜、あなたと過ごした時間だけは、消えることも、色あせることもない。",
  str_item_intro_4090263 = "存在の意義、虚無に対する認識……この不思議な服に着替えた後、漠然とした問いかけが一日中頭から離れなくなったウリエルは、ただ考え続けることしかできなかった。しかし、虚構に満ちた文学の世界でウリエルの求める答えは見つかるのだろうか？断言できることはない。それでもできることがあるとすれば、彼女が文学にふけっている間、彼女と共に歩み、共に考え、共に感じることだけだ。",
  str_item_intro_4090543 = "真面目で几帳面。それがナディーンの性格だ。疲れ知らずの彼女は、己の役割を全うしようと努力し続けている。いつもと違う、青春の雰囲気に満ちた衣装をまとっていたとしても、手に持つランタンが可愛らしく装飾されていたとしても、彼女のそうした雰囲気まで覆い隠すことはできない。",
  str_item_intro_4091113 = "普段は沈みがちなベリエも、海ではいくぶんか楽しそうだ。シンプルなデザインの水着ながら、ベリエのスタイルの良さを存分に引き出している。ただ、本人はそんなことを気にも留めず、砂の城作りに夢中になっている。彼女にとっては、それが海へ来ていちばん良かったことなのかもしれない",
  str_item_intro_4090883 = "青い空、白い雲、平坦な道――R・W砂漠とはまったく異なる風景だ。マギーもいつもとは違っている。きれいなセーラー服を着て、大きなリボンが風に揺れる。晴れた日の朝、食パンをかじりながら「のんびり」自転車に乗っている彼女は、始業時刻に間に合わせるのをあきらめたのだろうか？\nこの不思議な服は、R・Wの中でマギーをひときわ目立たせるだけでなく、彼女にいつもと違った光景を見せることもできるようだ。それこそがこの服の持つ魔力なのかもしれない。",
  str_item_intro_4090963 = "せ、先生？シャリーが？アルバイトとはいえシャリーは真剣らしく、わざわざ教師用の服に着替えている。確かに今のシャリーは以前よりもずっと頼りがいがあり、喋り方も落ち着いている。彼女の授業には、本当に学べることがあるのかもしれない。",
  str_item_intro_4091053 = "普段着でもイブはR・Wの人気者だ。どれほどの人気かは、彼女自身も分かっていないことだろう。皆を応援するという彼女は、どこから手に入れてきたのか分からない、変わった服に着替えたが、人気は下がるどころか、天元を突破する勢いである。ただし、決して彼女をまじまじと見てはならない。さもなくば、怒りに満ちた巨大なレンチが空から降ってくることだろう。",
  str_item_intro_4090064 = "ふんわりつややかな生地、いたるところにあしらわれたリボン…しかし、これは本当に「パジャマ」なのだろうか！？なぜ、こんな常識を超えたデザインの服が存在するのか、そして、これを人前に着て行っていいものなのか？カレンは困り果てた。どうするべきか分からずに、とりあえず着てみると、知性と厳格さにあふれたオーラを漂わせるカレンも、いつもと違った雰囲気に変わった。\nパジャマパーティのため、そして皆と打ち解けるため…カレンは思い切った冒険に出た。",
  str_item_intro_4090303 = "漆黒の着物、真っ赤な羽織。我こそ天下の悪人を成敗する者――赤浪サメ之助、参上！「郷に入っては郷に従え」、R・Wの首領として、自ら手本を実践するのが彼の流儀だ。着物に腰の刀と、どれも完璧なまでに雲島のおもむきを備え、笑い声までいつもより豪快になっている気がする。ただし、この流浪人は機嫌が良くなると、即興で作った俳句を大声で詠み始めることがある。皆の者、ゆめゆめご油断めされませぬよう…",
  str_item_intro_4090443 = "清々しい風が松林に吹き、暖かな日差しが室内を照らす。都会の喧騒と煩雑な業務から離れ、静かな「雲桜旅館」にやって来た。この機会にゆっくり休もうではないか。「ライフワークバランス」こそビビアンのモットー、そして1日女将の勤めは心身ともにリラックスできた。やる気を満タンチャージして、さあ、また仕事に戻ろう！\nもちろん、すべては計画のうち！",
  str_item_intro_4090643 = "ラスに支給された新しい「潜入用戦闘服」。東方の絹糸で織られた生地は軽く、身体にフィットし、ひらひらと揺れて美しい。軽装だが、その分動きやすく、ラスの戦闘力には一切影響をおよぼさない。\n拳を振るい、身体を動かし、勇んで前へ進み、すべてを打ち払う――どんな危険も、ラスさえいれば一件落着！",
  str_item_intro_4090893 = "珍しく休みのとれたイルンティ。休暇のために、雲島式の着物まで用意した。金色の生地と刺繍に真っ白な毛皮の肩掛けを合わせ、漂う優雅な華やかさ。さて、この服を着て、雲島の街をゆっくり歩いて回ろうか、それとも列車に揺られて景勝の地をめぐろうか…期待が彼女の胸をふくらませる。\nしかし、彼女の計画は突然の事件に狂わされた。せっかくの休暇を守るため、雲島の駅でイルンティのお取り調べが始まる…。",
  str_item_intro_4090653 = "「兄さん、うちと羽根つきしませんか？」\nタタがうきうきした様子で羽子板を抱え、近づいてくる。しかし、その笑顔の裏で燃えるのは、必勝の闘志。気楽な遊びと思っていたが、最後は手練れ同士の激戦に！？華麗なサーブと強烈なスマッシュが飛び交う、素人離れしたレベルの試合が繰り広げられる！\n負けると罰ゲームとして顔に落書きされるらしいが、タタがどうか落書きを手加減してくれますように…",
  str_item_intro_4090233 = "恥ずかしがり屋のクラリンだが、皆が「レース」を見に行ったと聞いて興味を抱き、ある商人に勧められて応援の仕事を引き受けることになった。しかし、普段の服装と比べると、コスチュームが少し「特別」で…\nだが、明るく元気な性格になりたいと考えたクラリンは、あえて挑戦することにした。",
  str_item_intro_4090613 = "「ああ…これが大陸の姿なんですね！」\n雲間に浮かぶチャンドラ。高さを恐れることもなく、地上で開催されているラリーを興味深く眺めている。激しいレース展開を思わず実況してしまう彼女。しかし、この熱気球と、そのエキゾチックな服は…\nそう、これはすべて彼女の不思議な「心療セラピー」。溜まった負の感情を解き放つには、最適の方法なのだ。",
  str_item_intro_4090843 = "「砂の熱さ、水の温もりと柔らかさ。ヴィンテージ感と新しさをかね備えた服」\n「礼をわきまえておらぬ」\nさまざまな評価はあったものの、この服を着たイスタバンが現れ、その場の人々は圧倒された。華やかな場所にいなくても、見る人に大物の風格を感じさせる。もしかすると、それこそが「シャドウマスター」のカリスマであり、魅力なのかもしれない。",
  str_item_intro_4090603 = "レースの審判は常に目立つ格好をしている。目にもとまらぬスピードで駆け抜けるレーサーにも見えるようにするためには、目立たなければならないのだ。\n酒代に困りレースの審判を引き受けたジョナは、すぐにうさん臭い裏事情を知ることとなった。本来なら余計なことに首を突っ込まない性分だったが、純真な少女のためにコースへ飛び込み、八百長レースに出場する悪党どもに「公正さ」を叩き込むのであった。",
  str_item_intro_4090713 = "灼熱の太陽が照りつける過酷な気候の中、レースカーさえ煙を上げそうになる。汗は砂漠に滴り落ちることもなく、たちまち蒸発してしまう。\nそれでもタキは「完全武装」でレースに出場し、スキをうかがうライバルたちを倒し、一気に優勝するつもりだ。彼がこれほど真剣なのは、お金のためだけなのだろうか？",
  str_item_intro_4091263 = "スランプに悩む売り出し中の恋愛小説作家が変装して街へ繰り出し、インスピレーションを探している。なぜ変装する必要があるのか？きっと、普段は凛とした商会の管理人が、プライベートで「乙女心」むき出しの趣味を持っていると知られたくないからだろう。\nしかし、この趣味に対するベセルの執着を侮ってはならない――彼女は創作のインスピレーションのためなら、自分の身の危険すらいとわないのだ…",
  str_item_intro_4090673 = "そよ風が吹くと、白くてふんわりしたスカートがかすかになびき、赤い花が顔をのぞかせる。アリスの衣装は不思議とケーキを連想させる…そう、誕生日にしか食べることのできない、あのイチゴのケーキだ！しかし、「幻のスイーツ屋」では、店主アリスの質問に正直に答えるだけで、大好きなスイーツを何でも無料で食べられる。それはアリスからの特別なおしお…いや、「ご褒美」なのだ。",
  str_item_intro_4090103 = "「きれいで清潔な服。それこそがメイドの誇り！」\nそれじゃあ、リタの手縫いのメイド服に着替えて、レースの縁取りがついたヘアバンドをつけよっと！あっ、そうそう。金色のリボンが縫い付けられたエプロンも、忘れずにね！\n今日のルイスのお仕事は…ご主人様のメイクのお世話、それからアフタヌーンティーの用意だね。心配しないで！ミツバチさんとシカの赤ちゃん、それからお空の雲さんも手伝ってくれるから。\nさあ、メイドさんのお仕事、始まるよ～！",
  str_item_intro_4090283 = "オッホン！それでは、アップトン荘園のメイド長をお迎えしましょう！…えっ、見覚えがある？その通り！我らがかわいいラファエルだ！\n彼女が最近受けていた特別任務は、白夜城のメイドたちを訓練し、ある程度の戦闘能力を身につけさせるというものだった。訓練期間も終わりに近づき、ラファエルの丁寧な指導により、メイドたちはメキメキと成績を上げていったが…ラファエルの方のメイド修行は、あまり順調ではないようだ。",
  str_item_intro_4091163 = "思い出の中の「あのパン」を作るため、フェラールは知恵を絞り、何度も試行錯誤を繰り返していたが、うまくいっていなかった。\n今日のフェラールの準備は今まで以上にばっちりだ。縫い目が整ったシャツ、アイロンがけされたエプロン、そしてピカピカに磨かれた革靴。美味しいパンを作るには、服装が大事と言われたからだ。あまり信憑性のない話だが、フェラールは思い出のパンのために、出来ることは何でもする覚悟だった。",
  str_item_intro_4090703 = "空気まで熱くなり、呼吸が荒くなるような気がするような視線…これは緊張だろうか？そうかもしれない。リオナほど強くて美しい者の前では、緊張しない人の方が少ないだろう。ストラップ式サンダルのひもが彼女の両足に絡みつき、いつものスタイルとはまったく異なるアクセサリーが体を飾っている。そして彼女自身は、世界のすべてを手に入れたかのような雰囲気でゆったりとたたずんでいる…",
  str_item_intro_4090813 = "これはヘールが「あるもの」を探すために用意した服らしい。動きやすい水着、彼らしいサーフボード、レインコートを参考にしてデザインされた透明な上着…透明？そう、ヘールの透明な上着を着ている本当の目的は、肉体を見せつけるためだろう――プロテインとハードなトレーニング、太陽と汗でできた彼の肉体が、賞賛の声を待っているのだ！",
  str_item_intro_4091123 = "最近、影ノ街に流れているウワサ。予告状、追っ手を手玉にとる怪盗、盗まれた宝石…犯人は我々の前で興味なさそうにしているスモーキーなのだろうか？真相を知りたければ、まずは彼女の手錠を外さなければならないだろう。もちろん、彼女の新しいあだ名と服も気になる。「怪盗クロネコ」は3日後に約束通り宝石を奪いに来るそうだ…",
  str_item_intro_4090384 = "水着が先だったのか、それともゲームが先だったのか？今さらどちらでもいいことだ。重要なのはこれを着たガルーが休暇モードになるということだ。つまり、これはガルーが休暇のためにわざわざ用意したものなのだ。たとえ、行先がビーチではなく、水族館だったとしても",
  str_item_intro_4090413 = "果たしていくつの顔があるのだろうか？白夜城のガイド以外にも、彼女には数々の副業がある。その1つが「ホテル・フルートプラチナ」のイメージキャラクターだ。この水着は広告の撮影時に着たもので、素材や裁断も洗練されている。青い海と青い空の下に建つホテルには、人々も心を奪われてしまうことだろう",
  str_item_intro_4090873 = "バーバリーが島の領地を巡察した時、現地に融け込むために着替えた甲冑のような水着。普段よりはずっとシンプルな着こなしだが、貴族らしいオーラは隠しきれない。これは武を貴ぶ家柄の影響というよりも、バーバリー自身が貴族としての名誉を追い求めた結果なのだ",
  str_item_intro_4091293 = "涼しげな夏の装いだが、ルークの真剣な眼差しが、くつろぐためではなく、重要な任務のために来たのだと物語っている。これは高温多湿な森の中で彼の体力を保つだけでなく、貴重な蝶を守り、恥知らずな密猟者を撃退するために用意された「礼服」なのだ",
  str_item_intro_4091483 = "砂漠の水祭りがまもなく始まる。しかし、多くの人がそれ以上に興奮しているのは、アズールの魅惑的なスタイルのせいだ！特に肌見せ多めの服を着た姿はなんとも…オッホン！皆さん、あまりじっと見過ぎないよう、視線にはご注意を。時には熱く湿った夜風に吹かれながら、騒がしい音楽に合わせて皆と一緒に踊るのもいいだろう！",
  str_item_intro_4090254 = "古き時代の貴族のようなたたずまいと華麗なステージの空気感…見るからに非日常そのものの衣装は、カロン自らデザインした舞台衣装である。誇張されたデザインもカメラの前に立てば、一気に観客の目を引き付け、役になりきったカロンの印象深い演技を一層と引き立てる。カロンも、この衣装も、まさに芝居のために生まれたかのようだ。",
  str_item_intro_4090683 = "さあ、買った買った！クーリエ隊と影ノ街の新聞社が提携し、クーリエたちは新しい任務――新聞購読のセールスを任されることになった。ウェンディは新聞配達用の制服を身にまとい、新聞を手に飛び回ってセールスに励む。常にスピード重視のウェンディは、新しい業務であろうと誰にも引けをとらないようだ。",
  str_item_intro_4091003 = "過去に縛られるスカーレイがいつもと違う服装に着替えた。一見、普通の医者のようだが、常に持ち歩く医療バッグが普通とは違う「業務内容」をうかがわせる。というのも、彼女が治すのは生きた人の病だけではない。亡くなった人の、「墓所」から響く声にも、平等に耳を傾けるのだ…",
  str_item_intro_4091203 = "友好を深めるための交流活動で、白夜城のヘイディは同僚たちの推薦を受け、交通安全と犯罪予防の意識向上を呼びかける「1日護衛官」になることに。啓光連邦のカナン城に出向いたヘイディだったが、そこでは白夜城の騎士といえども、啓光の制服に着替えなければならない。ヘイディ自身はどうもなじめないようだが、彼女の自信と魅力は変わることなく輝いている。",
  str_item_intro_4091193 = "記憶の中の魅惑の味を求めて、レビィは独り危険を犯し、監獄に潜入した。グレーゾーンで生きるさまざまな犯罪者が集まる監獄には危険がいっぱい…啓光連邦から混沌の地に足を踏み入れたレビィは、順調に目標を達成し、自らの潜入任務を果たせるのだろうか？",
  str_item_intro_4091213 = "真っ赤な花びら、枝を埋めつくすトゲ…パロマのスタイルは、見る者にまるで「近寄るな」と告げているようだ。うっすらと浮かぶ笑みが、彼女の冷たく美しい危険な香りをさらに際立てる。軽率に怒らせてしまえば、恐ろしいことになりそうだ。影ノ街の組織のボスたちが敵を片付けるように…それとも、彼女はもうすでに…",
  str_item_intro_4090123 = "カナン城でにわかにささやかれるようになった「正義執行、a.k.a.天罰代行」のウワサ。規律を守らない者がいると、突如雷鳴と共にナミシスが現れ、罰を与えるという。そして、相手の心を刺すラップで相手を悔い改めさせ、「正義」の執行を終えると、再び起こった雷鳴と共に一瞬で姿を消し、また別のところへ向かうのだとか…",
  str_item_intro_4090773 = "休日を過ごしていたベツレヘムは、偶然ある天才女性シンガーの伝記を手にした。文字が描き出す世界に浸るベツレヘムは、まるで自分がその歌手になったかのような感覚に包まれ、鮮烈なデビューを飾り、一世を風靡したのちに声を失い、人々の視界から姿を消した一生を体験する。「もし自分だったら、どうしていただろうか？」――いくら考えても答えが見つからないベツレヘムは、想像に身を任せる。もしも自分がその女性シンガーで、楽器を手にし、情熱的に創作活動を行い、最後のステージで声を失うのだとしたら。彼女の人生を想像し体験することは、自身の未来の可能性を探ることでもあるのだ",
  str_item_intro_4090833 = "「リリ」を覚醒させるためにできることは…アイドルになること！？メイドのルールをかたくなに守り続ける彼女たちは、果たしてアイドルになれるのだろうか？なんといっても、アイドルには生き生きとした魅力と創造性が必要なのだから。だが、一連の行動基準と数の優位性があれば、可能性もゼロではないかもしれない…",
  str_item_intro_4091313 = "音楽に垣根はない。ノーヴィオはこの日、いつもとは全く異なる服を身にまとい、ピアニストに変身した。そして、北境で強くたくましく暮らす人々にあたたかい祝福を届け、一縷（いちる）の期待を抱く特別な観客に励ましを贈った。これからの日々も、人々が強くたくましく暮らしていけるように。",
  str_item_intro_4091383 = "上司と色々あって参加したアイドルオーディションではあったが、シヴォーンは相当の準備と訓練をして臨んだ。衣装もコストを惜しむことなく、精魂込めて研究しデザインしたものだ。そうした科学者としてのプロ意識がもたらした効果は、まさに驚くべき大変身！誰も止めることのできない光り輝く魅力は、まさにスターへの階段を予感させる…",
  str_item_intro_4090273 = "白夜城の恋人たちの間でささやかれる恐ろしいウワサ――毎年冠月祭の季節になると、白い服をまとった騎士が白夜城の隅々を巡回し、熱愛中の人々を見つけると「恋愛禁止告知書」を突き付けるという。こうしてこの騎士は恋人たちから「恋を断ち切る雷光」と呼ばれ、恐れられるようになった",
  str_item_intro_4090553 = "普段の厳かな服装と違い、今日はピアタマンも街の冠月祭の空気に影響されたのか、いつもの毅然とした雰囲気の中にも優しさを感じさせる装いをしている。もちろん、意中の人に会うためではない。ある人の願いをかなえるため、使者としてふさわしい服装を選んだのだ",
  str_item_intro_4090913 = "クロエにとって、愛は常に別れと共にある。そんな彼女に幸せいっぱいの愛をたたえる曲を演奏させるのは少々無理がある。ならばいっそのこと、神の名において、永遠の愛をたたえよう――人々の抱く愛は限られた月日の中に消えていく。だが、それでよいのだ。光はいつでも平等にこの世のすべての者を祝福し、愛してくれる",
  str_item_intro_4091673 = "この手の社交場には数々の小さなマジックが存在する。そのタネは「秘密」。1枚のカード、1つの言葉、そして視線…宴はたけなわ、誰も気づかぬ間に、壮大かつ巧妙なパフォーマンスはすでに完成している。ジェノにしてみれば、いつもの拍手喝采には欠ける。だが、たまには友人に恩を売るのも悪くない。",
  str_item_intro_4090043 = "冷えきった遺体、証拠の横に置かれた札やチョークのアウトライン、そして規制線…よく見る典型的な疑惑漂う事件現場に立てば、様々な憶測が浮かんでくる。「探偵が犯人ではないか？」、「探偵は犯人と通じていたのではないか？」、「犯人は身近な者の中に潜んでいるのではないか？」、さらには「証人がすべて犯人」なんてことも…だが、いったい誰が想像しただろう？被害者と探偵が仲間だったとは…",
  str_item_intro_4090483 = "穏やかな影ノ街にひそかに漂う不吉な空気。静かな夜を楽しむ道行く人々の中で、鋭いパトロールの眼差しはわずかな罪悪も見逃さない。罪悪が潜むかぎり、この街の平和を守る彼女は歩みを止めることなく、パトロールは永遠に続く。それもこれもすべて…かけがえのないたった一人の妹のために！",
  str_item_intro_4091484 = "整然と明るい事務所、柔らかいソファー、心も酔いしれるような美酒、そしてソファーにもたれかかる「マネージャー代理」…彼女のけだるい雰囲気に騙されてはいけない。この美女には危険な香りが漂っている。特にこれからやってくる獲物には…本当の「危険」が待ち受けているのだ",
  str_item_intro_4091663 = "「うーん…かわいい子たちはどこにいるんだろう？」珍獣を探し出し、真相を突き止めるため、探偵に扮したフィアが「事件」調査に挑む！集めた証拠を分析し、怪しい点を洗い出す…調査に没頭する真剣なフィアの姿を見ていると、本当に何か発見できそうな気がする",
  str_item_intro_4090983 = "シャドウマスターの命を受け、引きこもりがちなクスッタも最近街にのさばっている罪人をつかまえるべく、探偵とならざるを得なくなった。もちろん、クスッタは聞き込みや事情聴取が得意ではない。だが、鋭い彼女はあの「安楽椅子」に座ったまま手元の手がかりだけで、事件の全体を見通し、思考によって犯人を突き止める。",
  str_item_intro_4091034 = "この世に生きるすべての者は罪を犯すべきではない。罪を犯せば、必ず天罰がくだる。人の世において、それは尋問、判決、懲罰として現れる。もちろん、その過程はそう恐ろしいものではない。殊にエルシーは尋問官として、優しく、暴力を一切用いることなく、相手の心の防御を崩していく…もちろん、心の防御など彼女の前では無意味なのだが。尋問官エルシーに会った時には、抵抗せず、すべてを彼女に任せよう。",
  str_item_intro_4090293 = "「先生」の願いをかなえるため、ガブリエルは厳かな礼服に着替え、影ノ街にある孤児院へと向かった。薄暗く、荒れ果てた環境と精巧な作りの礼服とのコントラストに、ガブリエルのゆったりとした話し方や立ち居振る舞いが加わって、子どもたちはガブリエルを「魔女」と勘違いしてしまう。しかし、最後には彼女のこの地を守りたいという気持ちが子どもたちに伝わり、礼服にも心やすらぐ輝きがきらめいたように見えた。",
  str_item_intro_4090463 = "大人たちにとっては恐怖の対象である黒魔術の本も彼らにとっては神秘の世界へと続く入口だ。そこにはたくさんの幻想と魔法、不思議が満ちており、まさに彼らのような好奇心あふれる、かつ高慢な魂のために用意された世界だ。「禁じられた魔法の薬」を作ろうと、様々な奇妙な材料を探し回るため、専用の服装に着替えた彼らはいつも以上に個性豊かな姿となった。",
  str_item_intro_4090623 = "リアの勉強会が順調に進むよう、シルヴァはわざわざ正式な服装に着替えた。これから先生に会いに行く若手学者のような服装は知的で聡明な印象とともに、粛然とした雰囲気を漂わせている。シルヴァのこうした態度は当然勉強会にもよい空気感をもたらした。シルヴァはまさに「模範生」と言えるだろう…",
  str_item_intro_4091433 = "夜の森を突然の雷雨が襲うと、不吉なものがこの世に現れるという。リンネは厳かな巫女の衣装をまとい、神楽鈴を掲げ、穢れを祓い、衆生を救う。\n「…即ち陰陽を誦み、此の曲、汝の魂と伴に彼岸へと帰らん…」\n「三途の川の下にて、曲の幽生なるを怨み…」\n「曼荼羅は語り、琴瑟は和して鳴する」\n「聴く者の心を寧んじ、吾が魂は満たされり…」",
  str_item_intro_5000001 = "古代の情報に関する謎の物質が含まれているらしい。建物建設や家具製造の速度を加速できる",
  str_item_intro_5000002 = "天空ノ庭-宝物更新回数",
  str_item_intro_5002101 = "堅くてしなりのある木材。家屋建設や家具製造などに適している",
  str_item_intro_5002201 = "採掘したばかりの鉱石。加工する必要はあるが、それでも市場で一定の値がつく",
  str_item_intro_5003001 = "天空ノ庭の各地で発見される石片。遺物と思われるが、具体的な機能は不明。キューブたちの好物らしく、何かしらのアイテムと交換してくれる",
  str_item_intro_5003101 = "建物建設や家具製造で使われる接着剤。材料同士をよく接着させ、部品を強固にする",
  str_item_intro_5003102 = "建物建設や家具製造で使われる上等な接着剤。少し塗るだけで材料同士をしっかり接着でき、部品をとても強固にする",
  str_item_intro_5011001 = "Lv1の軽量斧。持ち手の部分がくり抜かれて軽量化されている。持ち上げやすく、素早く動かせるため、太い木でも短時間で伐採できる",
  str_item_intro_5011002 = "Lv2の軽量斧。持ち手の部分がくり抜かれて軽量化されている。持ち上げやすく、素早く動かせるため、太い木でも短時間で伐採できる",
  str_item_intro_5011003 = "Lv3の軽量斧。持ち手の部分がくり抜かれて軽量化されている。持ち上げやすく、素早く動かせるため、太い木でも短時間で伐採できる",
  str_item_intro_5011004 = "Lv4の軽量斧。持ち手の部分がくり抜かれて軽量化されている。持ち上げやすく、素早く動かせるため、太い木でも短時間で伐採できる",
  str_item_intro_5011005 = "Lv5の軽量斧。持ち手の部分がくり抜かれて軽量化されている。持ち上げやすく、素早く動かせるため、太い木でも短時間で伐採できる",
  str_item_intro_5012001 = "Lv1の釣竿。重量のバランスがとれ、しなやかさもある竿。釣り糸も丈夫で、大物が引っ掛かった際には大きな助けとなる",
  str_item_intro_5012002 = "Lv2の釣竿。重量のバランスがとれ、しなやかさもある竿。釣り糸も丈夫で、大物が引っ掛かった際には大きな助けとなる",
  str_item_intro_5012003 = "Lv3の釣竿。重量のバランスがとれ、しなやかさもある竿。釣り糸も丈夫で、大物が引っ掛かった際には大きな助けとなる",
  str_item_intro_5012004 = "Lv4の釣竿。重量のバランスがとれ、しなやかさもある竿。釣り糸も丈夫で、大物が引っ掛かった際には大きな助けとなる",
  str_item_intro_5012005 = "Lv5の釣竿。重量のバランスがとれ、しなやかさもある竿。釣り糸も丈夫で、大物が引っ掛かった際には大きな助けとなる",
  str_item_intro_5013001 = "Lv1の重量つるはし。頭の部分を重くしてあり、高く振り上げてから落とすと威力抜群。どのような岩でも砕ける",
  str_item_intro_5013002 = "Lv2の重量つるはし。頭の部分を重くしてあり、高く振り上げてから落とすと威力抜群。どのような岩でも砕ける",
  str_item_intro_5013003 = "Lv3の重量つるはし。頭の部分を重くしてあり、高く振り上げてから落とすと威力抜群。どのような岩でも砕ける",
  str_item_intro_5013004 = "Lv4の重量つるはし。頭の部分を重くしてあり、高く振り上げてから落とすと威力抜群。どのような岩でも砕ける",
  str_item_intro_5013005 = "Lv5の重量つるはし。頭の部分を重くしてあり、高く振り上げてから落とすと威力抜群。どのような岩でも砕ける",
  str_item_intro_5014001 = "先端の厚みを増したことで、硬い石に当たっても滑ることがなく、楽に採掘ができる",
  str_item_intro_5011012 = "表面が粗く、硬い石。鈍った刃物をとても鋭利に研げる\nバッグにある軽量斧をレベルアップできる",
  str_item_intro_5012012 = "天空ノ庭で見つけられる上質な木材。薄く切ると釣竿の強度を高め、しなやかにできる。特製の釣り糸と組み合わせると、釣竿があらゆる状況に対応できるようになる\nバッグにある釣竿をレベルアップできる",
  str_item_intro_5013012 = "手で回転砥石を素早く回すと、つるはしの鈍った先端を鋭く研げる\nバッグにある重量つるはしをレベルアップできる",
  str_item_intro_5111001 = "蒼覆のテラスの図面。風の塔で「蒼覆のテラス」の製造方法を解放できる",
  str_item_intro_5111002 = "ラピスのアーチの図面。風の塔で「ラピスのアーチ」の製造方法を解放できる",
  str_item_intro_5111003 = "物資集積所の図面。風の塔で「物資集積所」の製造方法を解放できる",
  str_item_intro_5111004 = "緑の井戸の図面。風の塔で「緑の井戸」の製造方法を解放できる",
  str_item_intro_5111005 = "風車小屋の図面。風の塔で「風車小屋」の製造方法を解放できる",
