  str_item_intro_5131002 = "円形石製テーブルの図面。風の塔で「円形石製テーブル」の製造方法を解放できる",
  str_item_intro_5131003 = "4本脚の木製テーブルの図面。風の塔で「4本脚の木製テーブル」の製造方法を解放できる",
  str_item_intro_5132001 = "円形石製椅子の図面。風の塔で「円形石製椅子」の製造方法を解放できる",
  str_item_intro_5132002 = "台形石製椅子の図面。風の塔で「台形石製椅子」の製造方法を解放できる",
  str_item_intro_5132003 = "2本脚の木製椅子の図面。風の塔で「2本脚の木製椅子」の製造方法を解放できる",
  str_item_intro_5132005 = "石製ハンギングチェアの図面。風の塔で「石製ハンギングチェア」の製造方法を解放できる",
