  str_item_intro_5211001 = "支柱が斜めになったテラス。コケで覆われた岩を屋根にしている。見た目は建築常識に合っていないが、とても頑丈",
  str_item_intro_5211002 = "ひと塊の岩を彫って作られたアーチらしい。表面を草が覆っているが、その堅固さは心配無用",
  str_item_intro_5211003 = "谷の中で物資を輸送する時に休憩する場所。短時間で建設でき、解体も簡単なため、道の途中にたくさん建てられる",
  str_item_intro_5211004 = "地下の水源が集まる場所に掘られた井戸。下をのぞくと底が見えないほど深いため、誤って落ちないように周囲を石製のフェンスで囲っている。深く掘られた井戸の水はきれいで冷たい",
  str_item_intro_5211005 = "独特な形をした風車。やや低く見えるが、風の力を十分に利用している。不思議な技術を利用しており、無風の時でもゆっくりと回転できる",
  str_item_intro_5221001 = "木製のフェンス。つなげて設置すると天空ノ庭の一区画を囲める",
  str_item_intro_5221002 = "背の低い柵。無造作につなぎ合わせた木が田舎らしさを醸し出している",
  str_item_intro_5221003 = "木製の囲い。製造方法は簡単で、建物やエリアの仕切りに使うのに適している",
  str_item_intro_5221004 = "石製のフェンス。重くて強固。木製のフェンスに比べて耐久性がある",
  str_item_intro_5221005 = "石製の囲い。地面に挿すだけで、風雨にさらされようと、何年も使える",
  str_item_intro_5221006 = "粗削りの石の柵。安定感があるだけでなく、不思議な安心感も与えてくれる",
  str_item_intro_5223001 = "方形のタイル。きれいに敷き詰められる。主要な道路や重要な建物の周りの地面に適している",
  str_item_intro_5223005 = "不規則な石をつなぎ合わせたタイル。細い道の舗装や庭園の装飾に適している",
  str_item_intro_5231001 = "台形の石板2枚で支えているテーブル。重くて頑丈",
  str_item_intro_5231002 = "やや小さい石製の円形テーブル。対応する椅子と組み合わせれば、少数でのお喋りに最適",
  str_item_intro_5231003 = "四方に脚がついた木製テーブル。広くて平らで、数人で気軽に座るのに適している",
  str_item_intro_5232001 = "円形の石製椅子。中空構造の中に支えとなる石柱が1本ある。頑丈なだけでなく、丸みを帯びた外側の構造によって、石の角にぶつかりにくくなっている",
  str_item_intro_5232002 = "底が広く、座面が狭くなった四角い石製椅子。表面には木の板を重ね、石の冷たさを感じないようにしている。大雑把なデザインで製造方法も簡単。石の角にぶつかりやすいのが玉にきず",
  str_item_intro_5232003 = "シンプルで簡素な木製椅子。両側を支える構造になっており、座った時にかすかな揺れを感じる",
  str_item_intro_5232005 = "不思議なデザインの石柱からロープが垂れ下がっている。座面をリーフ状にすることで快適に寝転がれるよう、巧みなバランスで設計されている",
  str_item_intro_5232006 = "石の台で作られたベンチ。座れるだけでなく、横にもなれる。石でできており、ひんやりとした手触りも得られる",
  str_item_intro_5233001 = "大小2つの岩が重なるように置かれている。適切な位置に設置すれば、周囲の建物にユニークな景観をもたらせる",
  str_item_intro_5233002 = "石筍を数倍に拡大したように見える。適切な装飾を加えれば、格別な雰囲気になるだろう",
  str_item_intro_5233003 = "形状が異なる岩石をいくつか組み合わせたもの。通常は道路脇や庭園に装飾として設置する",
  str_item_intro_5233004 = "パラソル状の屋根を持つテラス。屋根は1本の柱で支えられている。日陰を多く作るため、わざと斜めにしているという。屋根の上はつるに覆われ、風が吹くと枝や葉が垂れ下がり、違った味わいが楽しめる",
  str_item_intro_5233005 = "重なり合った岩、きれいな水が湧き出る滝、さらに大きな石片で囲われた池、この3つが結び合わさり、庭園に心地よい水の音を届け続けてくれる",
  str_item_intro_5233006 = "直立した岩の柱はメインの岩石として利用できる",
  str_item_intro_5233007 = "岩の柱が斜めに連なってできている。小さな峰を彷彿とさせる",
  str_item_intro_5233008 = "やや傾いた岩の柱。デザインがまったく違う岩の中間的装飾として適している",
  str_item_intro_5233009 = "先端が尖った岩の柱。全体的に細く見え、見る者を圧倒する。適切な岩と組み合わせるとよい",
  str_item_intro_5233010 = "傾斜した丘陵を彷彿とさせる。メインの岩としても使える",
  str_item_intro_5234001 = "不思議な技術を利用して明るく保たれている街灯。背が低く、狭い範囲しか照らせない",
  str_item_intro_5234002 = "1本の柱で支えられている街灯。背が高いので遠くまで十分に照らせる",
  str_item_intro_5234007 = "やや背の高いフラワースタンド。遠くからでも満開の花を楽しめる",
  str_item_intro_5234009 = "さまざまな道標が釘打ちされた看板。広大な天空ノ庭でも道に迷わずに済む。ただし、方角を間違えないようにすること",
  str_item_intro_5234011 = "十分な日陰と涼しさをもたらすパラソル。重くて持ち運びに不便なところが欠点",
  str_item_intro_5234012 = "太陽のような見た目から名付けられた花。背の高い茎と、大きく開く円盤状の花が誇り高きオーラを放っている。「光に憧れる」ことの象徴だと思っている人もいる",
  str_item_intro_5234013 = "石を積み上げた区画。地面も平らに整えられ、さまざまな花を植えるために使われる",
  str_item_intro_5234014 = "やや背の低いフラワースタンド。道路脇、ドアの前の装飾として設置するのに適している",
  str_item_intro_5234018 = "野外で使用する個人用テント。円錐型にすることで、テント内に十分な高さが確保されている。設営も簡単だが、狭いので1人用",
  str_item_intro_5234019 = "さまざまな食べ物が並べられたシート。野外でもおいしい食事を楽しめそうだ",
  str_item_intro_5234020 = "丈夫で火に強いかがり火の台座。台座部分の隙間から空気を取り込み、炎を大きくして強い熱を放つ",
  str_item_intro_5234023 = "雑草でも無駄にはできない。集めれば何か使い道があるかもしれない",
  str_item_intro_5234024 = "板を釘で打ち付けて作った箱。加工しやすく容量もあるので、物を保管するのに適している",
  str_item_intro_5234025 = "木箱をいくつも積み重ねたもの。おかれている場所はほぼ物置であることが見てとれる",
  str_item_intro_5234037 = "石で囲ったウッドストーブ。屋外で焚き火ができ、火事にもならない",
  str_item_intro_5234038 = "海底で見つかった錨（いかり）。非常にしっかりとしており、波にもまれる大型船もきっと流されることはないだろう。残念ながら元の持ち主はすでに行方知れずであり、錨はただ静かに再び使う者が現われることを待っている。",
  str_item_intro_5234039 = "揺れる波を動力としている。これを使えば、水面上を自由自在に進むことができるだけでなく、さまざまな動きも可能だ。天空ノ庭に置いておくのは、少々もったいない…",
  str_item_intro_5241002 = "座ると少し揺れるブランコ。力を入れすぎないように要注意。このブランコに座りながら寝るのが好きな人もいる。優しい揺れはすぐに眠りにつかせてくれる",
  str_item_intro_5241003 = "ちょっとした乗馬気分を味わえるおもちゃ。バランス感覚を鍛えられるらしい",
  str_item_intro_5241004 = "風が強すぎない晴れ日に行うのがよい。凧を空高くあげたら、風で飛ばされないように凧糸をスタンドに結ぼう",
  str_item_intro_5241005 = "屋外での写生用に設計された簡素なイーゼル。絵を描くのに、ちょうどいい角度と大きさになっている",
  str_item_intro_5241006 = "ステージやアンプの位置に工夫を凝らしたデザイン。観客がさまざまな角度からショーを楽しめるようになっている。また、異なる演出効果を見せるための不思議な技術が使われている",
  str_item_intro_5241007 = "大陸の有名な山や川をすべて踏破した空の末裔の女性を記念したものらしい。しかし、今では彼女の名前を知る人はおらず、このような彫像が記念として残されているだけだ",
  str_item_intro_5241008 = "見るたびに無性に殴りたくなる…しかし、どれだけ殴っても倒れることはない。少し残念だが、ストレス発散にはもってこい",
  str_item_intro_5241016 = "巨大な回廊。柱が何かの古代生物の骨のように見えることから、巨像内の重要パーツだと言う人もいる",
  str_item_intro_5242101 = "見た目は奇妙だが、独自の構造によって光をふんだんに取り入れる。風通しもよく、住むのにとても適している",
  str_item_intro_5243001 = "非常に栄養価の高い土地。あらゆる植物に十分な栄養を供給できる",
  str_item_intro_5234008 = "頭を麻布で作られたカカシ。近くで見ると、顔にあばたがたくさんあるようだ。これによって威嚇効果が大幅に上がるらしい",
  str_item_intro_5234015 = "百聞は一見にしかず。看板を見れば意味は一目瞭然――「イシマジロを守ろう！」",
  str_item_intro_5234016 = "太陽光の影で時間を知ることができる装置。初期の時計とも言われている。曇りや雨の日、または夜になると使えないのが欠点",
  str_item_intro_5234017 = "風向きの測定に使用する機械。とても感度が高く、微風でも正確に測定できる。風が強すぎたり、風向きが頻繁に変わる場合は、高速回転で壊れないように矢印を取り外すこと",
  str_item_intro_5234026 = "動かすのにかなりの力を要する石うす。古くは小麦粉をひくのに使われていたらしい。今では労力のわりに効率が悪い。ただし、筋力を鍛えるために時々使うぐらいなら悪くないだろう",
  str_item_intro_5234027 = "丈夫で軽い木桶。持ち手に滑り止めが施され、不注意でひっくり返ったり、力を無駄遣いしないようになっている",
  str_item_intro_5234028 = "セラミック製だが、縁の部分が補強され、落下や衝突に強くなっている。さらに取っ手があるので運びやすい",
  str_item_intro_5234029 = "1人でも簡単に生地を織れる機械。その代わり、メンテナンスがやや面倒…",
  str_item_intro_5234030 = "青草がいっぱいに植えられたつぼ。とても重く、運ぶのには力が必要",
  str_item_intro_5234033 = "つるで覆われた棚。夏には日陰を作り、晩秋でも緑がいっぱいのままになっている",
  str_item_intro_5234036 = "3段の石が積み上げられた花壇。日差しをたっぷり浴びられる最上部の花を、下の2段の草が引き立てる",
  str_item_intro_5241015 = "上に置いたレコードの音楽を流せる不思議な装置。スピーカーが付いているため、音が遠くまで届き、反響が長く続く。",
  str_item_intro_5241017 = "アクアリウム",
  str_item_intro_5251001 = "風の塔",
  str_item_intro_5252001 = "ミュージアム",
  str_item_intro_5253001 = "商店",
  str_item_intro_5254001 = "願いの泉",
  str_item_intro_5255001 = "大型で頑丈、防水、防塵の機能を持つ。たくさんのアイテムを収納できる",
  str_item_intro_5256001 = "挑戦もスリルも、喜びも笑いもたくさん詰まった、仲間たちとの冒険。旅の中で体験した、忘れがたい数々の出来事を記念するため、仲間たちがメダルを作った。大切にしまって、空の末裔と仲間たちの記念としよう",
  str_item_intro_5270001 = "栽培区画",
  str_item_intro_5275001 = "愛と希望のために、歌声を大陸全土に伝えよう！\nツアー用に特別に作られたステージ。急ごしらえながら様々な機能を満たし、歌やダンスを披露できるよう頑丈にできている",
  str_item_intro_5275002 = "リズミカルに叩くだけで雰囲気が盛り上がる！バンドのリーダーといえばドラマーだよね？だからツアーのステージには欠かせない",
  str_item_intro_5275003 = "ダンスに音楽は欠かせない。操作が簡単で多彩な音色があるキーボードは、ひとりでもバンドが組めるかも",
  str_item_intro_5275004 = "星に願いを！この星飾りに願いをかけると、自分の応援がアイドルの心に届く。いつからかそんな噂がファンの間で広まった",
  str_item_intro_5275005 = "アイドルの応援に応援グッズは欠かせない。ツアーステージのそばにこのテーブルを置けば、ファンが様々な応援グッズを受け取るのに便利",
  str_item_intro_5275006 = "ツアーに各種ギターを用意すれば、ギタリストが自分のスタイルに合ったギターを選べるのはもちろん、複数人で演奏もできるためライブが大いに盛り上がる",
  str_item_intro_5275007 = "ツアーにこのタイプのスピーカーは欠かせない。どれほど会場が広く観客が多くても、アイドルの声を皆に届けることができる。しかも、形がカワイイ",
  str_item_intro_5275008 = "ツアー会場付近の装飾。宙に漂い、風に舞う姿は、アイドルのバックダンサーのようにも見える",
  str_item_intro_5275009 = "ツアーステージのそばに置かれた装飾用ライト。ファンがアイドルの応援に使っているらしい。公式グッズではないが、意外にマッチしている",
  str_item_intro_5275010 = "ツアーにアイドルの等身大パネルは欠かせない。アイドルと写真が撮れなくても、本人に会えなくても、このパネルを見ればファンは慰められるだろう",
  str_item_intro_5275011 = "祝福を込めて花を贈ろう。たくさんの花はたくさんの祝福の証。しっかり管理しないと、ツアー会場全体がファンから届いた花で埋もれてしまうかも",
  str_item_intro_5275012 = "このボードの星はファンが一つ一つ貼り付けたものだそう。もはや装飾というより、アイドルのツアー成功を願うファンの祈りだ",
  str_item_intro_5275013 = "ツアー用に特別に手配されたシート。ファンの多くは座らずに、ここに立ってアイドルを応援したいと思っている。もちろん自分のほうを見てほしいから",
  str_item_intro_5234043 = "「ふわふわの雪でソファーが作れるの？」\nそう思った人も多いかも。もちろんこのソファーは普通の素材で作られているが、背もたれが雪山の形で、座面がふかふかなので、雪の上に寝そべっているような気分になる",
  str_item_intro_5234044 = "この不思議な生き物は永遠に歳を取らないと言われている。この奇妙な調度品もこの伝説をふまえたもので、しばらく眺めていると癖になるかも",
  str_item_intro_5234045 = "たとえ天の果て地の果てであろうと、必ず人々の思いと願いを届ける。このポストはもっぱらそのために設置されたものと言われており、心と心の距離を縮めてくれる",
  str_item_intro_5234046 = "面と向かって話せないことは手紙に書いて、ここに貼っておこう。きっと相手の目に触れて、思いが伝わるはずだ",
  str_item_intro_5276001 = "通常「冠月祭」で設営されるステージ。さまざまな集まりに使われ、特に仲睦まじいカップルの結婚式に最適である",
  str_item_intro_5276002 = "厳かな雰囲気が漂う、華やかな飾りを施した乗り心地のよい馬車。祝日のパレードにも、新郎新婦を迎えるにもふさわしい乗り物だ",
  str_item_intro_5276003 = "最近流行り出したらしい新しい娯楽。何回も回転した後も今まで通りお互いを気遣うことができれば、そのカップルの愛が本物であることは間違いないだろう",
  str_item_intro_5276004 = "ガゼボに咲くバラは特殊な方法で栽培されたものと言われている。「冠月祭」の当日にのみ満開の花を咲かせ、ここを訪れる新郎新婦たちを祝福してくれるのだ",
  str_item_intro_5276005 = "チョコレートは本来苦いものである。砂糖を入れなければ甘くはならない。もしかしたら愛情もまた、チョコレートのようなものなのかもしれない。いずれにせよ、チョコレートは今や冠月祭の代表的な贈り物となっている。多くの人々がその甘さだけに気をとられ、その奥にある苦みを忘れがちなためかもしれない",
  str_item_intro_5276006 = "美しい形のアーチ。色とりどりの花が飾られ、新郎新婦が記念写真を撮るのにも、願い事をするのにも最適だ",
  str_item_intro_5276007 = "「冠月祭」でよく見られる飾り付けの一つ。ドリンクをいっぱいについだグラスを積み上げて作る。賓客をもてなすのに用いられているようだ",
  str_item_intro_5276008 = "滑らかな流線形のフォルムが美しいキャンドルスタンド。その造形により、ロウソクの光がちりばめられた宝石のように分散し、結婚式にロマンチックな雰囲気を添えてくれる",
  str_item_intro_5276009 = "おそらく結婚式の司会者にとって、「心の恋人」のような存在と言えるアイテム。これがあれば、会場のゲストに新郎新婦の誓いの言葉を聞いてもらえるだけでなく、音楽を流してロマンチックな空気をさらに高めることもできる",
  str_item_intro_5276010 = "「冠月祭」に限らず、普段においても恋人たちにはぴったりのベンチ。「冠月祭」当日には、新たに夫婦となったばかりの幸せな2人が座ることだろう",
  str_item_intro_5276011 = "おや？どうやらこれは、対の人形らしい。冠月祭の衣装に着替えただけのようだが、お似合いとしか言いようがない",
  str_item_intro_5276012 = "贈り物としても飾り付けとしても、「冠月祭」にピッタリの花の飾り物。会場に鮮やかな色どりを添えてくれるだけでなく、訪れたゲストたちにかすかな花の香りを届けてくれる",
  str_item_intro_5276013 = "バラの花のじゅうたん。ぜいたくな趣向から、式典を催す者の思い入れが感じられる。新郎新婦がこの上を歩く時、すべての来客の視線が2人に集まることだろう",
  str_item_intro_5276101 = "クラシカルなデザインのテーブルと椅子。座り心地の良さが特徴。人との対話、特に事件を推理するのに、いかにもふさわしい。どこぞの名探偵の影響だろうか。",
  str_item_intro_5276102 = "あの名探偵は、よくこのようなボードで集めた情報を整理して手がかりを見出し、分析を行っていたという。情報分析だけで真犯人を見つけることも珍しくなかったらしい。",
  str_item_intro_5276103 = "あの名探偵が世に名を知られると、彼の愛用する車も人気を集めた。何しろこの車は丈夫で耐用性が高く、スピードも出て、運転もしやすい。人気が出るのも当然だ。",
  str_item_intro_5276104 = "「思考が鈍った時にはコーヒーを1杯飲むといい。それでも頭が働かない時はもう1杯飲めばいい」思考のお伴であるコーヒーを入れる道具には、あの名探偵も金を惜しむことはなかった",
  str_item_intro_5276105 = "犯罪は往々にして冷え切った夜に起こる。名探偵には風を防ぐコートと帽子が必要だ。当然、このような帽子かけも欠かせない。",
  str_item_intro_5276106 = "小ぶりで便利なワゴン。コーヒーやお茶菓子などを運び、アフタヌーンティーを楽しめる。お客様が来た時には、使用人たちが配膳するのにも便利。",
  str_item_intro_5276107 = "推理中、ひらめきが浮かばない時、あるいは思考が行き詰った時、あの名探偵はこの楽器を弾き、リラックスしていた。通りには、彼の決して高くはない腕前で奏でる楽器の音色が響き渡った。幸い、人々が関心をよせるのは楽器の腕前ではなく、名探偵に関する数々の伝説だ。人々はこぞってこの楽器を求めたという。",
  str_item_intro_5276108 = "高い背もたれに、柔らかいクッション。正しい姿勢を保てるだけでなく、非常に座り心地がよい。「リラックスこそ思考」をモットーとする探偵たちにはもってこいのソファーだ。",
  str_item_intro_5276109 = "何本ものパイプを置けるスタンド。凝った造りで、「探偵らしい」雰囲気を醸し出してくれる。もちろん、これも推理愛好者たちのあの名探偵に対するあこがれの表れである。たばこは吸わなくても、装飾品として置いておくだけで十分だ。",
  str_item_intro_5276110 = "「いかなる手がかりも見逃してはならない！」真相とは往々にして、ささいな所に隠されている。ルーペは名探偵に欠かせないアイテムだ。",
  str_item_intro_5276111 = "明るさも持続時間も優れたランタン。風を防ぎ、軽量なので片手で簡単に持てる。もちろん、地面に置いても構わない",
  str_item_intro_5276112 = "少し低めに作られた黒板。あの名探偵がソファーに座りながら、事件の手がかりを整理するのに使っていた。素早い推理分析に欠かせない道具だ。",
  str_item_intro_5276113 = "2本足で支えられた、珍しい造りのブックレスト。あの名探偵がとても気に入っていた。どうやら、個性の強い人物は美的感覚も他の人たちとは違うらしい。もちろん、探偵好きなら、何としても手に入れて、家に置きたいものだ。",
  str_item_intro_5276114 = "雨の日にも日差しの強い暑い日にも、傘は欠かせない。緊急時には武器にもなる。傘立てを1つ出入り口に置いて、様々な傘を収集しておいた方がよさそうだ。",
  str_item_intro_5234047 = "「作家が吹雪で山荘に足止めを食らうと、その創作効率が10倍に上がる」――影ノ街の多くの編集者たちの間でよく言われる話らしい。しかし、なぜかこのメーカーのタイプライターが大いに流行し、一時期書き物を仕事とする者たちの必須アイテムとなった。",
  str_item_intro_5234048 = "影ノ街のそれなりの事務所ならば欠かせないソファー。マネージャーたちはこうしたソファーで客と話し、取引も行われる。",
  str_item_intro_5223003 = "円形の小さなタイル。芝生や路傍のアクセントとして最適",
  str_item_intro_5223004 = "やや大きめの円形タイル。舗装に使うだけでなく、道のデザインにおいて主要な構成部分にもなる",
  str_item_intro_5351001 = "天空ノ庭で最も目立つ建物。この地の象徴ともいえる。天空ノ庭の再建に使われた資料が大量に保存されている",
  str_item_intro_5351002 = "天空ノ庭で最も目立つ建物。この地の象徴ともいえる。天空ノ庭の再建に使われた資料が大量に保存されている",
  str_item_intro_5351003 = "天空ノ庭で最も目立つ建物。この地の象徴ともいえる。天空ノ庭の再建に使われた資料が大量に保存されている",
  str_item_intro_5352001 = "さまざまな物の展示、知識の記録および普及のために設けれた場所",
  str_item_intro_5352002 = "空間が広くなっただけでなく、装飾が施されたことによって、展示品を見学しやすくなった",
  str_item_intro_5352003 = "展示室を増やしたミュージアム。空間が広くなっただけでなく、分類もしやすくなった",
  str_item_intro_5353001 = "天空ノ庭の取引をする場所。通常の売買だけでなく、謎の注文もあるという",
  str_item_intro_5353002 = "外観が流線形に装飾され、風格がかなり増した。",
  str_item_intro_5353003 = "豊富な部屋数を持つ商店。取引専用の館になっている",
  str_item_intro_5354001 = "透き通った泉の水を眺めながら、美しい魚を楽しめるだけでなく、コインを投げ入れて願い事もできるらしい",
  str_item_intro_5354002 = "やや大きな泉。光輝く水面の下を泳ぐ魚を眺められるだけでなく、願い事も叶えられそうだ",
  str_item_intro_5354003 = "噴水は魚たちのために水を流しているだけでなく、願い事も叶えてくれるらしい",
  str_item_intro_5355001 = "大型で頑丈、防水、防塵の機能を持つ。たくさんのアイテムを収納できる",
  str_item_intro_5276201 = "白夜城の公爵などの上級貴族が使用する屋外用の椅子。上級貴族らしい堂々たる風格を存分に表しており、謁見に来た者はその威厳に圧倒され、思わず言動を慎んでしまう。もちろん、座っている者に威厳があってこそだが。",
  str_item_intro_5276202 = "「小さな空間に別世界が広がる」この水晶玉の中には、ある都市の「幻影」が存在しているという。だが一部の人たちにとっては、その幻影も貴重な思い出である。",
  str_item_intro_5276203 = "「弱きを助け、強きをくじく」騎士は白夜城の礎であり、白夜城の旗である。彫像の名は知らないが、その堂々と毅然とした姿を見ると、平民でさえも騎士精神が自然と湧きおこってくる。",
  str_item_intro_5276204 = "「収集品は公開すべき。金庫にしまっていては逸品も台無し」この展示ケースは華やかな装飾が施されているだけでなく、構造も丈夫で、美しく実用的だ。どのような収集品の展示にも適している。",
  str_item_intro_5234049 = "「石碑に刻んだ文字は何万年も先まで残り続ける」碑に文字を刻んだ者がこの世を去り、都市は荒れ果て、文明が衰えても石碑はその地にそびえ続ける。後世の人々にわずかでも今を伝える――それが碑の存在意義なのかもしれない。",
  str_item_intro_5276206 = "白夜城貴族の邸宅でよく使われるテーブル。大きく、重厚感のある立派な造りで、賓客や友人をもてなす時にも、家族が集まる時にも、さらに重大事を話し合う時にもふさわしい。",
  str_item_intro_5276207 = "白夜城貴族の邸宅でよく見られる背もたれの高い椅子。座り心地がよいだけでなく、正しい姿勢が保てるため、失態を演じることもない。",
  str_item_intro_5276208 = "白い旗のはためく白い都市。白夜城の象徴たる旗は、それを目にした者に白夜城――騎士、貴族、空そして文明を想像させる。",
  str_item_intro_5276209 = "永遠に消えないと思われているランプだが、実際白夜城の強大な光力術のおかげで永遠に消えることはない。",
  str_item_intro_5276210 = "気品のある造形をしたフェンス。部外者の侵入を防ぐためではなく、貴族の邸宅や荘園の境界を示すために設置される。",
  str_item_intro_5276211 = "たかが鉢植えと言えど、白夜城は他の所と違い、精巧な作りの大型の花器に植物が立派に生い茂っている。どうやら空の上は陽の光が十分なようだ。",
  str_item_intro_5276212 = "豊かに生い茂ったツルがパーゴラを覆う。整然とはしていないが、大きくも小さくもないすき間が程よい間隔で広がり、陽の光が粒のようになって差し込む。このパーゴラの下にいれば、気持ちが落ち着き、そよ風の吹く午後ならば、アフタヌーンティーにもってこいの場所だろう。",
  str_item_intro_5234050 = "本物の観覧車ほどではないが、かなり大きい。ただ残念なことに乗ることはできず、回っているのを眺めながら、観覧車に乗った時のことを思い出すしかない。",
  str_item_intro_5234052 = "青い筐体に巨大な貯水タンクを備えている。この銃は砂漠では戦いの化身ではなく、雨露をもたらすめぐみの神だ。乾燥しきった大地に暮らす人々に涼しさと潤いを与えてくれる。",
  str_item_intro_5234053 = "可哀想な小鳥が砂にまみれてしまったのかと見まがうほど、生き生きとした姿をしている。ただし、水に触れさせてはいけない。水に触れれば、ただの砂となって消えてしまう。",
  str_item_intro_5234054 = "この椅子は…本当に座れるのだろうか？花は確かに美しいが、椅子はどこもかしこもトゲに覆われ、何やら警告を発しているようである――「姿勢を正して座りなさい。さもなければケガをするわよ」",
  str_item_intro_5400001 = "不思議なツリーの栽培時間を大幅に短縮できる謎の液体。蒸発しやすいため、必ず瓶で保管しなければならない",
  str_item_intro_5400002 = "最上級の不思議なツリーから抽出したエキスの混合物を煮詰め、秘密のレシピで作られた粘性のある液体。最上級の不思議なツリーの品種を変えられる。\n見た目：黄色い泥の混ざった、粘性のある緑色の液体。",
  str_item_intro_5401001 = "樹木 C-B 突破確定アイテム",
  str_item_intro_5401002 = "樹木 B-A 突破確定アイテム",
  str_item_intro_5401003 = "樹木 A-S 突破確定アイテム",
  str_item_intro_5402001 = "樹木 C-B 限定突破アイテム",
  str_item_intro_5402002 = "樹木 B-A 限定突破アイテム",
  str_item_intro_5402003 = "樹木 A-S 限定突破アイテム",
  str_item_intro_5403001 = "あまり見かけない結晶。細かく砕かれており、色彩豊かな光を放つ。不思議なツリーの色を変化させる力を秘めている",
  str_item_intro_5403002 = "樹木 染色結晶体Ⅱ型",
