  str_item_intro_5415413 = "赤のチルメガマッシュルームの木【エクセレント】の種子",
  str_item_intro_5415421 = "ミストメガマッシュルームの木【エクセレント】の種子",
  str_item_intro_5415422 = "赤のミストメガマッシュルームの木【エクセレント】の種子",
  str_item_intro_5415423 = "青のミストメガマッシュルームの木【エクセレント】の種子",
  str_item_intro_5415431 = "ドームメガマッシュルームの木【エクセレント】の種子",
  str_item_intro_5415432 = "緑のドームメガマッシュルームの木【エクセレント】の種子",
  str_item_intro_5415433 = "赤のドームメガマッシュルームの木【エクセレント】の種子",
  str_item_intro_5421111 = "バラ色瑠璃で栽培した赤色のクインランの木。強い生命力を感じる",
  str_item_intro_5421112 = "栽培したばかりのベーシックなクインランの木。特に変わった点はないが、風に吹かれると不思議な音を出す",
  str_item_intro_5421113 = "バラ色瑠璃で栽培した黄色のクインランの木。やや寂しげに感る",
  str_item_intro_5421211 = "小さな突然変異によって生まれる小さな葉のクインランの木。バラ色瑠璃で栽培すると手に入る品種。赤メノウに似た色をしている",
  str_item_intro_5421212 = "小さな突然変異があったアンコモンクインランの木。葉が小さく密集しているため、その名前がつけられた",
  str_item_intro_5421213 = "小さな突然変異によって生まれる小さな葉のクインランの木。バラ色瑠璃で栽培すると手に入る品種。そよ風に吹かれると、黄葉が美しく波打つ",
  str_item_intro_5421221 = "小さな突然変異によって生まれる大きな葉のクインランの木。バラ色瑠璃で栽培すると手に入る品種。どの葉も薄く、赤い水晶のように見える",
  str_item_intro_5421222 = "小さな突然変異があったアンコモンクインランの木。葉はそのまま服の素材として使えるほど大きくて丈夫",
  str_item_intro_5421223 = "小さな突然変異によって生まれる大きな葉のクインランの木。バラ色瑠璃で栽培すると手に入る品種。木全体が秋の気配に包まれている",
  str_item_intro_5421311 = "度重なる突然変異によって生まれるレアクインランの木。密生した樹冠と滑らか葉を持ち、特別な趣きがある",
  str_item_intro_5421312 = "度重なる突然変異によって生まれるウォームクインランの木。バラ色瑠璃で栽培すると手に入る品種。青い樹冠が人を楽しませてくれる",
  str_item_intro_5421313 = "度重なる突然変異によって生まれるウォームクインランの木。バラ色瑠璃で栽培すると手に入る品種。黄葉が幾度にも重なり、強風でも散ることはない",
  str_item_intro_5421321 = "度重なる突然変異によって生まれるサニークインランの木。バラ色瑠璃で栽培すると手に入る品種。赤い樹冠が激しさを増しているように見える",
  str_item_intro_5421322 = "度重なる突然変異によって生まれるレアクインランの木。樹冠が密で幹や枝も太く、強い生命力を持っている",
  str_item_intro_5421323 = "度重なる突然変異によって生まれるサニークインランの木。バラ色瑠璃で栽培すると手に入る品種。遠くから見ると、青い樹冠が湖のように見え、心を落ち着かせてくれる",
  str_item_intro_5421331 = "度重なる突然変異によって生まれるクールクインランの木。バラ色瑠璃で栽培すると手に入る品種。ピンクの葉が樹冠、樹幹と合わさり、春の雰囲気を添えている",
  str_item_intro_5421332 = "度重なる突然変異によって生まれるクールクインランの木。バラ色瑠璃で栽培すると手に入る品種。赤い樹冠が本来の冷たい雰囲気と強烈なコントラストになっている",
  str_item_intro_5421333 = "度重なる突然変異によって生まれるレアクインランの木。葉は不ぞろい。涼やかな印象を与える",
  str_item_intro_5421341 = "度重なる突然変異によって生まれるコールドクインランの木。バラ色瑠璃で栽培すると手に入る品種。青い樹冠が元の寒々しい雰囲気にさらなる冷たさを加えている",
  str_item_intro_5421342 = "度重なる突然変異によって生まれるレアクインランの木。緑の葉は不規則だが鋭い。そよ風が樹冠に吹き寄せると、鋭い刃物が舞っているかのようで、背筋に冷たいものが走る",
  str_item_intro_5421343 = "度重なる突然変異によって生まれるコールドクインランの木。バラ色瑠璃で栽培すると手に入る品種。薄黄色の葉が寒々しい雰囲気を和らげ、かすかな温もりをもたらしている",
  str_item_intro_5421411 = "複雑な突然変異によって生まれるスカイクインランの木。バラ色瑠璃で栽培すると手に入る品種。青い樹冠は、純粋な心を持つ信者が青空に祈りを捧げているように見えるので、別名「祈りのクインランの木」とも呼ばれている",
  str_item_intro_5421412 = "複雑な突然変異によって現れるエクセレントクインランの木。天に向かって開くラッパ状の大きな樹冠が特徴。細い幹だけで支えられており、想像もできないような不思議な力が働いているに違いない",
  str_item_intro_5421413 = "複雑な突然変異によって生まれるスカイクインランの木。バラ色瑠璃で栽培すると手に入る品種。黄色いラッパ状の樹冠がしんちゅうの角笛のように見える。大昔には巨人が吹いていたと言われていることから、「角笛のクインランの木」と名づけられた",
  str_item_intro_5421421 = "複雑な突然変異によって生まれるロッククインランの木。バラ色瑠璃で栽培すると手に入る品種。緑の樹冠の上に立つと、原野の丘にいるかのように錯覚するため、別名「ヒルクインランの木」とも呼ばれている",
  str_item_intro_5421422 = "複雑な突然変異によって生まれるロッククインランの木。バラ色瑠璃で栽培すると手に入る品種。純白の樹冠は、ゆっくり眠れそうなほど平らに見える",
  str_item_intro_5421423 = "複雑な突然変異によって現れるエクセレントクインランの木。とても貴重。樹冠が硬化して小さな石の台になっている。幹の中にはそれを支える石の柱があり、外側が分厚い樹皮で覆われているだけだとも言われている。これが植物と言えるのかについては、確かに議論の余地がある",
  str_item_intro_5421431 = "複雑な突然変異によって現れるエクセレントクインランの木。とても貴重。糸状の葉はひとまとまりに絡み合っており、軽くて柔らかい。浮遊する伝説の魂のように見える。この木には意志があり、魂さえも持っていると言われている",
  str_item_intro_5421432 = "複雑な突然変異によって生まれるソウルクインランの木。バラ色瑠璃で栽培すると手に入る品種。赤い樹冠は不吉なように見えるが、抗えない魅力を持っている。柔らかな葉が風に揺れると、つい見とれてしまい、何日も見続けてしまう",
  str_item_intro_5421433 = "複雑な突然変異によって生まれるソウルクインランの木。バラ色瑠璃で栽培すると手に入る品種。黄色い葉が小さなリボンのように樹冠の上で揺れている。その姿は誰かを歓迎しているように見えるため、別名「ウェルカムクインランの木」とも呼ばれている",
  str_item_intro_5421441 = "複雑な突然変異によって現れるエクセレントクインランの木。非常に貴重である。葉が重なり合って、巨大で密な樹冠をつくり、中から落ちてくる葉が「落葉の雨」という不思議な景観を作り出す。",
  str_item_intro_5421442 = "複雑な突然変異によって現れるフラワークインランの木。バラ色瑠璃で栽培すると得られる品種で、緑色の樹冠はいかにも生命力にあふれている。垂れ下がる枝に近づくと、枝がかすかに揺れるだけでなく、木全体が「カサカサ」と音を立て、まるで会話しようとしているようだ…",
  str_item_intro_5421443 = "複雑な突然変異によって現れるフラワークインランの木。バラ色瑠璃で栽培すると得られる品種で、青い葉がはらはらと舞い落ちると、海や川の中にいるような錯覚をおこす。「陸海のフラワークインラン」という別名もそれに由来する。",
  str_item_intro_5421451 = "複雑な突然変異によって現れるエクセレントクインランの木。とても貴重。非常に生命力が強く、伐採しても再び伸びてくる。そのため「不屈の強者」と呼ばれている",
  str_item_intro_5421452 = "複雑な突然変異によって生まれるフォートクインランの木。バラ色瑠璃で栽培すると手に入る品種。茶色がかった葉が年老いた雰囲気を感じさせるが、その生命力はたくましさを増しており、水をやらなくても生きていけると言われている",
  str_item_intro_5421453 = "複雑な突然変異によって生まれるフォートクインランの木。バラ色瑠璃で栽培すると手に入る品種。成長スピードが速く、ほぼ一晩で枝に青い葉の樹冠ができるため、「絶えることのない紺碧の樹海」と呼ばれている",
  str_item_intro_5421461 = "複雑な突然変異によって現れるエクセレントクインランの木。とても貴重。根元から両側に伸び、最終的にはリング状の幹になる。木でできたドア枠のような姿をしているため、「クインランの横木」とも呼ばれている",
  str_item_intro_5421462 = "複雑な突然変異によって生まれるリングクインランの木。バラ色瑠璃で栽培すると手に入る品種。青い輪からは時おり水蒸気が出ている。冬には霜が降り、遠くから見ると氷と雪が固まっているように見える",
  str_item_intro_5421463 = "複雑な突然変異によって生まれるリングクインランの木。バラ色瑠璃で栽培すると手に入る品種。赤い輪は見る人に恐怖心を与えないどころか、温かい安らぎをもたらしてくれる。栽培者に幸運をもたらすとも言われている",
  str_item_intro_5421471 = "複雑な突然変異によって生まれた世にも珍しいクインランの木。枝分かれした幹や樹冠が風に揺られる姿や、露が作り出す細い流れが不思議なリラックス効果を持つことから、「癒しのクインラン」と呼ばれている",
  str_item_intro_5421472 = "複雑な突然変異によって生まれたジョイクインランの木。バラ色瑠璃で栽培すると得られる品種。木が集める露は青色をしており、遠くから見ると浅い海に浸かっているように見えるため、別名「海の憩い処」と呼ばれている",
  str_item_intro_5421473 = "複雑な突然変異によって生まれたジョイクインランの木。バラ色瑠璃で栽培すると得られる品種。紫色の露のおかげで不思議な木全体に妖艶な雰囲気が漂っており、そよ風の下で悠々と揺れる姿も誘惑しているように見える",
  str_item_intro_5421481 = "複雑な突然変異によって生まれた世にも珍しいクインランの木。直立した幹に炎の形をした樹冠が加わり、松明のような大木になった。本当に灯りにしようと、間違って持ってしまう人がいるかも？",
  str_item_intro_5421482 = "複雑な突然変異によって生まれたトーチクインランの木。バラ色瑠璃で栽培すると得られる品種。巨大なピンク色の樹冠は不思議な霧が木の幹や枝先に浮かんでいるようだ。風が吹くとその「ピンクの霧」が不規則な形になるので、さらに異様な感じがする",
  str_item_intro_5421483 = "複雑な突然変異によって生まれたトーチクインランの木。バラ色瑠璃で栽培すると得られる品種。赤い樹冠はまさに「松明」の名にふさわしく、特に風に吹かれて舞う様はまさしく燎原（りょうげん）の火のようだ",
  str_item_intro_5422111 = "バラ色瑠璃で栽培した浅緑色のアーサーの木。まっすぐ伸び、孤高の存在のようだが春の雰囲気を漂わせている",
  str_item_intro_5422112 = "バラ色瑠璃で栽培した深緑色のアーサーの木。落ち着いた姿をしており、安らかな気分にしてくれる",
  str_item_intro_5422113 = "栽培したばかりのベーシックなアーサーの木。特に変わった点はないが、まっすぐ伸びた幹、密集した枝、そして空に向かって生える細長い葉が他との違いを際立たせている",
  str_item_intro_5422211 = "小さな突然変異によって生まれる短い葉のアーサーの木。バラ色瑠璃で栽培すると手に入る品種。赤く細い葉はとても短く、地面に落ちると赤い絨毯のようで、人を楽しませてくれる",
  str_item_intro_5422212 = "小さな突然変異によって生まれる短い葉のアーサーの木。バラ色瑠璃で栽培すると手に入る品種。短い葉には緑色の模様が入っており、まだらに輝くエメラルドのようだ",
  str_item_intro_5422213 = "小さな突然変異があったアンコモンアーサーの木。本来の大きさとはまったく異なり、木の幹が外側に伸びている。しかし、樹冠は薄く葉も短くて厚い。表記がなければ、アーサーの木が変異したものとは気づかないだろう",
  str_item_intro_5422221 = "小さな突然変異によって生まれる長い葉のアーサーの木。バラ色瑠璃で栽培すると手に入る品種。葉が落ちるとすぐに乾き、足で踏むと「カサッ」という心地よい音がする",
  str_item_intro_5422222 = "小さな突然変異によって生まれる長い葉のアーサーの木。バラ色瑠璃で栽培すると手に入る品種。細長い葉は柔らかく丈夫で、筆を作るのによく使われる",
  str_item_intro_5422223 = "小さな突然変異があったアンコモンアーサーの木。枝は奔放に伸び、葉も細長くなっている。まっすぐ伸びていたアーサーの木が元になっているとは想像できないほど、大きく変化している",
  str_item_intro_5422311 = "度重なる突然変異によって生まれるレアアーサーの木。樹冠と幹が一体となっており、表面は硬く山の岩のように見える。中は空洞になっており、叩くと不思議な反響がする",
  str_item_intro_5422312 = "度重なる突然変異によって生まれるマウンテンアーサーの木。バラ色瑠璃で栽培すると手に入る品種。枝の片側に緑色の模様が入っており、よくコケに見間違われる",
  str_item_intro_5422313 = "度重なる突然変異によって生まれるマウンテンアーサーの木。バラ色瑠璃で栽培すると手に入る品種。樹皮の一部がかすかに赤くなっているため恐ろしい言い伝えもあるが、どれも根も葉もない話だ",
  str_item_intro_5422321 = "度重なる突然変異によって生まれるレアアーサーの木。樹冠全体が低く垂れ下がっている。遠くから見ると小さな森のように見えるため、「一樹の森」とも呼ばれている",
  str_item_intro_5422322 = "度重なる突然変異によって生まれるウッドアーサーの木。バラ色瑠璃で栽培すると手に入る品種。赤くて巨大な樹冠が傘のように灼熱の太陽を遮り、涼しい木陰を作ってくれる",
  str_item_intro_5422323 = "度重なる突然変異によって生まれるウッドアーサーの木。バラ色瑠璃で栽培すると手に入る品種。緑色の大きな樹冠と垂れ下がる太い枝が特徴。中にいると森に迷い込んだような錯覚に陥るだろう",
  str_item_intro_5422331 = "度重なる突然変異によって生まれるデザートアーサーの木。バラ色瑠璃で栽培すると手に入る品種。やや寂しげな樹冠と割れた幹が特徴。枯れていると勘違いする人も多いが、長い間まっすぐ立っているのを見て考えを改める",
  str_item_intro_5422332 = "度重なる突然変異によって生まれるレアアーサーの木。荒野のいたる所で見られる枯れ木によく似ていることから名づけられた。しかし、ねじ曲がった幹の上の小さな樹冠は、イキイキとしたたくましい生命力を見せている",
  str_item_intro_5422333 = "度重なる突然変異によって生まれるデザートアーサーの木。バラ色瑠璃で栽培すると手に入る品種。緑色の樹冠が枯れた枝は、同じものなのかと疑いたくなるほど強烈なコントラストになっている。同じ木の一部であることは間違いないが、これこそ不思議なツリーの魅力なのかもしれない",
  str_item_intro_5422341 = "度重なる突然変異によって生まれるポンドアーサーの木。バラ色瑠璃で栽培すると手に入る品種。樹液は淡い黄色をしており、口に入れるとやや硬い口当たりがするが、後味はほんのり甘い。体力を回復させる効果があるとされ、飲みすぎるとフラフラになると言われている",
  str_item_intro_5422342 = "度重なる突然変異によって生まれるレアアーサーの木。樹冠の先からは水が滴り落ち、根元に天然の池ができていることから名づけられた。この不思議な循環の原理や存在意義は誰にも分からず、ただ根元の池の水を飲み、その不思議な力に感嘆することしかできない",
  str_item_intro_5422343 = "度重なる突然変異によって生まれるポンドアーサーの木。バラ色瑠璃で栽培すると手に入る品種。一見すると毒々しい緑色をしたその水は、意外にも非常にすっきりした味わい。ほのかな香りが驚くほど心地よく、体にしみわたる",
  str_item_intro_5422411 = "度重なる突然変異によって生まれるライトアーサーの木。バラ色瑠璃で栽培すると手に入る品種。幹や樹冠の一部から緑色の光を放ち、水のせせらぎが流れているかのようで、とても幻想的",
  str_item_intro_5422412 = "複雑な突然変異によって現れるエクセレントアーサーの木。とても珍しい。露出した根、膨張して硬化した幹、樹冠は光を放つ葉の塊になっている。遠くから見ると小さな灯台のように見えるので、「灯台アーサーの木」とも呼ばれている",
  str_item_intro_5422413 = "複雑な突然変異によって生まれるライトアーサーの木。バラ色瑠璃で栽培すると手に入る品種。石の台のような幹と樹冠が金色に光っている。金色に輝く宮殿にやって来たと勘違いする者もいるため、別名「宮殿アーサーの木」とも呼ばれている",
  str_item_intro_5422421 = "複雑な突然変異によって現れるエクセレントアーサーの木。幹の一部が硬化した樹冠と結合している。空洞は表面が硬くとても薄い岩盤になっており、叩くとさまざまな音が鳴る。樹冠を使って話をすると言う人までいる",
  str_item_intro_5422422 = "複雑な突然変異によって生まれるシャインアーサーの木。バラ色瑠璃で栽培すると手に入る品種。翡翠色の巨大な樹冠はエメラルドに見える。軽く叩くと心地よい乾いた音が響くため、「アーサーの木の音楽家」と呼ばれている",
  str_item_intro_5422423 = "複雑な突然変異によって生まれるシャインアーサーの木。バラ色瑠璃で栽培すると手に入る品種。青い岩盤が抑揚のある音を奏でながらかすかに震え、幻想的な青い閃光の残影を作り出す",
  str_item_intro_5422431 = "複雑な突然変異によって生まれるブリリアントアーサーの木。バラ色瑠璃で栽培すると手に入る品種。黄色の幹の中心から光を放つ際、幹の模様に淡い黄色の葉の幻影が浮かび上がり、再び生命力が宿ったかのような印象を与える。そのため、「アーサーの木の復活者」とも呼ばれている",
  str_item_intro_5422432 = "複雑な突然変異によって現れるエクセレントアーサーの木。幹は空洞になっている。その中心部は変わったキノコの形をしており、不思議な光を放っている。危険を察知すると外側の樹皮を閉じ、中の光を遮断するため、「輝きを隠すアーサーの木」とも呼ばれている",
  str_item_intro_5422433 = "複雑な突然変異によって生まれるブリリアントアーサーの木。バラ色瑠璃で栽培すると手に入る品種。幹の中心から放たれる青い光が幹の空洞で屈折し、まるでこの木が小川を取り囲んでいる、あるいは水中にいるかのような錯覚に陥ることもあるんだとか…",
  str_item_intro_5422441 = "複雑な突然変異によって現れるエクセレントアーサーの木。一部の枝と葉が変異によって「ランタン」を形づくり、「灯芯」になっている枝が暖かい光を放つ！その名の通り、野外で漆黒の闇を歩く旅人たちの行く手を照らしてくれる。",
  str_item_intro_5422442 = "複雑な突然変異によって現れるライトアーサーの木。バラ色瑠璃で栽培すると得られる品種。幹にはある特別な光力が宿っているため、この木の「ランタン」は優しい青い光を放つのだという。",
  str_item_intro_5422443 = "複雑な突然変異によって現れるランタンアーサーの木。バラ色瑠璃で栽培すると得られる品種。葉は赤色だが、「ランタン」は薄紅色の光を放っていて、白い幹との対照に何ともいえない味わいがある。",
  str_item_intro_5422451 = "複雑な突然変異によって現れるエクセレントアーサーの木。樹冠が消え、色鮮やかな花びらのつるが幹の上に広がっている。垂れ下がったつるや枝の間を通るつるによって、遠くから見ると花のゲートのように見える",
  str_item_intro_5422452 = "複雑な突然変異によって生まれるイリスアーサーの木。バラ色瑠璃で栽培すると手に入る品種。白い花びらがとても冷たい印象を与えるが、摘んで手に取ると、ほのかな温もりを感じる",
  str_item_intro_5422453 = "複雑な突然変異によって生まれるイリスアーサーの木。バラ色瑠璃で栽培すると手に入る品種。特徴的な緑色の花びらがあり、葉のように見える。近づいて観察しないと見分けがつかないほどだ",
  str_item_intro_5422461 = "複雑な突然変異によって現れるエクセレントアーサーの木。樹冠がなく、枝の先端に巨大な球体のつぼみができている。この「蛍玉」と呼ばれる球体は光力を含んでいるらしく、そよ風が拭くと、細かくなった葉とともに光力が流れ出て、周囲をほのかに明るく照らしてくれる",
  str_item_intro_5422462 = "複雑な突然変異によって生まれるスパークアーサーの木。バラ色瑠璃で栽培すると手に入る品種。「蛍玉」から大海原のような青い光が放たれている。風で揺らめく巨大な水玉がダンスしているかのように見えることから、「水の踊り子」という別名を持つ",
  str_item_intro_5422463 = "複雑な突然変異によって生まれるスパークアーサーの木。バラ色瑠璃で栽培すると手に入る品種。黄色の「蛍玉」は力強い生命の息づかいを持ち、周囲の植物が元気よく成長するよう後押ししてくれる",
  str_item_intro_5422471 = "複雑な突然変異によって現れるエクセレントアーサーの木。樹冠はすっかり形を変え、ひとつながりとなって椀状になり、縁は垂れ下がっている。「椀」の真ん中には変わった形の幹が伸び、松明のようにかすかに光を放って、観る者の目を引き付ける。",
  str_item_intro_5422472 = "複雑な突然変異によって生まれるブライトアーサーの木。バラ色瑠璃で栽培すると手に入る品種。椀状になった樹冠は心やすらぐ青色をしており、真ん中の幹の放つ光に照らされ、まるで深い水の中に漂っているような心地になる。よって「淵水の幻」とも呼ばれている",
  str_item_intro_5422473 = "複雑な突然変異によって生まれるブライトアーサーの木。バラ色瑠璃で栽培すると手に入る品種。この木の下に立つと、赤い樹冠が降り注ぐ日差しを遮り、まるで夕陽の浮かぶ黄昏時のような錯覚を覚える",
  str_item_intro_5422481 = "複雑な突然変異によって現れるエクセレントアーサーの木。木全体が硬くなり、石の台のような形になっている。上部から水がさらさらと樹洞の中に流れ落ち、なんとも不思議な光景を作り出している",
  str_item_intro_5422482 = "複雑な突然変異によって生まれるホローアーサーの木。バラ色瑠璃で栽培すると手に入る品種。白い木肌と青い水流の対照がとてもすがすがしく、木の下で水の音を聞いているだけで実に心地が良い。そのため「耳を潤す木」との別名が付いた",
  str_item_intro_5422483 = "複雑な突然変異によって生まれるホローアーサーの木。バラ色瑠璃で栽培すると手に入る品種。幹と上部の「枝」は不思議な青色をしているが、流れ落ちる黄色い水越しに眺めると、さらに一味違った印象になる。「紫を帯びた青」とも呼ばれる",
  str_item_intro_5423111 = "栽培したばかりのベーシックなブルーミングの木。満開の花がこの木の特徴で、すでにその性質が十分に表れている",
  str_item_intro_5423112 = "バラ色瑠璃で栽培した紫色のブルーミングの木。魅惑的なかすかな光を放つ",
  str_item_intro_5423113 = "バラ色瑠璃で栽培した黄色のアーサーの木。光に照らされると夕暮れのような雰囲気が漂う",
  str_item_intro_5423211 = "小さな突然変異があったアンコモンブルーミングの木。すでに別種といえるまでの変化を遂げており、1本の根から何株もの幹が伸び、複数の木が集まっているのかと見間違えてしまう。見た目はベーシックのブルーミングと大きく異なるが、その幹に咲く花を見れば、何から変化したものか容易に分かる",
  str_item_intro_5423212 = "小さな突然変異によって生まれるフォークブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。淡い黄色の花はまるで小さな太陽のようで、たくさん集まるとまぶしく感じるほどである",
  str_item_intro_5423213 = "小さな突然変異によって生まれるフォークブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。淡い青色の花がとても上品で、風に揺れる姿はまるで空に浮かぶ雲のようである",
  str_item_intro_5423221 = "小さな突然変異があったアンコモンブルーミングの木。幹が太くなり、花が別の形に変わっている。ラッパ状の花びらの中にはたくさんの花心があり、この名がついた",
  str_item_intro_5423222 = "小さな突然変異によって生まれるステイマンブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。青い花びらに囲まれた花心は水分を含んでおり、のどの渇きを潤せる。飲み物の原料にもなる",
  str_item_intro_5423223 = "小さな突然変異によって生まれるステイマンブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。通常のステイマンブルーミングとは異なり、花心、花びらともに燃えるような赤色をしている。摘み取ると、花心はすぐに乾いて柔らかくなり、火がつきやすくなる",
  str_item_intro_5423311 = "度重なる突然変異によって生まれるレアブルーミングの木。幹に花が咲き、根の深い所からたくさんの枝が花を囲むように伸びている。そのため、「守られた花の木」という別名がついた",
  str_item_intro_5423312 = "度重なる突然変異によって生まれるライズブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。花は金に近い黄色で、日の光に照らされた姿は、遠くから見ると光をまとって揺れ動いているように見える",
  str_item_intro_5423313 = "度重なる突然変異によって生まれるライズブルーミングの木。水色の花が幹と枝が鋭い雰囲気をかもし出し、「青き鋭利な植物」と呼ぶ人もいる",
  str_item_intro_5423321 = "度重なる突然変異によって生まれるジェードブルーミングの木。幹が丸く曲がり、樹冠の下に花が密集して垂れ下がるように咲く。どうやってその重みを支えているのかと、見る者は驚嘆するばかりである",
  str_item_intro_5423322 = "度重なる突然変異によって生まれるジェードブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。垂れ下がった青い花は丸まった幹と相まって、建物の前廊に見える。庭にも調和する",
  str_item_intro_5423323 = "度重なる突然変異によって生まれるジェードブルーミングの木。花びらはみずみずしい白。花の下で風に吹かれると、清々しい香りが漂ってくる。香水の重要な原材料でもある",
  str_item_intro_5423331 = "度重なる突然変異によって生まれるレアブルーミングの木。幹がねじ曲がり、遠くから見ると木全体が花のようで、本当の花をつい見過ごしてしまう。研究者によると、花が他の生物に食べられてしまわないよう、幹と枝がこのような形に変化したのだという",
  str_item_intro_5423332 = "度重なる突然変異によって生まれるウォーヴィンブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。枝の先が水色に染まっている。枝から落ちる露はさらに深い水色をしていて、インクや染料にも使えるらしい",
  str_item_intro_5423333 = "度重なる突然変異によって生まれるウォーヴィンブルーミングの木。枝の先が黄緑色をしている。根もとにできる水たまりは青い光を放ち、自然の息吹を強く感じさせる",
  str_item_intro_5423341 = "度重なる突然変異によって生まれるレアブルーミングの木。その姿は遠方のある木に似ているらしく、咲き誇る花は美しいだけでなく、淡い香りを漂わせ、足を止めて眺めていると、虹の幻まで見られるという…もちろん、ただの伝説だが、名前の由来になっている",
  str_item_intro_5423342 = "度重なる突然変異によって生まれるアイリスブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。紫の花が妖艶な雰囲気を漂わせる。色味がきついため、飾りやワンポイントにする際には、適度な使用をお勧めする",
  str_item_intro_5423343 = "度重なる突然変異によって生まれるアイリスブルーミングの木。黄色の花がほぼ一日中咲き誇り、強い生命力を感じさせる。花心は薬にもなり、活力を補ってくれるという。そのため、「命の虹の木」という別名がある",
  str_item_intro_5423411 = "複雑な突然変異によって現れるエクセレントブルーミングの木。花は一輪しか咲かないが、とても大きく、色彩もはなやかである。少々危険な雰囲気の甘い香りを漂わせている。花心は上等な調味料になるという。見る者の心を惑わせるため、「魅惑の妖花」とも呼ばれている",
  str_item_intro_5423412 = "度重なる突然変異によって生まれるスイートブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。薄水色の花は夏の海の波を連想させ、潮の香りさえ漂ってくるようだ…そのため、海辺にいる気分を味わいたければ、この木を見てればよいとさえ言われている",
  str_item_intro_5423413 = "複雑な突然変異によって生まれるスイートブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。より危険な雰囲気のピンク色の花を咲かせる。見ているだけで一切の憂いを忘れることができ、名残惜しくなかなか立ち去れなくなってしまう。そのため、目覚まし時計で夢中になり過ぎないようにする者もいるそうだ",
  str_item_intro_5423421 = "複雑な突然変異によって現れるエクセレントブルーミングの木。花びらの数が多く、かつ細長くて柔らかい。遠くから見ると、少女の美しい髪のようで、その質感もきめ細かく、織物の材料にしようと試みた者もいるそうだ。残念ながら、花びらは摘み取るとすぐに乾いてヒビが入ってしまうことが分かっている",
  str_item_intro_5423422 = "複雑な突然変異によって生まれるフリンジブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。青い花が伝説の青い髪の「大海原の女」を連想させる。この木の近くで、本当に深海の香りを感じた人もいるという…",
  str_item_intro_5423423 = "複雑な突然変異によって生まれるフリンジブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。その緑色をした花びらには不思議な「花の精霊」が隠れているとも言われ、もし出会うことができれば、一目で心を奪われること間違いない…",
  str_item_intro_5423431 = "複雑な突然変異によって現れるエクセレントブルーミングの木。大きな花は皿のような形で、何かを仰ぎ見ているような姿をしている。しかも多くの人に注目されると、わずかに顔を反らし、注意をそらそうとする。そのため、「高慢でか弱い花」とも呼ばれている",
  str_item_intro_5423432 = "複雑な突然変異によって生まれるスカイブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。花の赤色が燃えるような情熱を感じさせる。仰ぎ見ている空に力を注いでいるのだという説がある",
  str_item_intro_5423433 = "複雑な突然変異によって生まれるスカイブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。花びらは白色。花の眺める方向をたどっていくと、不思議な幻像が見えると言われており、しかも、それぞれ異なる幻像が見えるという。そのため、「不思議な幻の創造者」とも呼ばれている。",
  str_item_intro_5423441 = "複雑な突然変異によって現れるエクセレントブルーミングの木。美しい花びらが幾重にも重なり、見る者を一目で魅了する。そのため、多くの少女たちに愛されている",
  str_item_intro_5423442 = "複雑な突然変異によって生まれるビューティーブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。青い花には人を魅了する効果があり、この木を見る者の多くが、辺りから雨上がりの青空のような爽やかな息吹を感じられる。そのため、「晴天の空」という別名が付けられている",
  str_item_intro_5423443 = "複雑な突然変異によって生まれるビューティーブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。紫の花は危険な色彩を帯びており、近くで誰かが見ていると、花はかすかに揺れて妖艶な香りを放ち、見る者を魅了してしまうらしい…。とにかく、気をつけよう",
  str_item_intro_5423451 = "複雑な突然変異によって現れるエクセレントブルーミングの木。巨大な花冠が天然のジョウロのようになっており、花びらの内壁はとてもなめらか。朝露を集め、幹の中に流し入れることで木を潤す",
  str_item_intro_5423452 = "複雑な突然変異によって生まれるサンライズブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。紫色の花が集めた露を同じ色に染める。一部の学者は、この露には不思議な力が宿っており、とある本を書くために使わていると考えている",
  str_item_intro_5423453 = "複雑な突然変異によって生まれるビューティーブルーミングの木。花が集めた露は青みを帯びており、見るだけで心が洗われ、体の中が浄化されたような気分になる。そのため、「早天の浄化者」とも呼ばれている",
  str_item_intro_5423461 = "複雑な突然変異によって現れるエクセレントブルーミングの木。花冠はいくつかの柔らかくて長い花びらに分かれ、花蕊を囲むように並んでいる。あるデザイナーがこの花を目にした後、突然、この花びらをモチーフにしてドレスをたくさんデザインしたことから、「美人ドレス」の異名を持つようになったらしい",
  str_item_intro_5423462 = "複雑な突然変異によって生まれるギルトブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。オレンジ色の花びらはとても誘惑的なオーラと特徴的な香りによって、魅力的で危険な存在を思い起こさせるだけでなく…",
  str_item_intro_5423463 = "複雑な突然変異によって生まれるギルトブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。花びらは空のような色に変わり、白い葉が彩りを加える。爽やかで純粋な印象を与えるため、子どもたちにとても人気がある",
  str_item_intro_5423471 = "複雑な突然変異によって現れるエクセレントブルーミングの木。花冠と花蕊がチョウのような形をしており、見る人を混乱させる。さらには本物のチョウも引き寄せ、その周りを飛び回っており、まるでチョウの神のように見える",
  str_item_intro_5423472 = "複雑な突然変異によって生まれるバタフライブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。遠くから見ると、巨大で黄色の花冠が大木に止まったチョウのように見える。そよ風が吹けば、さらに見分けがつかなくなるだろう…",
  str_item_intro_5423473 = "複雑な突然変異によって生まれるバタフライブルーミングの木。バラ色瑠璃で栽培すると手に入る品種。青い花冠と本来のチョウのような外観が相まって、怪しげな印象を与える。その真の姿を目にしたとき、この木の不思議さに感嘆せざるを得ない。そのため、「世界に存在しない美しいチョウ」の異名を持つ",
  str_item_intro_5424111 = "丸々とした根茎を見れば、レアフルーティの木と他の品種との違いがよく分かる。その不思議な見た目には思わず感嘆してしまう",
  str_item_intro_5424112 = "バラ色瑠璃で栽培した黄色のレアフルーティの木。その黄色い果実と葉はまるで秋の恵みのようだ",
  str_item_intro_5424113 = "バラ色瑠璃で栽培した紫のレアフルーティの木。一見、少々不気味な雰囲気を漂わせているが、その樹液は無味ですっきりとした味わいが特徴である",
  str_item_intro_5424211 = "小さな突然変異があったアンコモンレアフルーティの木。根茎がより太く丈夫になり、果実の外側にはトゲが生えて、外敵から身を守っている。巻き付くツルも「近づくべからず」と言わんばかりの様子である",
  str_item_intro_5424212 = "小さな突然変異によって生まれるソーンレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。青いツルと茎と葉は元の品種との違いを表しているが、果実に違いはないようだ",
  str_item_intro_5424213 = "小さな突然変異によって生まれるソーンレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。ツルや茎と葉は枯れかかっているかのような印象を与えるが、中に生っている果実はふっくらと熟していている。どうやら見た目は、一種のカモフラージュのようだ",
  str_item_intro_5424221 = "小さな突然変異があったアンコモンレアフルーティの木。根はまったく別の形に変わっていて、別々になった果実と葉はそれぞれ独自に栄養を取り入れているという。そうすることで、果実と葉のどちらかがダメになっても、他の部分は生長を続けることができ、生存率が上がる",
  str_item_intro_5424222 = "小さな突然変異によって生まれるノーリッシュレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。樹液に特別な成分が含まれているため、赤くなっているという",
  str_item_intro_5424223 = "小さな突然変異によって生まれるノーリッシュレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。果実は変わった黄色をしているが、皮の水分が失われたことによるものらしい。皮をむくと、すぐにもろくなって砕け、おがくずのようになる",
  str_item_intro_5424311 = "度重なる突然変異によって生まれるレアのレアフルーティの木。果実の外側が硬化し、石のようになっている。果実を食べるのは、相当難しいだろう…",
  str_item_intro_5424312 = "度重なる突然変異によって生まれるストーンレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。果実が変異したかどうかは分からないが、葉の様子から見る限り、この果実を口にするのは得策ではなさそうだ",
  str_item_intro_5424313 = "度重なる突然変異によって生まれるストーンレアフルーティの木。樹冠と葉の鮮やかな色が下方の「石の果実」と非常に対照的である。「花に覆われた石」と呼ぶ者もいる",
  str_item_intro_5424321 = "度重なる突然変異によって生まれるマチュアレアフルーティの木。幹が弯曲しているだけでなく、果実も2つに分かれ、天然の池を作っている。この木があれば、飲み水に困ることはない",
  str_item_intro_5424322 = "度重なる突然変異によって生まれるマチュアレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。その「果実の池」の中の樹液は何ともいえない味がする。まだ知られていない不思議な味の成分が入っているからだと言われている",
  str_item_intro_5424323 = "度重なる突然変異によって生まれるマチュアレアフルーティの木。池に満ちる樹液はさらに澄み、わずかながらひんやりとしている。暑い夏の日にはもってこいの木だ",
  str_item_intro_5424331 = "度重なる突然変異によって生まれるレアなレアフルーティの木。ひねったような形の幹が特徴的だが、実は中の果実が曲がっているため、そのような形になっている。研究によると、「幹」だと思っているものも、実は果実を守る表皮に過ぎないらしい",
  str_item_intro_5424332 = "度重なる突然変異によって生まれるベンドレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。枝の先端が緑色をしていて、果実はとても苦い。一口でもなめれば、数日間食事ができなくなる",
  str_item_intro_5424333 = "度重なる突然変異によって生まれるベンドレアフルーティの木。幹の色が明らかに変化している。これは中の果実の味が大きく変化していることを意味しており、勇気ある者の話によると、その味は少し辛く、後味は酸味を帯びていたという",
  str_item_intro_5424341 = "度重なる突然変異によって生まれるレアなレアフルーティの木。見た目がこの不思議なツリーの特徴をよく表している。かたまって生っており、いくつかの巨大な果実から枝が生えているため、別名「正真正銘のレアフルーティ」と呼ばれている",
  str_item_intro_5424342 = "度重なる突然変異によって生まれるプランプレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。青い巨大な果実はふっくらとよく熟しており、実際にも1つの村に十分な水を提供できるくらいの樹液を蓄えている。このことから、「ダムの木」と呼ぶ者もいる",
  str_item_intro_5424343 = "度重なる突然変異によって生まれるプランプレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。巨大な赤い果実が非常にあざやかで、目を向けずにはいられない。その樹液を飲むと元気になるという伝説があるが、どうやらただの伝説らしい",
  str_item_intro_5424411 = "複雑な突然変異によって現れるエクセレントレアフルーティの木。果実はとても大きく、かつその色彩は不思議な華やかさをたたえ、複雑に伸びる枝と相まって、見る者の心に独占欲を沸き上がらせる。家族や友人とさえ奪い合うこともいとわなくなると言われ、「争いの果実」との別名が付いた。",
  str_item_intro_5424412 = "度重なる突然変異によって生まれるレースレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。緑色の果実は見る者に大自然を想像させ、陶酔させる。まるで森林の中で鳥や虫の鳴き声を聞きながら、葉が風に揺られるのを肌で感じているような気分になる…",
  str_item_intro_5424413 = "複雑な突然変異によって現れるレースレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。果実は魅惑的で鮮やかなピンク色に変わり、長く眺めていると、中で何かが舞い踊っているように見えてくるという。あでやかでありながら、あやしい雰囲気が漂う",
  str_item_intro_5424421 = "複雑な突然変異によって現れるエクセレントレアフルーティの木。大きさのまちまちな果実が重なり合って生っている。最も古く出現したレアフルーティの1つと言われ、野生種の記載もある。そのため、「レアフルーティの祖先」との別名がある",
  str_item_intro_5424422 = "複雑な突然変異によって生まれるランタンレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。そのピンクの果実を見ると、思わず樹液を手に入れたくなる。この木の樹液で造る飲み物は、王もほめたたえる美味といわれ、そのため「帝王の果実」とも呼ばれている",
  str_item_intro_5424423 = "複雑な突然変異によって生まれるランタンレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。遠くから見ると、青い海が集まってできたような果実が生っている。中には波紋さえ見えるというが、それが幻覚なのかどうかは、誰も知らない…",
  str_item_intro_5424431 = "複雑な突然変異によって現れるエクセレントレアフルーティの木。巨大な果実が常に奇妙な香りを放っている。それを嗅ぐと不思議と勇気が湧き、天下を征服せんとする心が湧いてくると言われ、よって、この名が付いた",
  str_item_intro_5424432 = "複雑な突然変異によって生まれるドラゴンレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。緑色の果実は狂暴な戦士さえも心を静めると言われ、瞑想や深い思考にもってこいである。多くの賢者がこの果実のおかげで理を悟ったと言われ、そのため「悟りの果実」とも呼ばれている",
  str_item_intro_5424433 = "複雑な突然変異によって生まれるドラゴンレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。巨大な青い果実は勇気をもたらしてくれるだけでなく、他者の下にいることに甘んじることのない強い野心にも火をつけ、後戻りの許されない王座をめぐる戦いに身を投じるという。そのため、「危険な王者の果実」とも呼ばれている",
  str_item_intro_5424441 = "複雑な突然変異によって現れるエクセレントレアフルーティの木。果実は「木の幹」の中に隠されている。ある学者の研究によると、果実を包んでいるのは木の幹ではなく、果実の硬い外皮らしい。他人にその実を取られないように、この不思議なツリーは本当に努力をしているようだ",
  str_item_intro_5424442 = "複雑な突然変異によって生まれるヒヴァレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。緑色の果実には命の「原動力」があると言われ、適切に抽出すると、植物の成長や作物の豊作を促すだけでなく、荒廃した土壌や乾燥して塩分を含んだ土地すらも改善できる。そのため、多くの人々が「命の実」と呼んでいる",
  str_item_intro_5424443 = "複雑な突然変異によって生まれるヒヴァレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。青い大きな果実には、甘い水が含まれており、外側の「樹皮」は高い保湿能力を持っている。砂漠の中でも果実の水分が失われることはなく、まるで生きた貯水池のようだ…",
  str_item_intro_5424451 = "複雑な突然変異によって現れるエクセレントレアフルーティの木。巨大な果実は「ごく平凡」に見えるが、非常に魅力的な香りを一定時間放つことがあり、その香りは一生忘れられないと言われている。普段は特別な香りなど一切しないにもかかわらず、多くのチョウが集まってくるのは、それが理由なのだろう",
  str_item_intro_5424452 = "複雑な突然変異によって生まれるパフュームレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。一部の人々の言い伝えによると、紫色の果実は数百年ごとに大陸全体を覆う香りを放つらしい。そして、その香りの広がりとともに、ある「王者」が世に現われると言われている…",
  str_item_intro_5424453 = "複雑な突然変異によって生まれるパフュームレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。他のパフュームレアフルーティの木と異なり、青い果実にはかすかに爽やかな香りが含まれ、他の匂いを中和できる。そのため、園芸職人たちから重宝されているが、植え替えることができないため、普通の園芸職人たちをがっかりさせている",
  str_item_intro_5424461 = "複雑な突然変異によって現れるエクセレントレアフルーティの木。おりのような外殻を持っている。時々発する霧から、中の果実が非常に甘いことがうかがい知れる。その霧は近付いた生物を魅了し、果実に手を出させないようにするらしい",
  str_item_intro_5424462 = "複雑な突然変異によって生まれるミストレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。緑色の果実には強い酸味があり、放たれる霧も刺激臭がすると言われている。そのため、猛毒があるとうわさされているが、実際にはまったく害がない",
  str_item_intro_5424463 = "複雑な突然変異によって生まれるミストレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。青い果実の果肉部分に不思議な変化が起き、非常に丈夫で弾力性がある。大型車両にひかれても、すぐに元の形に戻るほどだ…",
  str_item_intro_5424471 = "複雑な突然変異によって現れるエクセレントレアフルーティの木。果実は大きく2つの部分に分かれている。1つは分厚い殻に包まれたメインの果実、もう1つは枝の末端にぶら下がり光を放つ果実だ。枝の末端の果実は樹冠が変異したものらしい。しかし、外観、匂い、味のいずれもがその主張の裏付けになっていない…",
  str_item_intro_5424472 = "複雑な突然変異によって生まれるシャイニングレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。その青い輝きは海の香りを呼び起こすと言われている。そのため、「海風の使者」と呼ばれているが、フルーティな香りによる幻覚作用にすぎないと主張する人もいる。",
  str_item_intro_5424473 = "複雑な突然変異によって生まれるシャイニングレアフルーティの木。バラ色瑠璃で栽培すると手に入る品種。最上部の「果実」が放つ緑色の光には人を落ち着かせる力がある。非常に狂暴な動物が近付いてもおとなしくなると言われているが、真偽のほどは不明",
  str_item_intro_5425111 = "この種の不思議なツリーは根本的に他の品種とは大きく異なる。そもそも「木」なのかどうかさえ疑わしい。学者たちの研究によれば木の仲間であることは確かだが、その名のとおり見る人にいつも不思議な印象を与える",
  str_item_intro_5425112 = "バラ色瑠璃で育てた赤のメガマッシュルームの木。赤い巨大な傘を見ると、誰もが落ち着かない気分になる。そのためこの傘の下で涼をとることはおすすめしない",
  str_item_intro_5425113 = "バラ色瑠璃で育てた青のメガマッシュルームの木。青い傘は大空のような広大さを感じさせ、近くにいると「雲の香り」がするという人もいる",
  str_item_intro_5425211 = "小さな突然変異があったアンコモンメガマッシュルームの木。傘が大きく変化し、しなやかで粘り強い。その重さから垂れ下がっているためドーム天井のように見える。木の梁で支えて周りを覆えば本物の小屋になるかもしれない",
  str_item_intro_5425212 = "小さな突然変異があったぺリラメガマッシュルームの木。バラ色瑠璃で栽培すると手に入る品種。傘内部がスカイブルーに変化し、中から見上げると大海原にいるような錯覚を覚える",
  str_item_intro_5425213 = "小さな突然変異があったぺリラメガマッシュルームの木。バラ色瑠璃で栽培すると手に入る品種。赤い傘の内側にいると恐怖を感じる。毒があるとも言われるが、それは偏見である",
  str_item_intro_5425221 = "小さな突然変異があったアンコモンメガマッシュルームの木。茎が太いわりに傘は小さく、バケツのように見える。その名のとおり太い茎は地下から吸い上げた水分を貯蔵できるため、天然の貯水槽である。別名「水キノコ」とも呼ばれる",
  str_item_intro_5425222 = "小さな突然変異があったパインメガマッシュルームの木。バラ色瑠璃で栽培すると手に入る品種。外観は赤いが、中に貯まった水分はその影響を受けない。近づくと中でかすかに流れる水の音が聞こえる",
  str_item_intro_5425223 = "小さな突然変異があったパインメガマッシュルームの木。バラ色瑠璃で栽培すると手に入る品種。青い傘は貯め込んだ水の影響によるもので、「海の蓋」と呼ばれることもある。傘の上で身をかがめ、耳を近づけると、太い茎から波の音が聞こえると言う人もいるが……",
  str_item_intro_5425311 = "度重なる突然変異によって生まれたレアメガマッシュルームの木。傘は本来の巨大さを保ちながらはるかに肥大化し、辺りは奇妙な香りに包まれている",
  str_item_intro_5425312 = "度重なる突然変異によって生まれたテンプメガマッシュルームの木。バラ色瑠璃で栽培すると手に入る品種。傘は青く変化し、離れた場所から見ているだけで浅瀬にいるような錯覚を覚える",
  str_item_intro_5425313 = "度重なる突然変異によって生まれたテンプメガマッシュルームの木。鮮やかな赤い傘を持っている。見る者を惑わせ、酔わせることで強大な力に近づけると言うが、こういった誘惑は悪い結果にならない。その理由は今なお不明である",
  str_item_intro_5425321 = "度重なる突然変異によって生まれたレアメガマッシュルームの木。より小型になり群生するようになったが、形はおおむね変わっていない。最大の特徴は傘が色とりどりの光を瞬かせ、キラキラ光る粉末を放散する美しい光景が見られることである",
  str_item_intro_5425322 = "度重なる突然変異によって生まれたネオンメガマッシュルームの木。バラ色瑠璃で栽培すると手に入る品種。苛烈な赤は燃え上がる炎に似ており、その輝きは飛び散る火花を思わせることから、「炎のキノコ」とも呼ばれる",
  str_item_intro_5425323 = "度重なる突然変異によって生まれたネオンメガマッシュルームの木。バラ色瑠璃で栽培すると手に入る品種。紫の傘は妖艶さを感じさせ、光り輝く粉には人を酔わせる効果があるという。テンプマッシュルームの変異種または遠い親戚だと語る学者もいるが、推測にすぎない",
  str_item_intro_5425331 = "度重なる突然変異によって生まれたレアメガマッシュルームの木。茎は歪み、傘が2つある。ある学者によると、2つの傘を維持するため地下から大量の水分を吸い上げ、貯蔵できる限界を超えると水分が傘から分泌されて、雨のように降り注ぐのではないかという",
  str_item_intro_5425332 = "度重なる突然変異によって生まれたモイストメガマッシュルームの木。全体が黄色く、落下する雨も淡い夕陽に似た香りがする。急な雨が降ると、木の周りに黄昏色の雨のとばりが出現したように感じる",
  str_item_intro_5425333 = "度重なる突然変異によって生まれたモイストメガマッシュルームの木。バラ色瑠璃で栽培すると手に入る品種。青は海の生き物を思わせ、落下する雨粒も青い波しぶきに似ている。そのため「海水の操り手」とも呼ばれる",
  str_item_intro_5425341 = "度重なる突然変異によって生まれたレアメガマッシュルームの木。しなやかな枝が何本も垂れ下がっているのが特徴で、老人のあごひげのようにも見える。賢者を思わせることから「キノコの賢者」とも呼ばれる",
  str_item_intro_5425342 = "度重なる突然変異によって生まれたベアードメガマッシュルームの木。バラ色瑠璃で栽培すると手に入る品種。黄色いヒゲは知性を感じさせ、光の加護を表していると語る人までいる。風でヒゲが揺れると、その1本1本が太陽のきらめきのように見える",
  str_item_intro_5425343 = "度重なる突然変異によって生まれたベアードメガマッシュルームの木。バラ色瑠璃で栽培すると手に入る品種。たくさんの緑のひげはツルにとって役立たずに見える。傘の下にいると、原始の森にいるような錯覚を覚える",
  str_item_intro_5425411 = "複雑な突然変異によって現れるエクセレントメガマッシュルームの木。傘は巨大だがかなり薄い。ある角度から見るとほぼ透明らしい。もちろん、傘が薄いから透明に見えるのではなく、常に放出している冷気が透明な氷を連想させるのだ",
  str_item_intro_5425412 = "度重なる突然変異によって生まれたチルメガマッシュルームの木。バラ色瑠璃で栽培すると手に入る品種。黄色い傘に時折流れる冷ややかな風は、照り付ける日差しの中でさえ寒さを感じさせる。そのため「凍てつく日向の奇妙な木」とも呼ばれる",
  str_item_intro_5425413 = "複雑な突然変異によって現れるチルメガマッシュルームの木。バラ色瑠璃で栽培すると手に入る品種。目の覚めるような赤い傘とわずかな透明感が相まって、人の手による芸術作品なのか、自然の産物なのか誰もがいぶかしむほどだ",
  str_item_intro_5425421 = "複雑な突然変異によって現れるエクセレントメガマッシュルームの木。傘の変化はほぼ「普通」だが、時おり気流を吹き出し、まるで呼吸をしているかのように見える。さらにほとんどが群生しているため、次々に気流を吹き出す姿が淡い霧のように見えることからこの名がついた",
  str_item_intro_5425422 = "複雑な突然変異によって現れるミストメガマッシュルームの木。バラ色瑠璃で栽培すると手に入る品種。赤い傘が「呼吸」するとき、時おり開閉する小さな穴は傷口を連想させる。さらに気流を吹き出す姿が、ある時刻になると固まった血しぶきのように見えることから、「悲壮な戦場の再現」とも呼ばれる",
  str_item_intro_5425423 = "複雑な突然変異によって現れるミストメガマッシュルームの木。バラ色瑠璃で栽培すると手に入る品種。青い傘から放出される霧は、見る者に「厳しい冬」を思わせる。そのため北境原産ではないかと誤解されることが多いが、それは誤りである。この木が放出する気流は低温ではなく、やや暖かいこともある",
  str_item_intro_5425431 = "複雑な突然変異によって現れるエクセレントメガマッシュルームの木。とても巨大な傘に変化しており、茎で支えられるか疑問に感じてしまう。傘があまりに巨大なため、その下に立って見上げると空が覆われてしまうことから「天を覆う木」とも呼ばれる",
  str_item_intro_5425432 = "複雑な突然変異によって現れるドームメガマッシュルームの木。バラ色瑠璃で栽培すると手に入る品種。緑色の傘は時折水草のようなすがすがしい香りを放ち、まるで水辺にいるような奇妙な錯覚を覚える。この木は近くの水草に養分を与えて成長させると言われているが、それを証明した者はいない",
  str_item_intro_5425433 = "複雑な突然変異によって現れるドームメガマッシュルームの木。バラ色瑠璃で栽培すると手に入る品種。真っ赤な傘は豊かに実る果実を思わせ、近寄ると爽やかな果物の香りがしたという人もいる。だがこの不思議なツリーは食用にはならず、特に傘は硬くて調理に向かないうえ、栄養もない",
  str_item_intro_5510001 = "腹に猛毒を持っているため、まるまる太った体でも問題なく生き延びられる。しかし、その極めて美味な肉質は死を恐れぬ多くの食通を魅了している",
  str_item_intro_5510002 = "鮮やかな色と数の多さで有名。柔らかい肉質で食卓を彩る存在",
  str_item_intro_5510003 = "細長く刀身に似ていることから、この名前がつけられた。いつも群れで行動している",
  str_item_intro_5510004 = "どう見ても蛇だが、実は小さなひれを持った魚で、とても細長い。水中の岩場に隠れ、突然飛び出して人を驚かせるのが好き",
  str_item_intro_5510005 = "澄んだ水に生息する魚。数が多く、分布範囲も広い。さまざまな場所で見かける。",
  str_item_intro_5510006 = "水中では圧倒的な捕食者と言われているが、その肉の美味しさから食通たちに狙われており、高級な宴会では「常連」となっている",
  str_item_intro_5510007 = "川岸に集まって休息したり、泳いだりしている細長い魚。水中のさまざまな微生物を餌としている。食用としてだけでなく、その魚油でさまざまな塗料も作れる",
  str_item_intro_5510008 = "群れで泳ぐことを好む。槍のように頭から敵に突っ込む狂暴な性格。肉質はしっかりしており、小さな鱗を乾燥させるとおやつにもなる",
  str_item_intro_5520001 = "水中をゆっくりと泳ぐ亀。岸にあがるとほとんど動かない。そのためか、背中にある硬い甲羅で敵からの攻撃を防ぐ",
  str_item_intro_5520002 = "この希少な水生生物は冷たい水を非常に好むという。したがって、通常は氷の張った海域で群れを成して暮らしている。体が透明で、玉虫のように美しく色が変わるため、この名がついた。暖かい水域には、ほとんど見られない。おそらく迷い込んだのだろう…",
  str_item_intro_5520004 = "平べったい体をした水生生物。ゆったりと泳ぎ、かつ活動するにも休むにも川底を好む。背にたくさんの丸い斑点があり、魚釣りに来た人が上からのぞくと、ちょうど水中に落ちた真珠のように見えるため、この名が付いた",
  str_item_intro_5520005 = "水底をはって暮らす生物。奇妙な姿かたちでよく知られている。多くの人が最初は少し変わった形をした藻かサンゴに見間違い、ゆっくりと動き始めた時に初めて、植物ではなく動物だと気づくらしい…",
  str_item_intro_5520006 = "ふだんは海藻やサンゴ、イソギンチャクの中に生息している奇妙な魚。外見は色鮮やかで、顔立ちは思わず笑ってしまうような「三枚目」。名前の由来は、姿を現すと周辺の海藻がユラユラと踊り出すので「お笑いの才能」があると思われたため",
  str_item_intro_5520007 = "最近発見されたという水生生物。滑らかな表皮と柔らかい筋肉を持ち、軽妙ながら、どこかけだるく水中を泳ぐ姿は人々を惹きつけてやまない。人によっては、水の中を行ったり来たり泳ぐその姿を見るだけで心身ともに癒され、1日の疲れもどこかへ吹き飛んでしまうという。",
  str_item_intro_5520016 = "広大な水域を好んで生息し、なぜかこの場所にやってきた。全体が黒く、非常に奇妙な形をしているためかつては恐れられていた。実際には穏やかな性質で、水中を悠々と泳ぎまわっていることが多い。小型の水中動物に出会うと自ら逃げることもある",
  str_item_intro_5520101 = "鮮やかな色によって最も貴重な観賞魚の一種となった。「水中の生きた宝石」という呼び名のほか、飼育者に幸運をもたらすと言われている",
  str_item_intro_5520102 = "その多彩な模様から「魚の中のジェントルマン」と呼ばれ、大勢の人に愛されている。見るだけで心がリラックスする。家族の仲を取り持つと考える人も多い",
  str_item_intro_5520103 = "高級鑑賞魚。優雅に泳ぐ姿から「泳ぐ芸術品」とも呼ばれている。飼育することで将来の災いを避けられるらしい",
  str_item_intro_5520104 = "穏やかな性格と自然な模様が特徴。人懐っこく特に子どもが好き。そのため、健やかに成長を見守ってくれると考える人もいる",
  str_item_intro_5520105 = "太陽の光に当てると、鱗が鮮やかな黄金色に輝く。金運をもたらすと信じられており、多くの商人が好んで飼育している",
  str_item_intro_5520201 = "水中で赤い点が光り輝く観賞魚。鱗は水中を淡いピンクに染めそうなほど目立ち、美しい光景を楽しめる",
  str_item_intro_5520202 = "やや「邪悪」な見た目をしているが、血のように赤い鱗は太陽光に照らされると朱色に見え、まるでルビーでできた甲冑をまとっているかのような印象を与える",
  str_item_intro_5520203 = "青い鱗が輝いている。水中でゆっくりと泳ぐ時、何とも言えない涼しさをもたらしてくれる。真夏には貴重な存在",
  str_item_intro_5520204 = "金色の整った鱗が伝説の将軍を彷彿とさせる。その泳ぐ姿は威圧的で、周囲の小魚が逃げていくほど",
  str_item_intro_5520205 = "他のフリッパーに比べ、優雅で隙がない。銀白色の鱗と流線形の体は貴族のようなオーラすら漂わせている",
  str_item_intro_5520301 = "平らな体とまばゆい色が特徴。水の中に落ちた蝶が泳いでいるかのように見える",
  str_item_intro_5520302 = "頭部が白く、体の大部分が黒い観賞魚。温厚な性格。よく観察してみると、白と黒の境目にある斑点が個体ごとに微妙に異なっており、一匹一匹の個性があると言える",
  str_item_intro_5520303 = "黄色と白の体色が大きく3つに分かれているため、この名前がつけられた。やんちゃでイタズラ好きな性格。水の中を賑やかにしてくれる",
  str_item_intro_5520304 = "美しい青い色をした観賞魚。色彩の変化に富んでいる。恥ずかしがり屋で、岩場や水草の中に隠れて顔を見せたがらない。「シャイな乙女」とも呼ばれている",
  str_item_intro_5520401 = "鮮やかな色とクリクリ動く大きな目が特徴。他の魚と仲良くすることを好み、仲間外れにされることもない。観賞魚の「八方美人」と言える",
  str_item_intro_5520402 = "背中の混合色の斑点が名前の由来。同じ色の水草と組み合わせると、天然の保護色になる。存在感を際立たせるためには、環境との配色に気を配らなければならない",
  str_item_intro_5520403 = "体は全体的に黒く、背中の黄白のひれが特徴。静かな性格だが、怒るととことんまで戦う。イバラのようなトゲがあるので触ってはいけない",
  str_item_intro_5520501 = "見た目の醜さから観賞魚として飼う人は少ない。光を放つひげだけが周りとの違いを際立たせている",
  str_item_intro_5520502 = "白いチョウチンアンコウ。親しみやすい見た目だが、光も弱くなっている。コントラストが原因かもしれない",
  str_item_intro_5520601 = "深海にしか生息しないと言われていたが、いつの間にかこの地に住み着いたようだ。深海に慣れているため、普段は水中深くに潜っており、なかなか見つけられない。\n普段は姿を見せず付近に光力がある時だけ現れるが、光力が強すぎると怖がって逃げてしまう。",
  str_item_intro_5520602 = "川の岩の間に好んで生息する。動きが素早く、黄色く染まった岩と間違えられたことから、この名前がつけられた。\n普段は姿を見せない。付近に光力がある時だけ現れるが、光力が強すぎると怖がって逃げてしまう。",
  str_item_intro_5520603 = "通常、川や小川に生息している。体の色が天然の保護色となっているだけでなく、縦向きの泳ぎも川の水泡で姿を隠すのに役立つため、天敵に発見されにくい。\n普段は姿を見せない。光力にあまり敏感ではなく、引き寄せるには強い光力が必要。ただし、光力が強すぎると怖がって逃げてしまう。",
  str_item_intro_5520701 = "川の湾曲部に好んで住まう水生動物。何本もの足を持ち、見たところ非常に凶暴そうだが見かけだけで、実は穏やかな性格をしている。普段は藻の中に隠れているので見つけにくい。",
  str_item_intro_5520702 = "透き通った水のきれいな川の湾曲部に好んで住まう。身体の大部分を同じような色をした水底の黄色い砂の中に埋めているため、他の生物に見つかることはほとんどない。しぜん、不意打ちが得意だ。",
  str_item_intro_5520801 = "「小さい」からといってあなどるなかれ。重さは1キロある上に「カープ」の中では最も小さな品種なのだ。見た目は平凡だが、成長のポテンシャルを秘めている…",
  str_item_intro_5520802 = "やや大きめの「カープ」。5キロはある。色は濃いが、つかまえにくい。体重だけではなく、警戒心も増しているようだ",
  str_item_intro_5520803 = "重さ10キロもある「カープ」。見た目は丸みを帯び、大きな目は「もっと重くなれる」と言わんばかりだ",
  str_item_intro_5520804 = "重さ20キロで、「カープ」の中でも猛者である。泳ぐスピードはやや遅いが、水の中でのんびりしている姿を見ると、何となく安心する。実に不思議だ",
  str_item_intro_5520805 = "とても大きな「カープ」。重さはなんと50キロ！「カープ」の王者として君臨している。「重さのすべてがここにある」と言わんばかりの大きなお腹が特徴。性格も荒々しく、他の水中生物は、その姿を見かけるとほとんどが逃げ出してしまう",
  str_item_intro_5520806 = "大きな体をしているにもかかわらず、「カープ」で最も人気があるのは、金でコーティングしたような体が理由だろう。まばゆいうろこに映る、さまざまな星のような模様を見ると、思わずため息が漏れる。まさに天の作った傑作と呼べるだろう",
  str_item_intro_5520811 = "大きな爪をもち、一見狂暴そうな水生生物。だが実際には、その大きな爪も行く手をふさぐ石や水草などをどけるためのもので、戦闘時の武器としての使い方は付属的な機能でしかない。とても穏やかな性格で、身を守る時にだけ、その猛々しさを発揮する",
  str_item_intro_5520812 = "水底の石の中に潜む生物。「潜む」とはいっても、実際には水底で暮らしているため、強くて大きな爪で石を運び、身を隠す「要塞」を築いているにすぎない。運悪く通りかかった、あるいは好奇心から近づいてくる水生生物を要塞に隠れて襲い、お腹を満たしている",
  str_item_intro_5520014 = "体中に青いリング模様があることでよく知られている。川ではめったに見かけない。だが、このタコが現れようものなら、他の生物たちはこぞって逃げ出す。なぜならこのタコは、たった1滴で致死量に値する猛毒をもっているからだ。そのため、非常に目を引く姿となって他の生物の注意を引こうとも、いっさい恐れる様子がないのである",
  str_item_intro_5520901 = "非常にめずらしい魚。多彩な色どりの華やかな身体は比較的小さく、とても速く泳げる。警戒心が強く、水面に少しでも動きがあると身体の色を消してしまうため、非常に見つけにくい。そのため、これを釣るには相当な辛抱が必要である。釣るのは大変だが、この魚が泳ぐことで出来る「七色のリボン」を見れば、苦労のかいがあったと誰もが思うことだろう",
  str_item_intro_5530001 = "偶然にも真珠が入っている。色や外観からして、質も悪くなさそうだ。いい値段で売れるだろう",
  str_item_intro_5530101 = "ボロボロのブリキ缶。誰が水の中に捨てたのか分からないが、環境を大切にしてもらいたいものだ…",
  str_item_intro_5530201 = "水中で何年も「生活」してきたのだろう。水草までもがこの靴を家にしている",
  str_item_intro_5601101 = "いつの日か、自分も大空の下で家を守れますように",
  str_item_intro_5601201 = "巨像を導く不思議なエネルギーについて分かる日が来ることを願う…",
  str_item_intro_5602101 = "記憶は一生残るが、記録は数千年と続く。だから記憶し、書き記し、誰かが見つけてくれるまで持ち続ける",
  str_item_intro_5602201 = "たとえ地の果て、天の果てだろうと、あの図面を見つけてみせる。",
  str_item_intro_5602202 = "ある人が言った。何事にも代価が必要であると。ならば、知識の代価は何だろう？",
  str_item_intro_5602203 = "頭は学習によって、生活は気分によって保守しなければならない",
  str_item_intro_5603101 = "軽々しく諦めると言ってはいけない。実験に99回失敗しても、次は成功するかもしれないのだから",
  str_item_intro_5603201 = "ある物を別の物に変える究極の原理とは何か？根源を見つけ、その道へ歩めばいいのだ",
  str_item_intro_5603202 = "インスピレーションは火花のように一瞬で消えてしまう。その火花を永遠に残すため、生涯をかけて探し求める",
  str_item_intro_5603301 = "刃は鋭利であるに越したことないが、時として少し鈍い方が予想外の効果を発揮する。彼女と一緒にいる時は少し「鈍く」なった方がいいのかもしれない…",
  str_item_intro_5604101 = "どの木にもそれぞれの運命がある。自分にもあるのだろうか？早く知りたい…",
  str_item_intro_5604201 = "銀色の葉はある？彼女はないと言ったが、私は信じなかった。だから来たのだ",
  str_item_intro_5604202 = "年輪は木に刻まれた歳月の印であり、木の歴史、そして記憶でもある。木と対話することで、我々の知らない過去を知れるかもしれない――それが我々の年輪なのだ",
  str_item_intro_5604203 = "葉と木が交錯する影の間に、彼の横顔が浮かんでいるようだ。これは運命的なデザインなのだろうか？",
  str_item_intro_5604301 = "独り静かに生長し、独り静かに散っていく。その孤高の姿こそ学ぶべき姿だ。",
  str_item_intro_5604302 = "私たちの根源はどこにあるのだろうか？生きている間に知ることができればいいのだが…",
  str_item_intro_5605201 = "水紋を見ながら、釣りを教えてくれた父のことを思い出した",
  str_item_intro_5605301 = "母親の形見である。私はそれを自分の娘に受け継がせる",
  str_item_intro_5605302 = "僕と彼女の間にはこの細い糸しか残されていない。丈夫で切れないといいのだが…",
  str_item_intro_5605303 = "彼女のプレゼントがただのエサだったとしても、釣られてみたい。",
  str_item_intro_5605304 = "魚釣りは、時として釣果ではなく、波にきらめく光を見るために行うのである",
  str_item_intro_5605305 = "水の流れる方向を知るように、彼女の心を知る日はくるのだろうか？",
  str_item_intro_5605306 = "釣り糸がかすかに揺れれば、それは魚がかかった証拠。日々の暮らしの中にもそんな知らせがあればいいのに。",
  str_item_intro_5606201 = "何も成し遂げられず、何も掘り起こせられなかった父のようにはなりたくない。我に幸運あれ！",
  str_item_intro_5606301 = "勤勉に働けば、いずれ自分の愚かさを補い、誰もが心から採掘の天才と呼んでくれるだろう",
  str_item_intro_5606302 = "小石を軽く見てはいけない。中に宝物が入っている時もあるのだ",
  str_item_intro_5606303 = "つるはしは常に研いでおこう！",
  str_item_intro_5606304 = "恋愛と同じように、採掘には力だけでなく、技術も必要だ！",
  str_item_intro_5606305 = "鉱脈にも匂いがある！このよく利く鼻で、彼の痕跡も見つけられればいいのに…",
  str_item_intro_5606306 = "頑張り続ければきっとあの鉱脈を見つけられる。この山の中にあろうとなかろうと…",
  str_item_intro_5607201 = "彼はかご。私の気持ちはその中にしまわれている",
  str_item_intro_5607301 = "彼女に私の気持ちを採集してもらえればいいのに",
  str_item_intro_5607302 = "幼い頃に木から落ちて来た果実に当たって以来、ずっと幸運に恵まれてきました。これからも、この幸運が続きますように。",
  str_item_intro_5607303 = "蜜蜂のあとをついていかないと、良質な花の蜜を見つけられないことが多い。彼らの言葉を理解できたらいいのに…",
  str_item_intro_5607304 = "心に手袋があれば、トゲある「草花」に傷つくこともないのでは？",
  str_item_intro_5607305 = "果実の在りかを一瞬で見わけるには、目が利かなければならない。これから先続いていく人生でも、そうあることを願う。",
  str_item_intro_5608101 = "作物が日差しを拒むことはない。どうか、あの人も私を拒むことのないよう願う。",
  str_item_intro_5608201 = "種まきは収穫のためだけではなく、希望を植えるためでもある",
  str_item_intro_5608301 = "風車がゆっくりと回る様子を眺めるのが何よりも好きだ。何も考える必要がなく、1日中見ていられるから…",
  str_item_intro_5608302 = "種子とは本当に不思議だ。あの大きさしかないのに、これほどの作物を実らせるのだから！種子さえあれば、希望はある！",
  str_item_intro_5608303 = "作物は養分を作るため、太陽を必要とする。それは私が彼女を必要とするのと同じだ。",
  str_item_intro_5608304 = "作物が育たなくなるので、日の光は強すぎてはいけない。彼への関心も同じだ。",
  str_item_intro_5608305 = "作物を密集させて植えてはいけない。必ず畝を作ること。彼女とも一定の距離を保たなければいけないようだ",
  str_item_intro_5609201 = "手入れする必要のない草が勝手に生えて、大きい毛布にならないかな～。",
  str_item_intro_5609301 = "水滴は柔らかくて硬い。自分もそのような人になれるだろうか？",
  str_item_intro_5609302 = "植物が丈夫で健康的に育つには良質な培土が必要だ。私たちも同じく、なりたい人間になれるように、さまざまな培土を用意してくれた長老に感謝している",
  str_item_intro_5609303 = "いちばん甘い花の蜜を集めて、未来の子どもたちに届けられますように。",
  str_item_intro_5609304 = "ああ、いつかミツバチのように自由気ままに飛び回ることができたらいいのに",
  str_item_intro_5609305 = "美しい花だけに目を向けていてはいけない。花を引き立てる緑の葉も見ること",
  str_item_intro_5610101 = "多くの動物たちを動かすことはできても、家族の心の内を理解することはできない。将来自分の子どもたちはそうならないことを願う。",
  str_item_intro_5610201 = "ミルクをコップの中に注いだ時、笑顔のような模様が浮かび上がれば、その先1年は幸運が訪れると言われている",
  str_item_intro_5610202 = "他の村では犬に放牧を手伝ってもらうらしい。私には、この子がいれば十分。",
  str_item_intro_5610203 = "はるか遠くの砂漠には「ラクダ」という生き物がいて、ミルクがなかなかうまいらしい。",
  str_item_intro_5610204 = "いつの日か、青草が芽吹くのを目にするだろう。そのときには、あの草原も再びここに現われるはずだ",
  str_item_intro_5610301 = "谷の外にはもっと広大な草原があるらしい。だけど、私はここの青草が好き",
  str_item_intro_5610302 = "チーズは世界で最もおいしい食べ物だ。一生毎日食べられたら、まさに天国だ",
  str_item_intro_5610303 = "砂漠の民は水源のそばに定住し、少しも離れられないという。私にとっての水源は、どうやら彼女のようだ",
  str_item_intro_5611101 = "海の近くに住む人々は昔、小島ほどの大きさの船を見たことがあるらしい。私も見てみたい！",
  str_item_intro_5611201 = "眠らなくても大丈夫なら、ずっと哨兵を務められる",
  str_item_intro_5611202 = "私がいる限り、どんな悪人もここには寄せ付けない。特にあの子たちを脅かそうとする者は…",
  str_item_intro_5611203 = "ここの守護者になったら、夜であろうと休むことはできません。",
  str_item_intro_5611204 = "いかなる細部もおろそかにしてはならない。でなければ、大きな災禍につながってしまう",
  str_item_intro_5611301 = "私は三日三晩歩いても疲れを感じない。この才能を谷の巡回に活かし、よそ者の侵入を警戒するつもりだ",
  str_item_intro_5611302 = "私は一族の盾となろう！ハハハ、白夜城の騎士の誓いを真似したんだけど、カッコいいよね！やると言ったらやるんだ！",
  str_item_intro_5611303 = "あの松明のような大木に本当に火を点せられたら、夜の灯りの代わりになるのでは？",
  str_item_intro_6400001 = "獲得すると称号が使用可能になる：先手必勝\nプロフィールの称号画面で使用できる",
  str_item_intro_6400002 = "獲得すると称号が使用可能になる：戦術マスター\nプロフィールの称号画面で使用できる",
  str_item_intro_6400003 = "獲得すると称号が使用可能になる：作戦のプロ\nプロフィールの称号画面で使用できる",
  str_item_intro_6400004 = "獲得すると称号が使用可能になる：災禍を封じる者\nプロフィールの称号画面で使用できる",
  str_item_intro_6400005 = "獲得すると称号が使用可能になる：罪業の粛清者\nプロフィールの称号画面で使用できる",
  str_item_intro_6400006 = "獲得すると称号が使用可能になる：不屈の意志\nプロフィールの称号画面で使用できる",
  str_item_intro_6400007 = "獲得すると称号が使用可能になる：黄金の城\nプロフィールの称号画面で使用できる",
  str_item_intro_6400008 = "獲得すると称号が使用可能になる：地平線の支配者\nプロフィールの称号画面で使用できる",
