  str_item_intro_6500001 = "初期ネームプレート。プロフィール-ネームプレートで使用できる",
  str_item_intro_6500002 = "初期ネームプレート。プロフィール-ネームプレートで使用できる",
  str_item_intro_6500003 = "初期ネームプレート。プロフィール-ネームプレートで使用できる",
  str_item_intro_6500004 = "初期ネームプレート。プロフィール-ネームプレートで使用できる",
  str_item_intro_6500005 = "初期ネームプレート。プロフィール-ネームプレートで使用できる",
  str_item_intro_6500008 = "白色に染まる山々の峰は冷たく、静かでありながら、また違った命の息吹を感じさせる。",
  str_item_intro_6500011 = "影ノ街を霧が包み込む。その中で、人知れず取引が行われる。それが影ノ街のもう1つの日常だ",
  str_item_intro_6500014 = "啓光シェルター内にある修理工場。大型の機械をはじめ、あらゆる壊れた装置を迅速に修理できる。",
  str_item_intro_6500015 = "白夜城の祝典は相変わらず盛大だ",
  str_item_intro_6500016 = "水の流れ、十字路。地理的・地形的な利便性が影ノ街に繁栄をもたらした",
  str_item_intro_6500017 = "太陽が謎の暗闇に呑み込まれるのは、大きな異変の予兆なのだろうか？",
  str_item_intro_6500018 = "北境、氷と凍てつく寒さ。そこはベツレヘムに属し、彼女が守るべき場所である",
  str_item_intro_6500020 = "どんなことがあろうと、あの悪党どもにライブをぶち壊されるわけにはいかない！これぞ正義！",
  str_item_intro_6500021 = "北境、氷と凍てつく寒さ。そこはベツレヘムに属し、彼女が守るべき場所である",
  str_item_intro_6500024 = "その瞬間、彼女は完全に警戒を解いたらしく、楽しげな笑顔には子どもらしさが垣間見えた。それこそが、あの2人だけの秘密なのだ",
  str_item_intro_6500026 = "R・Wの祝賀会は砂漠料理のグルメ大会に様変わりしたようだ。",
  str_item_intro_6500033 = "旅の途中、疲れを感じたらこの仲間たちと腰を下ろして休憩し、彼らの話を聞いてみるといいだろう",
  str_item_intro_6500035 = "空に浮かぶ城には長い間変わることのない陽の光が射している。昔日と同じ服をまとった彼女はあの大きな絵の前で長い間たたずんでいる。何か思い出したかのように…",
  str_item_intro_6500036 = "フロリナがいれば、どんなに危険な水域も安全な場所へと変わる。",
  str_item_intro_6500037 = "ある者はこの100年間ずっと、とうに忘れ去られた使命を果たし続けてきた。",
  str_item_intro_6500038 = "そよ風が吹き、過去の曇りを吹き払う。そして、雲の間からもれる光が炎のようにあらゆる憂いを焼き尽くし、新しい未来を届けるだろう",
  str_item_intro_6500039 = "彼女は灯台のように漆黒の海をあまねく照らす。冒険者たちの帰路の道しるべとなるために。",
  str_item_intro_6500041 = "寒さに凍え、雪と氷に大地が閉ざされていようと、仲間さえいれば、心の中にはいつも暖かいものが流れている。ナビゲーター、よい祝日を！",
  str_item_intro_6500042 = "シェオルが空高く飛び上がり、襲って来た敵を撃退する。彼女もついに今まで他人には見せなかった一面を見せたのだ。",
  str_item_intro_6500043 = "岩石砂漠の境界地帯の各所に見張所が立てられている。見張りに立つ者たちは、ここで遠くの故郷を敵の襲撃から守っている。",
  str_item_intro_6500044 = "店舗がひしめくように並び、人が多くて騒々しい。住民と観光客は双閣港の繁華街に集まり、自分の好きな商品を選んでおり、とてもにぎやかだ",
  str_item_intro_6500045 = "「認めていただき、ありがとうございます。白夜に捧ぐ！」",
  str_item_intro_6500046 = "「私は一人でぼんやりするのが好きなの。でも、今は…あなたがそばにいてくれるのも悪くはないわね。」",
  str_item_intro_6500047 = "「この世界はまだ戦火に包まれている。この先も私と一緒にそうした争いを解決してくれるのか？」",
  str_item_intro_6500049 = "「グワッグワッ！」",
  str_item_intro_6500051 = "タカのごときドローンが飛び交う中、たたずむ少女。少女は振り向いて言う。\n「もう大丈夫だ。」",
  str_item_intro_6500053 = "美しき彼女は微笑みながら深淵へ身を投げる。\n「あなたの力も、喜びも、誰にも奪わせやしない」",
  str_item_intro_6500054 = "宿命の分岐点に立ったら、どんな未来を選ぶべき？",
  str_item_intro_6500056 = "あらゆる経験が、真理結社を未来の道へと導くだろう",
  str_item_intro_6500057 = "潮風、かき氷、三輪車――あの子と過ごした夏の思い出は、今も色あせずに残っている。",
  str_item_intro_6500058 = "再会の誓い、心の交わる場所",
  str_item_intro_9993001 = "戦闘勝利後、チーム内の生存している光霊1体のHPを20%回復する",
