  str_item_intro_9993035 = "戦闘勝利時、「スナイパー」と「ボマー」ジョブの光霊の攻撃力+1.5%（最大15%まで）",
  str_item_intro_9993036 = "戦闘勝利時、チーム内の生存している光霊の内、ランダムで1体がダメージ軽減効果を1スタック獲得。1スタックごとに被ダメージ-1.5%、重ね掛け可能。効果は今回の秘境探索が終わるまで持続",
  str_item_intro_9994001 = "暗鬼を撃破するごとに、チーム内の生存している光霊1体のHPを10%回復する",
  str_item_intro_9994002 = "毒状態の暗鬼が毒ダメージを受けるたびに、「サポーター」ジョブの光霊が毒ダメージの100%相当のHPを回復する",
  str_item_intro_9994003 = "状態異常の暗鬼に対する「ボマー」ジョブの光霊の与ダメージ+30%",
  str_item_intro_9994004 = "毒、火傷または出血状態の敵を撃破した時、フィールド上にいる敵に3スタックの毒状態を付与する",
  str_item_intro_9994005 = "敵ターン開始時、毒、火傷または出血状態にある暗鬼が周囲2マス内にいる暗鬼を毒状態にする",
  str_item_intro_9994006 = "味方チームが状態異常にある場合、「スナイパー」ジョブの光霊の与ダメージ+30%",
  str_item_intro_9994007 = "ダメージを受けるたびに「ボマー」ジョブの光霊の与ダメージ+5%（この戦闘が終わるまで持続）",
  str_item_intro_9994008 = "戦闘開始時、戦場に包帯を1つ出現させる",
  str_item_intro_9994009 = "HPが70%以上残っている「スナイパー」ジョブの光霊の与ダメージ+20%",
  str_item_intro_9994010 = "攻撃時、「ボマー」ジョブの光霊の与ダメージが失ったHPの10%相当アップする",
  str_item_intro_9994011 = "光の泉で回復するMS値が5アップ",
  str_item_intro_9994012 = "光の泉でHP回復を選択する時、回復人数+1",
  str_item_intro_9994013 = "危険エリアで「ボマー」ジョブの光霊の攻撃力+10%",
  str_item_intro_9994014 = "致死エリアで「ボマー」ジョブの光霊の攻撃力+10%",
  str_item_intro_9994015 = "トレジャーハンターの逃走ターンを強制的に4ターン遅らせる",
  str_item_intro_9994016 = "大型暗鬼を撃破すると、すべての光霊のクールダウン-1ターン",
  str_item_intro_9994017 = "大型暗鬼を撃破すると、「スナイパー」ジョブの光霊の攻撃力+20%",
  str_item_intro_9994018 = "大型暗鬼を撃破すると、チーム内でHPが一番少ない光霊のHPを20%回復する",
  str_item_intro_9994019 = "全ての小型の敵に減速効果を付与する",
  str_item_intro_9994020 = "すべての小型暗鬼の初期HP-20%",
  str_item_intro_9994021 = "小型暗鬼の攻撃力-10%",
  str_item_intro_9994022 = "戦闘開始時、能動技がクールダウン中の「チェンジャー」ジョブの光霊のクールダウン-1",
  str_item_intro_9994023 = "獲得後、光霊の近くに浮遊し、隊長が攻撃する時に1回の火属性ダメージを与える",
  str_item_intro_9994024 = "獲得後、光霊の近くに浮遊し、隊長が攻撃する時に1回の水属性ダメージを与える",
  str_item_intro_9994025 = "獲得後、光霊の近くに浮遊し、隊長が攻撃する時に1回の森属性ダメージを与える",
  str_item_intro_9994026 = "獲得後、光霊の近くに浮遊し、隊長が攻撃する時に1回の雷属性ダメージを与える",
  str_item_intro_9995001 = "戦闘不能になった光霊を復活し、HPを50%回復する（1回の対戦で、致命ダメージを受けた1人目の光霊にのみ1回発動する）",
  str_item_intro_9995002 = "この聖物の所有時、「チェンジャー」ジョブの光霊は1回の被ダメージが最大HPの20%を超えなくなる",
  str_item_intro_9995003 = "「サポーター」ジョブの光霊の余った回復量が一定の比率で1スタックのシールドに変換される。1ターン持続",
  str_item_intro_9995004 = "戦闘開始時、50%の確率で衝撃波を発動し、敵全員に1ターンの眩暈状態を付与する",
  str_item_intro_9995005 = "「スナイパー」ジョブの光霊の通常攻撃と連鎖技ダメージが暗鬼のシールドを直接解除する",
  str_item_intro_9995006 = "戦闘開始時、周囲1マスからランダムに4つの万色マスが出現する",
  str_item_intro_9995007 = "戦闘開始時、戦場にMS値を補充する光力測定器を1つ出現させる",
  str_item_intro_9995008 = "戦闘開始時、2×2マスをランダムで10組選び、その位置に雷を落とし、範囲内にいる対象に比率固定のダメージを与える。光霊には無効",
  str_item_intro_9995009 = "移動する時、出発地点に爆弾を1つ残し、味方の行動がすべて終了すると爆発させる",
  str_item_intro_9995010 = "コンボ数が5の倍数になった通常攻撃に1回の爆発効果を付加する",
  str_item_intro_9995011 = "死の気配を召喚し、残りHPが7%以下の暗鬼を瞬殺する",
  str_item_intro_9995012 = "「ボマー」ジョブの光霊が連鎖技を発動すると、連鎖の発生位置に現在の技を発動している光霊の虚像を生成し、同時に連鎖技を放つ",
  str_item_intro_9995013 = "運命のサイコロを入れるためのボックス。運命のサイコロを消費すると秘境の聖物をランダムで1つ再獲得できる",
  str_item_intro_9995014 = "「スナイパー」ジョブの光霊が40%の確率で連鎖技を1回多く発動する",
  str_item_intro_9995015 = "1体の光霊が能動技を発動すると、ランダムで「チェンジャー」ジョブの光霊1体のクールダウン-1",
  str_item_intro_9995016 = "「スナイパー」ジョブの光霊が通常攻撃をすると、暗鬼に減速効果を付与し、暗鬼の移動力-1",
  str_item_intro_9995017 = "戦闘開始時、全ての暗鬼に重傷効果を付加し、暗鬼は1マス移動するたびに3%のダメージを受ける",
  str_item_intro_9995018 = "「サポーター」ジョブの光霊が通常攻撃をすると、暗鬼に盲目効果を付与し、暗鬼の攻撃時に30%の確率で攻撃が外れる",
  str_item_rpintro_9993001 = "暖かい光を発する蝋燭。その光には光霊の傷を癒す力が宿っている",
  str_item_rpintro_9993002 = "旧時代のペンキ。光力の吸収に優れている",
  str_item_rpintro_9993003 = "回復薬の補助品。戦闘員の傷を効率よく癒すことができる",
  str_item_rpintro_9993004 = "古代の学者が遺した手書き原稿。属性間の相性関係について詳しく記載している。相性を考慮した戦略を立てられるよう、戦闘員を指導できる",
  str_item_rpintro_9993005 = "旧時代の勲章。不思議な構造をしている。ミクロ単位で光力コネクトを果たすことができ、戦闘力を高める",
  str_item_rpintro_9993006 = "旧時代の遺物。強烈な呪いがかかっているらしく、これを装備した者が毒を扱うとかなり有利になる",
  str_item_rpintro_9993007 = "旧時代のお守り。ミクロ単位で光力コネクトを果たすことができ、敵に莫大なダメージを与えることが可能",
  str_item_rpintro_9993008 = "古の短剣。旧時代の高強度合金を使っているため、かなり鋭い",
  str_item_rpintro_9993009 = "光力を注入した革製のアーマー。軽くて丈夫で、探索者の打撃耐性を大いに高めることができる",
  str_item_rpintro_9993010 = "光力を注入した革製のアーマー。軽くて丈夫で、探索者の打撃耐性を大いに高めることができる",
  str_item_rpintro_9993011 = "光力を注入した革製のアーマー。軽くて丈夫で、探索者の打撃耐性を大いに高めることができる",
  str_item_rpintro_9993012 = "光力を注入した革製のアーマー。軽くて丈夫で、探索者の打撃耐性を大いに高めることができる",
  str_item_rpintro_9993013 = "光力を注入した革製のアーマー。軽くて丈夫で、探索者の打撃耐性を大いに高めることができる",
  str_item_rpintro_9993014 = "7つの角を持つ不思議な赤色の宝石。これを持っていると、火属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993015 = "7つの角を持つ不思議な赤色の宝石。これを持っていると、火属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993016 = "7つの角を持つ不思議な赤色の宝石。これを持っていると、火属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993017 = "7つの角を持つ不思議な赤色の宝石。これを持っていると、火属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993018 = "7つの角を持つ不思議な赤色の宝石。これを持っていると、火属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993019 = "7つの角を持つ不思議な青色の宝石。これを持っていると、水属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993020 = "7つの角を持つ不思議な青色の宝石。これを持っていると、水属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993021 = "7つの角を持つ不思議な青色の宝石。これを持っていると、水属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993022 = "7つの角を持つ不思議な青色の宝石。これを持っていると、水属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993023 = "7つの角を持つ不思議な青色の宝石。これを持っていると、水属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993024 = "7つの角を持つ不思議な緑色の宝石。これを持っていると、森属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993025 = "7つの角を持つ不思議な緑色の宝石。これを持っていると、森属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993026 = "7つの角を持つ不思議な緑色の宝石。これを持っていると、森属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993027 = "7つの角を持つ不思議な緑色の宝石。これを持っていると、森属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993028 = "7つの角を持つ不思議な緑色の宝石。これを持っていると、森属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993029 = "7つの角を持つ不思議な黄色の宝石。これを持っていると、雷属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993030 = "7つの角を持つ不思議な黄色の宝石。これを持っていると、雷属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993031 = "7つの角を持つ不思議な黄色の宝石。これを持っていると、雷属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993032 = "7つの角を持つ不思議な黄色の宝石。これを持っていると、雷属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993033 = "7つの角を持つ不思議な黄色の宝石。これを持っていると、雷属性の光霊の力が大幅にアップする",
  str_item_rpintro_9993034 = "旧時代が遺した小さな彫像。高強度の材料で作られており、丈夫で軽い。装備した者に祝福も与えるという",
  str_item_rpintro_9993035 = "旧時代の武器。高強度の材料で作られているだけでなく、光力も注入されており、装備した者に強大な力を与える",
  str_item_rpintro_9993036 = "旧時代の古き盾。完璧な曲線を描いている。太陽の力が注入されているらしく、光力があらゆる致命的な攻撃から守ってくれるとのこと",
  str_item_rpintro_9994001 = "邪悪な気配がする刀。上古時代は激戦に使われていた武器らしく、この刀が抜かれる時は必ず血飛沫が舞い散る",
  str_item_rpintro_9994002 = "旧時代の医者が装着していた仮面。戦乱が盛んだった時期は呪いの象徴だと思われていた",
  str_item_rpintro_9994003 = "旧時代の名刀。これを振ると神にも劣らない力を感じるという",
  str_item_rpintro_9994004 = "強力な戦士の手で作られたと言われている呪物。敵は死の運命から逃れられない",
  str_item_rpintro_9994005 = "無名の画家が大昔に描き上げた絵画。疫病が流行っていた頃の惨状を描いており、作者自身もこの病で逝去している。そのせいか、この絵にも恐ろしい力が宿るようになった",
  str_item_rpintro_9994006 = "旧時代の名刀。昔の主は有名な反逆者であり、死を迎えた際の叫び声がこの刀に不思議な力を与えたという",
  str_item_rpintro_9994007 = "この古き鎧には「復讐」の二文字が刻まれており、これを装備した者は鎧に秘められた果てしない憤怒を感じるという",
  str_item_rpintro_9994008 = "完璧に保存された女神の彫像。光の信者たちに治癒の力をもたらす",
  str_item_rpintro_9994009 = "これを持っていると、あなたも勝利の女神のご加護を受けられる。戦闘では常に優勢を得られるだろう",
  str_item_rpintro_9994010 = "この短刀は上古文明の内戦で製造されたと言われており、何やら不穏な気配をまとっている。鞘から抜く際は必ず血を浴びせなければならず、さもないと普通の短刀と変わりない",
  str_item_rpintro_9994011 = "旧時代の技術。小さく見えるが、大量の光力を保存できる",
  str_item_rpintro_9994012 = "誰かが残していった折り畳み寝袋。体力の回復に最適",
  str_item_rpintro_9994013 = "太陽の力によって祝福された火縄銃。攻撃速度は遅いが、威力は絶大。強敵と戦う時には有力な武器となる",
  str_item_rpintro_9994014 = "流れる年月の中、これまで多くの主の手を渡ってきたが、どれも長くは続いていない…",
  str_item_rpintro_9994015 = "相手を麻痺できるレーザーを発射する遠距離の兵器。射程は短く、威力もさほど強くはない。通常は泥棒の捕獲などに使われている",
  str_item_rpintro_9994016 = "昔の勇士の光輝遺物。過去の祝福が未だに憑依しており、強い敵に立ち向かう際に使うと効果抜群（同時に3種類の光輝遺物を所有すると効果が2倍になる）",
  str_item_rpintro_9994017 = "古の勇士の光輝遺物。過去の祝福が未だに残留しており、強い敵に立ち向かう際に使うと効果抜群（3種類の光輝遺物を所有していると効果が2倍になる）",
  str_item_rpintro_9994018 = "古の勇士の光輝遺物。過去の祝福が未だに残留しており、強い敵に立ち向かう際に使うと効果抜群（3種類の光輝遺物を所有していると効果が2倍になる）",
  str_item_rpintro_9994019 = "昔の勇士がよく使っていた武器。過去の祝福が未だに憑依しており、俊敏な敵に立ち向かう際に使うと効果抜群（同時に3種類の銀月遺物を所有すると効果が2倍になる）",
  str_item_rpintro_9994020 = "古の勇士がよく使っていた武器。過去の祝福が未だに残留しており、俊敏な敵に立ち向かう際に使うと効果抜群（3種類の銀月遺物を所有していると効果が2倍になる）",
  str_item_rpintro_9994021 = "古の勇士がよく使っていた武器。過去の祝福が未だに残留しており、俊敏な敵に立ち向かう際に使うと効果抜群（3種類の銀月遺物を所有していると効果が2倍になる）",
  str_item_rpintro_9994022 = "古の神秘的な硬貨。これを持った光霊はまれに力が増幅し、行動がより俊敏になる",
  str_item_rpintro_9994023 = "旧時代の産物。巨像の小さいバージョンに見える。戦闘中は主のサポートを担当する。同時に四属性の浮遊器を所有すると、光霊が連鎖技を発動する時に1回の強力な攻撃を繰り出す",
  str_item_rpintro_9994024 = "旧時代の産物。巨像の小型版に見える。戦闘中は主のサポートを行う。同時に四属性の浮遊器を所有していると、光霊が連鎖技を発動する時に1回の強力な攻撃を繰り出す",
  str_item_rpintro_9994025 = "旧時代の産物。巨像の小型版に見える。戦闘中は主のサポートを行う。同時に四属性の浮遊器を所有していると、光霊が連鎖技を発動する時に1回の強力な攻撃を繰り出す",
  str_item_rpintro_9994026 = "旧時代の産物。巨像の小型版に見える。戦闘中は主のサポートを行う。同時に四属性の浮遊器を所有していると、光霊が連鎖技を発動する時に1回の強力な攻撃を繰り出す",
  str_item_rpintro_9995001 = "この地と不思議な関わりを持っている人工製品。装着者の心臓が止まっても、その命を救うことができる",
  str_item_rpintro_9995002 = "太陽に祝福された強力なアーマー。これを装着すれば、どんなに残酷な戦いも乗り越えられる",
  str_item_rpintro_9995003 = "旧時代が遺した謎の装置。溢れた光力を感じ取ることができ、それを利用して装着者を守る力場を展開できる",
  str_item_rpintro_9995004 = "表面に細かい亀裂が入っている粗い水晶。これは溢れんばかりの光力を秘めていることを意味しており、軽く触れただけで敵を眩暈させるほどの力を放つ",
  str_item_rpintro_9995005 = "旧時代が遺した強力な武器。材料はもはや特定できないが、刃がかなり鋭いことは確か。これに対抗できるアーマーはないだろう",
  str_item_rpintro_9995006 = "ありとあらゆる色の宝石をすべて集めた。かなり華麗で眩い光を放つ",
  str_item_rpintro_9995007 = "光力を保存するための装置。これを解放すると、失われた光力をチャージすることができる",
  str_item_rpintro_9995008 = "旧時代の名刀。雷霆の力が封印されており、抜くと瞬時に暴走し、敵を消滅する",
  str_item_rpintro_9995009 = "旧時代の産物。追手に対抗する場面に適している。秘められた光力は路線上に残り、一定時間後に爆発し、追ってくる敵に大ダメージを与える",
  str_item_rpintro_9995010 = "旧時代の産物。美しい見た目をしているが、恐ろしい力を宿しており、敵を散りゆく花びらのように爆発に巻き込む",
  str_item_rpintro_9995011 = "この小さな彫像は敵の命の気配を感じ取ることができ、これを身につけると虫の息の敵を瞬く間に消せる",
  str_item_rpintro_9995012 = "旧時代の強力な装置。幻像を生成し、敵を惑わす",
  str_item_rpintro_9995013 = "古代の遺物。隙間から覗くと生きる者すべての運命が見える。もちろん、幻覚の可能性もあるが",
  str_item_rpintro_9995014 = "この希少な赤色の蘭は旧時代が特殊な栽培方法を以て育てた品種。必ず対をなして現れ、対をなして咲き誇り、対をなして散る。これを身につけた者たちは不思議な力によって繋がり、協調性が高まる",
  str_item_rpintro_9995015 = "旧時代の産物。二人の戦士の間に不思議な連携作用をもたらす",
  str_item_rpintro_9995016 = "旧時代の大戦乱から生まれた産物。瞬時に年老いたような感覚を与えることができ、足元がおぼつかなくなるらしい",
  str_item_rpintro_9995017 = "壊滅的な戦争の中で生まれた不思議な品だと言われている。強い呪いの力があり、敵に重傷を与えられる",
  str_item_rpintro_9995018 = "戦闘中、レンズは相手を盲目状態にできるほどの眩しい光を放つと同時に、装着者の両目を守る。サポート性の高い装備",
  str_item_gift_open_cond_1003 = "パックLv10で解放する",
  str_item_gift_open_cond_1004 = "パックLv20で解放する",
