  str_item_1601861 = "ティナ",
  str_item_1601891 = "ライン",
  str_item_1501901 = "マシュー",
  str_item_1601911 = "ハーティ",
  str_item_1501931 = "クリステン",
  str_item_1601921 = "レオ",
  str_item_1601991 = "インゲル",
  str_item_1502001 = "アナトリア",
  str_item_1602011 = "ミヤ・浄魂",
  str_item_1602021 = "ソルラド・響鳴",
  str_item_1502031 = "ジャキーニ",
  str_item_1602041 = "ヨシュア",
  str_item_1502051 = "ブラン・洗心",
  str_item_1602061 = "ローレライ",
  str_item_1602071 = "セナ",
  str_item_1502081 = "バップ",
  str_item_1501871 = "テンカン",
  str_item_1601881 = "タンドウ",
  str_item_1602371 = "マヤ",
  str_item_1602381 = "ミトラ",
  str_item_intro_1600011 = "北境の代表となる人物。秘密が隠された鏡を肌身離さず持っており、常に彼女の世俗離れした美しい容貌を映している",
  str_item_intro_1600021 = "啓光連邦の軍団長として、厳粛で、真面目で決して揺るがない。厳格かつ迅速にためらうことなく物事を進め、太刀を手に大きな戦功を上げてきた",
  str_item_intro_1600031 = "昔は白夜城のアップタウンに住む某貴族の執事を務めていたが、他の貴族の逆鱗に触れたことでダウンタウンに追放された。しかし、実は極秘任務に就いているとも噂されている",
  str_item_intro_1600041 = "動物の姿をした流れ者コンビ。今はあちこちを放浪している傭兵であり、強力な戦闘力とユーモアセンスで名を馳せている",
  str_item_intro_1600051 = "影ノ街に出没する、狂ったように笑う少女。危険な「ゲーム」を好み、皆から疎まれている",
  str_item_intro_1600061 = "白夜城城主の次女。貴族の家庭に生まれた彼女は強い正義感を持っており、才能と努力で白夜城護衛隊隊長の座を手にした",
  str_item_intro_1400071 = "R・Wのアサシン少女。他人に左右されることなく、己の道を貫く。高難易度の任務を得意としている",
  str_item_intro_1400081 = "R・Wの技術員。陽光発射器の開発者。独特な戦闘スタイルを持っている",
  str_item_intro_1500091 = "真理結社に属するハンサムで上品な青年。笑うとチャーミングで、知性的な魅力に溢れている。自身が認めた哲学を常に広めており、基本的にはおしゃべり",
  str_item_intro_1600101 = "北境出身。ポジティブ思考で笑顔を絶やさない彼女は、いつだって前向き。この世のあらゆる物事に楽観的な希望を持っている",
  str_item_intro_1600111 = "啓光連邦軍団長。「龍の力」を持つ若き士官。クールな外見と裏腹に、仲間としては頼りがいがある",
  str_item_intro_1500121 = "啓光連邦に属する勇猛な少女。正義の代弁者と執行者であり、崇高な理想を抱えながら戦いに挑んでいる",
  str_item_intro_1500131 = "雪と氷を操ることができる北境の少女。地域全体を寒さに陥れるほどの強力な魔力を持つ",
  str_item_intro_1600141 = "白夜城城主。白夜城の秩序を維持するため、気を休めることなく常に働いている",
  str_item_intro_1400171 = "R・Wの隊長。兎の素早く俊敏な動きを得意とし、戦闘中に彼女を捉えられる敵は少ない",
  str_item_intro_1500181 = "R・Wのロックバンドメンバー。人気者である彼女は、チームの士気を高めるだけではなく、仲間を率いて戦地に突撃することもいとわない",
  str_item_intro_1600191 = "魅惑的な女性。禁断の知識を持つ真理結社のメンバー。ある「真実」を広めるために尽力している…",
  str_item_intro_1500201 = "キタカゼ",
  str_item_intro_1500211 = "啓光連邦のメンバー。お兄ちゃん的な存在として慕われている。自然学にも精通しており、ガーデニングが得意。自然の力を導き出し、敵を攻撃する",
  str_item_intro_1300221 = "ウサギの頭を被っている情熱的な少年。軽油とバイオレンスに魅了されており、R・Wに属するならず者の1人",
  str_item_intro_1600231 = "内気でシャイな性格の持ち主だが、クラリネットと水を操る能力のおかげで、玉石混淆した影ノ街で自分の地位を確立することができた",
  str_item_intro_1500241 = "啓光の2人組。ベニは粗野で騒々しく、クロは冷静沈着で頭が切れる。性格は違うが、息はピッタリ。啓光の精鋭士官",
  str_item_intro_1600251 = "啓光連邦の補給長官。「彼岸号」と呼ばれる列車の持ち主。戦闘でも日常生活でも、両者の連携は阿吽の呼吸だと言われている",
  str_item_intro_1600261 = "白夜城騎士団所属。名高い四大天使の一人。彼女が纏う情熱的な炎とは裏腹に悲観的な性格の持ち主で、いつも心を閉ざしている",
  str_item_intro_1600271 = "白夜城の騎士で、名高い四大天使の一人。生真面目で正直者。過去に重傷を負い啓光連邦が改造手術を施した結果、感情の一部を失うこととなった",
  str_item_intro_1600281 = "白夜城騎士団所属。名高い四大天使の一人。格別な治療能力とポジティブな思考を擁している",
  str_item_intro_1600291 = "白夜城の騎士で、名高い四大天使の一人。冷静かつ穏やかで、何事にも動じない平和主義者である",
  str_item_intro_1600301 = "R・Wの首領。豪放磊落な中年男性。多くのメンバーと命をかけた付き合いをしている。妹のことをとても気にかけ、R・Wの存続のために力を尽くしている",
  str_item_intro_1500311 = "スーモア",
  str_item_intro_1400321 = "白夜城裁判官の1人で片翼の天使。デリケートで自尊心が高い。若く見えるが、戦争経験者の1人",
  str_item_intro_1500331 = "若くして多くの見識を持つ、熱心な努力家。啓光連邦に人材として重要視されている",
  str_item_intro_1500341 = "ソネット",
  str_item_intro_1400351 = "あらゆる地方を駆け巡っているクーリエ。仕事マニア。抱えている仕事をすべて終わらせなければ眠れないらしい…",
  str_item_intro_1500361 = "影ノ街出身の反逆的な一匹狼。白夜城の秩序になど全く興味がなく、貴族に対して特別な敵意を抱いている…",
  str_item_intro_1600381 = "巨大メカを操る少女。啓光連邦で最高科学責任者を務めており、軍を退役した天才少女だと言われている",
  str_item_intro_1400401 = "爆発が好きな女の子。爆発音を聞くとなぜか興奮するR・Wのメンバー",
  str_item_intro_1400411 = "白夜城でガイド、導き役を務める、何事にも動じない穏やかで上品な女性。過去に尋常ではない「何か」を経験したようだ",
  str_item_intro_1400441 = "啓光連邦軍の参謀長。生真面目で、役割を常に全うし、あらゆることを適切に処理する",
  str_item_intro_1300461 = "白夜城で小さな放送部を勝手に始めた4人の子ども。学院の聖歌隊に所属し、可愛らしい見た目をしているが、他人を嘲笑うのが趣味のとんでもない子どもたちである",
  str_item_intro_1300471 = "啓光連邦の天才研究員。あらゆる知識を渇望しており、彼女を惹きつけるものは、知識と…とある軍団長だけだと言われている",
  str_item_intro_1400481 = "若いながらも「ダイナ組」のリーダーとして活躍している。その優れた判断力と人を欺く冷徹な暗器さばきによって、影ノ街で確固たる地位を築き上げた",
  str_item_intro_1300491 = "気高く、強い戦士。影ノ街を歩く際も肌身離さず鎧と大剣を身につけており、ヘルメットを取ることはない。寡黙な性格で、言葉より武力で語る癖がある",
  str_item_intro_1200501 = "笑顔さえも恐ろしいサメ…！小さな集落の守護者。見た目は凶暴で恐ろしいが、実はとても優しい",
  str_item_intro_1300511 = "無口なワニの擲弾兵と大げさで騒々しい鳥の狙撃手は、変わり者が多いR・Wの中でも奇妙なチームを形成している。任務を全うする価値ある傭兵である",
  str_item_intro_1300521 = "啓光連邦に駐在しているクーリエ。非常に怠惰な性格でクーリエとしての勤勉さは一切なく、いつも仕事をごまかしている",
  str_item_intro_1300531 = "R・Wに所属する、お金に目がない狡猾な商人。お金さえ貰えれば、どんな依頼でも引き受ける…",
  str_item_intro_1300741 = "啓光連邦の下級士官。謎めいた血統のせいか仲間になじめず、一匹狼のようにいつも心を閉ざしている",
  str_item_intro_1300581 = "白夜城の新騎士。真面目でポジティブ。若くして職務を任されているため、無理をしがち",
  str_item_intro_1400161 = "R・Wのメンバー。強力なレールガンを持った狙撃手で、侵入してくる敵を全て排除する",
  str_item_intro_1400541 = "白夜城ナイトガーディアンの新隊長。冷静で注意力に優れている。何事にも周囲を感心させるほどの真剣さで取り組む",
  str_item_intro_1400611 = "楽観的で明るい啓光連邦の研究員。仲間のネガティブな感情を吸収し、他者の心の傷を癒すユニークな能力を持っている",
  str_item_intro_1400731 = "影ノ街イスタバン組の新メンバー。終始興奮状態の2人には気をつけるように",
  str_item_intro_1500421 = "啓光連邦軍団長。つまらない平和に耐えられず、勝つためならどんな手段もいとわない戦争マニア",
  str_item_intro_1500761 = "影ノ街で有名なペテン師。礼儀正しく穏やかな紳士だが、嘘をつくことに抵抗がない",
  str_item_intro_1500781 = "影ノ街「ダイナ組」のメンバー。心を閉ざしたコミュ障。姉のダイナと助け合い、影ノ街で生き残るため奮闘している",
  str_item_intro_1600771 = "北境の統治者。長年にわたって得た豊富な知識と経験から、変化にも臆することなく、何ごとも冷静に淡々と片付ける",
  str_item_intro_1300591 = "クーリエ隊のメンバー。真理結社への連絡を担当している。おっちょこちょいでだらしがなく責任感に欠けるが、隠し事をせず率直な物言いをする。",
  str_item_intro_1300801 = "啓光連邦の研究員。機械・模型マニアの天才少女。コミュニケーションが苦手だが、熱中している物のことになると話が止まらなくなる",
  str_item_intro_1300821 = "北境-緑松ノ地の妖精。天真爛漫で世事に疎い。貴重な宝石の角を持っているため、幼い頃から大切に守られてきた。",
  str_item_intro_1400451 = "真理結社の主要メンバーであり、ビクトリアの信者。口数少ないながら真理結社の理念を強く信じている",
  str_item_intro_1400571 = "啓光連邦の情報長官。普段は穏やかで人懐っこく、のんびりとした性格だが、内に秘めたもう一つの人格は非常に凶暴で、危険である。",
  str_item_intro_1400681 = "自信に満ちており、可愛くて勇気があって、挑戦をこよなく愛しているクーリエ隊のメンバー。R·W地域を担当している。郵便物の配達中に、あちこちで無茶をするのが好き。可愛いヤンキー",
  str_item_intro_1400791 = "白夜城の税務官。合理性、公平性、独立性を重んじている。全てを金銭に換算する習慣がある。",
  str_item_intro_1400811 = "R·W決死隊のメンバー。明るく負けず嫌い、自信に満ち溢れた熱血バカ。常に感情をむき出しにし、何事においてもナンバーワンになりたいという強い思いを持っている。",
  str_item_intro_1400831 = "啓光研究機構の給仕係。表向きは機械的な話し方をするメイドだが、 実際は強力な生命体のクローンである",
  str_item_intro_1601231 = "啓光連邦の治安維持を担う護衛官。任務遂行中に突発的状況が発生すると、いつも驚いて泣き出してしまう。しかし、自らの正義を実現するため、たゆまず前向きに仕事に励んでいる",
  str_item_intro_1601201 = "裕福な家庭に生まれ育った貴族令嬢。きわめて聡明で、家にこもって読書することを好む。自ら呼び覚ました巨大な鎧「ポンペイ」が唯一の友人だ",
  str_item_intro_1500151 = "影ノ街の画商。ハチは名画の鑑定に優れ、ギンは卓越した絵画技術を持つ。息の合ったコンビとして、画商のほか、傭兵としても活動している",
  str_item_intro_1501321 = "北境松の谷の民。ハチミツとハチミツに関するものが大好き。彼女の藤の花はとても美しいが、特殊な力を持っている",
  str_item_intro_1601311 = "北境の民。ベツレヘムと親しい。歴史に精通し、思いやりにあふれる。北境を光霊最後の楽園と考え、自分の力で守りたいと望んでいる",
  str_item_intro_1601331 = "かつては暴虐の限りを尽くすドラゴンだったが、単身で神の陣営に突っ込み、命を落としかける。逃げた異世界で出会った小林さんを好きになり、メイドとして彼女と過ごすことを選んだ。",
  str_item_intro_1601341 = "トールと同じドラゴンで、見た目と性格はまだ子ども。イタズラをして家を追い出され、その後はずっとトールの後を追い、一緒にいる。",
  str_item_intro_1501351 = "世の争いを調和し、かつては「聖海の巫女」と呼ばれていた。性格は一本気で真面目。甘いモノを中心に食べることへの執着は底無し。",
  str_item_intro_1501361 = "元々は文化を司る太古の神だった。強大な力をもっているが、普段は少しダル目のお姉さん。",
  str_item_intro_1401371 = "トールの友だちで、元の世界では洞窟内の財宝を守っていた。貪欲な者たちをあまりにも多く見てきたため、他人に深い敵意をもっている。",
  str_item_intro_1601381 = "啓光連邦の研究員。仕事の時は、理性的で効率的だが、私生活は気ままでだらしない。古代の科学技術に魅せられ、一年中さまざまな遺跡の調査のため、フィールドワークに駆けまわっている。",
  str_item_intro_1501391 = "白夜城出身、黎明学院の生徒会メンバー。いつもフロリナと一緒にいる。奇妙な考えを持っており、時々周囲を驚かせるようなことを言い出す",
  str_item_intro_1601401 = "白夜城生まれ、黎明学院時代は生徒会長。一見冷淡そうだが、温かい心の持ち主で、面倒見がいい。優秀な騎士になるべく奮闘中",
  str_item_intro_1601411 = "R・Wで生まれ、活発で明るい性格の彼女は、小さい頃から冒険の話を聞くのが好きだった。十分な知識とスキルを身に着け、みずからも探検の旅に出た",
  str_item_intro_1501421 = "R・Wのメンバー、ルビーにべったり。物言いには毒があるが、心はうらはらに、実は気遣いのできる、優しい子である",
  str_item_intro_1601431 = "雲島の巫女。知性にあふれ、礼儀正しい。雲島を統治する将軍に育てられ、自らの力で雲島の民を困難から救いたいと願っている。",
  str_item_intro_1501441 = "雲島出身の長身の女性。かつてリンネに救われたことがある。「もののけ」が見えるらしく、人見知り。",
  str_item_intro_1601451 = "雲島出身。戦乱で故郷を失ったところを助けられ、忍術を学んだ。その経験から淡泊な性格になったが、仲間に対してはとても義理堅い",
  str_item_intro_1601461 = "雲島出身。リン家商会で「気功術」を学んだ。武芸に秀で、活発な性格。人助けや各地を旅して回ることが好き",
  str_item_intro_1501471 = "雲島出身の双子。カニ家というラーメン屋台を営業しており、雲島では大繁盛している。お金を稼ぎながら、究極の美味を追求し続けている",
  str_item_intro_1201631 = "北境から来た謎の生物。ゲーム制作に熱中している。誰に会っても、まず「先生、仕事をお願いできますか？」と聞くのが口グセ",
  str_item_intro_1601481 = "偵察を担うR・Wのメンバー。我が道を行くタイプ。長期にわたり、R・Wのため有益な情報を独自に調査している。かつては伝説と呼ばれたレーサー",
  str_item_intro_1501491 = "R・Wの裏方を任されている男。だらしないように見えるが、実は思慮深い。R・Wの仲間を守るため、影で気を配っている",
  str_item_intro_1601501 = "真理結社のメンバー。寡黙だが、群を抜いた能力をもっている。自分の考えがなく、野心もない。ただ他人から指示がくるのを待っている",
  str_item_intro_1601511 = "真理結社のメンバー。普段は気だるげだが、興奮すると別人のようになる。自分はある童謡を広めるためにこの世に生まれたのだと信じている。",
  str_item_intro_1501521 = "人見知りで被害妄想気味な少女。真理結社で重用されるようになろうと、周りの大人に取りいっている。しかし、内心は愛に飢えており、皆から気にかけてもらいたいだけである",
  str_item_intro_1601551 = "啓光連邦の軍団長。「ハーモナイザー」の影響により外見と能力が変化した。中身は戦争マニアのまま。",
  str_item_intro_1601541 = "啓光合同探索隊隊長。明るい性格で、思いやりがある。偶然地下に閉じこめられていた空の末裔を助け出し、スリルに満ちた冒険の旅に出ることとなった。",
  str_item_intro_1601531 = "名実ともに啓光連邦の大元帥。戦いにおいては勇猛果敢、誠実な人柄と優れた統治能力を持ち、啓光の人々から敬愛されている。",
  str_item_intro_1601561 = "影ノ街で暮らす、白夜城貴族の家柄。近寄りがたいように見えるが、実際にはそれほど付き合いにくい人物ではない…おそらく。",
  str_item_intro_1501571 = "雲島出身、波乱万丈の人生を歩んできた。生活のためにアストラに来たが、知らず知らずのうちに巨額の借金を背負ってしまった。今はクビにされないようにすることで頭がいっぱい。",
  str_item_intro_1601581 = "異世界からやって来た少年。「ペルソナ」という特殊な能力を使う。\n素顔を覆う仮面、コードネームで名乗るなど、只者ではない雰囲気の少年。\n聞けば彼は、異世界を騒がせている「心の怪盗団」のリーダーとのこと。",
  str_item_intro_1601591 = "異世界からやってきた「心の怪盗団」の一人。\n作戦参謀として怪盗団の行動指針を提案する少女。\n「ペルソナ」を使うことができる。",
  str_item_intro_1501601 = "異世界からやってきた「心の怪盗団」の一人。\n独特の感性ゆえに、浮世離れした印象を受ける少年。\n「ペルソナ」を使うことができる。",
  str_item_intro_1501611 = "異世界から「心の怪盗団」と共に来訪した少女。\nある目的のために一時的に怪盗団と行動を共にしているとのこと。\n「ペルソナ」を使うことができる。",
  str_item_intro_1501621 = "異世界から来た、猫に似た姿をした謎の存在。人語を操る。\n「心の怪盗団」に様々な手引きをしたのも、このモナ。\n「ペルソナ」を使うことができる。",
  str_item_intro_1601641 = "カレン・ド・ソルラド。ハーバーシティの旅路で今までと異なる能力に目覚めた。「統率者とは何たるか」という問いにも、さらに深い悟りを得たようだ。",
  str_item_intro_1501651 = "啓光の工学の天才。内向的な性格で人見知りだが、実際は人との交流を渇望している。夢は強大なパワードスーツを造ること。",
  str_item_intro_1601661 = "小さな珍獣トレーナー。わがままで意地っ張りだが、意外と泣き虫。師匠ヴィックを超える珍獣マスターになるため、努力を続けている",
  str_item_intro_1601671 = "マジックハンド・ビルサーカス団の団長。真理結社のメンバーでもある。ミステリアスで寡黙。夢は最も偉大なマジシャンになること",
  str_item_intro_1501681 = "暗鬼の襲撃によって故郷を追われた少女。素直で元気いっぱい。エメラルド号を守ることを己の使命としているが、しばしばサーカス団の前座として場を盛り上げるアルバイトもしている",
  str_item_intro_1501301 = "白夜城トロイ家の出身。高貴な生まれでありながら、なぜ職位が低いのか？その答えは、彼の性格を知れば分かる",
  str_item_intro_1501711 = "一見冷淡そうだが、実は責任感が強い。教会の子どもたちによりよい環境を与えようと、ポルクスと共に「レイヴンズ・ブラッド」を名乗り、フリーの傭兵として働いている",
  str_item_intro_1601701 = "強気でやり手だが、振り返りたくない過去を隠している。今はさびれて荒れ果てたユーフォリアで教会を守り、家を失くした子どもたちを引き取っている",
  str_item_intro_1401691 = "影ノ街出身の怪力少女。見た目はクールだが、内心はとても純粋で忍耐強い。義賊になるための修行として、さまざまな依頼を引き受けている。",
  str_item_intro_1601721 = "明るく前向きな、かわいらしい女の子。映画女優を目指し、単身影ノ街の「アリーウッド」へやってきた。どんなに苦労しようとも、一度も夢をあきらめたことはない。",
  str_item_intro_1601731 = "影ノ街のアンデルセン家の執事。強くて優雅な完璧主義者。当主の恩に報いるべく、自身のすべてをささげている。",
  str_item_intro_1601751 = "アクセリアという名前の「戦闘サイボーグ」。啓光連邦に所属している。このような異名を持つ彼女だが、体の具合がとても気がかりのようだ。",
  str_item_intro_1501761 = "白夜城の戦医。ヨハネスという医師に命を助けられたことをきっかけに、優秀な医師になることを志した。",
  str_item_intro_1601771 = "影ノ街出身の有名なアイドル。生まれながらにして幸運に恵まれているだけでなく、彼女自身の前向きさと明るさはすべての人を元気にしてくれる",
  str_item_intro_1601781 = "森の中で隠居生活を続ける珍獣の研究者。彼の言動はよく他人を怒らせ、弟子のフィアをこき使うが、珍獣には優しい",
  str_item_intro_1501801 = "今はまだ小さな新聞社の見習い記者だが、報道という仕事に情熱を持っており、スキャンダルの追求に非常に熱心。目標は、影ノ街で最も名の知れた大物記者になることである",
  str_item_intro_1601811 = "かつて龍州の兆の国の大将軍だった人物。今は悠々自適に暮らしているが、いつどこにいようと己の信念を守り続けている",
  str_item_intro_1601821 = "「蜃風号」の船長。見た目通り冷淡で、決断力がある。目標は最強の遠洋船舶を造り、最も安全な遠洋航路を拓くことである",
  str_item_intro_1501831 = "名医卜存子に師事する、かわいらしく頼りになる薬師。幼いが賢く、口が達者。ほめられることに弱い",
  str_item_intro_1601841 = "クーリエ隊、R・W支部のエルダー。気さくでルーズな性格だが、極めて知的な観察者でもある",
  str_item_intro_1501851 = "新人クーリエだが、クーリエ隊では珍しく真面目で責任感が強い。ただ、クーリエ隊の制度を厳格に守りすぎるため、失敗することもある",
  str_item_intro_1601861 = "爵位を継いだ白夜城貴族であり、白夜城法廷の裁判官でもあるが、睡眠時間の多い「特異体質」の少女",
  str_item_intro_1601891 = "白夜城の裁判官。悪を憎み、強い信念を持つ。何者にも媚びず、誰しも平等に扱うが、その性格ゆえか他人と距離をとる一面もある",
  str_item_intro_1501901 = "白夜城法廷の裁判官。抜群の素質を持つが野心はなく、望みは平凡な人生を楽しく過ごすことだけ",
  str_item_intro_1601911 = "亜人族の血統を引く影ノ街の一匹狼。友人はおらず、言動があまりにも率直であるため、よく不必要な誤解を招いてしまう",
  str_item_intro_1501931 = "貴族の名家の生まれながら、周囲に流されることなく自身のやり方を貫き、自らの願いで白夜城の見習い裁判官となった",
  str_item_intro_1601921 = "「アイアンソーン騎士団」団長。決断力と威厳を備えているが、親しみやすさも持ち合わせている。白夜城の腐った現状を変えたいという野望を抱いている。",
  str_item_intro_1601991 = "啓光軍人の家庭に生まれ、現在は「委員会」の上級情報官。その深い瞳の奥には、何やら計画があるようだ…",
  str_item_intro_1502001 = "啓光連邦の情報官。冷静かつ頼りがいのある人物だが、時折思わぬツッコミを入れ、人々を驚かせる。それが故意なのか否か、誰にもわからない。",
  str_item_intro_1602011 = "影ノ街に身を隠している白夜城の騎士。表舞台に出ることのないソルラドの長女である。純粋で善良な彼女は父に認めてもらいたいと願い続けているようだ。",
  str_item_intro_1602021 = "壮年期のソルラド。剣を手に暗鬼征討に奮闘する。即位間もない白夜城の統治者であり、陣頭で敵に立ち向かう戦士でもある。",
  str_item_intro_1502031 = "北境の使者。情熱的で明るく元気いっぱいだが、占いの腕はまだ未熟だ。そのうえ大雑把な性格であるため、しばしばトラブルを起こす。",
  str_item_intro_1602041 = "人々はすでに他界した城主夫人に瓜二つだと言うが、別人のようにも思える。ヨシュアは理想を胸に世界の各地へと向かう…",
  str_item_intro_1502051 = "「ナイトガーディアン」隊長の職を辞して何年も経つMs.ブランが再び戦闘服を取り出す。あの「Ms.ロト」が帰って来た！",
  str_item_intro_1602061 = "影ノ街で育った裕福な家庭のお嬢様。本来なら何不自由ない暮らしを享受できたところ、独り立ちして起業し、夢をかなえるためまい進している",
  str_item_intro_1602071 = "「今を生きる」を人生のモットーとするデヌオリゾート村の管理責任者。見たところ軽薄そうだが、意外にも頼りになる",
  str_item_intro_1502081 = "巨像「トラベラー」のナビゲーターであり、R・Wの「軍師」である。だが他の皆からはマスコット的存在として扱われているようだ…",
  str_item_intro_1400861 = "白夜城黎明学院のメンバーであり、葬儀の司会も務める。積極的で大胆かつ、優しくて繊細な性格の持ち主。いつも穏やかで、笑顔を崩さず物事に対処する。",
  str_item_intro_1400911 = "白夜城の音楽家。優しくてフレンドリーだが、つい弱気になって悲しい記憶に溺れることも。戦争で家族を失って以来ずっと、悲しみの渦の中で苦しみ続けている",
  str_item_intro_1500701 = "影ノ街の一匹狼。「龍の力」を持ち、傲慢で気まぐれな性格をしている。自分こそが一族の運命を担っていると思っている。",
  str_item_intro_1500751 = "R·Wのエンジニア。自身が持つ通信技術の腕前を、誇りに思っている。いつも通信チャネルで人をバカにするが、現実で問題が発生すると慌てふためいてすぐに手一杯になってしまう",
  str_item_intro_1500841 = "影ノ街の裏の統治者。決断力に優れ、強い忍耐力を持ち、忠誠心を重んじる。過去に、生き残りをかけた残酷な試練を経て、現在の名声と地位を手に入れた",
  str_item_intro_1500881 = "R·Wの偵察担当。人見知りで不器用かつ、臆病な性格の持ち主。しかし、戦闘では興奮状態になり暴走する。本人も、自身が持つ制御できない程の力に悩んでいる。",
  str_item_intro_1500901 = "R·Wのアイドル歌手。表面的には優しくて美しい歌手だが、マナーの悪いファンに対しては荒っぽい一面を見せることも。",
  str_item_intro_1500921 = "真理結社のメンバー。真面目で融通が利かず、独特のテイストを持つ。いちど目標を決めたら、その達成に全力を注ぎこんでしまう。意地っ張りで譲らないタイプ。",
  str_item_intro_1600601 = "R·Wの幹部で射撃の名手。元賞金稼ぎ。不真面目で皮肉屋だが、敵には容赦ない。彼女の手錠が外された瞬間を、誰も目にしたことがない",
  str_item_intro_1600641 = "啓光連邦軍近衛兵団長。野心家で、啓光連邦統治者の地位を狙っている。気力旺盛で独占欲が強く、権力を得るためなら決して諦めることはない。",
  str_item_intro_1600891 = "白夜城の裁判長。善良、温和、正直、強靭、献身的な精神を有しているが、実は偏執的な一面を心のうちに秘めている",
  str_item_intro_1601031 = "真理結社の尋問官。ビクトリアの信者。その瞳には強い「災厄の力」が宿っているが、今は封印されている",
  str_item_intro_1500871 = "白夜城の武官の家柄。貴族として高貴な身分と強大な権力を持っている。伝統に忠実で、責任感が強い。傲慢なところもあるが、最近は変わりつつある",
  str_item_intro_1401011 = "啓光の連絡員。情報の伝達や連絡を担当している。仕事ぶりは真面目。空気を読むのが得意で、たまに他愛ない冗談を言う",
  str_item_intro_1401021 = "影ノ街ダイナ組の盟友。自由気ままな生活が好き。口にくわえたロリポップと手から放たれる電流がトレードマーク",
  str_item_intro_1500991 = "影ノ街をさすらう傭兵。呪いを背負って生まれた。幼い頃から病弱で、魔剣の力を借りなければ生きられない",
  str_item_intro_1501001 = "真理結社のメンバー。貴族の家庭に生まれた。幼くして秘密の墓所を守る番人に選ばれ、厳格な教育を受けたため、知性豊かだが冷淡な性格をしている",
  str_item_intro_1600931 = "啓光で生命科学を研究する研究員。普段はぶらぶらしているように見えるが、いざという時には冷静沈着な一面を見せる",
  str_item_intro_1500981 = "呪いのせいで普通の人間が持つ感情が欠落しているが、目覚めたとき最初に見た人になつくらしい。今は影ノ街に隠れ住み、イスタバン配下の暗殺者として働いている",
  str_item_intro_1400621 = "北境の森の守人。眉目秀麗で冷ややかに見える少年。実際は心優しく、親友を欲しがっている。まだ年も若く、どこか子どもっぽさが残っている",
  str_item_intro_1400951 = "各地を渡り歩く傭兵で、生まれつき動物のような姿形をしている。ひと言余計なことを言わないと気が済まない性格",
  str_item_intro_1300941 = "北境のパトロール隊員。社会経験が乏しいが、純粋で優しい性格の持ち主。極寒の中を一人でパトロールするのには慣れており、人々に春の息吹と希望を運んでくれる",
  str_item_intro_1600961 = "啓光の生まれだが、祖父の生前の情報を探して影ノ街に流れてきた。いつもぼーっとしていて、騙されやすい",
  str_item_intro_1500971 = "影ノ街に出没する殺し屋。イスタバンのために「特別任務」を遂行する。以前は優れた外科医だった",
  str_item_intro_1500561 = "大陸を独り歩く、一匹狼のハンター。やや変わった思考の持ち主。猟銃とノートを肌身離さず持ち歩き、いつでも暗鬼を狩れるよう身構えている。狩りの様子をノートに細かく記録するのが好き",
  str_item_intro_1701071 = "封印された古代の英雄。暗鬼に対する恨みから改造を受け入れ、とても粗暴になってしまうが、大胆かつ着実な性格を取り戻した",
  str_item_intro_1701081 = "封印された古代の英雄。改造を受け入れて強大な力を手に入れたが、己の力を制御できず、大きな災いを招いてしまった。今なお深い自責の念にさいなまれている",
  str_item_intro_1701091 = "封印された古代の英雄。かつて改造を受けて感情の大部分を失った。使命を終えたのち、自分が守った国に棄てられたらしい…",
  str_item_intro_1701101 = "封印された古代の英雄。幼くして暗鬼との戦いの最前線に立った。わがままでおしゃべり好き。改造を受け入れたが、真面目さと純粋な初心を残している",
  str_item_intro_1501041 = "闇の力の影響で両目を失明した。一見すると冷淡で人嫌いな少女だが、相手をよく知ると打ち解け、言いたいことは率直に言うタイプ",
  str_item_intro_1601051 = "サメヤマの妹。幼い頃暗鬼の力によって自分を制御できなくなり、自分を見失ったこともある。治療を受け、ようやくもとの天真爛漫な性格を取り戻した",
  str_item_intro_1500711 = "極東から来て影ノ街に定住した「何でも屋」の店主。イスタバンの盟友でもある。人付き合いが悪く、ひねくれ者。何をするにもためらいがない",
  str_item_intro_1400671 = "北境出身の少女。亜人族の血を引いている。無邪気で活発で、強い好奇心を持っている。2体の人形と旅をしている",
  str_item_intro_1601111 = "真理結社のメンバー。強大な「血晶の領域」を操り、敵の動きを封じることができる。しかし、赤い晶石は彼女自身の精神にも影響を与えており、彼女を冷淡で寡黙、悲観的な性格にしている",
  str_item_intro_1601121 = "影ノ街に暮らす自由人。粗野かつまっすぐな性格で、強大な炎の力をもつ。新鮮で刺激的なものを追い求めている",
  str_item_intro_1501131 = "真理結社の音楽家。表面上は可愛らしく情熱的だが、究極の楽章を手に入れるためなら手段を選ばない。自らの音感に絶対的な自信をもち、また白夜城の音楽のレベルを見下している",
  str_item_intro_1501141 = "表向きは賞金稼ぎだが、実は真理結社のメンバーである。優雅な立ち居振る舞いと明るい性格の持ち主で、ジュネヴァをこよなく愛する。現在は真理結社の情報網構築に努めているが、同時に「アイツ」の行方も探している",
  str_item_intro_1601151 = "クーリエ隊のメンバー、もっぱら白夜城の業務を担当する。性格は冷静沈着、上品で、動植物と意思疎通する不思議な能力をもっている。側にはいつも数匹の動物とたくさんのホタルが一緒にいる",
  str_item_intro_1601161 = "気の優しいR・Wの整備士。他人からの頼みごとを断れない。それが原因で度々騒ぎを起こしてしまうことに本人も悩んでいる。さまざまな機械の修理に長けており、いつか自分用のメカを作ることを目標に頑張っている",
  str_item_intro_1401271 = "もともとR・W砂漠に住んでいたが、のちに真理結社に加わった。奇妙な紙の札を操って戦う。普段は弱気な性格だが、霊魂の存在をかたくなに信じており、そこだけは譲らない。",
  str_item_intro_1601191 = "啓光連邦の新兵。戦闘の天才だが、プライドが高く衝動的な性格で、人との交流は苦手。戦いで功績をあげ、自分の実力を証明したいと強く望んでいる",
  str_item_intro_1601221 = "影ノ街出身の雇われ銃手。卓越した射撃技術をもつ。緻密な計画を好む性格で、骨董収集が趣味。夢は十分な資金を稼いで骨董店を開くこと",
  str_item_intro_1601171 = "かつて啓光連邦の防衛線で戦い、活躍した古参兵。現在は前線を退き、後方支援で働いている。一見粗暴ながら、実はきめ細やかな性格で、戦いでは頼れる戦友となる。過去の戦いで心に傷を負い、失意の底に沈み、無為に過ごした時期もあったが、今は立ち直っている",
  str_item_intro_1601211 = "真理結社のメンバー。反抗的な性格だが、理性的で最低限の礼節や道徳は守る。元は白夜城の修道女だったが、理不尽な不幸に見舞われたことで、白夜城の虚偽を知り、修道女をやめた。それ以来、白夜城の正体を暴くことに力を入れている",
  str_item_intro_1300651 = "クーリエ隊のメンバー、北境エリアの担当。とても熱心なクーリエだが、少々どんくさく、独特の訛りで話す。それが却って純粋で可愛らしい",
  str_item_intro_1500551 = "白夜城の裁判官。昔かたぎな性格だが、職務に熱心で手際も良い。今は過去の事件を解明するために奔走している",
  str_item_intro_1601261 = "影ノ街総合商会の責任者。イスタバンの右腕であり、彼の養女でもある。真面目で厳格。何事にもビジネスライク",
  str_item_intro_1601291 = "影ノ街傭兵団の副団長。信義を重んじ、影ノ街の裏の情報にも精通している。傭兵団の拡大を目指している",
  str_item_intro_1602371 = "幻蜃一族の子孫は記憶を留めるのが難しいと言われるが、性格は楽観的で心優しい。自分を受け入れてくれたハーバーシティに恩返ししようと努力している",
  str_item_intro_1602381 = "ミトラはロンギヌス一族に生まれ、二千年にわたり使命である星々の秘密を守り続けた。彼女は控えめで用心深く、その鋭い刃を黒い羽の下に隠している。",
  str_item_intro_1702361 = "祭剣座はかつて国王の右腕であり、静かなる猟兵の隊長だった。彼は正義を貫き、決して揺らぐことはなかった。光力が彼を見放そうとも、彼は星の力で未来を切り開いた。",
