  str_item_5273053 = "麦畑の装飾ボード",
  str_item_5273054 = "ヒマワリの装飾ボード",
  str_item_5273055 = "映写機",
  str_item_5273056 = "地図",
  str_item_5273057 = "郵便ポスト",
  str_item_5234040 = "「R・Wグルメフェスタ」",
  str_item_5234041 = "「ゴーストハウス」",
  str_item_5234042 = "「啓明の光のために」",
  str_item_5234031 = "ソーンビーストの像",
  str_item_5234032 = "三角獣の像",
  str_item_5241014 = "ファルベプッペ型熱気球",
  str_item_5232007 = "中空スツール",
  str_item_5234035 = "幾何学模様のモニュメント",
  str_item_5222001 = "低い生垣",
  str_item_5222002 = "高い生垣",
  str_item_intro_5212001 = "「船は沈めた、次はお前だ！あああ！おい、触手を滑り台にするんじゃない…まあ、いい。楽しそうなことに免じて、今回だけは許してやる！」\n海の怪物を模して造られたという滑り台。なかなかスリリング。",
  str_item_intro_5212002 = "いったい誰がここまでマストを運んできたのかは不明だが、上に登ると遠くまで見渡すことができる。「キャプテン！陸です！」と叫べば、大海原を航海している気分になれる。",
  str_item_intro_5212003 = "さらさらとした砂浜の上でもしっかりと立っていられるテント。軽くて扱いやすく、しかも防火素材で出来ている！テント内で火を起こすのを想定しての設計だろう。",
  str_item_intro_5212004 = "2人一緒に遊べるブランコ。海岸で遊ぶのに適しており、海から吹いてくる優しい風が顔をかすめれば、素敵な思い出をつくってくれる。",
  str_item_intro_5212005 = "廃棄された小型船の船体半分をそのまま使ったチェア。水夫たちの突飛なアイディアで造られたのだろう。",
  str_item_intro_5212006 = "ビーチでよく見る看板スタンド。看板にさまざまな絵や図を描くことができ、時には伝言板としても使える。さらにフラッグガーランドを付ければ、客の目を引くこと間違いなし。",
  str_item_intro_5212007 = "「廃品利用」の精神で水夫たちが小型船の船体半分を解体し、船板で作ったテーブルセット。キールは日よけ用のつる棚とし、おもむきある夏の雰囲気を存分にかもし出している。",
  str_item_intro_5212008 = "少し重量感のあるパラソル。移動に少々苦労する。支柱の先は砂浜にさしこみやすいようにとがっており、しっかりと固定することができる。",
  str_item_intro_5212009 = "身体に密着するよう設計されており、この上に横になると非常に気持ちがいい。手足も存分に伸ばすことができる。",
  str_item_intro_5212010 = "軽くて扱いやすいテーブル。自由に動かすことができ、客が自分たちで好きなところにこのテーブルを置き、皆で集まり素敵な一時を過ごすことができる。",
  str_item_intro_5212011 = "遊び疲れたら一休み！そんな時こそこれ。座って飲み物でも飲めば、すぐに元気いっぱいだ。",
  str_item_intro_5212012 = "海底にあった石柱とサンゴだろうか？いつの間に陸地に運ばれてきたのだろう？いや、よく見てみると、ペンキの塗られた非常によくできた木のフェンスだ。見た目が美しいだけでなく、海辺の雰囲気にピッタリだ。",
  str_item_intro_5212013 = "細かい砂を敷いて造られたタイル。まるで砂浜をそのまま移動させてきたかのようで、海辺の雰囲気をたっぷりと味わえる。",
  str_item_intro_5241018 = "大きな水槽の中にはミニチュアの石と水草が入っており、水を循環させる装置もついているので、魚たちはゆったりと自由に泳ぎまわることができる。",
  str_item_intro_5241019 = "カラフルなサンゴの置物。石が敷かれており、見る者はまるで海の中にいるような気分になる。魚の群れが行き過ぎる姿さえ見える気がする…",
  str_item_intro_5241020 = "不思議な古代の遺物の1種。周囲の光力を吸収して、害のない光線を発するという。装飾や照明に適しているほか、遠くへ信号を送ることもできる。",
  str_item_intro_5212014 = "なんと大きな貝殻だろう！大きすぎて天然のものとは思えない。もし中に真珠があったとしたら、きっと世にも珍しい逸品だろう。だが貝殻も無駄には出来ない。中にクッションを敷けば、この不思議なソファーの出来上がり。",
  str_item_intro_5212015 = "クラゲの形をしたバルーン。空に浮かべると、垂れ下がるリボンが「触手」となって、ゆらゆらと揺れる姿がまさに生きたクラゲ。違いは海を泳ぐか、空を泳ぐかだ。",
  str_item_intro_5212016 = "見た目に驚いてはいけない！道を明るく照らしてくれているのだから。ほら、口には歯がないでしょう？",
  str_item_intro_5212027 = "テーブルとセットで使うのに適している。高さを調節できるだけでなく座面が回転するので、子どもたちに大人気",
  str_item_intro_5212028 = "飾りつけには緑の植物が欠かせない。他の装飾品と合わせれば、さらに見映えがよくなる。何鉢か並べてみてもいいかもしれない",
  str_item_intro_5212029 = "祭りの際の区画割りに使うフェンス。きれいに塗装されているので、上に物を置いて飾りつけをするのもよさそうだ",
  str_item_intro_5212030 = "ウィンデリオンのためにわざわざ作った花畑。前もって植えておいたタンポポはすでに綿をつけ、祭りの夜に空を舞う時を待っている",
  str_item_intro_5212031 = "よくある木材で造ったシンプルな構造の街灯。要の箇所に補強を施してあるので、とても丈夫である。照明器具を取り付けるだけでなく、小動物たちが一休みする場所としても使える",
  str_item_intro_5212032 = "祭りの空気あふれる低柱。一列に並べればフェンスとしても使える",
  str_item_intro_5234034 = "石造りの外観で一見粗末に思えるが、中はかなり巧妙な造りになっており、容量も大きい。この箱を使えば、簡単にリサイクルができる",
  str_item_intro_5212020 = "道端に置いておくのにぴったりな小物ラック。通りかかったついでに小物を置くラックとしても、屋外装飾として飾り付けしてもよい",
  str_item_intro_5212021 = "一見大きくて厚い壁に見えるが板でできており、中は空洞になっている。とても軽いので、いろいろなところに運んで設置することができ、多くは祭りの補助的な装飾として使われる",
  str_item_intro_5212022 = "シンプルな枝状の木造物。内側から補強が施されているようで、たくさんの小動物が上に乗っても壊れない。人が寄りかかって休憩しても大丈夫。かも…？",
  str_item_intro_5212023 = "軽くてシンプルなランタンスタンド。特殊な構造になっており、たくさんのランタンを掛けることができる。照明にも、祭りの雰囲気づくりにもピッタリ",
  str_item_intro_5212024 = "木材と白い布で造ったアーチにツルや木の葉、花などを飾り付けたもの。さまざまな祭りや行事の際に使われる。アーチをくぐった時に風が吹き、白い布に体が触れたり花びらや木の葉が肩に落ちたりすると、幸運に恵まれるといわれている",
  str_item_intro_5212025 = "誰が最初にこの巣を作ったのかは知らないが、当時多くの小動物たちが巣に集まってきて、一緒ににぎやかな祭りを過ごしたという。それからというもの、祭りでは鳥の巣を作るのが伝統となった。集まった小動物が多いほど、より多くの祝福を受けられるという",
  str_item_intro_5212026 = "祭りの日に屋外に設置するテーブル。少し重いが、天板は天然木材でできており、さらにテーブルの脚には石が使われている。言い伝えによると、テーブルの上で踊っても壊れないよう、丈夫に造られたらしい",
  str_item_intro_5234021 = "屋内だけでなく、屋外でも使える棚。丈夫な木材でできており、雨風や日差しにさらされても問題ない。通常は使わない物を一時的に保管しておくのに使われる",
  str_item_intro_5212018 = "ウィンデリオンの祭りで飾られるファルベプッペ。中には色とりどりの紙やリボンが入っており、たたくとこぼれ落ちてくるので、子どもに大人気である。時には鈴や「ラッキーコイン」を入れることもあり、美しい音色やサプライズのごほうびに子どもたちは「興味津々」である",
  str_item_intro_5212019 = "人が上で踊れるほど大きなドラム。ドラムヘッドは薄い材質だが、とても丈夫でどんなに踊っても破れることはない。特別な構造をしているため、音が遠くまで響き、しかもドラムヘッドがドラマーのさまざまな微妙な動きを鋭くとらえ、変化に富んだ音色を奏でる",
  str_item_intro_5241021 = "イシマジロはかなり希少な動物である。伝説のイシマジロ一族とくれば、なおさらだ。さあ、急いでイシマジロ一族の一員になって、一緒に写真を撮ろう！",
  str_item_intro_1601881 = "鄴の国の郡主タンドウは人質となっても、とても落ち着いていた。済の国で勉学に専念しながら、故郷に帰る日を待ち続けていた。",
  str_item_intro_5212017 = "この石像が何かは分かっていないが、古代の遺物だといわれている。ウィンデリオンでは、多くの空の末裔がこの像の元にやってきて、祝福をささげたり、願い事をするという。キャンドルが空の末裔たちの心の声を石像に伝え、石像はその不思議な力で願い事をした人々を助けてくれるらしい",
  str_item_intro_5271001 = "非常に大きなプール。広い場所でないと設置できない。もちろん、このプールがあれば大勢で一緒に水遊びができる。",
  str_item_intro_5272001 = "通常プールの脇に置いておく小さな部屋。シャワーが付いているので身体を洗える。もちろん、もっと大事な――更衣室として使える。",
  str_item_intro_5272002 = "泳ぎ疲れたら、ひと休み。さらにこの不思議な機械が作るアイスを手に取れば、まさに至福の一時。",
  str_item_intro_5272003 = "音楽も欠かせない！水遊びに飽きたら、休憩時にはこのブースで音楽を聴いてリラックスしよう。音楽に合わせて踊るもよし！",
  str_item_intro_5272004 = "空気を入れて膨らませたソファー。横になるととても気持ちがいい。水に浮かべればボートにもなり、休憩にも水遊びにも最適のアイテムだ。",
  str_item_intro_5272005 = "エアクッションで出来たイス。とても軽く、持ち運びに便利なだけでなく、空気を抜けば、バッグの中にしまえるので場所もとらない。",
  str_item_intro_5272006 = "泳げない人に朗報！これを使えば金づちでも水に浮かび、ゆったり泳ぐこともできる。",
  str_item_intro_5272007 = "プールサイドでもプールの中でも使える。空気を入れると弾力が出て、地面をバウンドする。さらに重要なのは、水の中に落ちても沈まないことだ。",
  str_item_intro_5272008 = "泳ぐと体力を消耗する。必要に応じて横になり、体力を回復しよう。魚の形をしたクッションはとても気持ちがよく、ビーチの雰囲気にぴったりだ。",
  str_item_intro_5272009 = "このパラソルは大きく持ち運びに不便だが、日の光が直接肌に当たるのを防ぐためには十分価値がある。焼けるような日差しの中、貴重な日陰をもたらしてくれるのだ。",
  str_item_intro_5272010 = "さまざまな海の貝殻に装飾を加えて作ったもの。置く場所によっては、海岸さながらの雰囲気を作り出せる。",
  str_item_intro_5272011 = "ヒトデは海の星と呼ばれ、人気が高い。ヒトデの置物をいくつか置いただけでも、注目を集めること間違いなしだ。",
  str_item_intro_5272012 = "古代技術を用いて作られたと言われる看板。自動でさまざまな図案を表示できる！しかも、不思議な装置によって表示する情報を切り替えられる。何か思いもよらない使い道があるのかも…",
  str_item_intro_5271002 = "海をこよなく愛する空の末裔が設計したといわれている。彫像とのセットになっており、海の祝福を得られるという。海の旅に出かける際には、ここで少しの時間を過ごしてから出かければ、祝福を得られるかも",
  str_item_intro_5272013 = "海で彼女を見かけたら、その航行で大きな収穫が得られるといわれている。しかし、彼女らは実在するのだろうか？それとも、船乗りたちの幻にすぎないのだろうか？いずれにしても、この彫像はとても美しく、多くの若者たちが思わず足を止めて見入ってしまうのだ",
  str_item_intro_5272014 = "とある遠洋航海でのこと。道に迷ったタコたちが誤って船に乗り込み、帰れなくなってしまった。心優しい船乗りがタコたちを逃がしてやると、数日後、真珠や海に忘れられていったコインなどを、タコたちが贈り物として届けてくれるようになったという…。この彫像はそんな、友情と恩返しの気持ちを表している",
  str_item_intro_5272015 = "多くの人々の間で、航海中に海面を飛び跳ねるイルカを見かけたら、その航海は平安無事に終わるといわれている。イルカたちは、陸地を旅する者にも祝福を与えてくれるのだろうか？",
  str_item_intro_5271003 = "監督たちの自由な発想さえあれば、カメラアングルや道具の配置を利用してスリルも、夢のような美しさも、恐怖に満ちたシーンも生み出せる。書物の中の物語が、迫真の映像に早変わりだ",
  str_item_intro_5273001 = "ただの絵にすぎないのに、レンズの中では宮殿の迫力を存分に表現できる。宮廷ドラマの撮影にぴったり",
  str_item_intro_5273002 = "高価なタイルを思わせる床なのに、実は紙製！素早く交換したい撮影のニーズに合う。",
  str_item_intro_5273003 = "ただの小道具なのに、この「魔鏡」は重厚な鉄でできている…もちろん、表面のメッキや宝石は偽物。鏡には魔鏡らしい雰囲気があるのに、何も映し出さない。どうやって作られたのか…？まさか、本物の魔鏡？",
  str_item_intro_5273004 = "単なる小道具。もちろん、北境から取り寄せた本物のツリーであるはずがなく、普通の木に紙切れや飾りひもをくっつけただけ。北境の住民に贈ったりしないように！",
  str_item_intro_5273005 = "堅木のハンガーとは言うものの、実は低品質のベニヤ板製。本当に使うわけではないのだから、それっぽく見えれば十分だ",
  str_item_intro_5273006 = "中身は粘土、外側は白い細砂でできた人形。一見すると本物の雪のようだが、メリットはとけないこと！",
  str_item_intro_5273007 = "道具職人たちの手によって、木製の彫刻が本物同然の輝きを放っている。ポイントは軽くて持ち運びに便利なこと",
  str_item_intro_5273008 = "本物を洗って乾かした「小道具」。ところどころ古いのに、見る角度によっては新品に見える！？",
  str_item_intro_5273009 = "浮いてる！？この小道具…本物？本物かニセ物かはともかく、浮く理由はよく分からない。まあ、撮影にはぴったり？",
  str_item_intro_5273010 = "貼り付けた背景ボードでも恐怖を与えるのには十分。小道具職人の実力のたまもの？それともこの建物の真の力？あのホラー映画の悲鳴は演出じゃなかったのかも…",
  str_item_intro_5273011 = "恐怖の木造家屋の背景ボードに合わせたアイテム。敷き詰めると古く怪しい雰囲気が出て、ホラー映画にぴったり",
  str_item_intro_5273012 = "わざと古さを装った「古書」。中には文字が書いてある！リアルにするため、文字もレイアウトも挿絵も、表紙に至るまでそっくりに作られている。ほとんどコピーと言ってもいい。でも、書かれている内容は秘密！",
  str_item_intro_5273013 = "宙に浮く小道具、中には風船が入っているはず…飛んでいってしまわないように、下の部分は細い糸で台座に固定されている",
  str_item_intro_5273014 = "実際のおもちゃをそのまま使用している。新品と比べるとやや古い。本来はお祭りで子どもたちを楽しませるためのものだが、ホラー映画のセットの中では不気味さをかもし出している",
  str_item_intro_5273015 = "「墓石」も地面も、木の台や木片に紙を貼って作ったもので、とても軽い。手早くたくさん作れるというメリットがあり、撮影現場に置くだけで陰惨な墓地の雰囲気を手っ取り早く演出できる",
  str_item_intro_5273016 = "木と金属片で作られた受話器。もちろん通話はできない。ホラー映画にこういった受話器で会話をするシーンがあった場合、俳優2人が交代で使っているのかも…ご苦労様！",
  str_item_intro_5273017 = "お化けはホラー映画にぴったり、だがこの帽子からは…砂漠の風を感じる。もしかして、他とは違った映画ジャンルを追求している？",
  str_item_intro_5273018 = "鉢と土は本物だが、花はきっと偽物だろう。布を切って作ったようだ。安上がりで簡単、その上永遠に枯れない！",
  str_item_intro_5273019 = "これをセットするとお酒の香りが漂い、グラスを合わせる音や軽快な音楽まで聞こえてくるかのよう。こういった「酒場」で演じられる場面といえば？",
  str_item_intro_5273020 = "やや古びた床板、だいぶ年季が入っているようだ。きちんと敷き詰められていなくてもOK、酒場の床板なら穴ぐらいあるさ！",
  str_item_intro_5273021 = "最も高価な小道具のひとつか。本物なので、レコードを置けば音が鳴る！したがって、脚本家は絶対に「主人公がレコードプレイヤーを叩き壊す」シーンを書いてはならない。ある種のシーンは制限されるが、無料でスタジオ録音ができるので「一石二鳥」とも言える",
  str_item_intro_5273022 = "カウンターはベニヤ板だが、まあまあ頑丈。もちろん、本物の無垢材とは比べ物にならないが…。椅子はどこかのバーから買い受けた中古品、古いがペンキを塗り直したので新品同様",
  str_item_intro_5273023 = "酒場の雰囲気に合ったテーブルとイス。「酒場に置くべきもの」と思わせるスタイルと装飾により、これさえ置けば監督の指示がなくてもほとんどの俳優は酒場のシーンだと分かるはず",
  str_item_intro_5273024 = "ある監督が、奇妙なテーマの映画を撮るためにわざわざ借りてきたというデスクとチェア。むしろ職場のような雰囲気で、酒場っぽいかと言われると…？予算不足で無理やり使おうとしているようにも見える",
  str_item_intro_5273025 = "本物のピアノは重くて高価！だったら偽物で十分。どうせ新人俳優には弾けないし、1、2回演奏するふりをするだけなんだから！",
  str_item_intro_5273026 = "木の板で手早く作ったステージ。本物に比べると頑丈とは言えないが、人手もかからず、壊れても作り直せる",
  str_item_intro_5273027 = "木製の刀置きは本物だが、上の刀は…小道具に違いない。数回使うふりができれば大丈夫。本物の刃ではないので、戦闘シーンで手元が狂っても役者が大けがをすることはない",
  str_item_intro_5273028 = "陽の光が差し込む教室に机と椅子がきちんと並んでいる。チョークの匂いがどこからともなく漂ってくるようだ。窓際の後ろから二番目の席が、おそらくあなたの席だろう",
  str_item_intro_5273029 = "ごく一般的な木製の床板だが、特殊加工が施されているため、通常のものよりも耐用性が高い。室内履きに履き替えてから、歩くように。",
  str_item_intro_5273030 = "おかしな見た目をした調理器。同時にガチャガチャでもある。出てきたものを開けるまで、中に何が入っているか分からない",
  str_item_intro_5273031 = "不思議な調理器。油で揚げるよりも料理が`ヘルシーに仕上がり、初心者でも上手に使いこなせるという",
  str_item_intro_5273032 = "ぶくぶくと泡が湧きたつ鍋は、かき混ぜ続けなければ材料を十分に混ぜ合わせることはできない。そんな作業をする美少女に、見とれない者はいるだろうか？",
  str_item_intro_5273033 = "謎の液体の入ったたる。中からはかすかに、何やら怪しい香りが漂っている…",
  str_item_intro_5273034 = "昼夜を問わず、休みなく食べ物と飲み物を供給してくれる機械。怠け者にとって、これ以上うれしいものはない",
  str_item_intro_5273035 = "腕が良くなければ、音を鳴らない。しかし、夜になると誰が叩かなくとも、音を奏で続けるという…",
  str_item_intro_5273036 = "ただの小道具。決して食べないように！",
  str_item_intro_5273037 = "まるで街中のような雰囲気の宿屋。宿の中ではせわしなく声が響き、さまざまな人が行きかう。どのような人物がいて、何が起こっているのか、誰にも分からない",
  str_item_intro_5273038 = "木製の床板。歩くとギイギイ音がする",
  str_item_intro_5273039 = "宿屋の勘定台。店主はいつでも帳場に座っている。もし、一人旅でさみしさを感じたときは、店主とおしゃべりするのもよいだろう",
  str_item_intro_5273040 = "こだわりの光る磁器。店主の飾りつけに、趣味の良さがうかがえる",
  str_item_intro_5273041 = "おかしな置物。どこぞの客から贈られたものかもしれない",
  str_item_intro_5273042 = "魚の骨の標本。その大きさから見て、きっと狂暴な魚だったのだろう",
  str_item_intro_5273043 = "簡単な造りの木製家具。気性の荒い客が来た場合、最初に被害にあう家具であるため、高価なものを置くのは避けている",
  str_item_intro_5273044 = "なじみあるテーブルと椅子。座れば、家に帰った気分になれる",
  str_item_intro_5273045 = "家具。見るからに暖かそうである。冬にはここで1日中横になれば、どんなに気持ちいいだろう",
  str_item_intro_5273046 = "店主が造った美酒。蓋を開けると芳純な香りが漂う。その香りに包まれ、果たされなかった思いに失意の涙を落とす者も多い",
  str_item_intro_5273047 = "どこの土産物か分からないが、店内に異国情緒を添え、訪れた人々の想像をかき立てる。年老いた店主と異国の聖杯との間に、いったいどのような物語が秘められているのだろうか？",
  str_item_intro_5273049 = "カサカサと乾いた音を立てる風、四方から聞こえるカラスの鳴き声。寒々しい空気の中、独り進む勇ましい武士は険しい道を歩まねばならぬ宿命なのだ",
  str_item_intro_5273050 = "乱世には、こうした無名の地がたくさん存在する。ひそかに先へと進むならば、足元の枯れ葉に注意し、自身の気配を悟られてはいけない",
  str_item_intro_5273051 = "どう見てもごく普通の棚だが、ひとたびからくりを解けば、中から名高き刀剣が飛び出してくる。必ず詳しい者に教わりながら操作するように",
  str_item_intro_5273052 = "ススキが描かれた装飾ボード。セット内に設置すれば、思わず馬に乗って野を駆け巡りたくなる",
  str_item_intro_5273053 = "麦畑の装飾ボード。セット内に設置すれば、いかにもどこかに武士が隠れていそうな空気になる",
  str_item_intro_5273054 = "ヒマワリが描かれた装飾ボード。セット内に設置すれば、太陽の光さえ集まってくる気がする",
  str_item_intro_5273055 = "どこからもたらされたのか不明の謎の映写機。下に引かれた布も年季が入っていて、テープをセットすれば、何か大事な情報を得られる気がする",
  str_item_intro_5273056 = "どこからもたらされたのか謎の地図。戦乱の頃に使われた軍事地図らしく、何やら重要な情報が記載されているようだ",
  str_item_intro_5273057 = "どこからもたらされたのか不明の謎の郵便ポスト。いつからあるのか誰も知らない。ポスト表面のすり傷をよく見てみると、昔誰かが残していった情報のようなものがある",
  str_item_intro_5234040 = "抜け目のないR・Wの商人ジョムは、こんな所にも広告を出すことを忘れていなかった。「R・Wグルメフェスタ」に人を呼んでいるらしい。おトクな品がたくさんあると書かれているが、そこには砂漠しかない。何か怪しい食べ物でも出てくるのでは…？",
  str_item_intro_5234041 = "「史上最年少、天才美少女プロデューサー兼監督兼主演兼カメラマンによるセンセーショナルなデビュー作」の映画宣伝。ホラーだがコミカルな作品のようだということが、広告からも見て取れる。チケットの売れ行きはどうか？楽しみに待つしかない",
  str_item_intro_5234042 = "啓光連邦の募集看板。啓光ならではの気迫がある。「我らと共に暗鬼と戦う最強で最後の防衛線になろう」というキャッチコピーはとても力強く、大勢の心に響いているようだ",
  str_item_intro_5234031 = "頭のてっぺんに針の生えた動物で、肌はざらざらしているように見える。幸い、これは彫刻だが…",
  str_item_intro_5234032 = "長い角が生えているが、見たところ大人しそうだ…なんだか、なでてみたくなる。",
  str_item_intro_5241014 = "これが巨像！？どうしてこんなに太ってしまったんだ！？とはいえ、飛べることに変わりはない。人を乗せて空高く飛び、空中散歩を楽しめる。",
  str_item_intro_5232007 = "なんと不思議な技術だろう？原理は不明だが、これに座ると宙に浮くことができ、しかも自動でバランスを取ってくれる。怖がることはない、ぜひ試してみよう。",
  str_item_intro_5234035 = "この古代の記念碑に刻まれた紋様には整然とした規則性があり、不思議な図案を描き出している。数学の原理を表しているというが、具体的なことは分からない。",
  str_item_intro_5222001 = "よく生長する灌木（かんぼく）を並べて植え、さらに手を入れて造った生けがき。装飾効果だけでなく、空間の区分けにもなる。",
  str_item_intro_5222002 = "背が高めの灌木（かんぼく）を集めて植えた生けがき。通常は庭の外壁として使われるが、たくさん植えて、迷路を造る所もあるらしい。",
  str_item_condition_103 = "「π号シェルター」の上層で獲得",
