  str_item_use_3000299 = "映画の脚本。獲得すると天空ノ庭の撮影セットで撮影できる",
  str_item_3661026 = "祝日の鶏のごちそう",
  str_item_intro_3661026 = "家具。巨像のルーム内に設置できる。\n祝日にはごちそうがつきもの。この鶏料理は見た目も味も、祝日のメインディッシュにピッタリ。さあ、味わってみよう！",
  str_item_3661181 = "巨像の掛け時計",
  str_item_intro_3661181 = "家具。巨像のルーム内に設置できる。\nもともとはフクロウの形をした掛け時計だったが、商人たちがあまりにも平凡だと感じたため、巨像の形になったという…。ヘンテコなようだが、なかなかにいいデザインだ。ただ、残念なことに翼は動かない",
  str_item_3661182 = "スプーンナイト",
  str_item_intro_3661182 = "家具。巨像のルーム内に設置できる。\nさあ、このスプーンを食らえ！スプーンナイトは大食いでよく知られている。大きなお腹を見れば一目瞭然、よろいも特注しなければならないほどだ。口からヨダレを垂らしているが、またどこかの食卓に目をつけたのだろうか？",
  str_item_3661027 = "ゴルディ応援ボード",
  str_item_intro_3661027 = "家具。巨像のルーム内に設置できる。\nさあ、一緒に応援しよう！ゴルディの歌声を大陸の隅々まで届けるんだ！",
  str_item_3000289 = "異能EXP",
  str_item_3000290 = "異能ポイント",
  str_item_3661183 = "巨像用DJブース",
  str_item_intro_3661183 = "家具。巨像のルーム内に設置できる。\nスピーカーつきのDJブース。さまざまなボタン操作で無限の音のバリエーションを楽しむことができる。さらにリズムを変化させれば、DJ1人でも場を盛り上げ、人々を音楽の熱狂へといざなうことができる",
  str_item_3661184 = "アイドルのポスター",
  str_item_intro_3661184 = "家具。巨像のルーム内に設置できる。\n頑張れば、誰でも彼女のようになれる！あきらめずに夢へと向かい、ステージの上から大陸全土に愛と希望を届けよう",
  str_item_3661185 = "ツアードッグのフィギュア",
  str_item_intro_3661185 = "家具。巨像のルーム内に設置できる。\nつねに影ノ街の流行の最先端！フィギュアでありながら、ツアードッグのセンスが存分に光る立ち姿をしている。ファンの間ではとても人気があるらしい。誰かに盗られてしまわないよう、気を付けよう",
  str_item_3661186 = "衝撃の勇士",
  str_item_intro_3661186 = "家具。巨像のルーム内に設置できる。\n力強い音を発する楽器。弱い者はその衝撃で倒れてしまうほどの非常に力強い音を発するため、最も勇敢な者しか演奏しようとしないらしい。「少々」騒がしいが、人の波がごった返すコンサート会場にはもってこいの楽器だ",
  str_item_5259309 = "潜在能力ペンダント",
  str_item_5259310 = "降呪の石",
  str_item_5259311 = "謎のロックボックス",
  str_item_5259410 = "カオスブレード",
  str_item_5259411 = "狂戦の手甲",
  str_item_5259412 = "絆の彫像",
  str_item_5259505 = "チャージベルト",
  str_item_5259506 = "狂戦の魂",
  str_item_5259507 = "御光の大剣",
  str_item_5259513 = "狂戦の鎧",
  str_item_5259514 = "戦いの女神像",
  str_item_intro_5259301 = "連鎖が15マス以上に達した場合、連鎖技ダメージが増加する",
  str_item_intro_5259302 = "ダメージ計算時、味方は不利な属性の影響を受けない",
  str_item_intro_5259303 = "敵に毒/火傷/出血を付与したとき、ただちに追加ダメージを与える",
  str_item_intro_5259304 = "味方の最大HPが戦闘終了まで上昇する",
  str_item_intro_5259305 = "HPが半分未満まで低下するごとに、フィールド上にHP回復アイテムを出現させる",
  str_item_intro_5259306 = "各ウェーブ開始時にHPが回復する",
  str_item_intro_5259307 = "各ウェーブ開始時にシールドを獲得する",
  str_item_intro_5259308 = "毎ターン、近くのボス以外の敵に大ダメージを与える",
  str_item_intro_5259309 = "空の末裔の特殊装備の効果CD-1",
  str_item_intro_5259310 = "毎ターン、敵味方全体が一定比率でHPを失う",
  str_item_intro_5259311 = "空の末裔の特殊装備をランダムで1つ追加獲得する",
  str_item_intro_5259401 = "デバフ状態の敵の被ダメージが増加する",
  str_item_intro_5259402 = "光霊の余った回復量を一定比率でシールドに変換する",
  str_item_intro_5259403 = "敵撃破時にフィールド上の敵味方が毒状態になる。\n味方が受ける毒ダメージが減少する",
  str_item_intro_5259404 = "状態異常のとき、連鎖技のダメージが増加する",
  str_item_intro_5259405 = "極めて低い確率でボス以外の敵を瞬殺する",
  str_item_intro_5259406 = "能動技で敵を撃破したとき、味方がHPを回復する",
  str_item_intro_5259407 = "HP最大時、味方の全ダメージが増加する",
  str_item_intro_5259408 = "敵の毒ダメージが発動したとき、味方がHPを回復する。\n味方が受ける毒ダメージが減少する",
  str_item_intro_5259409 = "敵が味方にダメージを与えたとき、相手にカウンターダメージを与える",
  str_item_intro_5259410 = "チーム内に3種類以上の異なるメイン属性の光霊がいるとき、味方の与ダメージが増加する",
  str_item_intro_5259411 = "光霊のサブ属性でダメージを与えるとき、ダメージが減少しなくなる",
  str_item_intro_5259412 = "隊長変更回数+5。\nそのターンで初めて隊長になった光霊の能動技CD-1",
  str_item_intro_5259501 = "隊長が連鎖の開始地点で追加の連鎖技を放つ",
  str_item_intro_5259502 = "通常攻撃5回ごとに爆発効果を発動する",
  str_item_intro_5259503 = "毎ターン、周囲1マスに少数の万色マスを発生させる",
  str_item_intro_5259504 = "HP10%未満の敵を瞬殺する",
  str_item_intro_5259505 = "その場で待機したとき、能動技のCDを加速する",
  str_item_intro_5259506 = "味方光霊の防御力をすべて光霊の攻撃力に変換する",
  str_item_intro_5259507 = "連鎖の最初のマスとその後の色が異なっていた場合、その両方の色を攻撃時の属性として見なす",
  str_item_intro_5259508 = "森属性のマスを万色マスと見なす",
  str_item_intro_5259509 = "水属性のマスを万色マスと見なす",
  str_item_intro_5259510 = "火属性のマスを万色マスと見なす",
  str_item_intro_5259511 = "雷属性のマスを万色マスと見なす",
  str_item_intro_5259512 = "味方の与ダメージが大幅に増加するが、毎回の連鎖で損傷マスが出現する",
  str_item_intro_5259513 = "味方のHPが低くなるほど、連鎖技のダメージが大きくなる",
  str_item_intro_5259514 = "隊長変更回数+5。\nこのターン中隊長になったことのある光霊は、連鎖が何色でもメイン属性として行動できる",
  str_item_rpintro_5259301 = "味方の連鎖が15マス以上に達したとき、連鎖技のダメージ+30%",
  str_item_rpintro_5259302 = "味方がダメージを与えたとき、不利な属性によるダメージ減少効果を無視する。また、味方がダメージを受けたとき、不利な属性によるダメージ増加効果を無視する",
  str_item_rpintro_5259303 = "敵に対して毒/火傷/出血状態を付与したとき、ターゲットはただちに自身の攻撃力の50%相当のHPを失う。毎ターン1ターゲットにつき、発動は1回まで",
  str_item_rpintro_5259304 = "チーム内の光霊の最大HP+100%。ただし、現在のHPは変わらない",
  str_item_rpintro_5259305 = "味方の残りHPが50%以下に減少するごとに、フィールド上のランダムな位置に包帯を1個生成する。味方が包帯を通過すると最大HPの20%を回復する",
  str_item_rpintro_5259306 = "各ウェーブ開始時に最大HPの20%を回復する",
  str_item_rpintro_5259307 = "各ウェーブ開始時に最大HPの40%のシールドを獲得する。1ターン持続",
  str_item_rpintro_5259308 = "各ターン開始時に周囲1マスのボス以外の敵に対して、最大HPの50%のダメージを与える",
  str_item_rpintro_5259309 = "以降の戦闘で、空の末裔の特殊装備のCD-1",
  str_item_rpintro_5259310 = "毎ターン開始時、フィールド上の敵味方すべてが現在のHPの7%を失う（ボスを含む）",
  str_item_rpintro_5259311 = "異なる空の末裔の特殊装備をランダムで1つ獲得し、以降の戦闘中で使用できる。CDは個別に計算する",
  str_item_rpintro_5259401 = "敵が状態異常、または弱体化効果を保有しているとき、すべての被ダメージ+20%",
  str_item_rpintro_5259402 = "光霊の余った回復量の100%をシールドに変換する。1ターン持続",
  str_item_rpintro_5259403 = "敵を撃破するごとに、フィールド上の敵味方すべてに毒を1スタック付与する。味方の受ける毒ダメージ-50%",
  str_item_rpintro_5259404 = "味方チームが状態異常のとき、連鎖技の与ダメージ+30%",
  str_item_rpintro_5259405 = "ボス以外の敵が何らかのダメージを受けたとき、3%の確率でただちに撃破する",
  str_item_rpintro_5259406 = "能動技で敵を撃破するごとに、味方が技の使用者の最大HPの15%相当を回復する",
  str_item_rpintro_5259407 = "味方チームの現在のHPが最大の場合、すべての与ダメージ+20%",
  str_item_rpintro_5259408 = "敵が毒ダメージを受けるごとに、味方が毒ダメージの100%相当のHPを回復する。味方の受ける毒ダメージ-50%",
  str_item_rpintro_5259409 = "敵が味方にダメージを与えたとき、味方の被ダメージの100%相当のカウンターダメージを与える",
  str_item_rpintro_5259410 = "チーム内に3種類以上の異なるメイン属性の光霊がいる場合、味方のすべての与ダメージ+25%",
  str_item_rpintro_5259411 = "光霊がサブ属性でダメージを与えたとき、メイン属性と同じ倍率になる",
  str_item_rpintro_5259412 = "獲得時、隊長変更回数+5。\n隊長変更時、新しい隊長の能動技の残りCD-1。各光霊は1ターンに1回のみ発動可",
  str_item_rpintro_5259501 = "隊長の光霊が連鎖の開始位置に虚像を1体生成し、このターン中、同時に連鎖技を放つ",
  str_item_rpintro_5259502 = "通常攻撃のコンボ数が5の倍数になったとき、敵に爆発効果を1回与える",
  str_item_rpintro_5259503 = "毎ターン開始時、周囲1マス内の3マスを万色マスに変える",
  str_item_rpintro_5259504 = "残りHPが10%未満の敵をただちに撃破する",
  str_item_rpintro_5259505 = "このターンで連鎖移動をしない場合、すべてのCD中の光霊の能動技の残りCD-1",
  str_item_rpintro_5259506 = "味方チーム内の各光霊の防御力が0になり、低下した防御力の分だけ自身の攻撃力が上昇する",
  str_item_rpintro_5259507 = "連鎖の最初のマスとその後の色が異なっていた場合、その両方の色を攻撃時の属性として見なす",
  str_item_rpintro_5259508 = "他の色で連鎖を開始する場合、森属性のマスにも繋げられる",
  str_item_rpintro_5259509 = "他の色で連鎖を開始する場合、水属性のマスにも繋げられる",
  str_item_rpintro_5259510 = "他の色で連鎖を開始する場合、火属性のマスにも繋げられる",
  str_item_rpintro_5259511 = "他の色で連鎖を開始する場合、雷属性のマスにも繋げられる",
  str_item_rpintro_5259512 = "味方のすべての与ダメージ+25%。ただし、連鎖するごとに開始地点は5ターンの間、進入不可能な損傷マスになる",
  str_item_rpintro_5259513 = "味方が失っているHPの比率にもとづき、連鎖技のダメージが増加する。最大で+80%",
  str_item_rpintro_5259514 = "隊長変更回数+5。\nこのターン中隊長になったことのある光霊は、連鎖が何色でもメイン属性として行動できる",
  str_item_intro_9994027 = "チーム内に3種類以上の異なるメイン属性の光霊がいる場合、味方のすべての与ダメージ+25%",
  str_item_intro_9994028 = "光霊のサブ属性でダメージを与えるとき、ダメージが減少しなくなる",
  str_item_intro_9994029 = "隊長変更回数+3。\nそのターンで初めて隊長になった光霊の能動技CDターン-1",
  str_item_intro_9995019 = "その場でダブルタップして移動しない場合、能動技CD-1",
  str_item_intro_9995020 = "味方チーム内の各光霊の防御力が50%まで下がり、低下した防御力の分だけ自身の攻撃力が上昇する",
  str_item_intro_9995021 = "味方が失っているHPの比率にもとづき、連鎖技のダメージが増加する。最大で+80%",
  str_item_intro_9995022 = "隊長変更回数+3。\nこのターン中隊長になったことのある光霊は、連鎖が何色でもメイン属性として行動できる",
  str_item_rpintro_9994027 = "光力を完璧に融合できると思われる武器…まさに希少な逸品",
  str_item_rpintro_9994028 = "古代の戦士が利き手ではない手の力を十分に発揮できずに敗れた後、この手甲を作り、その後の戦いで無敵を誇ったと言われている",
  str_item_rpintro_9994029 = "手は心をつなぐことができる。握られた両手はお互いの心が通い合い、永遠に離れないことの象徴",
  str_item_rpintro_9995019 = "強力な光力術を高速で発動し、あらゆる危険な状況への対応を可能にするパワーを宿した古代の遺物",
  str_item_rpintro_9995020 = "昔から「剣を振るう者は剣で命を失う」と言われるが、これを使えば最強の敵でも倒すことが可能。ただし、捨て身の攻撃が必要",
  str_item_rpintro_9995021 = "この鎧は絶大で恐ろしい力を持っていると伝わる。ある者は秘宝と見なし、別の者は呪いと見なす",
  str_item_rpintro_9995022 = "この像は神ではなく、戦いを助ける伝説の女戦士の彫刻だとの説がある",
  str_item_3661187 = "龍州の福結び",
  str_item_intro_3661187 = "家具。巨像のルーム内に設置できる。\n1本のひもで精巧に正方形の文様が編まれており、作り手の豊かな発想力がうかがえる。龍州大陸から伝わった飾りで、家の中に飾っておくと平安無事を守ってくれるという",
  str_item_3661188 = "龍州の提灯掛け",
  str_item_intro_3661188 = "家具。巨像のルーム内に設置できる。\n龍州大陸から伝わった提灯掛け。木製で独特の造りをしており、赤い提灯をかけると瞬時に別世界に行ったような気分になれる",
  str_item_3661028 = "銀河と月の照明板",
  str_item_intro_3661028 = "家具。巨像のルーム内に設置できる。\nさまざまな形の照明をつなげて造られた装飾板。点灯すると、まるで銀河のような光を放つ。壁にかけて観賞するもよし、外の木に掛けて曇り空でも星空の下にいるかのような気分を味わうのもよいだろう",
  str_item_3010001 = "召集星標（期間限定）",
