  str_item_intro_3030019 = "見た目は正方形の水晶の箱。中心が光を放っており、プリズムに比較的多くのエネルギーを供給できる\n使用すると60プリズム獲得できる\n本アイテムは期間限定アイテムです。有効期限が過ぎるとアイテムは消失します。期限までにお使いください\n有効期限：2024年4月30日13:00",
