  str_item_intro_3010028 = "召集シグナルの発信に使う専用装置。光霊の注意を引き寄せ、召集シグナルに応じた光霊が仲間になってくれる\n本アイテムは期間限定アイテムです。有効期限が過ぎるとアイテムは消失します。期限までにお使いください\n有効期限：2024年11月27日13:00",
  str_item_intro_3020028 = "特殊なパターンのシグナルの発信に使う専用装置。光霊の注意を引き寄せることができる\n本アイテムは期間限定アイテムです。有効期限が過ぎるとアイテムは消失します。期限までにお使いください\n有効期限：2024年11月27日13:00",
  str_item_intro_3030028 = "見た目は正方形の水晶の箱。中心が光を放っており、プリズムに比較的多くのエネルギーを供給できる\n使用すると60プリズムを獲得できる\n本アイテムは期間限定アイテムです。有効期限が過ぎるとアイテムは消失します。期限までにお使いください\n有効期限：2024年11月27日13:00",
  str_item_3000301 = "食材パック",
  str_item_intro_3000301 = "調理に使うことができる\n食材の入ったパック。中にはさまざまな種類の食材が入っている",
  str_item_3000302 = "色鮮やかな羽根",
  str_item_intro_3000302 = "謎の鳥が残した羽。色鮮やかで、あるクーリエ隊メンバーが好きそうなので、何かと交換してもらえるかもしれない",
  str_item_3661189 = "バラのキャンドル",
  str_item_intro_3661189 = "家具。巨像のルーム内に設置できる。\n花は枯れることなく、明かりは消えることがない。この一瞬の美しさと思い出を永遠に心にとどめておこう",
  str_item_3661190 = "心のポスト",
  str_item_intro_3661190 = "家具。巨像のルーム内に設置できる。\n誰しも他人には話せない秘密や物事を抱えている。このポストはそんな時、とても頼りになる存在だ。根気強く、信頼性の高いポストになら何でも話せるだろう",
  str_item_3661191 = "愛を伝えるクマ",
  str_item_intro_3661191 = "家具。巨像のルーム内に設置できる。\n誰がこんなに可愛いクマさんを嫌いになれるだろうか？ましてや「ハート」をもったクマさんだ。もし誰かがこれを贈ったら、その送り主の気持ちは言わずとも明らかだろう",
  str_item_3661192 = "告白のバラ",
  str_item_intro_3661192 = "家具。巨像のルーム内に設置できる。\n赤と白の花が表すのは熱い思いと純粋な心。この花束を誰かに渡す時、気持ちはもう伝わっている",
  str_item_3661029 = "幸せのソファー",
  str_item_intro_3661029 = "家具。巨像のルーム内に設置できる。\n大きく座り心地のよいソファーは2人で仲良く寝転ぶのにもっていこいだ。しかし、たとえ1人でも問題はない。柔らかいクッションに包まれる心地は、まるで誰かが傍にいてくれるようだ…",
  str_item_3661193 = "純白の翼",
  str_item_intro_3661193 = "家具。巨像のルーム内に設置できる\n一部の天使は恋愛の守護神になるとのこと。この白い翼を壁に飾ればすぐに恋人が現れるかも～",
  str_item_3661194 = "スワンのケーキタワー",
  str_item_intro_3661194 = "家具。巨像のルーム内に設置できる\n美しい白鳥が飾られたケーキタワー。もはや芸術品…惜しくて食べられないかも？",
  str_item_3661030 = "スターバルーン",
  str_item_intro_3661030 = "家具。巨像のルーム内に設置できる\nテーマパークがお似合いだけど、室内に飾るとまた別の趣がある。でも繋いでおかないとフワフワと移動しちゃう",
  str_item_3000308 = "証拠回収記録",
  str_item_intro_3000308 = "犯人の一部の「特徴」を記した記録。これを使って真相を解き明かせるのだろうか…",
  str_item_3661195 = "レトロなレコードプレイヤー",
  str_item_intro_3661195 = "家具。巨像のルーム内に設置できる。\nこれぞレコードプレイヤーといったデザインのプレイヤー。数十年前影ノ街で大流行し、豊かな商人たちがこぞって所有したという。当時の腕のいい職人が作ったか、かなりのこだわりをもって作られたものらしく、音色も装飾も美しく、当時を懐かしむ人々をあの時代の音楽と時間の中に浸らせてくれる。",
  str_item_3661196 = "手がかり相関図",
  str_item_intro_3661196 = "家具。巨像のルーム内に設置できる。\n分析した事件の状況や考えを書き出すだけでなく、重要な手がかりや証人・証拠の写真、各方面から集めた情報を張り出し、その関連性を分析、整理し、考え方をまとめて、一刻も早く真相と真犯人を突き止めるのに便利。",
  str_item_3661197 = "資料の置かれたティーテーブル",
  str_item_intro_3661197 = "家具。巨像のルーム内に設置できる。\n本来はアフタヌーンティーやトランプを楽しむティーテーブルだが、今は事件捜査に関連する資料が積み上げられている。傍らにはルーペとパイプ、ランプが置かれていることから、どうやら、ここの主は名探偵のようだ。少なくとも「探偵愛好者」であることは間違いない。",
  str_item_3661198 = "探偵の帽子掛け",
  str_item_intro_3661198 = "家具。巨像のルーム内に設置できる。\n調査に出かけるなら、それ相応の身なりを整えなければならない。コートは夜の寒さ対策になるだけでなく、ノートやルーペ、小型の武器など調査に必要な様々な道具もおさめることができる。そして、風を防ぐ帽子は…より探偵らしい雰囲気を醸しだしてくれる。",
  str_item_3661031 = "推理のソファー",
  str_item_intro_3661031 = "家具。巨像のルーム内に設置できる。\n一部の探偵はソファーに座るだけで、他の者が集めた様々な手がかりから、事件の真相を突き止められるという。どうやら、このソファーはひと休みするのに適しているだけでなく、頭の回転も良くしてくれるようだ。",
  str_item_3661199 = "パイプラック",
  str_item_intro_3661199 = "家具。巨像のルーム内に設置できる。\n一面にパイプが掛けられたラック。タバコの匂いは好かないが、様々な変わったデザインのパイプには収蔵価値がある。",
  str_item_3661200 = "三脚付き望遠鏡",
  str_item_intro_3661200 = "家具。巨像のルーム内に設置できる。\n遠くの景色を一望できること――それが望遠鏡の役割だ。この望遠鏡はとても良いレンズを使っており、遠くがはっきりと見えるが、金属でできた鏡筒は少々重く、専用の三脚で安定させないと、じっくりと遠くを眺めることができない。",
  str_item_3661032 = "頑丈な金庫",
  str_item_intro_3661032 = "家具。巨像のルーム内に設置できる。\n「これはアストラ大陸で最も安全で丈夫な『モノ』の監獄です」――商人たちはこの金庫をそう説明する。確かに大きなハンドルはいかにも丈夫そうで、見るからに重たそうな筐体は何をしても壊れなさそうだ。",
  str_item_3661033 = "優勝者へ贈る栄光のアヒル",
  str_item_intro_3661033 = "家具。巨像のルーム内に設置できる。\nガルーが精魂こめてデザインしたオモチャのアヒル。ゲーム優勝者に贈られる。可愛い見た目だけでなく、金色に光輝く姿はまさに優勝という栄光そのものだ。",
  str_item_3661207 = "秩序と貴さのじゅうたん",
  str_item_intro_3661207 = "家具。巨像のルーム内に設置できる。\n雲の上に浮かぶ都市、空中の不落の都はアストラ大陸の文明の光そのものだ。このじゅうたんはその身分と地位だけではなく、秩序と礼節も表している。",
  str_item_3661208 = "不落の文明の旗",
  str_item_intro_3661208 = "家具。巨像のルーム内に設置できる。\n「最後の不落の都」の象徴として、この旗が大陸にはためく時、白夜城の文明の光はこの地を照らし、輝かせる。",
  str_item_3661201 = "賛歌のハープ",
  str_item_intro_3661201 = "家具。巨像のルーム内に設置できる。\n白夜城で盛大な式典を催す時にのみ使われるハープ。特殊な光力術で守られているため、永遠に音が狂うことはない。このハープで賛歌を演奏できるのは最も優れた楽師だけだ。",
  str_item_3661202 = "光と影の砂時計",
  str_item_intro_3661202 = "家具。巨像のルーム内に設置できる。\n「光と夜が入れ替わる時こそ正確な時を刻める」。この砂時計にはアストラ大陸で最も目の細かい砂が使われており、さらに特殊な光力術で調整を行うため、最も正確な時計と言われている。",
  str_item_3661203 = "雲の上の泉",
  str_item_intro_3661203 = "家具。巨像のルーム内に設置できる。\n雲の上の庭園で水の流れる音が聞こえる…驚くことはない。その音は白夜城の噴水から聞こえてくるのだ。不思議な光力術で守られ、水がどこからともなく湧いてくる。その水が一段一段と流れ落ちる姿は、空の上に暮らす人々に水が上から下へとあふれ出る美しい光景を見せてくれる。",
  str_item_3661204 = "最後の砦",
  str_item_intro_3661204 = "家具。巨像のルーム内に設置できる。\n永久不落の都、白夜城は文明の最後の防衛線だ。この剣と盾は最後の防衛線白夜城の最後の頼みの綱である。最後まで決してあきらめることなく戦う意志と責任、勇気の象徴なのだ。",
  str_item_3661034 = "昔日の水晶玉",
  str_item_intro_3661034 = "家具。巨像のルーム内に設置できる。\nさっと視線を向けただけでは、逆さになった自分の姿しか見えないが、じっと中を見つめると、あの日の光景が浮かび上がり、懐かしい響きが目の前で反響する。それをつかもうとするならば、水晶の中へと沈んでいかなければならない…",
  str_item_3000325 = "霊犀の珠",
  str_item_intro_3000325 = "この珠は世界の「涙」と呼ばれ、「あの日」にだけ得ることが出来ると言われているが…その中にはこの世界の真相が秘められているのかもしれない。\n用途：【追憶の間】で追憶する\n獲得方法：プリズムを消費するメインストーリーまたは資源ステージをクリアする",
  str_item_3661205 = "吊り下げ式ダブル燭台",
  str_item_intro_3661205 = "家具。巨像のルーム内に設置できる。\n「暗闇の中にいても光を放ち、人々が道を見つけられるようにする」この燭台には白夜城の特殊な光力術が施されており、フックがなくても自動的に壁に貼り付く。しかも風が吹いてもロウソクの火が消えにくい",
  str_item_3661206 = "ローズベース",
  str_item_intro_3661206 = "家具。巨像のルーム内に設置できる。\n白夜城貴族が使用する巨大な花瓶。優雅なデザインで有名。この花瓶1つで庶民が数年豊かに暮らせるほど高価。しかし、上流階級の屋敷では、ありふれたインテリアにすぎない",
  str_item_3661035 = "セレモニアルドレス",
  str_item_intro_3661035 = "家具。巨像のルーム内に設置できる。\n礼儀を最も重視する白夜城でも、このドレスは式典、祝祭、貴族の舞踏会など、どのような華やかな場にも着て行ける。着ている者の容姿が優れていれば、人々の注目の的となるだろう",
  str_item_3661209 = "リゾート村のビーチパラソルとチェア",
  str_item_intro_3661209 = "家具。巨像のルーム内に設置できる。\nリゾート地には、日差しを遮りながらひと休みできる道具が欠かせない。2つのどちらが欠けても、休日の雰囲気は味わえない",
  str_item_3661210 = "遊園地の広告看板",
  str_item_intro_3661210 = "家具。巨像のルーム内に設置できる。\nどの遊園地にも欠かせない巨大で派手な看板は、色とりどりの図柄で人の目を引き付ける。まるで「早くおいでよ！チャンスを逃しちゃダメ！」とでも言っているかのようだ",
  str_item_3661211 = "リゾートのアイスクリームカー",
  str_item_intro_3661211 = "家具。巨像のルーム内に設置できる。\n炎天下の夏の日に冷たいスイーツを提供してくれるキッチンカー。遊園地のエイドステーションのような存在で、いつでも多くの子どもたちがその周りを取り囲んでいる",
  str_item_3661212 = "リゾートのスプリング木馬",
  str_item_intro_3661212 = "家具。巨像のルーム内に設置できる。\n子どもたちに大人気の遊具。バネがついているため、乗ると揺れて振動し、あちこちから子どもたちの叫び声が聞こえてくる",
  str_item_3661213 = "オアシスのモーターボート",
  str_item_intro_3661213 = "家具。巨像のルーム内に設置できる。\n砂漠でも水上レースが楽しめるとは誰が想像しただろう！それもこれもオアシスの豊かな水流のおかげだ。これでモーターボートもガラクタになることなく、大いに力を発揮する場ができた",
  str_item_3661214 = "砂漠のサボテンの鉢植え",
  str_item_intro_3661214 = "家具。巨像のルーム内に設置できる。\n砂漠では最もよく目にする植物。乾燥にきわめて強いため、強靭さの象徴として鉢に植え替え、家で鑑賞する人もいる。ただし、水をやりすぎないように注意しよう。さもないと枯れてしまう",
  str_item_level_2905111 = "エネルギーマス",
  str_item_10000100 = "水属性光霊選択ボックス",
  str_item_10000101 = "火属性光霊選択ボックス",
  str_item_10000102 = "森属性光霊選択ボックス",
  str_item_10000103 = "雷属性光霊選択ボックス",
  str_item_intro_10000100 = "使用すると、特定の★5光霊の中から1名の光霊を選び、仲間にすることができます。\n（<color=#ffffff>ノーア、ヒドライ、バートン、クレーケン、フィリス、ワタリ</color>）",
  str_item_intro_10000101 = "使用すると、特定の★5光霊の中から1名の光霊を選び、仲間にすることができます。\n（<color=#ffffff>ファウスト、レジーナ、ベニ&クロ、リオナ、イスタバン、マギー、バーバラ</color>）",
  str_item_intro_10000102 = "使用すると、特定の★5光霊の中から1名の光霊を選び、仲間にすることができます。\n（<color=#ffffff>ルイス、ロビン、オティ、セファー、アイリーナ、スカーレイ、クスッタ</color>）",
  str_item_intro_10000103 = "使用すると、特定の★5光霊の中から1名の光霊を選び、仲間にすることができます。\n（<color=#ffffff>ミヤ、ナミシス、ソルラド、ビビアン、キーティン、ダイナ、バーバリー</color>）",
  str_item_3000327 = "ゲームコイン",
  str_item_intro_3000327 = "クレーンゲームやそのほかの施設で使えるコイン。表面に描かれたローレライの笑顔は客一人一人が存分に楽しめるよう祝福を送ってくれている",
  str_item_3000328 = "デヌオパスコイン",
  str_item_intro_3000328 = "デヌオリゾート村内で使用できるコイン。精巧に作られた純度の高いコインであるため、他の勢力の発行するコインと交換できる。\n運営モードで建物のランクアップに使う",
  str_item_intro_3410627 = "内容：黄の中級注文箱×15、黄の初級注文箱×25、R2蛍玉・雷×5、R1蛍玉・雷×8、白夜コイン×35000、連合軍の初級注文箱×8",
  str_item_intro_3410628 = "内容：黄の上級注文箱×15、黄の中級注文箱×25、R2蛍玉・雷×30、R1蛍玉・雷×7、白夜コイン×121000、連合軍の中級注文箱×8",
  str_item_intro_3410629 = "内容：黄の特級注文箱×15、黄の上級注文箱×25、R3蛍玉・雷×25、R2蛍玉・雷×10、R1蛍玉・雷×6、白夜コイン×331000、連合軍の上級注文箱×8",
  str_item_intro_3410630 = "内容：赤の中級注文箱×15、赤の初級注文箱×25、R2蛍玉・火×5、R1蛍玉・火×8、白夜コイン×35000、連合軍の初級注文箱×8",
  str_item_intro_3410631 = "内容：赤の上級注文箱×15、赤の中級注文箱×25、R2蛍玉・火×30、R1蛍玉・火×7、白夜コイン×121000、連合軍の中級注文箱×8",
  str_item_intro_3410632 = "内容：赤の特級注文箱×15、赤の上級注文箱×25、R3蛍玉・火×25、R2蛍玉・火×10、R1蛍玉・火×6、白夜コイン×331000、連合軍の上級注文箱×8",
  str_item_intro_3410633 = "内容：緑の中級注文箱×20、緑の初級注文箱×30、R2蛍玉・森×5、R1蛍玉・森×10、白夜コイン×42000、連合軍の初級注文箱×10",
  str_item_intro_3410634 = "内容：緑の上級注文箱×20、緑の中級注文箱×30、R2蛍玉・森×30、R1蛍玉・森×30、白夜コイン×149000、連合軍の中級注文箱×10",
  str_item_intro_3410635 = "内容：緑の特級注文箱×20、緑の上級注文箱×30、R3蛍玉・森×25、R2蛍玉・森×25、R1蛍玉・森×5、白夜コイン×427000、連合軍の上級注文箱×10",
