  str_item_intro_34106171 = "内容：R2蛍玉・共通×55、白夜コイン×150000、連合軍の中級注文箱×10、中級注文箱セット×30、上級注文箱セット×20",
  str_item_intro_34106181 = "内容：R2蛍玉・共通×50、白夜コイン×450000、連合軍の上級注文箱×10、上級注文箱セット×30、特級注文箱セット×20",
  str_item_3410642 = "アリスのスペシャル支援・覚醒1",
  str_item_3410643 = "アリスのスペシャル支援・覚醒2",
  str_item_3410644 = "アリスのスペシャル支援・覚醒3",
  str_item_3410645 = "カフカのスペシャル支援・覚醒1",
  str_item_3410646 = "カフカのスペシャル支援・覚醒2",
  str_item_3410647 = "カフカのスペシャル支援・覚醒3",
  str_item_intro_3410642 = "内容：赤の中級注文箱×15、赤の初級注文箱×25、R2蛍玉・火×5、R1蛍玉・火×8、白夜コイン×35000、連合軍の初級注文箱×8",
  str_item_intro_3410643 = "内容：赤の上級注文箱×15、赤の中級注文箱×25、R2蛍玉・火×30、R1蛍玉・火×7、白夜コイン×121000、連合軍の中級注文箱×8",
  str_item_intro_3410644 = "内容：赤の特級注文箱×15、赤の上級注文箱×25、R3蛍玉・火×25、R2蛍玉・火×10、R1蛍玉・火×6、白夜コイン×331000、連合軍の上級注文箱×8",
  str_item_intro_3410645 = "内容：黄の中級注文箱×15、黄の初級注文箱×25、R2蛍玉・雷×5、R1蛍玉・雷×8、白夜コイン×35000、連合軍の初級注文箱×8",
  str_item_intro_3410646 = "内容：黄の上級注文箱×15、黄の中級注文箱×25、R2蛍玉・雷×30、R1蛍玉・雷×7、白夜コイン×121000、連合軍の中級注文箱×8",
  str_item_intro_3410647 = "内容：黄の特級注文箱×15、黄の上級注文箱×25、R3蛍玉・雷×25、R2蛍玉・雷×10、R1蛍玉・雷×6、白夜コイン×331000、連合軍の上級注文箱×8",
  str_item_intro_3000900 = "柔らかい綿花は通常フィリングとして使われることが多いが、華やかな装飾品にもなる。",
  str_item_intro_3000901 = "アストラ大陸では一般的な服飾品材料。丈夫で長く使え、色も染まりやすい。",
  str_item_intro_3000902 = "染料。サメヤマが持ってきたのは1杯だけだが、他にも別の色の顔料がたくさんあるという。",
  str_item_intro_3000903 = "服を作る際よく使われるボタン。触るとひんやりとしていて、子どもはコインと間違えるかもしれない。",
  str_item_intro_3000904 = "一見ごく普通の糸。サメヤマは黒の糸だけ持ってきたのだが、あなたがいじって、きれいに並べてある色の順番が狂うのイヤだったからだそうだ。",
  str_item_7000100 = "破れた絵本",
  str_item_7000101 = "絵本の破片・ドクター",
  str_item_7000102 = "絵本の破片・空の植木鉢",
  str_item_7000103 = "診断書",
  str_item_7000104 = "ティーカップ",
  str_item_7000105 = "白い「ヒキガエル」",
  str_item_7000106 = "粗末なオモチャ",
  str_item_7000107 = "始末書",
  str_item_7000108 = "破れた帳簿",
  str_item_7000109 = "研究員のノート",
  str_item_7000110 = "可愛いレンチ",
  str_item_7000111 = "ミニバンダナ",
  str_item_7000112 = "導きのアマガエル",
  str_item_7000113 = "花の種",
  str_item_7000114 = "絵本の破片・ヨアケバナ",
  str_item_7000115 = "絵本の破片・レンチ",
  str_item_7000116 = "絵本の破片・R・Wの頭",
  str_item_7000117 = "絵本の破片・巨像",
  str_item_7000118 = "絵本の破片・カエル王子",
  str_item_7000119 = "完成された絵本",
  str_item_intro_7000100 = "スケッチ画の絵本。ページを開くと、少女と近くの3人が楽しそうに座っている情景が目に入ってくる。不思議なのは、そこに描かれている人たちの顔がすべて破り取られていることだ。",
  str_item_intro_7000101 = "あのボロボロの絵本から破り取られた破片らしい。破片には白衣を着た謎の女性の顔がうっすらと見える。",
  str_item_intro_7000102 = "紙切れには空の陶器の植木鉢が描かれている。中には半分ほど土が入っている。",
  str_item_intro_7000103 = "少し年季の入った紙。どうやら診断書のようだ。",
  str_item_intro_7000104 = "手の込んだ作りのティーカップ。いかにも高そうだ。",
  str_item_intro_7000105 = "謎の小さな白い生き物。どこから来たのか誰も知らない。タンポポが好きなようだ。",
  str_item_intro_7000106 = "非常に個性的な見た目のぬいぐるみ。センスはごく普通だが、作りはいい。",
  str_item_intro_7000107 = "シワくちゃになった紙には形の崩れた文字がいっぱいに並んでいる。字はきれいではないが、書いた人の誠意が伝わってくる。",
  str_item_intro_7000108 = "年季の入った帳簿。だが持ち主は決して記帳していたわけではなかったようだ。出納記録よりも、彼女に必要だったのは、その天才的な思考を記録できるものだった。",
  str_item_intro_7000109 = "古びたノート。持ち主は年配者らしい。",
  str_item_intro_7000110 = "巨大なレンチ。可愛いシールが貼ってある。",
  str_item_intro_7000111 = "ぬいぐるみ程の大きさの生き物しかつけられない柄付きバンダナ。",
  str_item_intro_7000112 = "ヘアバンドをネクタイにしている白いアマガエル。なかなか雰囲気がある。",
  str_item_intro_7000113 = "たった1粒の孤独な種。まるで誰かとの約束かのように、片隅で掘りあてられるのを待っている。",
  str_item_intro_7000114 = "夜明けを迎える花と同じ名を持つ少女は、花のように小さく、キラキラと美しい。",
  str_item_intro_7000115 = "超大型のレンチを描いた紙切れ。これほど大きなレンチなら、きっと背の高いたくましい人が持ち主だろう。",
  str_item_intro_7000116 = "R・Wの頭。どんな嵐もものともせず、陰謀に立ち向かい、窮地にも笑顔を浮かべる。その鉄のような強さの下には優しさが隠されている。",
  str_item_intro_7000117 = "伝説の龍の形をした巨像。可愛らしいタッチで、優雅な人の姿に描かれているが、その真っ白な羽は健在だ。",
  str_item_intro_7000118 = "白い使者、外の世界からやってきた。",
  str_item_intro_7000119 = "可愛い画風の絵本。登場人物はみな楽しそうに笑っている。",
  str_item_sub_intro_7000100 = "「楽しい思い出のはずなのに、あちこち穴だらけだ…私はあの時、いったい誰の絵を描いたんだろう？」",
  str_item_sub_intro_7000101 = "「ええ？誰がこんなひどい事をしたの？ドクターの顔が破り取られてるよ…小動物が食べちゃったのかな？だったら、どうしようもないな」",
  str_item_sub_intro_7000102 = "「この陶器の植木鉢、お家にもあるよ。しかもたくさん！だって私のお気に入りだから、たくさん集めたんだ。ただ…どうして気に入ってたのか覚えてないや…」",
  str_item_sub_intro_7000103 = "「恐怖、怒り、苦痛…生理状態と心理状態にマイナスの影響を与える要素は全て取り除いたわ。おめでとう、今あなたは健康な子どもになれたのよ」",
  str_item_sub_intro_7000104 = "「私以外にも、ドクターには診なきゃいけない患者さんがいたの。白夜城から来た貴族のお嬢様はすごく紅茶が好きで、どこへ行くにもティーカップを持ち歩いてた…今頃あの子もきっとよくなってるよね」",
  str_item_sub_intro_7000105 = "「ヒキガエルの何がいけないの？私は大好きだよ！…え？ヒキガエルって名前じゃない？」",
  str_item_sub_intro_7000106 = "「愛する■■への贈り物だ。俺たちがそばにいてやれなくても、あいつが楽しい気分でいられるように…」",
  str_item_sub_intro_7000107 = "「■■の前で汚ねえ言葉は使わねえように全員お互い監督し合え。違反者には18本のチリソースを飲んでもらうぞ。俺も例外じゃねえ」",
  str_item_sub_intro_7000108 = "「認めるわ、私もその激しさに驚いている。■■はすでにシードの到達できる極限だと思っていたけれど、■■■■は精神を突破口として、シードの人格に対する影響を探るべきだわ。■■■■の原始的で、狂暴で、想像を超える大きな力には、私も深く興味を覚えているわ。シードにこんなことまで出来るとは驚きよ。この力こそ、この強大さこそ■■の求めるもの。私には■■の世界を変える力が必要よ」",
  str_item_sub_intro_7000109 = "「現場に到着した時、その壊滅的な破壊の痕跡に驚いた。おそらく、一つの個体が巨大なエネルギーを放ち、地下から地上までのすべての設備と建物を完全に破壊してしまったのだろう…いったいどのような怪物か、想像もできない…」",
  str_item_sub_intro_7000110 = "「何だか見たことある気がする。このお花のシール…私が貼ったの？」",
  str_item_sub_intro_7000111 = "「白いバンダナ…黒いシマ模様…どこかで見たことあるような…」",
  str_item_sub_intro_7000112 = "「何か言いたいことがあるの？迷ってる私を導いてくれるの？」",
  str_item_sub_intro_7000113 = "「私の世界からお花がなくなったら、私の心ももっと深く、遠い深淵に落ちちゃうんだろうな」",
  str_item_sub_intro_7000114 = "「赤眼谷に帰って、谷いっぱいのお花を植えたいな」",
  str_item_sub_intro_7000115 = "「この絵の腕前で、本当にこのレンチのすごさを表せるかな…うーん、もしうまく書けてないなんて言ったら、本当にレンチのすごさを味わうことになりそう…」",
  str_item_sub_intro_7000116 = "「いつだって私を見つけてくれるの！」",
  str_item_sub_intro_7000117 = "「想像してみて。こんなきれいな巨像を操縦する人はどんな人だろう？…みんな、からかわないでよ。トラベラーをバカになんかしてないよ。誤解だよ――」",
  str_item_sub_intro_7000118 = "「生きていれば、きっとまた会えるよ」",
  str_item_sub_intro_7000119 = "「真実の世界と真実の幸せ」",
  str_item_get_7000100 = "「夢境-嵐起こる刻」で獲得",
  str_item_get_7000101 = "「夢境-嵐起こる刻」で獲得",
