  str_item_7000200 = "ルーペ",
  str_item_7000201 = "羽根ペン",
  str_item_7000202 = "成績表",
  str_item_7000203 = "教鞭",
  str_item_7000204 = "判例(1)",
  str_item_7000205 = "私的調査報告書",
  str_item_7000206 = "判例(2)",
  str_item_intro_7000200 = "ユニークな形と色使いのルーペ。犯罪捜査には欠かせないアイテム\n\n",
  str_item_intro_7000201 = "金色に輝く羽根ペン。持つと十分な重さがある\n\n",
  str_item_intro_7000202 = "全科目「優」の黎明学院の成績表\n\n",
  str_item_intro_7000203 = "片隅に置かれた目立たない教鞭。イルンティの幼い頃の記憶を呼び起こした\n\n",
  str_item_intro_7000204 = "裁判官「ローデル・ノブクール」が残した判例。その判決内容は彼自身と同様に冷酷かつ無情なものだった\n\n",
  str_item_intro_7000205 = "イルンティの父親が書いた私的な報告書。彼は男爵の遺言書には別の意図があることを審理の前に気付いていた\n\n",
  str_item_intro_7000206 = "裁判官「ローデル・ノブクール」が残した判例。彼の判決により1つの家族が存在を消されるだろう",
  str_item_sub_intro_7000200 = "「ルーペに名を呼ばれた気がしましたが、錯覚に決まって…しかし、このルーペには見覚えが…まさか、私のもの…？私はどうしてしまったのでしょう、こんなことも覚えていないとは」",
  str_item_sub_intro_7000201 = "「父親からも、同年代の仲間でさえも…なぜ彼らは何をしても認めてくれないのでしょう？」",
  str_item_sub_intro_7000202 = "「私は…本当に全力を尽くしていないのでしょうか…」",
  str_item_sub_intro_7000203 = "「あの暗い子供時代を忘れるには、どれほどの努力が必要なのでしょうか？」",
  str_item_sub_intro_7000204 = "「この判決の思考法を私は引き継ぐべきなのでしょうか…」",
  str_item_sub_intro_7000205 = "「私は…いったい何をしたのでしょう…」",
  str_item_sub_intro_7000206 = "「私には…私自身の答えがあります」",
  str_item_7000300 = "証拠を獲得する",
  str_item_7000301 = "証言を獲得する",
  str_item_7000302 = "証拠を獲得する",
  str_item_7000303 = "証言を獲得する",
  str_item_7000304 = "法令を獲得する",
  str_item_7000305 = "法令を獲得する",
  str_item_7000306 = "証拠を獲得する",
  str_item_7000307 = "証拠を獲得する",
  str_item_7000308 = "証言を獲得する",
  str_item_7000309 = "証言を獲得する",
  str_item_7000310 = "法令を獲得する",
  str_item_7000311 = "法令を獲得する",
  str_item_7000312 = "証拠を獲得する",
  str_item_7000313 = "証拠を獲得する",
  str_item_7000314 = "証言を獲得する",
  str_item_7000315 = "証言を獲得する",
  str_item_7000316 = "法令を獲得する",
  str_item_7000317 = "法令を獲得する",
  str_item_7000318 = "金色の分銅",
  str_item_7000319 = "金色の分銅",
  str_item_7000320 = "金色の分銅",
  str_item_intro_7000300 = "ノーディリーの体にバッジの痕跡はない",
  str_item_intro_7000301 = "生徒会メンバーの証言：パットの家は困窮している",
  str_item_intro_7000302 = "ノーディリーとパットはライバル関係にある",
  str_item_intro_7000303 = "門番の老人の証言：ノーディリーは自習室を訪れていた",
  str_item_intro_7000304 = "財産侵害罪",
  str_item_intro_7000305 = "公序良俗違反罪",
  str_item_intro_7000306 = "祖父の遺言書は本物であると証明された",
  str_item_intro_7000307 = "祖父が自殺に使ったナイフにはジェリーの指紋がついていた",
  str_item_intro_7000308 = "隣人の証言：祖父は孫娘にすべてを譲ると言っていた",
  str_item_intro_7000309 = "公証人の証言：祖父が遺言書を作成したとき、特に異常な点はなかった",
  str_item_intro_7000310 = "文書偽造罪",
  str_item_intro_7000311 = "遺言相続法",
  str_item_intro_7000312 = "ゴーティエ家内のピュロス家のバッジ",
  str_item_intro_7000313 = "スケッチブックに書かれたミレン・ゴーティエの雑言",
  str_item_intro_7000314 = "ゴーティエ家はピュロス家の人々を拉致し実験に使った",
  str_item_intro_7000315 = "ピュロス家は今も血染めの結晶の研究を続けている",
  str_item_intro_7000316 = "反逆罪",
  str_item_intro_7000317 = "風説流布罪",
  str_item_intro_7000318 = "「黎明バッジ盗難事件」の証拠収集に成功しました！",
  str_item_intro_7000319 = "「祖父の遺言書事件」の証拠収集に成功しました！",
  str_item_intro_7000320 = "「ゴーティエ家反逆事件」の証拠収集に成功しました！",
  str_item_sub_intro_7000300 = "パットの事件に関する証言を聞いたノーディリーはとても憤慨していた。パットに近寄ると「なぜ自分を貶めるのか」と問い詰め、さらには自身の潔白を証明するためにイルンティに体を調べさせたが、イルンティは何も発見できなかった。",
  str_item_sub_intro_7000301 = "自習室へ行く途中、イルンティは生徒会のメンバーにそっと引き留められた。彼はイルンティに自説を熱く語った。「パットの家は元から名のある貴族ではないし、両親もまともな公職に就いてはいない。最近一家は何らかの原因でお金に困っているようだ！」",
  str_item_sub_intro_7000302 = "イルンティはキャンパスの掲示板にあった神殿からの通知を読んだ。神殿は今年見習い修道女を2名採用した。その2名はパットとノーディリーであり、最終的に神殿に残れるのはその内の1名だけとのことだった。",
  str_item_sub_intro_7000303 = "イルンティは自習室の近くで居眠りをする年配の門番を見つけた。門番の老人は在学時に色々と手伝ってくれたイルンティを今もちゃんと覚えていた。その証言によると、今日はパット以外に自習室に入ったのはノーディリーだけであり、ノーディリーがドアノブにハンカチ越しに触れていたのを奇異に感じたが「潔癖症かと思って気に留めなかった」とのことだ。",
  str_item_sub_intro_7000304 = "他人の財産を盗み、その額が多額の者は3年以上10年以下の懲役に処し、罰金も科す",
  str_item_sub_intro_7000305 = "公然と他人を侮辱または故意に他人を誹謗中傷した者で状況が深刻な場合は、3年以下の懲役に処し、罰金も科す",
  str_item_sub_intro_7000306 = "イルンティはジェリーが持っていた遺言書を比較分析した。遺言書は確かにパットの祖父が書いたものであり、彼はジェリーに爵位とすべての財産を残していた。「私は十分に生きた、もう悔いはない」――イルンティはこの言葉に注目した。どうやら祖父は遺言書を書く際に自殺の意思を明かしていたようだ。",
  str_item_sub_intro_7000307 = "イルンティは祖父の家を訪れ、彼が果物ナイフを使って自殺したことを発見した。果物ナイフを注意深く調べると、そこにはジェリーの指紋も付着していたが、ジェリーは自分が食事の準備をしているので指紋が着いていても何ら不思議ではないと説明した。再度の現場検証でイルンティは祖父は確かに自殺であったことを確認した。",
  str_item_sub_intro_7000308 = "イルンティは祖父の隣家を訪ねた。隣人は祖父が息子の覇気のなさを嘆く一方で孫娘のことを自慢しており、また皆の前で「自分の爵位と財産はすべて孫娘に譲り、息子には何も残さない」と言っていたと話した。",
  str_item_sub_intro_7000309 = "遺言の公証人は学歴のある年老いた使用人だった。その使用人は祖父から公証人に選ばれたことは大変光栄なことだと言った。だが、すぐに自分の言葉が適切ではなかったと感じた彼は、遺言書の作成時、祖父に特に変わったところはなく、また内容について祖父の意志を何度も確認したのだと申し訳なさそうに説明した。",
  str_item_sub_intro_7000310 = "公文書または私文書を偽造し不正目的で使用した者は3年以上10年以下の懲役に処し、罰金も科す",
  str_item_sub_intro_7000311 = "遺言書が法的に有効であると判断された場合、財産は遺言書の内容に従って分配されるものとする",
  str_item_sub_intro_7000312 = "イルンティはダウンタウンの流刑地にあるゴーティエ家の部屋に忍び込んだ。注意深く部屋の中を探すと片隅にピュロス家のバッジを見つけた。ゴーティエ家とピュロス家は血染めの結晶事件のせいで共にダウンタウンに流されたのだが、まさか両家は協力して謀反を企てようとしているのだろうか？イルンティはその先を考えるのが怖くなった。「パットもピュロス家の一員…」",
  str_item_sub_intro_7000313 = "イルンティが別の荒れ果てた家を見つけると、そこには「ミレン・ゴーティエ」と記されたスケッチブックがあった。スケッチブックには理解し難い抽象的な図案が描かれており、目を細めて見ると図案の中に、ごく小さな文字で「私はなぜこんな扱いを受けるのか！？なぜなぜなぜ！？私は必ず自分の運命を取り戻す…たとえ彼らの力を借りようとも」と書かれていた。",
  str_item_sub_intro_7000314 = "突如1体の奇妙な姿の暗鬼が現れた。イルンティは迷わずにその胸を貫いた。暗鬼はいったんは倒れたものの意識を取り戻し、何かを訴えるかのように群衆に向かって手を上げた。イルンティは傍に寄り暗鬼のつぶやきを聞いた。「ゴーティエは…ピュロスに復讐している…私たちは…ゴーティエに…捕らえられ…実験台にされた…彼らは謀反を…企んでいる！」",
  str_item_sub_intro_7000315 = "イルンティが次の捜査について思案していると、みすぼらしい身なりの通行人がそっと近づいてきた。彼はダウンタウンのすべての情報を持っていると言い、ピュロス家が最近も血染めの結晶の研究をしていることを明かした。イルンティがなぜ自分にそんなことを告げるのか尋ねると、通行人は黒ずんだ歯を見せて言った。「俺をミッドタウンに戻してくれるかい？」",
  str_item_sub_intro_7000316 = "白夜城の統治機構の転覆を故意に企てた者、または実行した者は無期懲役、重大な場合は死刑に処す",
  str_item_sub_intro_7000317 = "故意に他人の流言を広めた者は、1年以下の懲役に処し、罰金も科す",
  str_item_sub_intro_7000318 = "証拠や証言を考え合わせ、イルンティは黎明バッジを盗んだ犯人はノーディリーであると推断した。",
  str_item_sub_intro_7000319 = "あなたは遺言書は有効であり、使用人のジェリーがパットの祖父の爵位とすべての財産を相続することを認める…",
  str_item_sub_intro_7000320 = "あなたはミレン・ゴーティエが人体実験のためにピュロス家の人間を拉致し、謀反を企てている事実を裏付ける最も完全な証拠と証言を集めた。",
  str_item_7000400 = "古い鍵",
  str_item_7000401 = "ダイナのクッキー",
  str_item_7000402 = "新しい家の青写真",
  str_item_7000403 = "荘厳なトロンボーン",
  str_item_7000404 = "新しい楽譜",
  str_item_7000405 = "ダイナの肖像画",
  str_item_7000406 = "ロビンの肖像画",
  str_item_7000407 = "ミス・ポットの肖像画",
  str_item_7000408 = "白いイルカの肖像画",
  str_item_intro_7000400 = "おばさんがクラリンに渡した屋根裏部屋の鍵。古びた錠前の音で他の人の迷惑にならないように、気をつけて使おう",
  str_item_intro_7000401 = "クラリンがダイナに持っていったクッキー。後に魚人の衛兵たちに持っていかれた。ダイナの要望に従い、砂糖を入れていない",
  str_item_intro_7000402 = "水の主のために建設した城の設計図。水の主の言っているものはこれではないようだが、最終解釈権はクラリン女王にある",
  str_item_intro_7000403 = "町の住民がクラリンのために探してきた新しい楽器。よりクリアで力強い音を出し、怒りを表現できる",
  str_item_intro_7000404 = "クラリンが古い屋根裏部屋で見つけた水の譜面。新しい名前が記されている",
  str_item_intro_7000405 = "海底の町の芸術家が護衛のダイナのために作った肖像画。現在はクラリン女王が観客席に置き、演説の練習用道具として使っている",
  str_item_intro_7000406 = "海底の町の芸術家が護衛のロビンのために作った肖像画。現在はクラリン女王が観客席に置き、演説の練習用道具として使っている",
  str_item_intro_7000407 = "海底の町の芸術家が謎の相談役のために作った肖像画。現在はクラリン女王が観客席に置き、演説の練習用道具として使っている",
  str_item_intro_7000408 = "海底の町の芸術家が女王の優秀な友人のために作った肖像画。現在はクラリン女王が観客席に置き、演説の練習用道具として使っている",
  str_item_sub_intro_7000400 = "彼女は屋根裏部屋で眠っていて、他人がいらないものを食べるんだよ。話し声は小さくて、遠くの隅っこに隠れているよ。昼間は部屋の掃除をして、夜は楽器を取り出し、音楽で孤独な心を慰めるんだ」",
  str_item_sub_intro_7000401 = "「私のクッキー！それはクラリンがくれたものなんだ！…このポンコツども、どうしてクッキーだけでも残しておかなかったんだ！」",
  str_item_sub_intro_7000402 = "「■。。…凹△…■■！」",
  str_item_sub_intro_7000403 = "「痛みと悲しみは…音楽で救われます！」",
  str_item_sub_intro_7000404 = "「以前、新しい名前をつけてほしいと私に言ったことがあります。ルービンシュタイン、サリエリ、レオポルト、ドヴォルザークなど、いろいろ考えました…どれもあの子の好きな音です…えっ？もっと親しみやすい方がいいですか？」",
  str_item_sub_intro_7000405 = "「なんだって？私がトゲトゲしている？仲間のために頑張っているんだから、トゲトゲしていないとダメだろ？」",
  str_item_sub_intro_7000406 = "「うーん…たしかに私は起伏が少なく、存在感がないと言った魚がいたわね…でも、それが私の生きる道なの…」",
  str_item_sub_intro_7000407 = "「また私に絵を描いてもらいたいの？フフ、それならお代をもらわないとね」",
  str_item_sub_intro_7000408 = "「僕とクラリン女王の関係？フフ、それは秘密だよ」",
  str_item_7000801 = "骨とう品",
  str_item_intro_7000801 = "双閣港の津々浦々から見つけてきた骨とう品。龍州産の美術品や調度品は異国でも珍重されるが、発注書と報酬を通じて正々堂々と取引されたものもあれば、盗賊が人知れず盗んできたものもある。",
  str_item_6030101 = "小さな絵本",
  str_item_6030102 = "微笑みの温度",
  str_item_6030103 = "イブの黎明の光",
  str_item_6030104 = "白夜神殿",
  str_item_6030105 = "均衡の秤",
  str_item_6030106 = "純白の祈り",
  str_item_6030107 = "水の暗号",
  str_item_6030108 = "愛の独奏",
  str_item_6030109 = "華美な家",
  str_item_6030110 = "藤花の夢",
  str_item_6030111 = "花と魔剣",
  str_item_6030112 = "夢の小舟",
  str_item_6030113 = "彼の見守り",
  str_item_6030114 = "彼女の誓い",
  str_item_6030115 = "禁衛の剣",
  str_item_6030116 = "甘い列車",
  str_item_6030117 = "ボアストーンのおしゃれ",
  str_item_6030118 = "クリームの森",
  str_item_6030119 = "兵士の認識票",
  str_item_6030120 = "星の炎の光",
  str_item_6030121 = "啓光の旗槍",
  str_item_6030122 = "ナシリスの思い",
  str_item_6030123 = "ニポリスの願い",
  str_item_6030124 = "北国の鏡",
  str_item_intro_6030101 = "記念メダル。\n小さく、絵も幼稚な絵本。しかし、そこには切っても切れない絆と思いがあふれている。",
  str_item_intro_6030102 = "記念メダル。\n世界の終わりが訪れようと、彼は妹のために適温の水を用意する。",
  str_item_intro_6030103 = "記念メダル。\nあの暗闇で過ごした日々、この花は彼女にとって黎明だった。",
  str_item_intro_6030104 = "記念メダル。\n白夜城の神殿に認められた証である。",
  str_item_intro_6030105 = "記念メダル。\nイルンティは傾いた天秤を決して見逃さない。",
  str_item_intro_6030106 = "記念メダル。\nあの頃のパロマはまだ信じていた…",
  str_item_intro_6030107 = "記念メダル。\nこれは偉大なる水の主の好意だ！俗物たちよ、速やかに体を差し出し、この恩恵を受け取るのだ！",
  str_item_intro_6030108 = "記念メダル。\nこの演奏には家族の願い、仲間たちの気遣い、そして…愛と勇気が込められている",
  str_item_intro_6030109 = "記念メダル。\nただ一時的な住みかを探していただけだったのだが、偶然にも素晴らしい居場所が見つかった",
  str_item_intro_6030110 = "記念メダル。\nこの温もりは朝の日差し？それともトゲを乗り越えた君の温かさ？",
  str_item_intro_6030111 = "記念メダル。\nハマゴウも花が咲くことを知る人は少ない。その花はフジより小さく、剣客のスカートの裾のような薄紫の色をしている。",
  str_item_intro_6030112 = "記念メダル。\n彼女はゴールド・リバーを見て、夢の中で舟に乗ったことを思い出し、また誰かと舟に乗りたいと思った。",
  str_item_intro_6030113 = "記念メダル\n「君がいるからこそ、この世界は守る価値がある」",
  str_item_intro_6030114 = "記念メダル。\n「あなたがいるからこそ、この世界を守りたい」",
  str_item_intro_6030115 = "記念メダル。\n禁衛座の愛が注がれているため、特別な強化が施された。だからこそ、彼女は他の方法で彼のそばにいられるのかもしれない…",
  str_item_intro_6030116 = "記念メダル。出立する時は、冷たく感情のない、ただの機械に思えるが、戻ってくる時にはその甘さに気づくことだろう",
  str_item_intro_6030117 = "記念メダル。どこへ行こうと振り切れない…それならいっそのこと、この世に二つとないファッションアイテムに変えてしまおう",
  str_item_intro_6030118 = "記念メダル。滑らかなクリームの流れる樹木に、さわやかで甘い果実を実らせる花が咲く…もう一度チャンスがあるなら、ここで思う存分ピクニックしてみたい",
  str_item_intro_6030119 = "記念メダル。1つ1つの認識票が命を表している。輝ける魂たちよ、安らかに眠りたまえ。",
  str_item_intro_6030120 = "記念メダル。それは誰の両親か？誰の子供か？誰の兄弟姉妹か？認識票に刻まれた名は沈黙のまま、未来を照らし出す。",
  str_item_intro_6030121 = "記念メダル。大きな音が鳴り響き、旗がはためく。わが身もかえりみず戦うアストラの防衛軍は後退することを知らず、暗闇を境界の外へと追いやる。",
  str_item_intro_6030122 = "記念メダル\n「できればお姉さまと一緒に……」",
  str_item_intro_6030123 = "記念メダル\n「妹に生きていってもらいたい……」",
  str_item_intro_6030124 = "記念メダル\nその鏡面は、これまであまりに多くの崩壊の瞬間を記録してきた。たまには別のものを記憶するべきだろう",
  str_item_6130101 = "忘却のパネル",
  str_item_6130102 = "記念の鏡",
  str_item_6130103 = "海の記念パネル",
  str_item_6130104 = "夢の記念パネル",
  str_item_6130105 = "記念相対パネル",
  str_item_6130106 = "旅の思い出",
  str_item_6130107 = "軍随行プレート",
  str_item_6130108 = "鏡と詩の記念パネル",
  str_item_intro_6130101 = "記念パネル。何もかも終わった。過去はもう過ぎ去った。家に帰ろう。",
  str_item_intro_6130102 = "記念パネル\n鏡の中のあなた。一緒に目を覚ましましょう",
  str_item_intro_6130103 = "記念パネル。\n心は今までにないほど強く、声は今までにないほど魅力的になった",
  str_item_intro_6130104 = "記念パネル。\n目を覚ました彼女には常に呪いとの戦いが待っている。しかし彼女は清潔で活気のある街で夜明けの光を迎える、そんな明るい夢を見ている。",
  str_item_intro_6130105 = "記念パネル\nたとえ千年の歳月がちりあくたのように空に消えても、私の心は変わらない",
  str_item_intro_6130106 = "記念パネル。「ゴオオ――ガタン、ゴトン…」列車がレールをたどり、明るい夢の中を駆け抜ける。クリームの森を抜け、ハチミツの泉を抜けて、旅人の心残りも吹き飛していく…",
  str_item_intro_6130107 = "記念パネル\n「何度でも磨かれたいと願い、千の焼き入れで光を放ち、百の鍛錬で鋼となる。鋭く尖った金属の弾丸には、後には引けぬ我らの願いが込められている」",
  str_item_intro_6130108 = "記念パネル\n「彼女の体は雪に埋もれ、魂は鏡に囚われ、顔は散った花びらに覆われている。しかし、彼女の愛は消えることがない」",
  str_item_3001000 = "夢の破片",
  str_item_intro_3001000 = "虚実の判断のつけがたい物語の中で得た破片。現実の痕跡を残している。【夢の痕跡】商店でアイテム報酬と交換できる",
  str_item_get_3001000 = "夢境-テーマ商店コイン期限切れで変換",
  str_item_3001001 = "崩壊の蕊",
  str_item_intro_3001001 = "困難に立ち向かい、成長した後に得られた記念。夢境-嵐起こる刻-記憶工房でアイテム報酬と交換できる。",
  str_item_get_3001001 = "夢境-嵐起こる刻ステージ",
  str_item_3001002 = "沈殿した欠片",
  str_item_intro_3001002 = "困難に立ち向かい、成長する過程で得た欠片。夢境-嵐起こる刻-記憶工房でアイテム報酬と交換できる。",
  str_item_get_3001002 = "夢境-嵐起こる刻ステージ",
  str_item_3001003 = "精神",
  str_item_intro_3001003 = "イブが理性と意識を保つための要素。「夢境-嵐起こる刻」のステージ挑戦に使用する。毎日14:00に3ポイント回復（上限に達していた場合、回復はされない）",
  str_item_get_3001003 = "決まった時間に自動回復",
  str_item_3001004 = "微笑みの水",
  str_item_intro_3001004 = "イブが愛用しているコップ。普通の水であっても、イブに絶えずパワーを与えてくれる。累積すると「微笑の導き」をレベルアップできる",
  str_item_get_3001004 = "夢境の難易度「潜夢」のステージを初めて★3でクリアすると獲得",
  str_item_3001005 = "計量の分銅",
  str_item_intro_3001005 = "本当の自分探しで獲得する分銅、人生との名の天秤を水平にするために使う。「夢境-審判は黄金の波の下」裁判所公売でアイテム報酬と交換できる",
  str_item_get_3001005 = "夢境-審判は黄金の波の下ステージ",
  str_item_3001006 = "正義のキャンドル",
  str_item_intro_3001006 = "理想のために正義を追い求める道に残した星のキャンドル。「夢境-審判は黄金の波の下」裁判所公売でアイテム報酬と交換できる",
  str_item_get_3001006 = "夢境-審判は黄金の波の下ステージ",
  str_item_3001007 = "精神",
  str_item_intro_3001007 = "理性と覚醒を保つ要素。探索中に消費されるが時間とともに回復する",
  str_item_get_3001007 = "決まった時間に自動回復",
  str_item_3001008 = "正義の光",
  str_item_intro_3001008 = "イルンティが自らの力で取り戻した正義の光。累積すると「真相フォーカス」をレベルアップできる",
  str_item_get_3001008 = "夢境の難易度「潜夢」のステージを初めて★3でクリアすると獲得",
  str_item_3001010 = "響音の巻貝",
  str_item_intro_3001010 = "音楽が流れ出る巻貝。その中には古い楽章の断片が記録されている。夢境-クラリンと遊水の夢境-シーサイドカフェでアイテム報酬と交換できる",
  str_item_get_3001010 = "夢境-クラリンと遊水の夢境ステージ",
  str_item_3001011 = "佳肴の海藻",
  str_item_intro_3001011 = "海底の片隅に生える蛍光海藻。ある大人気深海飲料を作るのに使用する。夢境-クラリンと遊水の夢境-シーサイドカフェでアイテム報酬と交換できる",
  str_item_get_3001011 = "夢境-クラリンと遊水の夢境ステージ",
  str_item_3001012 = "精神",
  str_item_intro_3001012 = "理性と覚醒を保つ要素。探索中に消費されるが時間とともに回復する",
  str_item_get_3001012 = "夢境-クラリンと遊水の夢境ステージ",
  str_item_3001013 = "契約研修",
  str_item_intro_3001013 = "クラリンは水の主の話す内容をすべて理解しようとして、その不思議な頭足類の思考に接続した。ためると「水の感触」をレベルアップできる",
  str_item_get_3001013 = "夢境の難易度「潜夢」のステージを初めて★3でクリアすると獲得",
  str_item_3001014 = "藤花のかんざし",
  str_item_intro_3001014 = "小さいけれど強靭な花で作られたかんざし。夢境-夢隔てる緞帳・渡剣歌-花径商店でアイテム報酬と交換できる",
  str_item_get_3001014 = "夢境-夢隔てる緞帳・渡剣歌ステージ",
  str_item_3001015 = "古代の銅銭",
  str_item_intro_3001015 = "錆びた東方の古銭。歴史の変遷とともに本来の貨幣機能を失ってしまった。夢境-夢隔てる緞帳・渡剣歌-花径商店でアイテム報酬と交換できる",
  str_item_get_3001015 = "夢境-夢隔てる緞帳・渡剣歌ステージ",
  str_item_3001016 = "精神",
  str_item_intro_3001016 = "理性と覚醒を保つ要素。探索中に消費されるが時間とともに回復する",
  str_item_get_3001016 = "夢境-夢隔てる緞帳・渡剣歌ステージ",
  str_item_3001017 = "鍛剣の志",
  str_item_intro_3001017 = "すべての戦いが侠客の剣技を磨き、積み上げてゆけば、やがて質的な変化をもたらす。一定数累積すると「剣の心」をレベルアップできる。",
  str_item_get_3001017 = "夢境の難易度「潜夢」のステージを初めて★3でクリアすると獲得",
  str_item_3001018 = "運転資金",
  str_item_intro_3001018 = "影ノ街の人の慣習的な言い方で言えば、紫紺商会は最初はペーパーカンパニーにすぎなかったが、金があるのに稼がないのは設立者のやり方ではない。本当にやってみたらいい。",
  str_item_3001019 = "運気",
  str_item_intro_3001019 = "商売を営む中で金や財物を通じて得られる吉兆の気。運勢を高め、魔除けのために使われる。",
  str_item_3001021 = "銀白の桂冠",
  str_item_intro_3001021 = "勝利と平和を象徴するオリーブの枝で造られた桂冠。夢境-眠れる千年の誓い-ノースウインド市場でアイテム報酬と交換できる。",
  str_item_get_3001021 = "夢境-眠れる千年の誓いのステージ",
  str_item_3001022 = "誓いの銅貨",
  str_item_intro_3001022 = "ノースウインド守護軍の凱旋を記念し造られた青銅の記念銅貨。夢境-眠れる千年の誓い-ノースウインド市場でアイテム報酬と交換できる",
  str_item_get_3001022 = "夢境-眠れる千年の誓いのステージ",
  str_item_3001023 = "精神",
  str_item_intro_3001023 = "理性と覚醒を保つ要素。探索中に消費されるが時間とともに回復する",
  str_item_get_3001023 = "決まった時間に自動回復",
  str_item_3001024 = "黄金色の麦の穂",
  str_item_intro_3001024 = "心休まる麦の香りは、誓いの言葉に込められた未来への期待だ。その香りは常に剣の中の魂に離れてはならないと呼びかける。蓄積すると「剣の中の魂」をレベルアップできる",
  str_item_3001025 = "神殿の破片",
  str_item_intro_3001025 = "神殿がどっと大きな音を立て倒壊した。精巧な彫刻の施されたレンガも神殿内の貴重な器類も、建物の倒壊と共に破片と化す。しかし、破片たちは完全に価値を失ったわけではない。",
  str_item_3001026 = "パチパキャンディ",
  str_item_intro_3001026 = "「パチパキャンディ」という希少な植物になる果実。夢境-奇天烈美食タウン-美味宅配便でアイテム報酬と交換できる。",
  str_item_get_3001026 = "夢境-奇天烈美食タウン",
  str_item_3001027 = "クリーム原木",
  str_item_intro_3001027 = "クリームの森に生えている立派で丈夫な木で作った原木。夢境-奇天烈美食タウン-美味宅配便でアイテム報酬と交換できる。",
  str_item_get_3001027 = "夢境-奇天烈美食タウン",
  str_item_3001028 = "精神",
  str_item_intro_3001028 = "理性と覚醒を保つ要素。探索中に消費されるが時間とともに回復する",
  str_item_get_3001028 = "決まった時間に自動回復",
  str_item_3001029 = "心の宝物",
  str_item_intro_3001029 = "セファーの飾らない関心と呼びかけ…ボアストーンは一度も望んだことなどない。累積すると「ボアストーン」をレベルアップできる",
  str_item_3001030 = "高級食器",
  str_item_intro_3001030 = "大家の手になる非常に精緻で美しい伝世品の食器。一流の食材をさらに魅力的なものにしてくれる。",
  str_item_3001031 = "啓明の星勲章",
  str_item_intro_3001031 = "かつての啓光の勲章。すでに絶版になっており、深い意味を持っている。勲章そのものに価値があるわけではなく、英雄の輝きによってその栄光を受け継ぎ、値段のつけようがない宝となる。英雄に贈られる勲章は、大いなる感謝の中のささやかな返礼にすぎない。夢境-星が暁に出会う夜-夢幻配給部でアイテム報酬と交換できる",
  str_item_get_3001031 = "夢境-星が暁に出会う夜ステージ",
  str_item_3001032 = "啓光交換券",
  str_item_intro_3001032 = "啓光内部で流行している券。労働と軍務の時間に応じてポイントを獲得し、さまざまな物資と交換できる。夢境-星が暁に出会う夜-夢幻配給部でアイテム報酬と交換できる",
  str_item_get_3001032 = "夢境-星が暁に出会う夜ステージ",
  str_item_3001033 = "精神",
  str_item_intro_3001033 = "理性と覚醒を保つ要素。探索中に消費されるが時間とともに回復する",
  str_item_get_3001033 = "決まった時間に自動回復",
  str_item_3001034 = "ホイッスル",
  str_item_intro_3001034 = "鋭い音を発し、兵士の神経を引き付ける。しかし、それから離れた後、ここ以上に安心できる場所などあるだろうか？累積すると「尖鋭弾」のレベルを上げられる",
  str_item_3001035 = "戦争ゲーム",
  str_item_intro_3001035 = "啓光内では珍しい娯楽方法だが、それでも戦闘の特性を保っている。素晴らしい戦争ゲームには、制作者の思いが込められている",
  str_item_3001036 = "ドライフラワーのしおり",
  str_item_intro_3001036 = "少女が読書の際に使っていた手作りのしおり。彼女は花に囲まれながら、多くの寓話集を読み、その断片的な過去を確かめようとした。夢境-鏡の世界 · 雪中の詩歌-名も無き市場でアイテム報酬と交換できる",
  str_item_get_3001036 = "夢境-鏡の世界 · 雪中の詩歌ステージ",
  str_item_3001037 = "鏡の破片",
  str_item_intro_3001037 = "こうした断片は、魔鏡の力の延長であるだけでなく、鏡の世界の構成要素をも含んでおり、ひとつひとつが小さな裂け目の境界となっている。夢境-鏡の世界 · 雪中の詩歌-名も無き市場でアイテム報酬と交換できる",
  str_item_get_3001037 = "夢境-鏡の世界 · 雪中の詩歌ステージ",
  str_item_3001038 = "精神",
  str_item_intro_3001038 = "理性と覚醒を保つ要素。探索中に消費されるが時間とともに回復する",
  str_item_get_3001038 = "決まった時間に自動回復",
  str_item_3001039 = "鏡界の花",
  str_item_intro_3001039 = "ナシリスの力は、花の形で現れることが多く、境界の倒影でも例外はない",
  str_item_3001040 = "北境の寓話集",
  str_item_intro_3001040 = "ナシリスは自分の記憶を取り戻そうとしている。他の人に助けを求めながらも、自分にある手がかりもあきらめてはいない",
  str_item_not_enough_plm = "アイテム「ファイアソーンのつぼみ」が足りません",
  str_item_3751396 = "黒い眼鏡の黒いクマ",
  str_item_3751397 = "トワイライトシティの修道女",
  str_item_3751551 = "新任元帥の悩み",
  str_item_intro_3751396 = "光がトワイライトシティをあまねく照らし、闇を払い去ることを願います",
  str_item_intro_3751397 = "クマ？そんなものないわ。",
  str_item_intro_3751551 = "報告以外に話すことはないわけ？",
  str_item_3000131 = "黄昏の交響曲特別召集星標",
  str_item_intro_3000131 = "【黄昏の交響曲】限定召集で1回召集できる\nこのアイテムは期間限定アイテムです。【黄昏の交響曲】限定召集が終了するまでにお使いください。期限を過ぎると、他のアイテムに変換されることなく消失します",
  str_item_10000992 = "クレーケン協力箱",
  str_item_intro_10000992 = "使用すると、クレーケンが冒険に加わってくれる。",
  str_item_1000099 = "クレーケン協力箱",
  str_item_intro_1000099 = "使用すると、クレーケンが冒険に加わってくれる。",
  str_item_3755023 = "良い子のイヌのぬいぐるみ",
  str_item_3755024 = "アマガエル？",
  str_item_3755025 = "黎明の花",
  str_item_intro_3755023 = "獲得すると対応するアイコンが使用可能になる\nクゥン…クゥン…気に入った？",
  str_item_intro_3755024 = "獲得すると対応するアイコンが使用可能になる\nタンポポ？待って、行かないで～！",
  str_item_intro_3755025 = "獲得すると対応するアイコンが使用可能になる\n小さな白い花は黎明の象徴…",
  str_item_3661219 = "輝星の騎士の肖像",
  str_item_intro_3661219 = "家具。巨像のルーム内に設置できる。\n騎士時代のイルンティをモデルにした肖像。贈れずじまいとなってしまった、ある少女からの贈り物らしい。\n「イルンティ様、ずっと私のことを助けてくれて、気に掛けてくれてありがとうございます。これからもイルンティ様が正義と仁愛の信念を守り、白夜城をより一層光に満ちた未来へと導いてくれることを願っています」",
  str_item_3661220 = "純粋な修道女の肖像",
  str_item_intro_3661220 = "家具。巨像のルーム内に設置できる。\n修道女の頃のパロマをモデルにした肖像。贈れずじまいとなってしまった、ある父親からの贈り物らしい。\n「パット、お前が永遠に純粋で善良でいられますように。私たち家族がずっと幸せに暮らせますように」",
  str_item_3751039 = "剛毅不動",
  str_item_3751040 = "光明の果て",
  str_item_3751041 = "永遠の凱歌",
  str_item_3751398 = "知の渇望者",
  str_item_3751399 = "守護の力",
  str_item_3751400 = "何か言ったか？",
  str_item_intro_3751039 = "獲得すると対応するアイコンが使用可能になる\n「デニール、レインハト…何が起ころうとも、我々全員が自分の道を見つけられるよう願っている」",
  str_item_intro_3751040 = "獲得すると対応するアイコンが使用可能になる\n「誰かを敵視するつもりはないし、その手のことに興味もない。 行く手を阻む者が邪魔なだけだ」",
  str_item_intro_3751041 = "獲得すると対応するアイコンが使用可能になる\n「啓明の光は誰でもいい。光霊を率いる重責を負って前進できるなら、お前であっても、私であっても」",
  str_item_intro_3751398 = "獲得すると対応するアイコンが使用可能になる\n「星空か…あれはまるで世界のあらゆる秘密が収められた広大な図書館のようだ」",
  str_item_intro_3751399 = "獲得すると対応するアイコンが使用可能になる\n「運命によって与えられたこの力を、いつの日かきちんと使いこなしたい」",
  str_item_intro_3751400 = "獲得すると対応するアイコンが使用可能になる\n「あれ？」",
  str_item_3751552 = "それは言わないで！",
  str_item_intro_3751552 = "獲得すると対応するアイコンが使用可能になる\n「もう、アイスキャンディ呼ばわりはやめて！」",
  str_item_3751553 = "楽しそうなタタ",
  str_item_intro_3751553 = "獲得すると対応するアイコンが使用可能になる\n「もうすぐ休暇だ。タタはすでにどう過ごすか決めているようだが、いったいどんな計画なのだろう？」",
  str_item_3763034 = "心温まる贈り物",
  str_item_intro_3763034 = "獲得すると対応するフレームが使用可能になる\nザーリャが北境の気候に耐えられないのではと心配して、帽子をかしてくれた。",
  str_item_3661215 = "ライティングデスク",
  str_item_intro_3661215 = "家具。巨像のルーム内に設置できる。\n上品な雰囲気の木製のライティングデスク。このデスクなら心静かに作業に励める。",
  str_item_3661216 = "小さなティーテーブル",
  str_item_intro_3661216 = "家具。巨像のルーム内に設置できる。\n木製のティーテーブル。トップの一部には大理石が使われており、非常に凝った造りのようだ。",
  str_item_3661217 = "フクロウのサイドテーブル",
  str_item_intro_3661217 = "家具。巨像のルーム内に設置できる。\nテーブルの上に止まったフクロウが何やら遠くを見つめている。",
  str_item_3661218 = "魔法のほうき",
  str_item_intro_3661218 = "家具。巨像のルーム内に設置できる。\n言い伝えによると、ほうきに乗れば、空を飛べるらしい。いったいどこから湧いたインスピレーションなのだろう？",
  str_item_5234055 = "ボートの置物",
  str_item_intro_5234055 = "色鮮やかなボートをスタンドに立てかけた置物。見ていると、航海に出たくなってくる。",
  str_item_3661052 = "浮遊蛍灯",
  str_item_intro_3661052 = "家具。巨像のルーム内に設置できる。\n浮かぶだけで、あちこち動き回ることはできない…何に使ったらよいのだろうか？物掛けにする？それとも手すり代わりにする？",
  str_item_3000338 = "遺跡の欠片",
  str_item_intro_3000338 = "古代遺跡の欠片と考えられるが、長い月日の中で各地に散逸した。価値の分かる人はおそらくかなりの報酬を払ってでも、手に入れようとするだろう。",
  str_item_3751401 = "ヘールのバスケットボール",
  str_item_3751402 = "卓球初心者バイス",
  str_item_3751403 = "eスポーツプレイヤーガルー",
  str_item_3751404 = "射撃の王者カロン",
  str_item_intro_3751401 = "獲得すると対応するアイコンが使用可能になる\nよぉし！3ステップでシュート決めてやるぜ！ああ？なんだって跳ね返ってきやがったんだ！？",
  str_item_intro_3751402 = "獲得すると対応するアイコンが使用可能になる\nスポーツは元気の源よ！卓球は初心者だけど、全力で頑張るわ！",
  str_item_intro_3751403 = "獲得すると対応するアイコンが使用可能になる\nゲームじゃ絶対に負けないもんね～！eスポーツ大会でのあたしの活躍、楽しみにしてて！",
  str_item_intro_3751404 = "獲得すると対応するアイコンが使用可能になる\n射撃場での華麗なるパフォーマンスをとくとご覧あれ！",
  str_item_3440011 = "光の宝箱",
  str_item_intro_3440011 = "開封後、以下の材料からランダムで1つ獲得できる：白夜コイン×10000、白夜コイン×5000、R2蛍玉・共通×2、R1蛍玉・共通×3、霊質×100、霊質×50",
  str_item_3440012 = "啓発の箱",
  str_item_intro_3440012 = "開封後、以下の材料からランダムで1つ獲得できる：白夜コイン×5000、白夜コイン×2000、白夜コイン×1000、R2蛍玉・共通×1、R1蛍玉・共通×2、霊質×30",
  str_item_3440013 = "暗海の宝箱",
  str_item_intro_3440013 = "開封後、以下の材料からランダムで1つ獲得できる：匿名ギフトパック×1、連合軍の上級注文箱×2、白夜コイン×20000、R2蛍玉・共通×4",
  str_item_3440019 = "海霊の宝箱",
  str_item_intro_3440019 = "開封後、以下の材料からランダムで1つ獲得できる：匿名ギフトパック×1、連合軍の上級注文箱×2、白夜コイン×20000、R2蛍玉・共通×4",
  str_item_3755036 = "法廷の騎士イルンティ",
  str_item_intro_3755036 = "獲得すると対応するアイコンが使用可能になる\n「わずかな手がかりも見逃すわけにはいきません！」",
  str_item_3755037 = "パットの料理",
  str_item_intro_3755037 = "獲得すると対応するアイコンが使用可能になる\n「見た目はあまりよくありませんが、味は保証します！」",
  str_item_6110001 = "薫香の風",
  str_item_intro_6110001 = "記念パネル。この模様を見ていると、海風に乗って遠方よりやってきた客人と琵琶の音色、そして旗のはためく音を思い出す。",
  str_item_3661221 = "機関車の記念模型",
  str_item_intro_3661221 = "有名俳優カロンが映画のプレミア上映に出席した観客に贈ったプレゼント。迫力満点の機関車のデザインは、カロン自身のインパクト十分な演技のように、観客に深い印象を残した。\n「この感動を胸に刻むのだ！」",
  str_item_3000027 = "ハート券",
  str_item_3000028 = "ハートバルーン",
  str_item_intro_3000027 = "コーデ投票イベントでお気に入りの光霊への投票に使用する。\n「この気持ち、無事に伝わるだろうか？」",
  str_item_intro_3000028 = "コーデ投票イベントでお気に入りのコーデへの投票に使用する。\n「ハートが飛んでいかないように、しっかりと相手の手に渡そう」",
  str_item_3661222 = "クラリネットの少女の肖像",
  str_item_3661223 = "水の女王の肖像",
  str_item_intro_3661222 = "家具。巨像のルーム内に設置できる。\nもともとはカフェの特別なポットとして作られたが、口から水が出てくるデザインはあまり評判がよくない。\n「わ、私はこんなことしません！」",
  str_item_intro_3661223 = "家具。巨像のルーム内に設置できる。\n精巧に作られた女王の肖像。重量を減らすため、中は空洞になっている。このデザインを参考に光る海藻の汁を入れる器を作ってはどうかと提案する者がいたが、女王にきっぱりと断られた。\n「ううっ…どうして毎回…同じようなこと言われるんでしょう…」",
  str_item_3661224 = "医療棚",
  str_item_3661225 = "医療用ベッド",
  str_item_3661226 = "医療用カート",
  str_item_3661227 = "横並びの椅子",
  str_item_intro_3661224 = "家具。巨像のルーム内に設置できる。\n木製の戸棚。さまざまな瓶入りの薬などがたくさん並んでいる。人々の痛みが和らぎますように。",
  str_item_intro_3661225 = "家具。巨像のルーム内に設置できる。\n患者のために用意されたベッド。体調がすぐれない時はここで休むといい。",
  str_item_intro_3661226 = "家具。巨像のルーム内に設置できる。\n簡易版医療カート。載せられる量には限られているが、非常に重要な設備の一つである。",
  str_item_intro_3661227 = "家具。巨像のルーム内に設置できる。\n横並びになった椅子。仲間たちとおしゃべりすれば、焦りや心配も和らぐ。",
  str_item_5234056 = "静かな東屋",
  str_item_intro_5234056 = "涼んだり、休んだりするのにぴったりの場所。何か悩み事があるならば、ここへ来るといい。",
  str_item_3000344 = "薬瓶",
  str_item_intro_3000344 = "いったいいくら集めれば、終わりになるのだろう…",
  str_item_3000345 = "プレイチケット",
  str_item_intro_3000345 = "影ノ街が作ったプレイチケットで見た目はごく普通。今人気の「ブラインドボックス」の指定通貨である。",
  str_item_3661228 = "築炉蟹",
  str_item_3661229 = "帆船の模型",
  str_item_intro_3661228 = "家具。巨像のルーム内に設置できる。\n職人の仕事を手伝うカラクリの動物で、センキョクが自ら製作した。長年の使用で動かなくなってしまっているが、一風変わった置物として飾るのもまた粋である。",
  str_item_intro_3661229 = "家具。巨像のルーム内に設置できる。\n龍州の人々は海に出る帆船に多くの思いを込める。ほぞに銅銭や銅鏡をかませるなど、さまざまな願いを形や物に込め、幸運と航海の無事を祈って船を作る。この船はセンキョクが作った模型にすぎないが、細かい所やそこに込められた思いまで余すところなく表現されている。",
  str_item_3763035 = "治療薬",
  str_item_intro_3763035 = "獲得すると対応するフレームが使用可能になる\n安心してください、あなたを傷つけることはありません……",
  str_item_3751554 = "虚弱",
  str_item_intro_3751554 = "獲得すると対応するアイコンが使用可能になる\n「ゴホゴホ…わ、私は大丈夫…少し安静にしていれば」",
  str_item_3751555 = "あんたに感謝",
  str_item_intro_3751555 = "獲得すると対応するアイコンが使用可能になる\n「今日はあたしのおごり～」",
  str_item_3751405 = "患者への気づかい",
  str_item_intro_3751405 = "獲得すると対応するアイコンが使用可能になる\n「座ってください。私が力になります」",
  str_item_3751406 = "力はすべてを解決する",
  str_item_intro_3751406 = "獲得すると対応するアイコンが使用可能になる\n「誰があんたに借りがあるって？」",
  str_item_3751407 = "海底に眠る遺物",
  str_item_intro_3751407 = "獲得すると対応するアイコンが使用可能になる\n深海に埋もれていた宝物。\n摩耗に抵抗し、海水の浸食に抗ってきた。それもこれもいつの日か再び陸地へ戻るためだ。",
  str_item_3751408 = "センキョクのお誘い",
  str_item_intro_3751408 = "獲得すると対応するアイコンが使用可能になる\n「空の末裔が信じる理念は私の一族と似てるところがあるって聞いたんだけど。どう？鄴の国に来て、一族と交流してみない？」",
  str_item_3751556 = "銅製のカラクリ",
  str_item_intro_3751556 = "獲得すると対応するアイコンが使用可能になる\n「実用性のないカラクリだけど、素敵って思ったなら、それで十分価値があるの」",
  str_item_3751409 = "無数の金貨",
  str_item_intro_3751409 = "獲得すると対応するアイコンが使用可能になる\n「私の資産の100分の1にも満たないけど、ただで手に入るなら、もらわない手はないわ」",
  str_item_3751410 = "シャドウマスターの休み",
  str_item_intro_3751410 = "獲得すると対応するアイコンが使用可能になる\n「もうすぐ祝日か。ならば、少しは楽しもうじゃないか」",
  str_item_3751557 = "チェックメイト",
  str_item_intro_3751557 = "獲得すると対応するアイコンが使用可能になる\n「迷うな。意表を突き、勝利を収めろ」",
  str_item_3751558 = "幸運の金貨",
  str_item_intro_3751558 = "獲得すると対応するアイコンが使用可能になる\n「新しい年幸運に恵まれるであろう君に、幸運の金貨を送ろう」",
  str_item_3763036 = "霧巻く蛇",
  str_item_intro_3763036 = "獲得すると対応するアイコンが使用可能になる\nとぐろをまく霧のヘビが、いつか必ずすべてを飲み込むだろう",
  str_item_3751411 = "お茶にしよう",
  str_item_intro_3751411 = "獲得すると対応するアイコンが使用可能になる\n「3時になったな。お茶にするか」",
  str_item_3751559 = "山桜の彩り",
  str_item_intro_3751559 = "獲得すると対応するアイコンが使用可能になる\n「ヒイロの顔を微かに染め上げたのは、どこかで早咲きした山桜だろう」",
  str_item_3751560 = "ハッピーピザ",
  str_item_intro_3751560 = "獲得すると対応するアイコンが使用可能になる\n「私を満たしてくれるものは食べ物ではない、知識だ」",
  str_item_3751412 = "知的司令官",
  str_item_intro_3751412 = "獲得すると対応するアイコンが使用可能になる\n「光霊の敵は光霊」",
  str_item_3763037 = "櫻花の礼法",
  str_item_intro_3763037 = "獲得すると対応するフレームが使用可能になる\n櫻花一族の血脈が一族に代わって常にヒイロを守り続けた",
  str_item_3751561 = "てぇてぇトラ",
  str_item_3751562 = "甘口",
  str_item_3751563 = "ピリ辛",
  str_item_3751564 = "中辛",
  str_item_3751565 = "アストラ辛",
  str_item_intro_3751561 = "獲得すると対応するアイコンが使用可能になる\n「こんなに可愛くて美味しい力を持ったトラ、思わず抱きしめたくなっちゃう！」",
  str_item_intro_3751562 = "獲得すると対応するアイコンが使用可能になる\n「R・Wにとっては、こんなの辛さのうちに入らない」",
  str_item_intro_3751563 = "獲得すると対応するアイコンが使用可能になる\n「鄴の国ではピリ辛が好まれる。激辛はタンドウには少し行き過ぎだが、料理の腕が抜群の彼女はこの味の良さを理解できる」",
  str_item_intro_3751564 = "獲得すると対応するアイコンが使用可能になる\n「食事は優雅に！カレンは口の中の刺激のせいで白夜の騎士のテーブルマナーを失することがあってはならないと、繰り返し自分に言い聞かせた」",
  str_item_intro_3751565 = "獲得すると対応するアイコンが使用可能になる\n「ア～ア～ア～アストラカラ！これはハッカチョウがチリソースを食べた後にようやく発した最初の言葉だ」",
