  str_item_9997040 = "双生蘭",
  str_item_9997041 = "「氷原」浮遊器",
  str_item_9997042 = "「烈陽」浮遊器",
  str_item_9997043 = "「葉植」浮遊器",
  str_item_9997044 = "「雷霆」浮遊器",
