  str_item_9997047 = "光力魔法箱",
  str_item_intro_9997004 = "戦闘開始時、戦場に包帯を1つ出現させる",
  str_item_intro_9997005 = "戦闘開始時に最大HPの20%のシールドを獲得する。2ターン持続",
  str_item_intro_9997008 = "戦闘開始時にHPが30%未満の場合、ただちに30%まで回復する",
  str_item_intro_9997009 = "ターン開始時、現在のHPの7%を失う。その後周囲2マス内にいる敵に、チーム平均攻撃力の150%のダメージを与える",
  str_item_intro_9997010 = "光霊の能動技ダメージ+50%、能動技を使用するたびに現在のHPの8%を失う",
  str_item_intro_9997011 = "味方が失っているHPの比率にもとづき、連鎖技のダメージが増加する。最大で+40%",
  str_item_intro_9997012 = "現在のHPが70%以上の時、光霊の与えるダメージ+20%",
  str_item_intro_9997013 = "光霊が同時に少なくとも3人の敵を攻撃すると、フィールド全体の敵に雷を落とし、チーム平均攻撃力の100％のダメージを与える",
  str_item_intro_9997014 = "毎ターン開始時、フィールド上のランダムな位置に1つの万色マスを生成する",
  str_item_intro_9997015 = "1回のタップで15マス以上消したとき、光霊の連鎖技ダメージ+30%。消したマスの数が7以下の場合、連鎖技を発動できない",
  str_item_intro_9997016 = "敵との距離が近いほど、光霊の連鎖技のダメージが増加する。最大で+20%",
  str_item_intro_9997017 = "敵との距離が遠いほど、光霊の連鎖技のダメージが増加する。最大で+30%",
  str_item_intro_9997018 = "「ボマー」ジョブの光霊が30%の確率で連鎖技を1回多く発動する",
  str_item_intro_9997019 = "「スナイパー」ジョブの光霊の連鎖技ターゲット+1",
  str_item_intro_9997020 = "戦闘時、「サポーター」ジョブの光霊の連鎖技と能動技の回復効果+25%",
  str_item_intro_9997021 = "戦闘開始時、「チェンジャー」ジョブの光霊の能動技のCD-1",
  str_item_intro_9997023 = "光霊の能動技または連鎖技でダメージを与えると、30%の確率でただちに目標に毒/火傷/出血効果が発現する",
  str_item_intro_9997024 = "敵が状態異常、または弱体化効果を保有しているとき、すべての被ダメージ+20%",
  str_item_intro_9997025 = "死の気配を召喚し、残りHPが7%以下の敵を瞬殺する",
  str_item_intro_9997026 = "タップでマスを消した時、このターンでまだ光霊が連鎖技を使用していなければ、すべての光霊の能動技のCD-1",
  str_item_intro_9997027 = "光霊の余った回復量を一定比率で1スタックのシールドに変換する。1ターン持続",
  str_item_intro_9997028 = "毒/火傷/出血状態を持つ敵を撃破した時、フィールド上の別のランダムな敵に1スタックの毒状態を付与する",
  str_item_intro_9997029 = "陣営のサポートスキルの発動に必要な消去マスの数-5",
  str_item_intro_9997030 = "光霊が能動技を使用した時、絆を持つ光霊の能動技のCD-1",
  str_item_intro_9997031 = "戦闘開始時に使用した最初の能動技、使用後のCD-2",
  str_item_intro_9997033 = "各ターン開始時、戦場のランダムな位置にインジケーターが1個発生する。インジケーターを消すと、そのターン内の連鎖技のダメージ+25%",
  str_item_intro_9997035 = "光霊がダメージを与えた時、2%の吸血効果を得る。各ターン開始時、現在のHPの15％を失う",
  str_item_intro_9997003 = "戦闘勝利後、最大HPの10%を回復する",
  str_item_intro_9997006 = "戦闘勝利後、すべての光霊の最大HP+3%",
  str_item_intro_9997007 = "戦闘勝利後、すべての光霊の防御力+1.5%",
  str_item_intro_9997032 = "戦闘勝利後、すべての光霊の攻撃力+1%",
  str_item_intro_9997022 = "獲得したとき、総ターン数+10 ",
  str_item_intro_9997036 = "タップでマスを消去した時、25%の確率で消去回数が1回増加する",
  str_item_intro_9997037 = "タップでマスを消去した時、消去範囲内の敵に1スタックの毒/出血/火傷効果をランダムに付与する",
  str_item_intro_9997038 = "タップでマスを消去した時、消去範囲内の敵にチーム平均攻撃力の120%のダメージを与える",
  str_item_intro_9997034 = "このターン、タップして消去したエリア内を敵が1マス移動するごとに、チームの平均攻撃力の150%のダメージを受ける",
  str_item_intro_9997039 = "戦闘開始時、ランダムな空の末裔の特殊装備1つの使用回数が1回増える",
  str_item_intro_9997040 = "空の末裔の特殊装備を獲得：選択した2マスを万色マスに変える。60マス消去するごとに使用回数を1回獲得する",
  str_item_intro_9997041 = "空の末裔の特殊装備を獲得：選択した3×3範囲内の水属性マスを消去する。50マスを消去するごとに使用回数を1回獲得する",
  str_item_intro_9997042 = "空の末裔の特殊装備を獲得：選択した3×3範囲内の火属性マスを消去する。50マスを消去するごとに使用回数を1回獲得する",
  str_item_intro_9997043 = "空の末裔の特殊装備を獲得：選択した3×3範囲内の森属性マスを消去する。50マスを消去するごとに使用回数を1回獲得する",
  str_item_intro_9997044 = "空の末裔の特殊装備を獲得：選択した3×3範囲内の雷属性マスを消去する。50マスを消去するごとに使用回数を1回獲得する",
  str_item_intro_9997045 = "空の末裔の特殊装備を獲得：フィールド上のすべてのマスをリセットする。80マスを消去するごとに使用回数を1回獲得する",
  str_item_intro_9997046 = "空の末裔の特殊装備を獲得：フィールド上の選択した属性のマスをすべてリセットする。80マスを消去するごとに使用回数を1回獲得する",
  str_item_intro_9997047 = "空の末裔の特殊装備を獲得：選択した1マスから最も近い同属性のマス4個を消去する。60マスを消去するごとに使用回数を1回獲得する",
  str_item_rpintro_9997004 = "回復薬の補助品。戦闘員の傷を効率よく癒すことができる",
  str_item_rpintro_9997005 = "昔の勇士がよく使っていた武器。過去の祝福が未だに憑依しており、俊敏な敵に立ち向かう際に使うと効果抜群",
  str_item_rpintro_9997008 = "完璧に保存された彫像。身につけた者に治癒の力をもたらす",
  str_item_rpintro_9997009 = "旧時代の産物。使用者に呪いをかける一方で、それに応じた力を与えてくれる",
  str_item_rpintro_9997010 = "壊滅的な戦争の中で生まれた不思議な品だと言われている。強い呪いの力があり、敵に重傷を与えられる",
  str_item_rpintro_9997011 = "身にまとうと痛みが力に変わり、最終的には勝利へと導いてくれる",
  str_item_rpintro_9997012 = "これを持っていると、あなたも勝利の女神のご加護を受けられる。戦闘では常に優勢を得られるだろう",
  str_item_rpintro_9997013 = "旧時代の名刀。雷霆の力が封印されており、抜くと瞬時に暴走し、敵を消滅する",
  str_item_rpintro_9997014 = "ありとあらゆる色を持つ宝石。美しくまぶしい光を放つ",
  str_item_rpintro_9997015 = "旧時代の大剣。握りしめると、体内の力が増していくのを感じられる",
  str_item_rpintro_9997016 = "昔の勇士がよく使っていた武器。過去の祝福が未だに憑依しており、俊敏な敵に立ち向かう際に使うと効果抜群",
  str_item_rpintro_9997017 = "昔の勇士がよく使っていた武器。過去の祝福が未だに憑依しており、俊敏な敵に立ち向かう際に使うと効果抜群",
  str_item_rpintro_9997018 = "古の短剣。旧時代の高強度合金を使っているため、かなり鋭い",
  str_item_rpintro_9997019 = "戦闘中、レンズは相手を盲目状態にできるほどの眩しい光を放つと同時に、装着者の両目を守る。サポート性の高い装備",
  str_item_rpintro_9997020 = "旧時代のペンキ。光力の吸収に優れている",
  str_item_rpintro_9997021 = "旧時代の産物。美しい見た目をしているが、恐ろしい力を宿しており、敵を散りゆく花びらのように爆発に巻き込む",
  str_item_rpintro_9997023 = "旧時代の遺物。強烈な呪いがかかっているらしく、これを装備した者が毒を扱うとかなり有利になる",
  str_item_rpintro_9997024 = "旧時代の名刀。これを振ると神にも劣らない力を感じるという",
  str_item_rpintro_9997025 = "この小さな彫像は敵の命の気配を感じ取ることができ、これを身につけると虫の息の敵を瞬く間に消せる",
  str_item_rpintro_9997026 = "体にフィットするベルト。起動条件を満たしている場合、着用者に必要な光力を提供してくれる",
  str_item_rpintro_9997027 = "旧時代が遺した謎の装置。溢れた光力を感じ取ることができ、それを利用して装着者を守る力場を展開できる",
  str_item_rpintro_9997028 = "強力な戦士の手で作られたと言われている呪物。敵は死の運命から逃れられない",
  str_item_rpintro_9997029 = "旧時代のお守り。ミクロ単位で光力コネクトを果たすことができ、敵に莫大なダメージを与えることが可能",
  str_item_rpintro_9997030 = "旧時代の産物。絆で結ばれた光霊の光力を一定程度回復できる",
  str_item_rpintro_9997031 = "旧時代の産物。使用後、失った光力の一部を素早く補充できる",
  str_item_rpintro_9997033 = "光力を保存するための装置。これを解放すると、失われた光力をチャージすることができる",
  str_item_rpintro_9997035 = "邪悪な気配がする刀。上古時代は激戦に使われていた武器らしく、この刀が抜かれる時は必ず血飛沫が舞い散る",
  str_item_rpintro_9997003 = "暖かい光を発する蝋燭。その光には光霊の傷を癒す力が宿っている",
  str_item_rpintro_9997006 = "旧時代が遺した小さな彫像。高強度の材料で作られており、丈夫で軽い。装備した者に祝福も与えるという",
  str_item_rpintro_9997007 = "旧時代の古き盾。完璧な曲線を描いている。太陽の力が注入されているらしく、光力があらゆる致命的な攻撃から守ってくれるとのこと",
  str_item_rpintro_9997032 = "旧時代の勲章。不思議な構造をしている。ミクロ単位で光力コネクトを果たすことができ、戦闘力を高める",
  str_item_rpintro_9997022 = "誰かが残していった折り畳み寝袋。体力の回復に最適",
  str_item_rpintro_9997036 = "古代の学者が遺した手書き原稿。属性間の相性関係について詳しく記載している。相性を考慮した戦略を立てられるよう、戦闘員を指導できる",
  str_item_rpintro_9997037 = "無名の画家が大昔に描き上げた絵画。疫病が流行っていた頃の惨状を描いており、作者自身もこの病で逝去している。そのせいか、この絵にも恐ろしい力が宿るようになった",
  str_item_rpintro_9997038 = "光力を完璧に融合できると思われる武器…まさに希少な逸品",
  str_item_rpintro_9997034 = "旧時代の産物。追手に対抗する場面に適している。秘められた光力は路線上に残り、一定時間後に爆発し、追ってくる敵に大ダメージを与える",
  str_item_rpintro_9997039 = "古の神秘的な硬貨。これを持った光霊はまれに力が増幅し、行動がより俊敏になる",
  str_item_rpintro_9997040 = "この希少な赤色の蘭は旧時代が特殊な栽培方法を以て育てた品種。必ず対をなして現れ、対をなして咲き誇り、対をなして散る。これを身につけた者たちは不思議な力によって繋がり、協調性が高まる",
  str_item_rpintro_9997041 = "旧時代の産物。巨像の小さいバージョンに見える。戦闘中は主のサポートを担当する。",
  str_item_rpintro_9997042 = "旧時代の産物。巨像の小さいバージョンに見える。戦闘中は主のサポートを担当する。",
  str_item_rpintro_9997043 = "旧時代の産物。巨像の小さいバージョンに見える。戦闘中は主のサポートを担当する。",
  str_item_rpintro_9997044 = "旧時代の産物。巨像の小さいバージョンに見える。戦闘中は主のサポートを担当する。",
  str_item_rpintro_9997045 = "旧時代の産物。二人の戦士の間に不思議な連携作用をもたらす",
  str_item_rpintro_9997046 = "表面に細かい亀裂が入っている粗い水晶。これは溢れんばかりの光力を秘めていることを意味しており、軽く触れただけで敵を眩暈させるほどの力を放つ",
  str_item_rpintro_9997047 = "旧時代の技術。小さく見えるが、大量の光力を保存できる",
  str_item_3000349 = "浮遊商会コイン",
  str_item_intro_3000349 = "浮遊商会のボーナスコイン。お得意様だけがもらえる。",
  str_item_3000134 = "貪欲な毒蛇特別召集星標",
  str_item_intro_3000134 = "【貪欲な毒蛇】限定召集で1回召集できる\nこのアイテムは期間限定アイテムです。【貪欲な毒蛇】限定召集が終了するまでにお使いください。期限を過ぎると、他のアイテムに変換されることなく消失します",
  str_item_3420133 = "2.5周年記念特選召集ボックス",
  str_item_intro_3420133 = "指定の★6光霊リストから、1名の光霊を選び、仲間にすることができます。以下の光霊が選択可能です：<color=#ffffff>タンドウ/ザーリャ/アントニー/ローレライ/セナ/ヨシュア/ソルラド・響鳴/インゲル/レオ/ハーティ/ティナ/ライン/イェリア/ユエ/シュウ/ヴィック/アクセリア/リリカ/ミノス/ポルクス/ジェノ/フィア/カレン・照魂/ニナ/バートン・鋭刃/ギルス/レノーア/アズール/ヨウ/アメモリ/リンネ/フロリナ/ルビー/シヴォーン/ノーヴィオ/ヘイディ/ベセル/ルーク/パロマ/グラム/レビィ/スモーキー/フェラール/ベリエ/ヒイロ/サメヤマ/イブ/ウリエル/カレン/キシローナ/シャリー/ラファエル/クラリン/カロン/エルシー/ビクトリア/ジョナ/ナシリス/ガブリエル/ミジャード/ミカエル/ガルー/イルンティ/ラス</color>\n注意：2.5周年記念特選召集ボックスには使用期限があります。期限を過ぎると自動的に3000光珀に変換され、ゲーム内メールにて送付されます。使用期限は2024年2月28日18:00です。期限までにご使用ください。",
  str_item_3661231 = "シャドウの椅子",
  str_item_intro_3661231 = "家具。巨像のルーム内に設置できる。\n硬い革で造られた、覇気あふれる豪華な椅子。浮遊商会がイスタバンのために作った。ゆえに同じデザインの椅子は高価ながら、常によく売れている",
  str_item_3661232 = "浮遊商会艇の模型",
  str_item_intro_3661232 = "家具。巨像のルーム内に設置できる。\n浮遊商会が造った観光、ショッピング、レジャー、バカンスなどが楽しめる多目的施設「浮遊商会艇」。もちろん、さまざまな大きさの模型も販売している。これは一番大きなモデルではないが、造りは最も精巧である",
  str_item_3661233 = "微かな光",
  str_item_intro_3661233 = "家具。巨像のルーム内に設置できる。\n幾列ものライトが暗闇を照らす。記念すべきこの日、この微かな光があなたの元へ暖かさを届けてくれますように",
  str_item_3661234 = "聖夜の贈り物",
  str_item_intro_3661234 = "家具。巨像のルーム内に設置できる。\n光霊たちから届いた贈り物。高価なものではないが、彼らの気持ちと努力が詰まっている。この贈り物が新しい一年の幸運をもたらしてくれますように",
  str_item_5234057 = "氷の馬車",
  str_item_intro_5234057 = "氷で造られた観覧馬車。輝く透明な車体は人の心を和ませてくれる",
  str_item_3661236 = "着せ替え剣士",
  str_item_3661237 = "舟の上の剣士",
  str_item_3661241 = "ブール扇風機",
  str_item_3661242 = "植物ライト",
  str_item_intro_3661236 = "家具。巨像のルーム内に設置できる。\nある機巧師が造った着せ替えカラクリ人形。ボタンを押すと、ランダムで人形の着せ替えができる。龍州のある演芸から着想を得て、造られたという。\n「龍州人に扮するには…早着替えの技も習得しなくてはいけないのでしょうか？」",
  str_item_intro_3661237 = "家具。巨像のルーム内に設置できる。\nある機巧師が剣士との協力の成功を記念して、任務中の剣士の姿をモデルに造った肖像。\n「反対側に空席をつくっておいてほしい？いいわよ。誰か乗せたい人ができたら、いつでも言ってね」",
  str_item_intro_3661241 = "家具。巨像のルーム内に設置できる。\n啓光の科学者の実験室専用扇風機。スタンドが自由に曲がり、また、どこにでも貼り付けられる。「ブール」と言う名のロボットからインスピレーションを得て造られたという。",
  str_item_intro_3661242 = "家具。巨像のルーム内に設置できる。\n巧妙な設計の照明器具。植物の生長に必要な光を提供してくれるだけでなく、室内を暖かい大自然の雰囲気で満たしてくれる。",
  str_item_3000352 = "空の末裔の羽",
  str_item_intro_3000352 = "ユニークな姿をした羽。空の末裔内で高い価値を持っていたらしい",
  str_item_3661243 = "ギョーザソファー",
  str_item_3661244 = "版画・辰",
  str_item_3661238 = "爆竹の飾り",
  str_item_3661239 = "新年の飾り",
  str_item_3661240 = "古典的な棚",
  str_item_intro_3661243 = "家具。巨像のルーム内に設置できる。\nギョーザの形をしたビーズクッション。もともとは音声装置が内蔵されており、以下のセリフを再生していた。\n「ギョーザギョーザギョーザ！」\n「みんなで一緒にギョーザを作ろう！」\nしかし、一部の光霊がうるささに不満を抱いたために装置が取り外され、巨像に静けさが戻った",
  str_item_intro_3661244 = "家具。巨像のルーム内に設置できる。\n龍女が彫られた版画。済の国では縁起のいい新年の品としてとても人気がある。ただし、龍女の本当の姿を現しているものは、シンゲイが送ってくれたこの「アート写真」しかない",
  str_item_intro_3661238 = "家具。巨像のルーム内に設置できる。\n龍州の伝統的な祭りがもうすぐ始まる。巨像にいる龍州の仲間たちに祭りの雰囲気を感じてもらうべく、皆は一緒に作った爆竹の飾りを持ってきた。この飾りが縁起の悪い出来事をすべてはらい、来年は幸運続きとなることを願っている",
  str_item_intro_3661239 = "家具。巨像のルーム内に設置できる。\n現在、双閣港の店で飛ぶように売れている品。龍州大陸では新年や節句を過ごすときに必ず飾る品の1つ。未来への素晴らしい希望を象徴している",
  str_item_intro_3661240 = "家具。巨像のルーム内に設置できる。\n双閣港の職人が誇りとする作品。精巧な木彫りと素晴らしいデザインが特徴。小物の収納やそのユニークな作りを鑑賞するのに適している。巨像に設置すれば、室内の古典的な雰囲気が増すこと間違いなし",
  str_item_intro_3763039 = "獲得すると対応するフレームが使用可能になる\n桃の夭夭たる、灼々たり其の華。桃花正印にありて、幸運到来す。",
  str_item_intro_3751417 = "獲得すると対応するアイコンが使用可能になる\n「空の末裔は、新年に特別な帽子をもらった。さっそく嬉しそうにかぶっている！」",
  str_item_intro_3751566 = "獲得すると対応するアイコンが使用可能になる\n「わらわ加護を授ければ、百禄多福なり！」\n海を護る神とされる龍女は、果たして人々に俗世の幸せを授けられるのだろうか？それでもシンゲイは試してみたい！",
  str_item_intro_3751567 = "獲得すると対応するアイコンが使用可能になる\n「僕の舌こそ基準だ！」\nアストラの大使となったナビゲーター。料理の品評も、経験豊かな彼にはお手の物。なかなか好みがうるさい。",
  str_item_intro_3763038 = "獲得すると対応するフレームが使用可能になる\n「すべてのカードを集めれば、神龍を召喚できる！」\n本当に龍を召喚できるかどうかはともかく、カード集めは龍州の新年に新しい楽しみをもたらした。",
  str_item_intro_3751413 = "獲得すると対応するアイコンが使用可能になる\n「浮空島にあるという大きなカラクリの甲冑、砂漠とやらで催される歌と舞の祭り、それから地の下で行われる武術の手合わせ…わらわも見てみたいの…」\n新年には、神様もたくさんの願い事をする。",
  str_item_intro_3751414 = "獲得すると対応するアイコンが使用可能になる\n角の生やした猛獣が人を食らう！影ノ街に年獣が！？影ノ街アリーウッド作品『縁日～行ってはいけない』、絶叫と共に春新節ロードショー！\n「で…何役を演じればいいんだ…？」",
  str_item_intro_3751415 = "獲得すると対応するアイコンが使用可能になる\n「はい、これ。テキトーに作ったの…私だってアイスキャンディ以外のもの作れるのよ！」\nザーリャが何度も失敗したすえに、ようやく完成した唯一の力作。こめた気持ちの分だけ、甘みも増してある。",
  str_item_intro_3751416 = "獲得すると対応するアイコンが使用可能になる\n今日のこの集まりが「家」の温かみをもたらしてくれますように。どこにいようと、私たちは同じ空を見上げている。",
  str_item_intro_3751568 = "獲得すると対応するアイコンが使用可能になる\n「いろんな人から好かれるけど、キミは特別だよ。俺たちは本当に通じ合ってるな！」",
  str_item_intro_3751569 = "獲得すると対応するアイコンが使用可能になる\n「ハ、ハートのポーズ！？…いいわ。私の気持ち、感謝して受け取って…でも、いい気にならないでよ！」",
  str_item_3763039 = "恋愛運",
  str_item_3751417 = "龍の帽子と空の末裔",
  str_item_3751566 = "辰年の龍州の龍女",
  str_item_3751567 = "美食大使",
  str_item_3763038 = "龍の舞う新春",
  str_item_3751413 = "新年の願い事",
  str_item_3751414 = "新春ロードショー",
  str_item_3751415 = "スイート・スイート",
  str_item_3751416 = "大家族",
  str_item_3751568 = "フェラールの気持ち",
  str_item_3751569 = "ザーリャの気持ち",
  str_item_3763041 = "千日の冠",
  str_item_3751420 = "冠月騎士の日",
  str_item_3751419 = "千の昼夜を越えて",
  str_item_3751570 = "燃焼する浄界",
  str_item_3763040 = "最後の火の光",
  str_item_3751421 = "千日の心",
  str_item_3751422 = "恋心が射落とされる日",
  str_item_intro_3751421 = "獲得すると対応するアイコンが使用可能になる\n「ナビゲーター、こっちを見て！」\n千日の航海では、常に愛が伴う。これからも皆の祝福を受け、前進し続けよう！",
  str_item_intro_3751422 = "獲得すると対応するアイコンが使用可能になる\n「行動を起こしましょう。今日が運命を決める時かもしれません！」",
  str_item_intro_3763041 = "獲得すると対応するフレームが使用可能になる\n「揺るぎない者に栄光あれ！」\n千日頑張り続け、千日連れ添ってきました。あなたの導きと見守りに感謝し、今後も共に歩み続けることを楽しみにしています",
  str_item_intro_3751420 = "獲得すると対応するアイコンが使用可能になる\n「参加されますか？冠月祭の特別裁判に」",
  str_item_intro_3751419 = "獲得すると対応するアイコンが使用可能になる\nこの空の下で私たちと千日の時間を共にしてくれたあなたに感謝します。ナビゲーター、これからもよろしくお願いします。",
  str_item_intro_3751570 = "獲得すると対応するアイコンが使用可能になる\n「私と一緒に浄界に沈んでくれる？それなら……ほら、手をとって。一緒に希望を燃やしましょう」",
  str_item_intro_3763040 = "獲得すると対応するフレームが使用可能になる\n「魔薬の効果が切れて、この身が炎と化しても…あなたは残り火をたどって、私を見つけてくれる？」",
  str_item_3751042 = "同業者からのメッセージ",
  str_item_3751043 = "鍛錬の成果",
  str_item_3751044 = "真理はすぐそこに",
  str_item_3751045 = "旅の守護",
  str_item_3751046 = "茶会の常連",
  str_item_3751047 = "私の物語",
  str_item_3751048 = "戦友たち",
  str_item_3751573 = "かくれんぼ狐",
  str_item_3763042 = "グワグワッ",
  str_item_intro_3751042 = "獲得すると対応するアイコンが使用可能になる\n「わかってるよ。ナビゲーターって大変だよね。これからも頑張ろうね」",
  str_item_intro_3751043 = "獲得すると対応するアイコンが使用可能になる\n「こんな長いこと続くとはな。たいしたもんだぜ。これからも一緒に鍛えようぜ！」",
  str_item_intro_3751044 = "獲得すると対応するアイコンが使用可能になる\n「覚えておくのよ。どれだけ時が移り変わろうとも、真理は永遠に共にある」",
  str_item_intro_3751045 = "獲得すると対応するアイコンが使用可能になる\n「これからの旅路も、あなたをお守りいたします」",
  str_item_intro_3751046 = "獲得すると対応するアイコンが使用可能になる\n「もう何度お茶をおもてなししたことかしら？」",
  str_item_intro_3751047 = "獲得すると対応するアイコンが使用可能になる\n「私の物語はこれで終わりだ。そなたの物語は？」",
  str_item_intro_3751048 = "獲得すると対応するアイコンが使用可能になる\n「もう長い付き合いではないか。兄弟も同然だろう！」\n",
  str_item_intro_3751573 = "獲得すると対応するアイコンが使用可能になる\n「ちゃんと隠れた？まだだよ」",
  str_item_intro_3763042 = "獲得すると対応するフレームが使用可能になる\n「すごく見慣れた感じだね」",
  str_item_intro_3751423 = "獲得すると対応するアイコンが使用可能になる\n「グ↗ワッ↘グ↗ワッ—」",
  str_item_intro_3751424 = "獲得すると対応するアイコンが使用可能になる\n「どうしようかな…答えは、私の中にあったりして？」",
  str_item_3751423 = "カエル王子",
  str_item_3751424 = "灯台の照らす答え",
  str_item_3440014 = "がま口のお楽しみ袋",
  str_item_intro_3440014 = "「私」はただの哀れなカエル、一生の蓄えをあなたにあげる",
  str_item_intro_3440015 = "超お得な福袋の中身はだいたいサギだ",
  str_item_intro_3440016 = "運がどんどん良くなっていく。まるで私の人生のよう",
  str_item_intro_3440017 = "もう一度引いてみよう。もうすぐ天井な気がする",
  str_item_intro_3440018 = "このお楽しみ袋を引いたら、タップして戻って、画面を閉じて、ゲームをやめるんだ",
  str_item_3751574 = "推しのゴルディ",
  str_item_intro_3751574 = "獲得すると対応するアイコンが使用可能になる\n「すべての視線を集める彼女こそ、パーフェクトでキラキラしたアイドルだ」",
  str_item_3751425 = "アイドルの眠気",
  str_item_intro_3751425 = "獲得すると対応するアイコンが使用可能になる\n「ふわぁ～、パジャマを着ると、つい眠くなっちゃう」",
  str_item_3763043 = "推しの綿あめ",
  str_item_intro_3763043 = "獲得すると対応するアイコンが使用可能になる\n「ふんわりモコモコ姿の彼女は元気いっぱい、可愛らしさ満点！またひとり虜になる」",
  str_item_3751572 = "父の行方",
  str_item_intro_3751572 = "獲得すると対応するアイコンが使用可能になる\n「父よ、どこに行くのか教えてください」",
  str_item_3751571 = "ほほ笑みの祝福",
  str_item_intro_3751571 = "獲得すると対応するアイコンが使用可能になる\n「この部品を父に贈ります。父の表情が画面の中と同じになることを祈っています」",
  str_item_3751429 = "ボーンへのあいさつ",
  str_item_intro_3751429 = "獲得すると対応するアイコンが使用可能になる\n「やあ、ボーン！温かい巨像は心が折れた労働者を全員受け入れているよ」",
  str_item_3751430 = "勲章と栄誉",
  str_item_3751577 = "ホークアイ小隊、集合！",
  str_item_3751578 = "カーニバルフラワー",
  str_item_3751579 = "千代の春",
  str_item_3763046 = "願いの組みひも",
  str_item_3763047 = "鯉のぼり",
  str_item_intro_3751430 = "獲得すると対応するアイコンが使用可能になる\n「よし、今日も栄誉を汚すことはなかった」",
  str_item_intro_3751577 = "獲得すると対応するアイコンが使用可能になる\n「眼差しはタカのごとし、攻撃は鋭い爪のごとく、その動きたるはまさに翼を得たごとし」",
  str_item_intro_3751578 = "獲得すると対応するアイコンが使用可能になる\n「カーニバルを楽しみましょう。ほら、一緒に言って！」",
  str_item_intro_3751579 = "獲得すると対応するアイコンが使用可能になる\n「この先、天地万物、四方八方、見るもの会うものすべてが願いにかない、100年先も1000年先も栄えんことを」",
  str_item_intro_3763046 = "獲得すると対応するフレームが使用可能になる\n「おぬしが順風満帆、万事順調、志成就、不撓不屈であらんことを。わらわと共に面白き時を過ごせるように」",
  str_item_intro_3763047 = "獲得すると対応するフレームが使用可能になる\n雲島に伝わる儀式的意味を持つ旗。成長と勇気を象徴している",
  str_item_3751581 = "感動の味",
  str_item_3751582 = "おいしいケーキ",
  str_item_3751580 = "「秘密の牙」のオーナー",
  str_item_intro_3751581 = "獲得すると対応するアイコンが使用可能になる\n「キャロ～これが…人間に愛される味キャロ？」",
  str_item_intro_3751582 = "獲得すると対応するアイコンが使用可能になる\n「一口味見…うんうん、もう一口！」",
  str_item_intro_3751580 = "獲得すると対応するアイコンが使用可能になる\n「影ノ街のゲームセンター、『秘密の牙』のオーナーだ。ゲームの世界へようこそ」",
  str_item_3751436 = "毅然とした眼差し",
  str_item_3751583 = "反逆の炎",
  str_item_3751584 = "上客来訪",
  str_item_3751585 = "我らの友情に乾杯",
  str_item_3763048 = "啓光の未来を展望する",
  str_item_3763049 = "秘密の墓の鍵",
  str_item_intro_3751436 = "獲得すると対応するアイコンが使用可能になる\n「お前たちがいて実によかった！」",
  str_item_intro_3751583 = "獲得すると対応するアイコンが使用可能になる\n「より強くならねば。頂点に立つ光霊よりも、強く。」",
  str_item_intro_3751584 = "獲得すると対応するアイコンが使用可能になる\n「たとえ今日死ぬとしても、君の本性をこの目で見てやる。」",
  str_item_intro_3751585 = "獲得すると対応するアイコンが使用可能になる\n「彼と仲良くしたいのならそれは構わないが、もっと敬意を以て接することだ。何しろ――彼はこのレインハトの客人なのだから。」",
  str_item_intro_3763048 = "獲得すると対応するアイコンが使用可能になる\n「心配するな。万物は変化する。中には失意に陥るような変化もあるだろう。だが少なくとも私は――人を奮い立たせる変化のほうが多いと見ている。」",
  str_item_intro_3763049 = "獲得すると対応するアイコンが使用可能になる\n「ほのかなロウソクの光で、中の見えない箱が守る秘密をのぞくことはできるのかしら？」",
  str_item_3751438 = "真理洞察",
  str_item_3751586 = "神聖なる啓示を受けし者",
  str_item_3763050 = "輝かしい道のり",
  str_item_intro_3751438 = "獲得すると対応するアイコンが使用可能になる\n「真理とは、あのはるか遠くに光る星を追うように、心の目をもってこそ見えるもの」",
  str_item_intro_3751586 = "獲得すると対応するアイコンが使用可能になる\n「私はざんげします！罪をあがないます！私は――真理の祝福を受けた者です」",
  str_item_intro_3763050 = "獲得すると対応するフレームが使用可能になる\n「真理の祝福あれ。これからの人生が輝かんことを」",
  str_item_3751426 = "ライザのひらめき",
  str_item_3751427 = "クラウディアの微笑み",
  str_item_3751428 = "意地っ張りパティ",
  str_item_3751575 = "新たな冒険へ",
  str_item_3751576 = "輝く夏の花",
  str_item_3751587 = "野望の海軍王",
  str_item_3751588 = "水上ドローン",
  str_item_3763044 = "スパークルレヴァリエ",
  str_item_3763045 = "潮風のきらめき",
  str_item_3763051 = "胸いっぱいの夏",
  str_item_3763052 = "富と名誉の追求",
  str_item_3763053 = "誓いを守る者",
  str_item_3751444 = "試合を楽しもう",
  str_item_3751443 = "海の精霊",
  str_item_3751589 = "おとぎ話のお姫様",
  str_item_3751594 = "冥界の狩猟神",
  str_item_3751593 = "黄金に輝くヘビ",
  str_item_3751592 = "誓約の読者",
  str_item_3751591 = "祭剣座",
  str_item_intro_3751594 = "獲得すると対応するアイコンが使用可能になる\n「黒き翼はステュクスの空を切り裂く刃！」",
  str_item_intro_3751593 = "獲得すると対応するアイコンが使用可能になる\n「ビジネスの話も、遊びの話も、十分な報酬さえあれば、すべてお応えしますわ！」",
  str_item_intro_3751592 = "獲得すると対応するアイコンが使用可能になる\n「千年の誓いは忘れてはならない。ロンギヌス一族の願いは、英雄の偉業を果たした者に捧ぐべきもの」",
  str_item_intro_3751591 = "獲得すると対応するアイコンが使用可能になる\n「敵は必ず殺す。わが剣で星々の物語を守る」",
  str_item_intro_3763052 = "獲得すると対応するフレームが使用可能になる\n「富は人の目を眩ます！」",
  str_item_intro_3763053 = "獲得すると対応するフレームが使用可能になる\n「黒き翼は千年の誓いを守り続ける！」",
  str_item_intro_3751444 = "獲得すると対応するアイコンが使用可能になる\n「見て見て、みんな一番になるために頑張ってるよ！試合を楽しみながら、選手たちを応援しようよ！」",
  str_item_intro_3751443 = "獲得すると対応するアイコンが使用可能になる\n「マヤは水が大好きだし、泳ぐのも大好き！試合に参加してみようかな。みんなと一緒に楽しみたい！」",
  str_item_intro_3751589 = "獲得すると対応するアイコンが使用可能になる\n「マヤはこんな夢を見たかったの。この世界から悲しみがなくなって、みんなが幸せに暮らしている夢を……」",
  str_item_intro_3751426 = "獲得すると対応するアイコンが使用可能になる\n「これ、なにかな？ワクワクするよ…」",
  str_item_intro_3751427 = "獲得すると対応するアイコンが使用可能になる\n「おかえりなさい、冒険はどうだった？楽しい話が聞けるかな」",
  str_item_intro_3751428 = "獲得すると対応するアイコンが使用可能になる\n「あっ…すみません。お恥ずかしい姿をお見せしてしまいました。もう一度やり直します」",
  str_item_intro_3751575 = "獲得すると対応するアイコンが使用可能になる\n「新たな冒険へ、しゅっぱーつ！」",
  str_item_intro_3751576 = "獲得すると対応するアイコンが使用可能になる\n「夏はやっぱり友達と過ごすのが一番だね～！」",
  str_item_intro_3751587 = "獲得すると対応するアイコンが使用可能になる\n「陸地を制する者に、海くれえ何でもねえ…よな？」",
  str_item_intro_3751588 = "獲得すると対応するアイコンが使用可能になる\n「ピピッ。水上航行モードを起動…」",
  str_item_intro_3763044 = "獲得すると対応するフレームが使用可能になる\n「その光を浴びると、周囲にいる人々の心まで明るくなる」",
  str_item_intro_3763045 = "獲得すると対応するフレームが使用可能になる\n「アストラに来られたことが、この夏の嬉しい贈り物！」",
  str_item_intro_3763051 = "獲得すると対応するフレームが使用可能になる\n「思わず海に飛び込みたくなるオシャレな浮き輪。短い夏を逃すわけにはいかない。さあ、今すぐ飛び出そう！浮き輪と共にこの夏をその胸に！」",
  str_item_3661248 = "古代英雄の肖像",
  str_item_3661249 = "古代将校の肖像",
  str_item_intro_3661248 = "家具。巨像のルーム内に設置できる。\n最近発掘された古代の彫像。服装と頭の飾りからして、古代に賞賛された平民の戦士の像のようだ。考古学者によれば、この時代では通常、自分の彫像を作る権利を持っていたのは貴族だけだそうだ。このことから、この戦士が著しい戦功を立て、人々が彼のためにこの彫像を作ったことが分かる。\n「彼女が愛した世界は、私が守る！」",
  str_item_intro_3661249 = "家具。巨像のルーム内に設置できる。\n最近発掘された古代の彫像。服装と頭の飾りからして、軍隊で高位の将校の像のようだ。考古学者によれば、この時代の軍隊の将校はほとんどが貴族出身で、この彫像はもう1体の平民の戦士の彫像と異なり、貴族お抱えの彫刻家によって作られた可能性が高いそうだ。\n「次は、私に任せて。」",
  str_item_3661250 = "雪狐の彫刻",
  str_item_3661251 = "マツの燭台",
  str_item_3661252 = "ロビンの本棚",
  str_item_3661253 = "荘厳な音響装置",
  str_item_3661254 = "やすらぎのテーブル",
  str_item_intro_3661250 = "家具。巨像のルーム内に設置できる。\n北境でとても愛されている彫刻。モデルは北境の護衛だった人物で、戦いで犠牲になった大切な仲間を想い、作られたのだという。",
  str_item_intro_3661251 = "家具。巨像のルーム内に設置できる。\n上等なマツ材を使い作られた趣のある燭台。上品な香りが安らかな眠りへと誘ってくれる。",
  str_item_intro_3661252 = "家具。巨像のルーム内に設置できる。\nシンプルなデザインの本棚。上質な木材がほのかな香りを放つ。",
  str_item_intro_3661253 = "家具。巨像のルーム内に設置できる。\n荘厳なシーンで使うのに適した雅な音響装置。この音響装置から流れてくる音楽の多くは。儀式や式典で流れる音楽の類であり、アンシアが聞き慣れた、騒がしいヘヴィメタルではない",
  str_item_intro_3661254 = "家具。巨像のルーム内に設置できる。\nデザインが美しいだけでなく、お手頃なテーブル。都市の住民も穏やかな1日を過ごせる。どこでも大人気の商品である。",
  str_item_3661256 = "レトロな掛け時計",
  str_item_3661257 = "装飾画「月夜」",
  str_item_3661258 = "ビーグルぬいぐるみ",
  str_item_3661260 = "R・WのBBQグリル",
  str_item_intro_3661256 = "家具。巨像のルーム内に設置できる。\n時計の枠は精巧な金属で作られ、表面は特殊な加工が施されている。長い年月の蓄積を感じさせるブロンズの光沢が美しい。",
  str_item_intro_3661257 = "家具。巨像のルーム内に設置できる。\n美しい装飾画。神秘的な夜空を背景に、月が画面の真ん中で優しい光を放っている。",
  str_item_intro_3661258 = "家具。巨像のルーム内に設置できる。\nビーグル犬のぬいぐるみ。その目はまるで「あ、それ欲しい。やった、もらえた」と言っているようだ。",
  str_item_intro_3661260 = "家具。巨像のルーム内に設置できる。\nR・Wのキャンプでよく見られるバーベキューグリル。スクラップを集めて作ったものではあるが、これで焼き上げると、食材はこの上なくおいしくなる！――少なくともR・Wのメンバーはそう思っている。",
  str_item_3661265 = "優雅な旅人の肖像",
  str_item_3661266 = "ニンジンのオバケの像",
  str_item_intro_3661265 = "家具。巨像のルーム内に設置できる。\n言い伝えでは、ある旅人がある甘い土地に「フォーチュンタウン」という町を作った。そこには食べきれない程のハチミツや飲み切れない程のミルクがあるという…\n「その町、いったいどこにあるの？まさか…もう一つの世界？」",
  str_item_intro_3661266 = "家具。巨像のルーム内に設置できる。\nニンジン嫌いの子どもたちにとって、ニンジンは恐ろしい牙と爪を持ち、目には異様な光がひかっていて…暗鬼よりも恐ろしい存在なのだろうか？\n「キャキャキャ…私は可哀想なニンジンにすぎないよ、キャキャ…」",
  str_item_3661267 = "レトロなアーケードゲーム",
  str_item_intro_3661267 = "家具。巨像のルーム内に設置できる\n「巨像で暮らすなら、これは持っていかなきゃ…でなきゃ生きていけない」\n仲間の頼みとあっては、ナビゲーターは当然運ぶのを手伝ってあげないと。その代償に肉離れを起こそうとも。",
  str_item_3661268 = "ドット絵サングラスの壁飾り",
  str_item_intro_3661268 = "家具。巨像のルーム内に設置できる\n「インゲル、あんたの負け。戦利品は置いていって」\nインゲルから勝ち取った戦利品は、とあるゲームのグッズのようだ。",
  str_item_3661271 = "ドール収納ボックス",
  str_item_intro_3661271 = "家具。巨像のルーム内に設置できる。\nうっかり者のドールコレクターにとっての、この世で最も偉大なる発明。",
  str_item_3661272 = "猫脚掛け時計",
  str_item_intro_3661272 = "家具。巨像のルーム内に設置できる。\n萌えの最高峰こと猫の肉球の掛け時計。触るとふわふわもちもちだ！壁に掛けないといけないという欠点にも目をつぶれる…",
  str_item_3661273 = "新人講演台",
  str_item_intro_3661273 = "家具。巨像のルーム内に設置できる。\n啓光ではこのような話が広まっている。「入学時に講演台で大声で夢を語った新入生は、後に人々から崇拝される英雄になる」と。",
  str_item_3661274 = "鋳物暖炉",
  str_item_intro_3661274 = "家具。巨像のルーム内に設置できる。\n啓光で製造された鋳物暖炉。保温性が高い他、落ち着いた外観と暖かそうに燃える小さな火が、部屋を段違いに暖かくしてくれる。",
  str_item_3661275 = "啓示を受ける寝台",
  str_item_intro_3661275 = "家具。巨像のルーム内に設置できる\nワラーキ村で作られた高級ベッド。温もりがあり、快適で独自のクラシックな趣がある。真理結社の信者はそれを天啓降臨の寝台として崇めている",
  str_item_3661276 = "未来を映す鏡",
  str_item_intro_3661276 = "家具。巨像のルーム内に設置できる。\n「真理を探究する者は、古の木の鏡から未来をのぞき見る。」一体誰がこんな宣伝文を考えたのだろう…",
  str_item_3661277 = "勇敢な兵士の肖像",
  str_item_intro_3661277 = "家具。巨像のルーム内に設置できる\n暗鬼の大規模攻撃の中で、突撃の号令すらも咆哮にかき消されてしまう。しかし、一人の勇敢な兵士が軍旗を担いで進むと、無数の兵士がその後に続いた\n「勇敢で犠牲をも恐れない者たちに捧げる」",
  str_item_3661278 = "滅日の暮鐘の像",
  str_item_intro_3661278 = "家具。巨像のルーム内に設置できる\n醜く恐ろしい像。その恐ろしい姿は、生まれつき世界に敵対していると信じさせる\nその像が動き始めると、身に着けた金属の鎧が互いにぶつかり合い、くもった音を立てるのだが、それは命を憎む落日の鐘の音だと言われている",
  str_item_3661262 = "遺跡の守護者の模型",
  str_item_intro_3661262 = "家具。巨像のルーム内に設置できる。\n遺跡の守護者を忘れられないフェラールが作った模型。\n「アレは一種のメカと考えるべきだよ！」",
  str_item_3661263 = "錬金釜",
  str_item_intro_3661263 = "家具。巨像のルーム内に設置できる\nこれがあれば、巨像にライザのアトリエをオープンできるよ！",
  str_item_3661264 = "冒険の記念写真",
  str_item_intro_3661264 = "家具。巨像のルーム内に設置できる\n夏が過ぎ去ったら、この夏をまた思い出そう！",
  str_item_3661279 = "夏風の舵輪",
  str_item_intro_3661279 = "家具。巨像のルーム内に設置できる。\n両手を置くと優しい潮風を感じるような、夏の海の爽やかな息吹を見事に再現している。航海愛好家なら絶対に備えたい家具。",
  str_item_3661280 = "夏風の浮環",
  str_item_intro_3661280 = "家具。巨像のルーム内に設置できる。\nクラシックな色調、丈夫な材質。家に飾っても、航海中に実用的に使っても、美しい風物詩となるだろう。",
  str_item_3661281 = "夏風の旗",
  str_item_intro_3661281 = "家具。巨像のルーム内に設置できる。\nシンプルかつエレガントな装飾用の旗。どこに置いても航海の雰囲気を添えてくれる。",
  str_item_3661282 = "海鳥を待つほら貝",
  str_item_intro_3661282 = "家具。巨像のルーム内に設置できる。\n「ほら貝を吹き鳴らすと～それを聞いたカモメたちは飛べなくなる～」\n誰が巨像でこの民謡を広め始めたのか、それを知るものはいない。",
  str_item_3661283 = "シャボン玉マシン",
  str_item_intro_3661283 = "家具。巨像のルーム内に設置できる。\n台座の上に固定されているシャボン玉銃で、押せばシャボン玉が飛び出る。\n「心からリラックスできるアイテムね。夢の世界に引き込まれなければいいけど～」",
  str_item_3661284 = "白の水仙の肖像画",
  str_item_intro_3661284 = "家具。巨像のルーム内に設置できる。\nナシリスは水仙の栽培が好きだ。彼女は自分の花を大切にしており、それを踏みにじる者を鏡湖に投げ込む。",
  str_item_3661285 = "純潔のユリの肖像画",
  str_item_intro_3661285 = "家具。巨像のルーム内に設置できる。\n二ポリスはユリの栽培が好きだ。彼女は花を摘んで他の人に贈り、その香りだけがいつまでも残っている。",
  str_item_3661286 = "星が輝く時",
  str_item_intro_3661286 = "家具。巨像のルーム内に設置できる。\nアクリュスの一瞬の微笑みを描いたミトラの絵。\n不屈の流星よ、どうか仲間とともに再び輝いて。",
  str_item_3661287 = "双剣",
  str_item_intro_3661287 = "家具。巨像のルーム内に設置できる。\n静かなる猟兵の正副隊長の武器のレプリカ。\n見届けよ！これぞ開拓の極意、守護の決意だ！これこそ静かなる猟兵の真髄。",
  str_item_3661288 = "猛獣スタンド",
  str_item_intro_3661288 = "家具。巨像のルーム内に設置できる。\nミトラが猛禽のために用意した止まり木。\n彼らは従順そうに見えても、その爪は非常に強力。",
  str_item_3661289 = "群星",
  str_item_intro_3661289 = "家具。巨像のルーム内に設置できる。\n古い作品の復元品。\nもし、空を流れゆく星たちが暖かい月日の中で、帰る場所を見つけられたのなら…\n今度こそ遅れてやってきた幸せをつかんでほしい。",
  str_item_3661290 = "幽月の声",
  str_item_intro_3661290 = "家具。巨像のルーム内に設置できる。\nルートヴィヒという名の空の末裔が作曲した曲。\n月光のように気高く優雅でありながら、悲しみも帯びている。\n今度こそ遅れてやってきた幸せをつかんでほしい。",
  str_item_9998002 = "毒医の仮面",
  str_item_9998003 = "叛乱の反響",
  str_item_9998004 = "神裁の手",
  str_item_9998005 = "死神の凝視",
  str_item_9998006 = "瓦解の仮面",
  str_item_9998007 = "疫病の遺作",
  str_item_9998008 = "壁を破る者",
  str_item_9998009 = "狂戦の手甲",
  str_item_9998010 = "狂戦の魂",
  str_item_9998011 = "隊長の彫像",
  str_item_9998012 = "双生蘭",
  str_item_9998013 = "連鎖のお守り",
  str_item_9998014 = "運命のサイコロボックス",
  str_item_9998015 = "ホログラムレンズ",
  str_item_9998016 = "共鳴の勲章",
  str_item_9998017 = "戦いの女神像",
  str_item_9998018 = "身代わりカカシ",
  str_item_9998019 = "光る蝋燭",
  str_item_9998020 = "応急包帯",
  str_item_9998021 = "太陽の栄光",
  str_item_9998022 = "太陽の盾",
  str_item_9998023 = "祝福のアーマー",
  str_item_9998024 = "治癒女神の彫像",
  str_item_9998025 = "カオスブレード",
  str_item_9998026 = "潜在能力ペンダント",
  str_item_9998027 = "御光の大剣",
  str_item_9998028 = "幻彩の絆",
  str_item_9998029 = "友愛の彫像",
  str_item_9998030 = "友情ポイント",
  str_item_9998031 = "友情の拳",
  str_item_9998032 = "絆の彫像",
  str_item_9998033 = "敏速スカーフ",
  str_item_9998034 = "チャージベルト",
  str_item_9998035 = "銀月の猟刀",
  str_item_9998036 = "銀月の長弓",
  str_item_9998037 = "白光の刃",
  str_item_9998038 = "復讐の刻印",
  str_item_9998039 = "降呪の石",
  str_item_9998040 = "狂戦の鎧",
  str_item_9998041 = "裂解水晶",
  str_item_9998042 = "鋭刃の短剣",
  str_item_9998043 = "呪いの手",
  str_item_9998044 = "王を弑する者",
  str_item_9998045 = "チャージ装置",
  str_item_9998046 = "陣営の彫像",
  str_item_9998047 = "拡声器",
  str_item_9998048 = "輝光眼鏡",
  str_item_9998049 = "寂滅の女神像",
  str_item_9998050 = "貫通の剣",
  str_item_9998051 = "神々の黄昏",
  str_item_9998052 = "光力革アーマー",
  str_item_9998053 = "光力の盾",
  str_item_9998054 = "光力魔法箱",
  str_item_9998055 = "ダメージ増強装置",
  str_item_9998056 = "ドロップ缶",
  str_item_9998057 = "旧学の手稿",
  str_item_9998058 = "移動エネルギー器",
  str_item_9998059 = "爆裂ブーツ",
  str_item_9998060 = "謎のロックボックス",
  str_item_9998061 = "万色の宝石",
  str_item_9998062 = "体を縛する者",
  str_item_9998063 = "死の手紙",
  str_item_9998064 = "銀月の盾",
  str_item_9998065 = "散りゆく櫻",
  str_item_9998066 = "敬虔の証",
  str_item_9998067 = "節約戦略",
  str_item_9998068 = "陣営の盾",
  str_item_9998069 = "陣営協奏曲",
  str_item_9998070 = "陣営の祭器",
  str_item_9998071 = "陣営太鼓",
  str_item_9998072 = "陣旗",
  str_item_9998073 = "摂魂の斬刀",
  str_item_9998074 = "砲撃手",
  str_item_9998075 = "幻彩のハマビシ",
  str_item_9998076 = "光吸収ペンキ",
  str_item_intro_9998002 = "各ターン開始時、フィールド上のすべての敵にランダムで1スタックの毒/出血/火傷状態を付与する。効果は繰り返し4回発動する。光霊の与ダメージ-15%",
  str_item_intro_9998003 = "敵が状態異常、または弱体化効果を保有しているとき、すべての被ダメージ+20%",
  str_item_intro_9998004 = "マスを消去した時、消去範囲内の敵にランダムで1スタックの毒/出血/火傷効果を付与する。効果は繰り返し5回発動する",
  str_item_intro_9998005 = "毒/火傷/出血状態を持つ敵を撃破した時、フィールド上の残りのすべての敵に1スタックの毒、火傷、出血状態を付与する",
  str_item_intro_9998006 = "敵の毒/出血/火傷の被ダメージ+100%",
  str_item_intro_9998007 = "敵に対して毒/火傷/出血状態を付与したとき、ターゲットはただちに現在のHPの1%を失う",
  str_item_intro_9998008 = "空の末裔の特殊装備を獲得：2ターン消費すると、ただちにLv.2の陣営サポートスキルを1回発動する。使用は1ターン1回のみ",
  str_item_intro_9998009 = "敵との距離が近いほど、光霊の連鎖技のダメージが増加する。最大で+30%",
  str_item_intro_9998010 = "「ボマー」光霊が30%の確率で連鎖技を1回多く発動する。そのターン内にマスを1マス消去するごとに、発動確率+1%",
  str_item_intro_9998011 = "隊長が自身の属性に基づき出陣する。与ダメージ+100%",
  str_item_intro_9998012 = "隊長が連鎖技を発動する時、消去前の位置に虚像を1つ生成し、同時に連鎖技を放つ",
  str_item_intro_9998013 = "次の勝利後、啓発装備を追加で2回選択できる。1回有効",
  str_item_intro_9998014 = "啓発装備の選択時、再度シャッフルできる。8回使用可",
  str_item_intro_9998015 = "初期の空の末裔の特殊装備を削除し、ただちに啓発装備を2回選択する",
  str_item_intro_9998016 = "光霊が能動技で少なくとも敵3体を同時に攻撃する時、フィールド上の敵すべてに雷を落とし、チーム平均攻撃力の200％のダメージを与える",
  str_item_intro_9998017 = "隊長変更後、新しい隊長の能動技CDターン-1。光霊1名につき、発動は毎ターン最多1回まで",
  str_item_intro_9998018 = "チームのHPが1%になった時、HPが1ターン固定され、その後、最大HPの20%を回復する（1回の対戦につき発動は1回まで。総発動回数は2回まで）",
  str_item_intro_9998019 = "戦闘勝利後、チームが失ったHPの35%を回復する",
  str_item_intro_9998020 = "戦闘開始時、フィールド上に包帯を1つ出現させる",
  str_item_intro_9998021 = "チームのHPが90%以上の時、光霊の与えるダメージ+15%",
  str_item_intro_9998022 = "各ウェーブ開始時に最大HPの40%のシールドを獲得する。2ターン持続",
  str_item_intro_9998023 = "戦闘開始時にHPが50%未満の場合、ただちに50%まで回復する",
  str_item_intro_9998024 = "戦闘時、「サポーター」ジョブの光霊の連鎖技と能動技の回復効果+40%",
  str_item_intro_9998025 = "チーム内の光霊のメイン属性1種につき、光霊の与ダメージ+6%。最大+24%",
  str_item_intro_9998026 = "光霊がダメージを与えた時、属性相性によるダメージ減少効果を無視する。また、ダメージを受けた時、属性相性によるダメージ増加効果を無視する",
  str_item_intro_9998027 = "光霊がサブ属性でダメージを与えたとき、メイン属性と同じ倍率になる",
  str_item_intro_9998028 = "絆を持つ光霊が消去したマスの属性を無視して連鎖技を発動できる",
  str_item_intro_9998029 = "絆を持つ光霊1組につき、毎ターン開始時、チーム最大HPの5%を回復する",
  str_item_intro_9998030 = "絆を持つ光霊1組につき、マス消去時に40%の確率で、空の末裔の特殊装備を追加で1回チャージする。複数組存在する場合、単独で発動する",
  str_item_intro_9998031 = "絆を持つ光霊が互いに20%の基礎攻撃力を継承する",
  str_item_intro_9998032 = "光霊が能動技を発動する時、その絆を持つ光霊の能動技CDターン-1。1回の対戦につき、発動は最多5回まで",
  str_item_intro_9998033 = "1回の対戦で最初に能動技を発動するたび、発動後ただちに技のCDターン-2",
  str_item_intro_9998034 = "タップでマスを消した時、このターンでまだ光霊が連鎖技を使用していなければ、すべての光霊の能動技のCD-1",
  str_item_intro_9998035 = "光霊が敵から離れているほど、連鎖技のダメージが大きくなる。最大+50%",
  str_item_intro_9998036 = "「スナイパー」ジョブの光霊の連鎖技ターゲット+2",
  str_item_intro_9998037 = "光霊がダメージを与えた時、3%の吸血効果を得る。各ターン開始時、現在のHPの10％を失う",
  str_item_intro_9998038 = "現在のHPが低いほど、光霊の連鎖技ダメージが高くなる。最大+50%",
  str_item_intro_9998039 = "各ターン開始時、フィールド上の敵味方すべてが現在のHPの7%を失う",
  str_item_intro_9998040 = "現在のHPが50%の時、光霊の与ダメージ+30%。HPが1%減るごとに、強化効果-5%",
  str_item_intro_9998041 = "ターン開始時、現在のHPの7%を失う。その後周囲2マス内にいる敵に、チーム平均攻撃力の150%のダメージを与える",
  str_item_intro_9998042 = "戦闘開始時、現在のHPの70%を失い、フィールド上の敵すべてに失ったHPの300%のダメージを与える",
  str_item_intro_9998043 = "光霊の能動技ダメージ+80%、能動技を使用するたびに現在のHPの8%を失う",
  str_item_intro_9998044 = "タップして消去したマスの数を無視し、消去するたびに必ず光霊の最高段階の連鎖技を発動する",
  str_item_intro_9998045 = "戦闘開始時、すべての空の末裔の特殊装備の使用回数が1回増える",
  str_item_intro_9998046 = "空の末裔の特殊装備を使用するたび、Lv.1の陣営サポートスキルを1回発動する。1回の対戦につき2回有効",
  str_item_intro_9998047 = "初期の空の末裔の特殊装備の有効範囲が5×5になる。エネルギーを40獲得後、使用回数が1回増える。",
  str_item_intro_9998048 = "空の末裔の特殊装備の使用回数のチャージ効率+50%",
  str_item_intro_9998049 = "死の気配を召喚し、残りHPが9%以下の敵を瞬殺する",
  str_item_intro_9998050 = "光霊の与ダメージ+20%。経過ターン消費数が倍増する",
  str_item_intro_9998051 = "チームのすべての光霊の防御力がクリアされる。ただし、その基礎防御力の50%が攻撃力に変わる",
  str_item_intro_9998052 = "啓発装備を1つ所有するごとに、すべての光霊の最大HP+2%",
  str_item_intro_9998053 = "啓発装備を1つ所有するごとに、すべての光霊の防御力+1.5%",
  str_item_intro_9998054 = "啓発装備を1つ所有するごとに、すべての光霊の攻撃力+1%",
  str_item_intro_9998055 = "各ターン開始時、フィールド上のランダムな位置にダメージ増強装置を1つ設置する。ダメージ増強装置を消去後、そのターン内の連鎖技のダメージ+35%",
  str_item_intro_9998056 = "各ウェーブ開始時、フィールド上のランダムな位置にドロップ缶を1つ設置する。ドロップ缶を消去後、ランダムで1つの空の末裔の特殊装備の使用回数が1回増える",
  str_item_intro_9998057 = "フィールド上のすべての消去可能な道具の更新数が2になる",
  str_item_intro_9998058 = "各ウェーブ開始時、フィールド上のランダムな位置に移動エネルギー器を1つ更新する。移動エネルギー器を消去後、総ターン数を3獲得する",
  str_item_intro_9998059 = "各ターン開始時、足下のマスを粉砕する。光霊の与ダメージ+15%",
  str_item_intro_9998060 = "すべての啓発装備の有効回数が初期状態に戻る",
  str_item_intro_9998061 = "空の末裔の特殊装備を獲得：フィールド上のすべてのマスを万色マスに変える。使用は2回まで",
  str_item_intro_9998062 = "消去範囲内の敵に与える連鎖技ダメージ+35%",
  str_item_intro_9998063 = "タップでマスを消去した時、消去範囲内の敵にチーム平均攻撃力の150%のダメージを与える",
  str_item_intro_9998064 = "タップでマスを消去した時、1マス消去するごとに、最大HPの0.5%のシールドを獲得する。1ターン持続",
  str_item_intro_9998065 = "1回のタップで少なくとも15マス以上消去した時、光霊の連鎖技ダメージ+30%。消去したマスの数が7未満の場合、連鎖技は発動できない",
  str_item_intro_9998066 = "チーム内で攻撃力が最も低い光霊の基礎攻撃力+60%",
  str_item_intro_9998067 = "陣営サポートスキル発動のために必要な消去すべきマスの数が減少する。Lv.1、Lv.2でそれぞれ5マスと10マス減少する",
  str_item_intro_9998068 = "陣営サポートスキルに、敵を1マスノックバックする効果を付加する",
  str_item_intro_9998069 = "各ターン開始時、チーム内の陣営サポートスキルと同じ陣営の光霊1名につき、すべての空の末裔の特殊装備がエネルギーを3獲得する",
  str_item_intro_9998070 = "陣営サポートスキルに吸血効果を付与する。チーム内のその陣営に属する光霊1名につき、5%の吸血効果を獲得する",
  str_item_intro_9998071 = "タップでマスを消去した時、1マス消去するごとに、そのターンの陣営サポートスキルの最終ダメージ+5%",
  str_item_intro_9998072 = "チーム内の陣営サポートスキルと同じ陣営の光霊1名につき、陣営サポートスキルの最終ダメージ+25%",
  str_item_intro_9998073 = "チーム内の陣営サポートスキルと同じ陣営の光霊1名につき、すべての光霊の基礎防御力とHP上限+3%",
  str_item_intro_9998074 = "光霊の能動技ダメージ+100%。連鎖技は1段階のみ発動可能",
  str_item_intro_9998075 = "各ターン開始時、フィールド上のランダムの敵2体の足下1マスを万色マスに変える",
  str_item_intro_9998076 = "敵撃破時、足下の1マスの色が隊長と同じ属性に変わる",
  str_item_4090264 = "魔法薬の夜",
  str_item_intro_4090264 = "「私、光霊をやめる」\n虚無に耐えられないウリエルは、魔法薬を使って自分を他の存在に変えたいと思っていた。しかし、魔法薬を飲んだ彼女は願いを果たせず、不思議な酩酊状態に陥った。もともと意気消沈して孤立気味だった彼女だが、突然積極的になり、あなたを巻き込んで型破りなことを試し始めた。あなたはこれからまる一日、どう対処するのだろうか？",
  str_item_3400132 = "意識接続、グワッ",
  str_item_intro_3400132 = "獲得すると背景-「意識接続、グワッ」が使用可能になる\n万物の意識を感知するのがカエルの奇跡の能力である。その能力を持つがために、カエルもまた仲間を癒す重責を担っているのである…",
