  str_item_intro_9011001 = "ターン開始時、フィールド全体の敵に4444の固定ダメージを与え、HPが6%未満の敵を撃破する",
  str_item_intro_9011002 = "毎ターン周囲で万色マスを更新する。数量はチーム内にいる光霊のメイン属性の種類数と同じ。戦闘開始時に追加で2回実行する",
  str_item_intro_9011003 = "戦闘の3ターン目にすべてのマスを万色マスに変える。連鎖終了後、すべての万色マスをクリアする",
  str_item_intro_9011004 = "HPが上限値と同じである光霊の全与ダメージ+15%",
  str_item_intro_9011005 = "呑夢の暗影のステージをクリアした後、現在所有する夢の金貨の30%相当の利息を獲得する",
  str_item_intro_9011006 = "1回のみ：爆夢弾を2個獲得する",
  str_item_intro_9011007 = "現在所有する夢の金貨が多いほど、通常攻撃のダメージが大きくなる",
  str_item_intro_9011008 = "連鎖の最初のマスとその後のマスの属性と異なっていてもよく、2種類の属性の光霊はいずれも攻撃できる",
  str_item_intro_9011009 = "未装備の幻珠をすべてシャッフルして新しい幻珠にする（新しい幻珠のレベルはシャッフル前を下回らない）。さらに各幻珠のレア度が30%の確率で上昇する",
  str_item_intro_9011010 = "連鎖で通過したマスが隊長と同じ属性のとき、2マス連鎖するごとに幻珠のエネルギー充填+1",
  str_item_intro_9011011 = "幻珠の技でダメージを与えるとき、ランダムの範囲内で2回シャッフルして高いステータスを取る。ダメージの変動範囲は10%拡大する",
  str_item_intro_9011012 = "獲得後、それ以降に獲得する幻珠のレア度+1",
  str_item_intro_9011013 = "夢占い札を選択するとき、選択可能な夢占い札の数-1。ただし、夢占い札を通じて得られる報酬が2倍になる。",
  str_item_intro_9011014 = "戦闘開始後、全光霊の最大HP-20%。行動時、選択可能な夢占い札の数+1。",
  str_item_intro_9011015 = "連鎖開始前、光霊が移動するたびに、終着点に平均攻撃力の150%の菱形ダメージを1回与え、かつ1マス移動するごとに、幻珠へのエネルギー充填+1",
  str_item_intro_9011016 = "チェンジャーとサポータージョブの光霊の連鎖技がダメージを与えるとき、ターゲットに毒/出血/火傷状態をランダムで1スタック付与する",
  str_item_intro_9011017 = "毒/出血/火傷状態の敵にダメージを与えるとき、各種効果のダメージが一定程度増加する",
  str_item_intro_9011018 = "ターゲットに毒/出血/火傷状態を1種類付与した後、一定確率でさらにランダムで1スタック付与する。この効果は重複して発動でき、毎回発動確率が半減する",
  str_item_intro_9011019 = "敵を撃破したとき、フィールド全体の敵に毒/出血/火傷状態をランダムで1スタック付与する",
  str_item_intro_9011020 = "隊長が通常攻撃をするとき、チーム全体の攻撃力の50%の火属性ダメージを追加で1回与える",
  str_item_intro_9011021 = "隊長が通常攻撃をするとき、チーム全体の攻撃力の50%の雷属性ダメージを追加で1回与える",
  str_item_intro_9011022 = "隊長が通常攻撃をするとき、チーム全体の攻撃力の50%の森属性ダメージを追加で1回与える",
  str_item_intro_9011023 = "隊長が通常攻撃をするとき、チーム全体の攻撃力の50%の水属性ダメージを追加で1回与える",
  str_item_intro_9011024 = "毎ターン開始時、最も近くにある火属性のマス3つを万色マスに変える",
  str_item_intro_9011025 = "毎ターン開始時、最も近くにある雷属性のマス3つを万色マスに変える",
  str_item_intro_9011026 = "毎ターン開始時、最も近くにある森属性のマス3つを万色マスに変える",
  str_item_intro_9011027 = "毎ターン開始時、最も近くにある水属性のマス3つを万色マスに変える",
  str_item_intro_9011028 = "毎ターン開始時、すべての暗鬼の足下にある最大1マスを万色マスに変える",
  str_item_intro_9011029 = "ダメージを受けたとき、周囲2マス以内にある3マスが万色マスに変わる",
  str_item_intro_9011030 = "毎ターン開始時、HPの低い光霊が失ったHPの比率に応じてHPを回復する",
  str_item_intro_9011031 = "戦闘終了後、すべての光霊がHPを20%回復する",
