  str_item_intro_9011041 = "危険夢域を通過した後、夢境経験値を30獲得できる",
  str_item_intro_9011042 = "代理購入中の商品価格が低下し、夢境装備、光霊、商品を改めてシャッフルするコスト-35%",
  str_item_intro_9011043 = "獲得後、未開拓夢域内で光霊派遣を行うと、ただちに帰還し、かつ派遣の夢の金貨と夢の利息の収益が2倍になる",
  str_item_intro_9011044 = "キャンプを通過するごとに、夢境経験値を40獲得できる",
  str_item_intro_9011045 = "1回のみ：すべての光霊が現在のHPの70%を失う。HPを失った光霊1人につき、夢境経験値を25獲得できる",
  str_item_intro_9011046 = "1回のみ：現在の半分の数の夢の金貨を消費する。消費した夢の金貨1個につき、夢境経験値を2獲得できる",
